	pullIssue := &issues_model.Issue{RepoID: repo.ID, Index: 2, PosterID: 2, Title: "human lock merged pull", IsPull: true, IsClosed: true}
	closed := &issues_model.Issue{RepoID: repo.ID, Index: 3, PosterID: 2, Title: "human lock closed", IsClosed: true}
	_, err = db.GetEngine(ctx).Insert(issue, pullIssue, closed)
	require.NoError(t, err)
	pull := &issues_model.PullRequest{IssueID: pullIssue.ID, Index: 2, BaseRepoID: repo.ID, HeadRepoID: repo.ID, BaseBranch: "main", HeadBranch: "work", HasMerged: true}
