func runInlineSnapshot(t *testing.T, fixture sourceTestFixture, repo *repo_model.Repository, issue *issues_model.Issue, pr *issues_model.PullRequest, probe string) {
	t.Helper()
	ctx := t.Context()
	contextLines := func(changed bool) string {
		var b strings.Builder
		for i := 1; i <= 20; i++ {
			if i == 3 {
				b.WriteString("\n")
				continue
			}
			if changed && (i == 5 || i == 15) {
				fmt.Fprintf(&b, "changed %d\n", i)
			} else {
				fmt.Fprintf(&b, "line %d\n", i)
			}
		}
		return b.String()
	}
	for name, content := range map[string][]byte{"context.txt": []byte(contextLines(false)), "deleted.txt": []byte("deleted\n"), "renamed-old.txt": []byte("first\nsecond\n"), "binary.dat": {0, 1, 2}, "no-eol": []byte("old"), "literal[*].txt": []byte("literal old\n")} {
		require.NoError(t, os.WriteFile(filepath.Join(fixture.work, name), content, 0o600))
	}
	sourceTestGit(t, fixture.work, nil, "add", ".")
	sourceTestGit(t, fixture.work, nil, "commit", "-m", "inline base")
	fixture.base = sourceTestGit(t, fixture.work, nil, "rev-parse", "HEAD")
	require.NoError(t, os.Rename(filepath.Join(fixture.work, "renamed-old.txt"), filepath.Join(fixture.work, "renamed-new.txt")))
	require.NoError(t, os.Remove(filepath.Join(fixture.work, "deleted.txt")))
	require.NoError(t, os.Symlink("README", filepath.Join(fixture.work, "inline-link")))
	for name, content := range map[string][]byte{"README": []byte("inline head\n"), "context.txt": []byte(contextLines(true)), "added.txt": []byte("added\n"), "binary.dat": {0, 1, 3}, "no-eol": []byte("new"), "literal[*].txt": []byte("literal new\n"), "empty.txt": {}, "huge.txt": bytes.Repeat([]byte("x"), (5 << 20))} {
		require.NoError(t, os.WriteFile(filepath.Join(fixture.work, name), content, 0o600))
	}
	sourceTestGit(t, fixture.work, nil, "add", ".")
	sourceTestGit(t, fixture.work, nil, "update-index", "--add", "--cacheinfo", "160000", fixture.base, "module")
	sourceTestGit(t, fixture.work, nil, "commit", "-m", "inline head")
	fixture.tip = sourceTestGit(t, fixture.work, nil, "rev-parse", "HEAD")
	sourceTestGit(t, repo.RepoPath(), nil, "fetch", fixture.work, "HEAD")
	sourceTestGit(t, repo.RepoPath(), nil, "update-ref", "refs/heads/master", fixture.base)
	sourceTestGit(t, repo.RepoPath(), nil, "update-ref", pr.GetGitRefName(), fixture.tip)
	require.NoError(t, nativeoperation_service.WithAuthorityOwnership(ctx, "inline-preparation-fixture", repo.ID, func(context.Context) error { return nil }))
	if probe := os.Getenv("SODA_FOUNTAIN_THREAD_SDK_PROBE"); probe != "" {
		runHumanReviewSDK(t, fixture, repo, issue, pr, probe)
		return
	}
	if os.Getenv("SODA_FOUNTAIN_THREAD_NATIVE") == "1" {
		runHumanThreadNative(t, fixture, repo, issue, pr)
		return
	}
	if os.Getenv("SODA_FOUNTAIN_THREAD_PRIMARY") == "1" {
		runPreparedHumanThreadPrimary(t, fixture, repo, issue, pr)
		return
	}
	if probe := os.Getenv("SODA_FOUNTAIN_THREAD_SNAPSHOT_PROBE"); probe != "" {
		runThreadSnapshot(t, fixture, repo, issue, pr, probe)
		return
	}
	if os.Getenv("SODA_FOUNTAIN_INLINE_PRIMARY") == "1" {
		runPreparedHumanInlinePrimary(t, fixture, repo, issue, pr)
		return
	}
	if os.Getenv("SODA_FOUNTAIN_INLINE_GROUPS") == "1" {
		runInlineGroups(t, fixture, repo, issue, pr)
		return
	}
	if os.Getenv("SODA_FOUNTAIN_INLINE_NATIVE") == "1" {
		runHumanInlineNative(t, fixture, repo, issue, pr)
		return
	}
	if probe := os.Getenv("SODA_FOUNTAIN_INLINE_SDK_PROBE"); probe != "" {
		runHumanReviewSDK(t, fixture, repo, issue, pr, probe)
		return
	}
	root := shortWitnessRoot(t)
	socket := filepath.Join(root, "i")
	listener, err := net.Listen("unix", socket)
	require.NoError(t, err)
	server := &http.Server{Handler: CallbackHandlerForInstance("source-test")}
	go func() { _ = server.Serve(listener) }()
	t.Cleanup(func() { _ = server.Close() })
	var own *issues_model.Review
	counts := func() [3]int64 {
		var result [3]int64
		for i, row := range []any{new(issues_model.Review), new(issues_model.Comment), new(nativeoperation_model.Operation)} {
			var err error
			result[i], err = db.GetEngine(ctx).Count(row)
			require.NoError(t, err)
		}
		return result
	}
	readMutation := int64(0)
	run := func(mode string) {
		t.Helper()
		pending := ""
		if own != nil {
			pending = strconv.FormatInt(own.ID, 10)
		}
		raw, err := json.Marshal(struct {
			Authority                                                       extension.Authority
			Admission, Socket, Repository, Pull, Issue, Base, Head, Pending string
		}{fixture.authority, fixture.token, socket, strconv.FormatInt(repo.ID, 10), strconv.FormatInt(pr.ID, 10), strconv.FormatInt(issue.ID, 10), fixture.base, fixture.tip, pending})
		require.NoError(t, err)
		path := filepath.Join(root, "inline.json")
		require.NoError(t, os.WriteFile(path, raw, 0o600))
		before := counts()
		command := exec.CommandContext(ctx, probe, mode)
		command.Env = append(os.Environ(), "SODA_FOUNTAIN_READ_BINDING="+path)
		output, err := command.CombinedOutput()
		require.NotContains(t, string(output), fixture.token)
		t.Log(string(output))
		require.NoError(t, err, "inline phase %s", mode)
		before[0] += readMutation
		require.Equal(t, before, counts(), "inline preparation allocated native rows")
	}
	run("good")
	foreign := &issues_model.Review{IssueID: issue.ID, ReviewerID: 4, Type: issues_model.ReviewTypePending, CommitID: fixture.tip, Content: "foreign inline secret"}
	_, err = db.GetEngine(ctx).Insert(foreign)
	require.NoError(t, err)
	own = &issues_model.Review{IssueID: issue.ID, ReviewerID: 2, Type: issues_model.ReviewTypePending, CommitID: fixture.base, Content: "own inline secret"}
	_, err = db.GetEngine(ctx).Insert(own)
	require.NoError(t, err)
	run("own-draft")
	_, err = db.GetEngine(ctx).ID(own.ID).Delete(new(issues_model.Review))
	require.NoError(t, err)
	own = nil
	_, err = db.GetEngine(ctx).ID(repo.ID).Cols("is_archived").Update(&repo_model.Repository{IsArchived: true})
	require.NoError(t, err)
	run("denied")
	_, err = db.GetEngine(ctx).ID(repo.ID).Cols("is_archived").Update(&repo_model.Repository{})
	require.NoError(t, err)
	block := &user_model.BlockedUser{UserID: 1, BlockID: 2}
	_, err = db.GetEngine(ctx).Insert(block)
	require.NoError(t, err)
	run("denied")
	_, err = db.GetEngine(ctx).ID(block.ID).Delete(new(user_model.BlockedUser))
	require.NoError(t, err)
	setPermission := func(mode perm.AccessMode) {
		for _, row := range []any{&access_model.Access{Mode: mode}, &repo_model.Collaboration{Mode: mode}} {
			_, err := db.GetEngine(ctx).Where("repo_id=? AND user_id=?", repo.ID, 2).Cols("mode").Update(row)
			require.NoError(t, err)
		}
	}
	setPermission(perm.AccessModeNone)
	run("hidden")
	setPermission(perm.AccessModeRead)
	require.NoError(t, nativeoperation_service.WithAuthorityOwnership(ctx, "inline-busy", repo.ID, func(context.Context) error { run("busy"); return nil }))
	for _, race := range []string{"head", "base", "draft", "source", "permission", "archive", "actor", "revision"} {
		t.Logf("inline preparation race: %s", race)
		start := fixture.session.reads
		changed := false
		fixture.session.onRead = func(n int) {
			if n != start+4 {
				return
			}
			changed = true
			switch race {
			case "head":
				sourceTestGit(t, repo.RepoPath(), nil, "update-ref", pr.GetGitRefName(), fixture.base)
			case "base":
				sourceTestGit(t, repo.RepoPath(), nil, "update-ref", "refs/heads/master", fixture.tip)
			case "source":
				_, err = db.GetEngine(ctx).ID(pr.ID).Cols("head_branch").Update(&issues_model.PullRequest{HeadBranch: "changed-private-source"})
				require.NoError(t, err)
			case "draft":
				own = &issues_model.Review{IssueID: issue.ID, ReviewerID: 2, Type: issues_model.ReviewTypePending, CommitID: fixture.base, Content: "own inline secret"}
				_, err = db.GetEngine(ctx).Insert(own)
				require.NoError(t, err)
			case "permission":
				setPermission(perm.AccessModeNone)
			case "archive":
				_, err = db.GetEngine(ctx).ID(repo.ID).Cols("is_archived").Update(&repo_model.Repository{IsArchived: true})
				require.NoError(t, err)
			case "actor":
				fixture.session.uid = 4
			case "revision":
				require.NoError(t, nativeoperation_service.WithAuthorityOwnership(ctx, "inline-revision-race", repo.ID, func(context.Context) error { return nil }))
			}
		}
		mode := "changed"
		if race == "actor" {
			mode = "refused"
		}
		readMutation = 0
		if race == "draft" {
			readMutation = 1
		}
		run(mode)
		readMutation = 0
		require.True(t, changed, "inline race did not execute")
		fixture.session.onRead = nil
		fixture.session.uid = 2
		sourceTestGit(t, repo.RepoPath(), nil, "update-ref", pr.GetGitRefName(), fixture.tip)
		sourceTestGit(t, repo.RepoPath(), nil, "update-ref", "refs/heads/master", fixture.base)
		_, err = db.GetEngine(ctx).ID(pr.ID).Cols("head_branch").Update(&issues_model.PullRequest{HeadBranch: pr.HeadBranch})
		require.NoError(t, err)
		_, err = db.GetEngine(ctx).ID(repo.ID).Cols("is_archived").Update(&repo_model.Repository{})
		require.NoError(t, err)
		setPermission(perm.AccessModeRead)
		if own != nil {
			_, err = db.GetEngine(ctx).ID(own.ID).Delete(new(issues_model.Review))
			require.NoError(t, err)
			own = nil
		}
	}
	entry := nativeAdmissions.get(fixture.token)
	delete(entry.capabilities, extension.CapabilityRepositoryRead)
	run("refused")
	entry.capabilities[extension.CapabilityRepositoryRead] = struct{}{}
	t.Log("PASS: actual inline SDK/private callback with immutable literal Git file/side/range proof, renamed/added/deleted/context/no-newline/binary/gitlink/large semantics, own draft privacy, live denial and Git/draft/source/permission/session/revision races; no read effects or write authority")
}

func runPreparedHumanReviewRequestPrimary(t *testing.T, fixture sourceTestFixture, repo *repo_model.Repository, issue *issues_model.Issue, pr *issues_model.PullRequest) {
	t.Helper()
	ctx := t.Context()
	team := &organization.Team{OrgID: repo.OwnerID, Name: "primary-reviewers", LowerName: "primary-reviewers", AccessMode: perm.AccessModeRead}
	_, err := db.GetEngine(ctx).Insert(team)
	require.NoError(t, err)
	teamRepo := &organization.TeamRepo{OrgID: repo.OwnerID, TeamID: team.ID, RepoID: repo.ID}
	access := &access_model.Access{RepoID: repo.ID, UserID: 4, Mode: perm.AccessModeRead}
	_, err = db.GetEngine(ctx).Insert(teamRepo, access, &repo_model.Collaboration{RepoID: repo.ID, UserID: 4, Mode: perm.AccessModeRead})
	require.NoError(t, err)
	rule := &git_model.ProtectedBranch{RepoID: repo.ID, RuleName: "master", EnableApprovalsWhitelist: true, ApprovalsWhitelistUserIDs: []int64{4}, ApprovalsWhitelistTeamIDs: []int64{team.ID}}
	_, err = db.GetEngine(ctx).Insert(rule)
	require.NoError(t, err)
	completed := &issues_model.Review{IssueID: issue.ID, ReviewerID: 4, Type: issues_model.ReviewTypeApprove, Official: true, CommitID: fixture.base, Content: "retained approval 完整\r\n", CreatedUnix: 1, UpdatedUnix: 2}
	teamCompleted := &issues_model.Review{IssueID: issue.ID, ReviewerID: -team.ID, Type: issues_model.ReviewTypeApprove, Official: true, CommitID: fixture.base, Content: "retained team approval", CreatedUnix: 1, UpdatedUnix: 2}
	own := &issues_model.Review{IssueID: issue.ID, ReviewerID: 2, Type: issues_model.ReviewTypePending, CommitID: fixture.base, Content: "own older draft"}
	foreign := &issues_model.Review{IssueID: issue.ID, ReviewerID: 4, Type: issues_model.ReviewTypePending, CommitID: fixture.tip, Content: "foreign current draft"}
	_, err = db.GetEngine(ctx).Insert(completed, teamCompleted, own, foreign)
	require.NoError(t, err)
	inline := &issues_model.Comment{IssueID: issue.ID, ReviewID: foreign.ID, PosterID: 4, Type: issues_model.CommentTypeCode, Content: "foreign unpublished inline 完整\r\n", TreePath: "context.txt", Line: 6, CommitSHA: fixture.tip, OriginalAnchor: &issues_model.CodeCommentAnchor{Base: fixture.base, Head: fixture.tip, Path: "context.txt", Side: "new", Scope: "lines", StartLine: 4, EndLine: 6}}
	_, err = db.GetEngine(ctx).Insert(inline)
	require.NoError(t, err)
	if os.Getenv("SODA_FOUNTAIN_REVIEW_REQUEST_NATIVE") == "1" {
		runHumanReviewRequestNative(t, fixture, repo, issue, pr, team, completed, teamCompleted, foreign)
		return
	}

	prepare := func(kind string, id int64) extension.RepositoryReviewRequestSnapshot {
		t.Helper()
		p, status := resolveReviewRequestSnapshot(ctx, nativeAdmissions.get(fixture.token), extension.CallbackRequest{RepositoryID: strconv.FormatInt(repo.ID, 10), ReviewRequestSnapshot: &extension.RepositoryReviewRequestSnapshotRequest{Index: "2", ReviewerKind: kind, ReviewerID: strconv.FormatInt(id, 10)}})
		require.Equal(t, http.StatusOK, status)
		require.NotNil(t, p)
		return *p
	}
	admit := func(tx context.Context) error {
		actor, status := resolveCurrentUser(tx, nativeAdmissions.get(fixture.token))
		if status != http.StatusOK || actor.ID != 2 {
			return nativeoperation_service.ErrAuthorityLost
		}
		return nil
	}
	encode := func(v any) string { raw, err := json.Marshal(v); require.NoError(t, err); return string(raw) }
	reviews := func() []*issues_model.Review {
		var rows []*issues_model.Review
		require.NoError(t, db.GetEngine(ctx).Where("issue_id=?", issue.ID).Asc("id").Find(&rows))
		return rows
	}
	comments := func() []*issues_model.Comment {
		var rows []*issues_model.Comment
		require.NoError(t, db.GetEngine(ctx).Where("issue_id=?", issue.ID).Asc("id").Find(&rows))
		return rows
	}
	apply := func(q extension.RepositoryReviewRequestSnapshot, requested, rollback bool, gate nativeoperation_service.HumanReviewAdmission) (*nativeoperation_service.PreparedHumanReviewRequestResult, error) {
		var result *nativeoperation_service.PreparedHumanReviewRequestResult
		err := nativeoperation_service.WithAuthorityOwnership(ctx, "prepared-human-review-request", repo.ID, func(owned context.Context) error {
			if rollback {
				tx, committer, err := db.TxContext(owned)
				if err != nil {
					return err
				}
				defer committer.Close()
				result, err = nativeoperation_service.ApplyPreparedHumanReviewRequest(tx, 2, q, requested, gate)
				if err != nil {
					return err
				}
				return errors.New("intentional-outer-review-request-rollback")
			}
			var err error
			result, err = nativeoperation_service.ApplyPreparedHumanReviewRequest(owned, 2, q, requested, gate)
			return err
		})
		return result, err
	}
	refused := func(q extension.RepositoryReviewRequestSnapshot, requested bool, gate nativeoperation_service.HumanReviewAdmission) {
		t.Helper()
		before, history := encode(reviews()), encode(comments())
		result, err := apply(q, requested, false, gate)
		require.Error(t, err)
		require.Nil(t, result)
		require.Equal(t, before, encode(reviews()), "refused primary changed review history/drafts")
		require.Equal(t, history, encode(comments()), "refused primary left history/inline changes")
	}
	commit := func(kind string, id int64, requested bool) {
		t.Helper()
		q := prepare(kind, id)
		before, history := reviews(), comments()
		result, err := apply(q, requested, false, admit)
		require.NoError(t, err)
		require.NotNil(t, result)
		require.Equal(t, q.Requests, result.Before)
		require.Equal(t, requested != (len(q.Requests.RequestIDs) > 0), result.Changed)
		require.Equal(t, requested, len(result.After.RequestIDs) > 0)
		require.Len(t, result.ReviewsBeforeDigest, 64)
		require.Len(t, result.ReviewsAfterDigest, 64)
		if !result.Changed {
			require.Empty(t, result.HistoryIDs)
			require.Equal(t, result.Before, result.After)
			require.Equal(t, result.ReviewsBeforeDigest, result.ReviewsAfterDigest)
			require.Equal(t, encode(before), encode(reviews()))
			require.Equal(t, encode(history), encode(comments()))
			return
		}
		removed := map[int64]bool{}
		if !requested {
			for _, id := range q.Requests.RequestIDs {
				removed[nativeIDForEdit(id)] = true
			}
		}
		created := map[int64]bool{}
		if requested {
			for _, id := range result.After.RequestIDs {
				created[nativeIDForEdit(id)] = true
			}
		}
		var expected, remaining []*issues_model.Review
		for _, row := range before {
			if removed[row.ID] {
				continue
			}
			if kind == "user" && row.ID == completed.ID {
				row.Official = !requested
			}
			expected = append(expected, row)
		}
		for _, row := range reviews() {
			if !created[row.ID] {
				remaining = append(remaining, row)
			}
		}
		require.Equal(t, encode(expected), encode(remaining), "primary changed unrelated history or draft metadata")
		newHistory := map[int64]bool{}
		for _, id := range result.HistoryIDs {
			newHistory[nativeIDForEdit(id)] = true
		}
		var oldComments []*issues_model.Comment
		for _, row := range comments() {
			if !newHistory[row.ID] {
				oldComments = append(oldComments, row)
			}
		}
		require.Equal(t, encode(history), encode(oldComments), "primary changed retained inline/history data")
		wantHistory := len(q.Requests.RequestIDs)
		if requested {
			wantHistory = 1
		}
		require.Len(t, result.HistoryIDs, wantHistory)
	}
	q := prepare("user", 4)
	_, err = nativeoperation_service.ApplyPreparedHumanReviewRequest(ctx, 2, q, true, admit)
	require.ErrorIs(t, err, nativeoperation_model.ErrBusy)
	q = prepare("user", 4)
	require.NoError(t, nativeoperation_service.WithAuthorityOwnership(ctx, "review-request-owner-checks", repo.ID, func(owned context.Context) error {
		held, err := nativeoperation_model.ReadReservation(owned)
		require.NoError(t, err)
		for _, carried := range []*execcontext.Execution{nil, {Owner: "foreign-owner", Generation: held.Generation}, {Owner: held.Owner, Generation: held.Generation + 1}} {
			wrong := ctx
			if carried != nil {
				wrong = execcontext.NewContext(owned, carried)
			}
			_, err := nativeoperation_service.ApplyPreparedHumanReviewRequest(wrong, 2, q, true, admit)
			require.ErrorIs(t, err, nativeoperation_model.ErrBusy)
		}
		return nil
	}))
	for _, subject := range []struct {
		kind string
		id   int64
	}{{"user", 4}, {"team", team.ID}} {
		for _, requested := range []bool{true, true, false, false} {
			commit(subject.kind, subject.id, requested)
		}
	}
	// Legacy duplicate requests are one desired-state selection; remove all of
	// them atomically and preserve exact records on an already-requested no-op.
	_, err = db.GetEngine(ctx).Insert(&issues_model.Review{IssueID: issue.ID, ReviewerID: 4, Type: issues_model.ReviewTypeRequest, Official: true}, &issues_model.Review{IssueID: issue.ID, ReviewerID: 4, Type: issues_model.ReviewTypeRequest})
	require.NoError(t, err)
	commit("user", 4, true)
	commit("user", 4, false)
	// Both changing and no-op primaries join the caller's transaction.
	q = prepare("user", 4)
	before, history := encode(reviews()), encode(comments())
	result, err := apply(q, true, true, admit)
	require.Error(t, err)
	require.NotNil(t, result)
	require.Equal(t, before, encode(reviews()))
	require.Equal(t, history, encode(comments()))
	q = prepare("team", team.ID)
	require.NoError(t, nativeoperation_service.WithAuthorityOwnership(ctx, "review-request-noop-outer", repo.ID, func(owned context.Context) error {
		tx, committer, err := db.TxContext(owned)
		if err != nil {
			return err
		}
		defer committer.Close()
		marker := &issues_model.Review{IssueID: issue.ID, ReviewerID: 1, Type: issues_model.ReviewTypeComment, Content: "joined no-op marker"}
		if _, err := db.GetEngine(tx).Insert(marker); err != nil {
			return err
		}
		result, err := nativeoperation_service.ApplyPreparedHumanReviewRequest(tx, 2, q, false, admit)
		if err != nil {
			return err
		}
		require.False(t, result.Changed)
		return committer.Commit()
	}))
	count, err := db.GetEngine(ctx).Where("issue_id=? AND content=?", issue.ID, "joined no-op marker").Count(new(issues_model.Review))
	require.NoError(t, err)
	require.EqualValues(t, 1, count)
	for _, change := range []func(*extension.RepositoryReviewRequestSnapshot){
		func(p *extension.RepositoryReviewRequestSnapshot) { p.Review.ActorID = "1" }, func(p *extension.RepositoryReviewRequestSnapshot) { p.Review.RepositoryID = "2" }, func(p *extension.RepositoryReviewRequestSnapshot) { p.Review.PullID = "1" }, func(p *extension.RepositoryReviewRequestSnapshot) { p.Review.IssueID = "1" }, func(p *extension.RepositoryReviewRequestSnapshot) { p.Review.Index = "1" }, func(p *extension.RepositoryReviewRequestSnapshot) { p.Review.NativeRevision++ }, func(p *extension.RepositoryReviewRequestSnapshot) { p.Review.HeadOID = fixture.base }, func(p *extension.RepositoryReviewRequestSnapshot) { p.Review.BaseOID = fixture.tip }, func(p *extension.RepositoryReviewRequestSnapshot) { p.Review.MergeBaseOID = fixture.tip }, func(p *extension.RepositoryReviewRequestSnapshot) { p.Requests.Digest = strings.Repeat("0", 64) }, func(p *extension.RepositoryReviewRequestSnapshot) { p.ReviewerID = "999999" }, func(p *extension.RepositoryReviewRequestSnapshot) { p.AddAction.State = "denied" },
	} {
		q = prepare("user", 4)
		change(&q)
		refused(q, true, admit)
	}
	q = prepare("user", 4)
	require.NoError(t, nativeoperation_service.WithAuthorityOwnership(ctx, "advance-review-request-revision", repo.ID, func(context.Context) error { return nil }))
	refused(q, true, admit)
	for _, at := range []int{1, 2, 3} {
		q = prepare("user", 4)
		calls := 0
		refused(q, true, func(tx context.Context) error {
			calls++
			if calls == at {
				fixture.session.uid = 4
			}
			return admit(tx)
		})
		require.Equal(t, at, calls)
		fixture.session.uid = 2
	}
	for _, field := range []string{"head", "base", "archive", "reviewer-access", "team-org", "actor-inactive", "code-unit", "pr-unit"} {
		kind, id := "user", int64(4)
		if field == "team-org" {
			kind, id = "team", team.ID
		}
		q = prepare(kind, id)
		switch field {
		case "head":
			sourceTestGit(t, repo.RepoPath(), nil, "update-ref", pr.GetGitRefName(), fixture.base)
		case "base":
			sourceTestGit(t, repo.RepoPath(), nil, "update-ref", "refs/heads/master", fixture.tip)
		case "archive":
			_, err = db.GetEngine(ctx).ID(repo.ID).Cols("is_archived").Update(&repo_model.Repository{IsArchived: true})
		case "reviewer-access":
			_, err = db.GetEngine(ctx).ID(access.ID).Cols("mode").Update(&access_model.Access{Mode: perm.AccessModeNone})
		case "team-org":
			_, err = db.GetEngine(ctx).ID(team.ID).Cols("org_id").Update(&organization.Team{OrgID: 1})
		case "actor-inactive":
			_, err = db.GetEngine(ctx).ID(2).Cols("is_active").Update(&user_model.User{IsActive: false})
		case "code-unit":
			unit.DisabledRepoUnitsSet([]unit.Type{unit.TypeCode})
		case "pr-unit":
			unit.DisabledRepoUnitsSet([]unit.Type{unit.TypePullRequests})
		}
		require.NoError(t, err)
		refused(q, true, admit)
		unit.DisabledRepoUnitsSet(nil)
		sourceTestGit(t, repo.RepoPath(), nil, "update-ref", pr.GetGitRefName(), fixture.tip)
		sourceTestGit(t, repo.RepoPath(), nil, "update-ref", "refs/heads/master", fixture.base)
		_, err = db.GetEngine(ctx).ID(repo.ID).Cols("is_archived").Update(&repo_model.Repository{})
		require.NoError(t, err)
		_, err = db.GetEngine(ctx).ID(access.ID).Cols("mode").Update(&access_model.Access{Mode: perm.AccessModeRead})
		require.NoError(t, err)
		_, err = db.GetEngine(ctx).ID(team.ID).Cols("org_id").Update(&organization.Team{OrgID: repo.OwnerID})
		require.NoError(t, err)
		_, err = db.GetEngine(ctx).ID(2).Cols("is_active").Update(&user_model.User{IsActive: true})
		require.NoError(t, err)
	}
	// Admission I/O between proofs cannot silently alter selected history.
	q = prepare("user", 4)
	calls := 0
	refused(q, true, func(tx context.Context) error {
		calls++
		if calls == 2 {
			_, err := db.GetEngine(tx).ID(completed.ID).Cols("content").Update(&issues_model.Review{Content: "changed during admission"})
			if err != nil {
				return err
			}
		}
		return admit(tx)
	})
	// SQL aborts and trigger corruption roll back requests and native history,
	// including writes already performed by nested native model functions.
	for _, body := range []string{
		"BEFORE INSERT ON review BEGIN SELECT RAISE(ABORT, 'review-request-primary-abort'); END",
		fmt.Sprintf("AFTER INSERT ON review WHEN NEW.type=%d BEGIN UPDATE review SET content='unexpected old-review corruption' WHERE id=%d; END", issues_model.ReviewTypeRequest, completed.ID),
		fmt.Sprintf("AFTER INSERT ON comment WHEN NEW.type=%d BEGIN UPDATE review SET content='unexpected created-request corruption' WHERE id=NEW.review_id; END", issues_model.CommentTypeReviewRequest),
	} {
		q = prepare("user", 4)
		_, err = db.GetEngine(ctx).Exec("CREATE TRIGGER prepared_review_request_failure " + body)
		require.NoError(t, err)
		refused(q, true, admit)
		_, err = db.GetEngine(ctx).Exec("DROP TRIGGER prepared_review_request_failure")
		require.NoError(t, err)
	}
	commit("user", 4, true)
	commit("user", 4, false)
	operations, err := db.GetEngine(ctx).Where("repository_id=?", repo.ID).Count(new(nativeoperation_model.Operation))
	require.NoError(t, err)
	require.Zero(t, operations)
	held, err := nativeoperation_model.ReadReservation(ctx)
	require.NoError(t, err)
	require.Empty(t, held.Owner)
	t.Log("PASS: actual ownership-required native user/team reviewer desired-state SQL primary; exact request/history/Git proof, official history and draft preservation, complete duplicate removal, no-ops and joined transactions, stale scope/revision/policy/session refusal, outer/SQL/corruption rollback and no journal/transport activation")
}

func runHumanReviewRequestNative(t *testing.T, fixture sourceTestFixture, repo *repo_model.Repository, issue *issues_model.Issue, pr *issues_model.PullRequest, team *organization.Team, completed, teamCompleted, foreign *issues_model.Review) {
	t.Helper()
	ctx := t.Context()
	const installation = "11111111-2222-4333-8444-555555555555"
	svc := nativeoperation_service.NewService()
	notifier := uinotification.NewNotifier()
	notify_service.RegisterNotifier(notifier)
	t.Cleanup(func() { notify_service.UnregisterNotifier(notifier) })
	_, setupErr := db.GetEngine(ctx).Insert(&organization.TeamUser{OrgID: repo.OwnerID, TeamID: team.ID, UID: 4})
	require.NoError(t, setupErr)
	admit := func(tx context.Context) error {
		entry := nativeAdmissions.get(fixture.token)
		if entry == nil {
			return nativeoperation_service.ErrAuthorityLost
		}
		actor, status := resolveCurrentUser(tx, entry)
		if status != http.StatusOK || actor.ID != 2 {
			return nativeoperation_service.ErrAuthorityLost
		}
		return nil
	}
	serial := 0
	prepare := func(kind string, id int64, requested bool) extension.HumanReviewRequestChange {
		t.Helper()
		p, status := resolveReviewRequestSnapshot(ctx, nativeAdmissions.get(fixture.token), extension.CallbackRequest{RepositoryID: strconv.FormatInt(repo.ID, 10), ReviewRequestSnapshot: &extension.RepositoryReviewRequestSnapshotRequest{Index: "2", ReviewerKind: kind, ReviewerID: strconv.FormatInt(id, 10)}})
		require.Equal(t, http.StatusOK, status)
		require.NotNil(t, p)
		serial++
		return extension.HumanReviewRequestChange{OperationID: fmt.Sprintf("human-review-request:native-%d", serial), Expected: *p, Requested: requested, NotAfter: time.Now().Add(5 * time.Minute).Unix()}
	}
	encode := func(v any) string { raw, err := json.Marshal(v); require.NoError(t, err); return string(raw) }
	rows := func() string {
		var reviews []*issues_model.Review
		var comments []*issues_model.Comment
		require.NoError(t, db.GetEngine(ctx).Where("issue_id=?", issue.ID).Asc("id").Find(&reviews))
		require.NoError(t, db.GetEngine(ctx).Where("issue_id=?", issue.ID).Asc("id").Find(&comments))
		return encode(struct {
			Reviews  []*issues_model.Review
			Comments []*issues_model.Comment
		}{reviews, comments})
	}
	notifications := func() string {
		require.NoError(t, queue.GetManager().FlushAll(ctx, 5*time.Second))
		var rows []*activities_model.Notification
		require.NoError(t, db.GetEngine(ctx).Where("issue_id=?", issue.ID).Asc("id").Find(&rows))
		return encode(rows)
	}
	check := func(q extension.HumanReviewRequestChange, record extension.OperationRecord) extension.HumanReviewRequestReceipt {
		t.Helper()
		require.Equal(t, extension.EffectCommitted, record.EffectState)
		var receipt extension.HumanReviewRequestReceipt
		require.NoError(t, json.Unmarshal(record.Receipt, &receipt))
		require.True(t, extension.ValidHumanReviewRequestReceipt(receipt, q))
		evidence, err := nativeoperation_service.ReadHumanReviewRequestEvidence(ctx, issue.ID, receipt.ReviewerKind, receipt.ReviewerID)
		require.NoError(t, err)
		require.Equal(t, receipt.After, evidence)
		op, err := nativeoperation_model.LookupOperation(ctx, installation, q.OperationID)
		require.NoError(t, err)
		require.True(t, op.Admitted)
		require.Zero(t, op.TokenID)
		require.Empty(t, op.CredentialFingerprint)
		canonical, digest, err := extension.CanonicalHumanReviewRequestIntent(q)
		require.NoError(t, err)
		require.Equal(t, canonical, op.Intent)
		require.Equal(t, digest, op.IntentDigest)
		require.Equal(t, string(record.Receipt), op.Receipt)
		_ = notifications()
		_, err = db.GetEngine(ctx).Where("issue_id=? AND user_id=4", issue.ID).Cols("status").NoAutoTime().Update(&activities_model.Notification{Status: activities_model.NotificationStatusRead})
		require.NoError(t, err)
		before, notices := rows(), notifications()
		replay, err := svc.SubmitHumanReviewRequest(ctx, installation, q, admit)
		require.NoError(t, err)
		require.Equal(t, record.Receipt, replay.Receipt)
		require.Equal(t, record.CompletionState, replay.CompletionState)
		changed := q
		changed.Requested = !q.Requested
		_, err = svc.SubmitHumanReviewRequest(ctx, installation, changed, admit)
		require.ErrorIs(t, err, nativeoperation_service.ErrIntentConflict)
		late, err := svc.Cancel(ctx, installation, q.OperationID)
		require.NoError(t, err)
		require.Equal(t, extension.CancellationTooLate, late.CancellationStatus)
		require.Equal(t, record.Receipt, late.Receipt)
		require.Equal(t, before, rows(), "replay/cancel repeated native reviewer work")
		require.Equal(t, notices, notifications(), "replay/cancel repeated native notification work")
		return receipt
	}
	commit := func(kind string, id int64, requested bool) extension.HumanReviewRequestReceipt {
		t.Helper()
		q := prepare(kind, id, requested)
		_ = notifications()
		if requested && len(q.Expected.Requests.RequestIDs) == 0 {
			_, err := db.GetEngine(ctx).Where("issue_id=? AND user_id=4", issue.ID).Cols("status").NoAutoTime().Update(&activities_model.Notification{Status: activities_model.NotificationStatusRead})
			require.NoError(t, err)
		}
		notices := notifications()
		r, err := svc.SubmitHumanReviewRequest(ctx, installation, q, admit)
		require.NoError(t, err)
		require.Equal(t, extension.CompletionComplete, r.CompletionState)
		receipt := check(q, r)
		if receipt.Changed && requested {
			n := &activities_model.Notification{IssueID: issue.ID, UserID: 4}
			exists, err := db.GetEngine(ctx).Get(n)
			require.NoError(t, err)
			require.True(t, exists, "native UI notification was not delivered")
			require.Equal(t, nativeIDForEdit(receipt.HistoryIDs[0]), n.CommentID)
		} else {
			require.Equal(t, notices, notifications(), "no-op/removal changed UI notifications")
		}
		return receipt
	}
	refused := func(q extension.HumanReviewRequestChange, gate nativeoperation_service.HumanReviewAdmission) {
		t.Helper()
		before := rows()
		r, err := svc.SubmitHumanReviewRequest(ctx, installation, q, gate)
		require.NoError(t, err)
		require.Equal(t, extension.EffectNotCommitted, r.EffectState)
		require.Empty(t, r.Receipt)
		require.Equal(t, before, rows())
	}
	recover := func() nativeoperation_service.RecoveryAssessment {
		t.Helper()
		held, err := nativeoperation_model.ReadReservation(ctx)
		require.NoError(t, err)
		require.NotEmpty(t, held.Owner)
		require.NoError(t, os.WriteFile(nativeoperation_model.OfflineMarkerPath(), []byte("synchronous reviewer writer returned; offline recovery\n"), 0o600))
		notices := notifications()
		assessment, err := svc.Recover(ctx, held.Owner, held.Generation)
		require.NoError(t, err)
		require.NoError(t, os.Remove(nativeoperation_model.OfflineMarkerPath()))
		require.Equal(t, notices, notifications(), "recovery repeated native UI notification work")
		return assessment
	}
	for _, subject := range []struct {
		kind string
		id   int64
	}{{"user", 4}, {"team", team.ID}} {
		for _, requested := range []bool{true, true, false, false} {
			commit(subject.kind, subject.id, requested)
		}
	}
	_, err := db.GetEngine(ctx).Insert(&issues_model.Review{IssueID: issue.ID, ReviewerID: 4, Type: issues_model.ReviewTypeRequest}, &issues_model.Review{IssueID: issue.ID, ReviewerID: 4, Type: issues_model.ReviewTypeRequest})
	require.NoError(t, err)
	receipt := commit("user", 4, false)
	require.Len(t, receipt.Before.RequestIDs, 2)
	require.Len(t, receipt.HistoryIDs, 2)
	require.False(t, nativeoperation_model.ValidKind(nativeoperation_model.KindHumanReviewRequest))
	_, err = nativeoperation_service.ValidateIntent("human-review-request:reserved", 2, repo.ID, nativeoperation_model.KindLifecycleNote, "revision", 1, time.Now().Add(time.Minute).Unix(), nil, time.Now().Unix())
	require.ErrorIs(t, err, nativeoperation_service.ErrInvalidIntent)
	q := prepare("user", 4, true)
	_, err = svc.Cancel(ctx, installation, q.OperationID)
	require.NoError(t, err)
	before := rows()
	r, err := svc.SubmitHumanReviewRequest(ctx, installation, q, admit)
	require.ErrorIs(t, err, nativeoperation_service.ErrCancelledBeforeSubmit)
	require.Equal(t, extension.EffectNotCommitted, r.EffectState)
	require.Equal(t, before, rows())
	for _, mutate := range []func(*extension.HumanReviewRequestChange){func(q *extension.HumanReviewRequestChange) { q.NotAfter = 0 }, func(q *extension.HumanReviewRequestChange) { q.NotAfter = 1 }, func(q *extension.HumanReviewRequestChange) { q.NotAfter = time.Now().Add(2 * time.Hour).Unix() }, func(q *extension.HumanReviewRequestChange) { q.Expected.ReviewerID = "0" }, func(q *extension.HumanReviewRequestChange) { q.Expected.AddAction.State = "denied" }} {
		q = prepare("user", 4, true)
		mutate(&q)
		_, err = svc.SubmitHumanReviewRequest(ctx, installation, q, admit)
		require.Error(t, err)
		op, e := nativeoperation_model.LookupOperation(ctx, installation, q.OperationID)
		require.NoError(t, e)
		require.Nil(t, op)
	}
	q = prepare("user", 4, true)
	_, err = svc.SubmitHumanReviewRequest(ctx, "invalid", q, admit)
	require.ErrorIs(t, err, nativeoperation_service.ErrInvalidIntent)
	_, err = svc.SubmitHumanReviewRequest(ctx, installation, q, nil)
	require.ErrorIs(t, err, nativeoperation_service.ErrInvalidIntent)
	require.NoError(t, nativeoperation_service.WithAuthorityOwnership(ctx, "busy-review-request", repo.ID, func(context.Context) error {
		_, err := svc.SubmitHumanReviewRequest(ctx, installation, q, admit)
		require.True(t, nativeoperation_service.IsBusy(err))
		return nil
	}))
	refused(q, admit)
	q = prepare("user", 4, true)
	sourceTestGit(t, repo.RepoPath(), nil, "update-ref", pr.GetGitRefName(), fixture.base)
	refused(q, admit)
	sourceTestGit(t, repo.RepoPath(), nil, "update-ref", pr.GetGitRefName(), fixture.tip)
	q = prepare("user", 4, true)
	q.NotAfter = time.Now().Add(2 * time.Second).Unix()
	calls := 0
	refused(q, func(tx context.Context) error {
		calls++
		if calls == 2 {
			time.Sleep(2 * time.Second)
		}
		return admit(tx)
	})
	for _, at := range []int{2, 3, 4} {
		q = prepare("user", 4, true)
		calls = 0
		before = rows()
		r, err = svc.SubmitHumanReviewRequest(ctx, installation, q, func(tx context.Context) error {
			calls++
			if calls == at {
				fixture.session.uid = 4
			}
			return admit(tx)
		})
		require.ErrorIs(t, err, nativeoperation_service.ErrAuthorityLost)
		require.Empty(t, r.Receipt)
		require.Equal(t, before, rows())
		fixture.session.uid = 2
	}
	q = prepare("user", 4, true)
	calls = 0
	r, err = svc.SubmitHumanReviewRequest(ctx, installation, q, func(tx context.Context) error {
		calls++
		if calls == 5 {
			fixture.session.uid = 4
		}
		return admit(tx)
	})
	require.ErrorIs(t, err, nativeoperation_service.ErrAuthorityLost)
	require.Empty(t, r.Receipt)
	fixture.session.uid = 2
	found, err := svc.Get(ctx, installation, q.OperationID)
	require.NoError(t, err)
	require.NotNil(t, found.Record)
	check(q, *found.Record)
	commit("user", 4, false)
	for _, body := range []string{"BEFORE INSERT ON review BEGIN SELECT RAISE(ABORT, 'review-request-sql-failure'); END", "BEFORE UPDATE OF receipt ON operation WHEN NEW.kind='pull_request.human_review_request.apply' AND NEW.admitted=1 BEGIN SELECT RAISE(ABORT, 'review-request-receipt-failure'); END"} {
		q = prepare("user", 4, true)
		before = rows()
		_, err = db.GetEngine(ctx).Exec("CREATE TRIGGER human_review_request_atomic_failure " + body)
		require.NoError(t, err)
		_, err = svc.SubmitHumanReviewRequest(ctx, installation, q, admit)
		require.Error(t, err)
		_, err = db.GetEngine(ctx).Exec("DROP TRIGGER human_review_request_atomic_failure")
		require.NoError(t, err)
		require.Equal(t, before, rows())
		op, err := nativeoperation_model.LookupOperation(ctx, installation, q.OperationID)
		require.NoError(t, err)
		require.False(t, op.Admitted)
		require.Empty(t, op.Receipt)
		assessment := recover()
		require.Equal(t, nativeoperation_service.RecoveryReleased, assessment.Verdict)
		require.Equal(t, extension.EffectNotCommitted, assessment.Effect)
	}
	// Cancellation is ordered against the actual paused conditional writer.
	q = prepare("user", 4, true)
	point := nativeoperation_service.CrashPointHumanReviewRequestBeforePrimary
	dir := t.TempDir()
	t.Setenv("NATIVEOP_TEST_CRASH_POINT", point)
	t.Setenv("NATIVEOP_TEST_CRASH_BARRIER_DIR", dir)
	t.Setenv("NATIVEOP_TEST_CRASH_TIMEOUT_SECONDS", "10")
	type submitResult struct {
		r   extension.OperationRecord
		err error
	}
	results := make(chan submitResult, 1)
	go func() {
		r, err := svc.SubmitHumanReviewRequest(ctx, installation, q, admit)
		results <- submitResult{r, err}
	}()
	until := time.Now().Add(5 * time.Second)
	for {
		if _, err := os.Stat(filepath.Join(dir, point+".entered")); err == nil {
			break
		}
		require.True(t, time.Now().Before(until))
		time.Sleep(10 * time.Millisecond)
	}
	_, err = svc.Cancel(ctx, installation, q.OperationID)
	require.NoError(t, err)
	require.NoError(t, os.WriteFile(filepath.Join(dir, point+".release"), []byte("release\n"), 0o600))
	cancelled := <-results
	require.NoError(t, cancelled.err)
	require.Equal(t, extension.EffectNotCommitted, cancelled.r.EffectState)
	t.Setenv("NATIVEOP_TEST_CRASH_POINT", "")
	t.Setenv("NATIVEOP_TEST_CRASH_TIMEOUT_SECONDS", "1")
	for _, mode := range []string{"user-add", "user-remove", "user-noop-add", "user-noop-remove", "team-add", "team-remove", "team-noop-add", "team-noop-remove"} {
		kind, id, historyRow := "user", int64(4), completed
		if strings.HasPrefix(mode, "team") {
			kind, id, historyRow = "team", team.ID, teamCompleted
		}
		for _, point := range []string{nativeoperation_service.CrashPointHumanReviewRequestBeforePrimary, nativeoperation_service.CrashPointHumanReviewRequestAfterPrimary} {
			desired := !strings.HasSuffix(mode, "remove")
			initial := !desired
			if strings.Contains(mode, "noop") {
				initial = desired
			}
			commit(kind, id, initial)
			q = prepare(kind, id, desired)
			t.Setenv("NATIVEOP_TEST_CRASH_POINT", point)
			t.Setenv("NATIVEOP_TEST_CRASH_BARRIER_DIR", t.TempDir())
			_, err = svc.SubmitHumanReviewRequest(ctx, installation, q, admit)
			require.Error(t, err)
			t.Setenv("NATIVEOP_TEST_CRASH_POINT", "")
			op, err := nativeoperation_model.LookupOperation(ctx, installation, q.OperationID)
			require.NoError(t, err)
			committed := point == nativeoperation_service.CrashPointHumanReviewRequestAfterPrimary
			require.Equal(t, committed, op.Admitted)
			if committed {
				var receipt extension.HumanReviewRequestReceipt
				require.NoError(t, json.Unmarshal([]byte(op.Receipt), &receipt))
				require.True(t, extension.ValidHumanReviewRequestReceipt(receipt, q))
				for _, field := range []string{"receipt", "receipt-encoding", "intent", "token", "scope", "review-history", "history", "request-evidence"} {
					var restore func()
					switch field {
					case "receipt":
						_, err = db.GetEngine(ctx).ID(op.ID).Cols("receipt").Update(&nativeoperation_model.Operation{Receipt: "{}"})
						restore = func() { _, err = db.GetEngine(ctx).ID(op.ID).Cols("receipt").Update(op) }
					case "receipt-encoding":
						_, err = db.GetEngine(ctx).ID(op.ID).Cols("receipt").Update(&nativeoperation_model.Operation{Receipt: op.Receipt + " "})
						restore = func() { _, err = db.GetEngine(ctx).ID(op.ID).Cols("receipt").Update(op) }
					case "intent":
						_, err = db.GetEngine(ctx).ID(op.ID).Cols("intent").Update(&nativeoperation_model.Operation{Intent: op.Intent + " "})
						restore = func() { _, err = db.GetEngine(ctx).ID(op.ID).Cols("intent").Update(op) }
					case "token":
						_, err = db.GetEngine(ctx).ID(op.ID).Cols("token_id").Update(&nativeoperation_model.Operation{TokenID: 99})
						restore = func() { _, err = db.GetEngine(ctx).ID(op.ID).Cols("token_id").Update(op) }
					case "scope":
						held, e := nativeoperation_model.ReadReservation(ctx)
						require.NoError(t, e)
						var scope nativeoperation_service.Scope
						require.NoError(t, json.Unmarshal([]byte(held.Scope), &scope))
						scope.IssueID++
						_, err = db.GetEngine(ctx).ID(1).Cols("scope").Update(&nativeoperation_model.Reservation{Scope: encode(scope)})
						restore = func() { _, err = db.GetEngine(ctx).ID(1).Cols("scope").Update(held) }
					case "review-history":
						saved, e := issues_model.GetReviewByID(ctx, historyRow.ID)
						require.NoError(t, e)
						_, err = db.GetEngine(ctx).NoAutoTime().ID(saved.ID).Cols("content").Update(&issues_model.Review{Content: "changed historical proof"})
						restore = func() { _, err = db.GetEngine(ctx).NoAutoTime().ID(saved.ID).Cols("content").Update(saved) }
					case "history":
						if len(receipt.HistoryIDs) == 0 {
							continue
						}
						saved, e := issues_model.GetCommentByID(ctx, nativeIDForEdit(receipt.HistoryIDs[0]))
						require.NoError(t, e)
						_, err = db.GetEngine(ctx).Exec("UPDATE comment SET updated_unix=? WHERE id=?", saved.UpdatedUnix+100, saved.ID)
						restore = func() {
							_, err = db.GetEngine(ctx).Exec("UPDATE comment SET updated_unix=? WHERE id=?", saved.UpdatedUnix, saved.ID)
						}
					case "request-evidence":
						if len(receipt.After.RequestIDs) == 0 {
							continue
						}
						saved, e := issues_model.GetReviewByID(ctx, nativeIDForEdit(receipt.After.RequestIDs[0]))
						require.NoError(t, e)
						_, err = db.GetEngine(ctx).NoAutoTime().ID(saved.ID).Cols("official").Update(&issues_model.Review{Official: !saved.Official})
						restore = func() { _, err = db.GetEngine(ctx).NoAutoTime().ID(saved.ID).Cols("official").Update(saved) }
					}
					require.NoError(t, err)
					before = rows()
					assessment := recover()
					require.Equal(t, nativeoperation_service.RecoveryFenced, assessment.Verdict, "mode=%s field=%s", mode, field)
					require.Equal(t, before, rows())
					restore()
					require.NoError(t, err)
				}
			} else {
				_, err = db.GetEngine(ctx).ID(op.ID).Cols("receipt").Update(&nativeoperation_model.Operation{Receipt: "{}"})
				require.NoError(t, err)
				assessment := recover()
				require.Equal(t, nativeoperation_service.RecoveryFenced, assessment.Verdict)
				_, err = db.GetEngine(ctx).ID(op.ID).Cols("receipt").Update(op)
				require.NoError(t, err)
			}
			before = rows()
			assessment := recover()
			require.Equal(t, nativeoperation_service.RecoveryReleased, assessment.Verdict, "%+v", assessment)
			require.Equal(t, before, rows(), "recovery replayed reviewer SQL/history")
			if committed {
				lookup, err := svc.Get(ctx, installation, q.OperationID)
				require.NoError(t, err)
				require.Equal(t, []byte(op.Receipt), []byte(lookup.Record.Receipt))
				completion := extension.CompletionComplete
				if !strings.Contains(mode, "noop") && (kind == "user" || desired) {
					completion = extension.CompletionNeedsIntervention
				}
				require.Equal(t, completion, lookup.Record.CompletionState)
				check(q, *lookup.Record)
			} else {
				require.Equal(t, extension.EffectNotCommitted, assessment.Effect)
			}
		}
	}
	// Full pending-draft metadata remains part of user history proof.
	retained, err := issues_model.GetReviewByID(ctx, foreign.ID)
	require.NoError(t, err)
	require.Equal(t, foreign.Content, retained.Content)
	held, err := nativeoperation_model.ReadReservation(ctx)
	require.NoError(t, err)
	require.Empty(t, held.Owner)
	t.Log("PASS: actual human reviewer native journal and atomic exact receipts; user/team add/remove/no-op/duplicate effects, replay/cancel/expiry/current admission, native completion, primary/receipt SQL rollback, stopped-writer before/after SQL recovery and altered-evidence fences without mutation or notification replay; owned-process death remains a later gate")
}

func runReviewRequestSnapshot(t *testing.T, fixture sourceTestFixture, repo *repo_model.Repository, issue *issues_model.Issue, pr *issues_model.PullRequest, probe string) {
	t.Helper()
	ctx := t.Context()
	reviewerAccess := &access_model.Access{RepoID: repo.ID, UserID: 4, Mode: perm.AccessModeRead}
	reviewerCollab := &repo_model.Collaboration{RepoID: repo.ID, UserID: 4, Mode: perm.AccessModeRead}
	team := &organization.Team{OrgID: repo.OwnerID, Name: "review-request-team", LowerName: "review-request-team", AccessMode: perm.AccessModeRead}
	foreignTeam := &organization.Team{OrgID: 1, Name: "foreign-review-request-team", LowerName: "foreign-review-request-team", AccessMode: perm.AccessModeRead}
	_, err := db.GetEngine(ctx).Insert(reviewerAccess, reviewerCollab, team, foreignTeam)
	require.NoError(t, err)
	teamRepo := &organization.TeamRepo{OrgID: repo.OwnerID, TeamID: team.ID, RepoID: repo.ID}
	_, err = db.GetEngine(ctx).Insert(teamRepo)
	require.NoError(t, err)
	foreignDraft := &issues_model.Review{IssueID: issue.ID, ReviewerID: 4, Type: issues_model.ReviewTypePending, Content: "review request foreign private draft", CommitID: fixture.tip}
	ownDraft := &issues_model.Review{IssueID: issue.ID, ReviewerID: 2, Type: issues_model.ReviewTypePending, Content: "review request own private draft", CommitID: fixture.base}
	_, err = db.GetEngine(ctx).Insert(foreignDraft, ownDraft)
	require.NoError(t, err)
	require.NoError(t, nativeoperation_service.WithAuthorityOwnership(ctx, "review-request-preparation-fixture", repo.ID, func(context.Context) error { return nil }))
	root := shortWitnessRoot(t)
	socket := filepath.Join(root, "r")
	listener, err := net.Listen("unix", socket)
	require.NoError(t, err)
	server := &http.Server{Handler: CallbackHandlerForInstance("source-test")}
	go func() { _ = server.Serve(listener) }()
	t.Cleanup(func() { _ = server.Close() })
	userRequest := &issues_model.Review{IssueID: issue.ID, ReviewerID: 4, Type: issues_model.ReviewTypeRequest, Official: true, Content: "retained request metadata 完整\r\n", CreatedUnix: 3, UpdatedUnix: 4}
	teamRequest := &issues_model.Review{IssueID: issue.ID, ReviewerTeamID: team.ID, Type: issues_model.ReviewTypeRequest, Official: true, CreatedUnix: 3, UpdatedUnix: 4}
	run := func(mode string) {
		t.Helper()
		var selected []string
		for _, row := range []*issues_model.Review{userRequest, teamRequest} {
			if row.ID > 0 {
				selected = append(selected, strconv.FormatInt(row.ID, 10))
			} else {
				selected = append(selected, "")
			}
		}
		binding, err := json.Marshal(struct {
			Authority                                                                 extension.Authority
			Admission, Socket, Repository, Pull, Issue, Base, Head, Team, ForeignTeam string
			Requests                                                                  []string
		}{fixture.authority, fixture.token, socket, strconv.FormatInt(repo.ID, 10), strconv.FormatInt(pr.ID, 10), strconv.FormatInt(issue.ID, 10), fixture.base, fixture.tip, strconv.FormatInt(team.ID, 10), strconv.FormatInt(foreignTeam.ID, 10), selected})
		require.NoError(t, err)
		path := filepath.Join(root, "review-request.json")
		require.NoError(t, os.WriteFile(path, binding, 0o600))
		var before, after [3]int64
		for i, row := range []any{new(issues_model.Review), new(issues_model.Comment), new(nativeoperation_model.Operation)} {
			before[i], err = db.GetEngine(ctx).Count(row)
			require.NoError(t, err)
		}
		command := exec.CommandContext(ctx, probe, mode)
		command.Env = append(os.Environ(), "SODA_FOUNTAIN_READ_BINDING="+path)
		out, err := command.CombinedOutput()
		require.NotContains(t, string(out), fixture.token)
		t.Log(string(out))
		require.NoError(t, err, "review request phase %s", mode)
		for i, row := range []any{new(issues_model.Review), new(issues_model.Comment), new(nativeoperation_model.Operation)} {
			after[i], err = db.GetEngine(ctx).Count(row)
			require.NoError(t, err)
		}
		require.Equal(t, before, after, "review request preparation allocated native rows")
	}
	readRows := func() string {
		var rows []*issues_model.Review
		require.NoError(t, db.GetEngine(ctx).Where("issue_id=?", issue.ID).Asc("id").Find(&rows))
		raw, err := json.Marshal(rows)
		require.NoError(t, err)
		return string(raw)
	}
	before := readRows()
	revision, err := nativeoperation_service.Default().ReadNativeRevision(ctx)
	require.NoError(t, err)
	run("empty")
	require.Equal(t, before, readRows())
	afterRevision, err := nativeoperation_service.Default().ReadNativeRevision(ctx)
	require.NoError(t, err)
	require.Equal(t, revision, afterRevision, "preparation claimed native ownership")
	_, err = db.GetEngine(ctx).Insert(userRequest, teamRequest)
	require.NoError(t, err)
	before = readRows()
	run("requested")
	run("invalid")
	require.Equal(t, before, readRows())
	_, err = db.GetEngine(ctx).ID(repo.ID).Cols("is_archived").Update(&repo_model.Repository{IsArchived: true})
	require.NoError(t, err)
	run("archived")
	_, err = db.GetEngine(ctx).ID(repo.ID).Cols("is_archived").Update(&repo_model.Repository{})
	require.NoError(t, err)
	_, err = db.GetEngine(ctx).Where("repo_id=? AND user_id=2", repo.ID).Delete(new(repo_model.Collaboration))
	require.NoError(t, err)
	_, err = db.GetEngine(ctx).ID(repo.ID).Cols("is_private").Update(&repo_model.Repository{IsPrivate: false})
	require.NoError(t, err)
	run("reader-policy")
	selfRequest := &issues_model.Review{IssueID: issue.ID, ReviewerID: 2, Type: issues_model.ReviewTypeRequest}
	_, err = db.GetEngine(ctx).Insert(selfRequest)
	require.NoError(t, err)
	run("self-removal")
	_, err = db.GetEngine(ctx).ID(selfRequest.ID).Delete(new(issues_model.Review))
	require.NoError(t, err)
	_, err = db.GetEngine(ctx).Insert(&repo_model.Collaboration{RepoID: repo.ID, UserID: 2, Mode: perm.AccessModeRead})
	require.NoError(t, err)
	_, err = db.GetEngine(ctx).ID(repo.ID).Cols("is_private").Update(&repo_model.Repository{IsPrivate: true})
	require.NoError(t, err)
	_, err = db.GetEngine(ctx).ID(teamRepo.ID).Delete(new(organization.TeamRepo))
	require.NoError(t, err)
	run("team-no-access")
	_, err = db.GetEngine(ctx).Insert(teamRepo)
	require.NoError(t, err)
	_, err = db.GetEngine(ctx).ID(issue.ID).Cols("is_closed").Update(&issues_model.Issue{IsClosed: true})
	require.NoError(t, err)
	run("closed-requested")
	_, err = db.GetEngine(ctx).NoAutoTime().ID(userRequest.ID).Cols("type").Update(&issues_model.Review{Type: issues_model.ReviewTypeApprove})
	require.NoError(t, err)
	run("closed-completed")
	_, err = db.GetEngine(ctx).NoAutoTime().ID(userRequest.ID).Cols("type").Update(&issues_model.Review{Type: issues_model.ReviewTypeRequest})
	require.NoError(t, err)
	_, err = db.GetEngine(ctx).ID(issue.ID).Cols("is_closed").Update(&issues_model.Issue{})
	require.NoError(t, err)
	// Exact record/byte limits refuse incomplete evidence instead of truncating.
	var excess []*issues_model.Review
	for range extension.MaxReviewRequestSnapshotRecords - 1 {
		excess = append(excess, &issues_model.Review{IssueID: issue.ID, ReviewerID: 4, Type: issues_model.ReviewTypeRequest})
	}
	_, err = db.GetEngine(ctx).Insert(excess)
	require.NoError(t, err)
	run("record-limit")
	extra := &issues_model.Review{IssueID: issue.ID, ReviewerID: 4, Type: issues_model.ReviewTypeRequest}
	_, err = db.GetEngine(ctx).Insert(extra)
	require.NoError(t, err)
	run("too-large")
	_, err = db.GetEngine(ctx).Where("issue_id=? AND reviewer_id=4 AND id<>? AND type=?", issue.ID, userRequest.ID, issues_model.ReviewTypeRequest).Delete(new(issues_model.Review))
	require.NoError(t, err)
	_, err = db.GetEngine(ctx).NoAutoTime().ID(userRequest.ID).Cols("content").Update(&issues_model.Review{Content: strings.Repeat("x", extension.MaxReviewRequestSnapshotBodyBytes)})
	require.NoError(t, err)
	run("byte-limit")
	_, err = db.GetEngine(ctx).NoAutoTime().ID(userRequest.ID).Cols("content").Update(&issues_model.Review{Content: strings.Repeat("x", extension.MaxReviewRequestSnapshotBodyBytes+1)})
	require.NoError(t, err)
	run("too-large")
	_, err = db.GetEngine(ctx).NoAutoTime().ID(userRequest.ID).Cols("content").Update(&issues_model.Review{Content: string([]byte{0xff})})
	require.NoError(t, err)
	run("unavailable")
	_, err = db.GetEngine(ctx).NoAutoTime().ID(userRequest.ID).Cols("content").Update(&issues_model.Review{Content: userRequest.Content})
	require.NoError(t, err)
	require.NoError(t, nativeoperation_service.WithAuthorityOwnership(ctx, "review-request-busy", repo.ID, func(context.Context) error { run("unavailable"); return nil }))
	for _, race := range []string{"request", "prose", "head", "base", "private-source", "reviewer-access", "team-access", "archive", "revision", "actor", "final-actor"} {
		start, changed := fixture.session.reads, false
		at := start + 5 // first current-human check in the second observation
		if race == "final-actor" {
			at = start + 9 // final live-human check after both observations
		}
		fixture.session.onRead = func(n int) {
			if n != at {
				return
			}
			changed = true
			switch race {
			case "request":
				_, err = db.GetEngine(ctx).NoAutoTime().ID(userRequest.ID).Cols("official").Update(&issues_model.Review{Official: false})
			case "prose":
				_, err = db.GetEngine(ctx).NoAutoTime().ID(userRequest.ID).Cols("content").Update(&issues_model.Review{Content: "Changed retained request metadata"})
			case "head":
				sourceTestGit(t, repo.RepoPath(), nil, "update-ref", pr.GetGitRefName(), fixture.base)
			case "base":
				sourceTestGit(t, repo.RepoPath(), nil, "update-ref", "refs/heads/master", fixture.tip)
			case "private-source":
				_, err = db.GetEngine(ctx).ID(pr.ID).Cols("head_branch").Update(&issues_model.PullRequest{HeadBranch: "changed-review-request-private-source"})
			case "reviewer-access":
				_, err = db.GetEngine(ctx).ID(reviewerAccess.ID).Cols("mode").Update(&access_model.Access{Mode: perm.AccessModeNone})
			case "team-access":
				_, err = db.GetEngine(ctx).ID(teamRepo.ID).Delete(new(organization.TeamRepo))
			case "archive":
				_, err = db.GetEngine(ctx).ID(repo.ID).Cols("is_archived").Update(&repo_model.Repository{IsArchived: true})
			case "revision":
				err = nativeoperation_service.WithAuthorityOwnership(ctx, "review-request-race", repo.ID, func(context.Context) error { return nil })
			case "actor", "final-actor":
				fixture.session.uid = 4
			}
			require.NoError(t, err)
		}
		mode := "changed"
		if race == "team-access" {
			mode = "changed-team"
		} else if race == "actor" || race == "final-actor" {
			mode = "actor-race"
		}
		run(mode)
		require.True(t, changed, "review request race %s did not run", race)
		fixture.session.onRead = nil
		fixture.session.uid = 2
		sourceTestGit(t, repo.RepoPath(), nil, "update-ref", pr.GetGitRefName(), fixture.tip)
		sourceTestGit(t, repo.RepoPath(), nil, "update-ref", "refs/heads/master", fixture.base)
		_, err = db.GetEngine(ctx).ID(pr.ID).Cols("head_branch").Update(&issues_model.PullRequest{HeadBranch: pr.HeadBranch})
		require.NoError(t, err)
		_, err = db.GetEngine(ctx).ID(reviewerAccess.ID).Cols("mode").Update(&access_model.Access{Mode: perm.AccessModeRead})
		require.NoError(t, err)
		_, err = db.GetEngine(ctx).ID(repo.ID).Cols("is_archived").Update(&repo_model.Repository{})
		require.NoError(t, err)
		_, err = db.GetEngine(ctx).NoAutoTime().ID(userRequest.ID).Cols("official", "content").Update(&issues_model.Review{Official: true, Content: userRequest.Content})
		require.NoError(t, err)
		if race == "team-access" {
			_, err = db.GetEngine(ctx).Insert(teamRepo)
			require.NoError(t, err)
		}
	}
	entry := nativeAdmissions.get(fixture.token)
	delete(entry.capabilities, extension.CapabilityRepositoryRead)
	run("refused")
	entry.capabilities[extension.CapabilityRepositoryRead] = struct{}{}
	run("requested")
	t.Log("PASS: actual review-request SDK/private callback and native SQL/Git; separate user/team selection, exact complete request evidence, native add/remove policy and closed/no-op distinctions, draft/private-source privacy, bounds, held ownership, changed records/Git/policy/revision/session refusal and no read effects")
}

func runReviewSnapshot(t *testing.T, fixture sourceTestFixture, probe string) {
	t.Helper()
	ctx := t.Context()
	owner := unittest.AssertExistsAndLoadBean(t, &user_model.User{ID: 1})
	if os.Getenv("SODA_FOUNTAIN_REVIEW_REQUEST_SDK_PROBE") != "" || os.Getenv("SODA_FOUNTAIN_REVIEW_REQUEST_SNAPSHOT_PROBE") != "" || (os.Getenv("SODA_FOUNTAIN_REVIEW_REQUEST_PRIMARY") == "1" || os.Getenv("SODA_FOUNTAIN_REVIEW_REQUEST_NATIVE") == "1") {
		owner = &user_model.User{Name: "review-request-org", LowerName: "review-request-org", Type: user_model.UserTypeOrganization, IsActive: true}
		_, err := db.GetEngine(ctx).Insert(owner)
		require.NoError(t, err)
	}
	repo := &repo_model.Repository{OwnerID: owner.ID, OwnerName: owner.Name, Name: "human-review-preparation", LowerName: "human-review-preparation", IsPrivate: true}
	_, err := db.GetEngine(ctx).Insert(repo)
	require.NoError(t, err)
	units := map[unit.Type]*repo_model.RepoUnit{}
	for _, kind := range []unit.Type{unit.TypeCode, unit.TypePullRequests} {
		row := &repo_model.RepoUnit{RepoID: repo.ID, Type: kind}
		_, err = db.GetEngine(ctx).Insert(row)
		require.NoError(t, err)
		units[kind] = row
	}
	access := &access_model.Access{RepoID: repo.ID, UserID: 2, Mode: perm.AccessModeRead}
	collab := &repo_model.Collaboration{RepoID: repo.ID, UserID: 2, Mode: perm.AccessModeRead}
	_, err = db.GetEngine(ctx).Insert(access, collab)
	require.NoError(t, err)
	issue := &issues_model.Issue{RepoID: repo.ID, Index: 2, PosterID: 1, IsPull: true, Title: "review preparation"}
	_, err = db.GetEngine(ctx).Insert(issue)
	require.NoError(t, err)
	otherIssue := &issues_model.Issue{RepoID: repo.ID, Index: 1, PosterID: 1, Title: "other review parent"}
	_, err = db.GetEngine(ctx).Insert(otherIssue)
	require.NoError(t, err)
	// The base repository's hidden PR ref is reviewable even when the source
	// fork is private/unreadable. Its ID and branch must not leak through prep.
	pr := &issues_model.PullRequest{IssueID: issue.ID, Index: 2, BaseRepoID: repo.ID, HeadRepoID: 6, BaseBranch: "master", HeadBranch: "private-head-preparation-secret", MergeBase: fixture.tip}
	_, err = db.GetEngine(ctx).Insert(pr)
	require.NoError(t, err)
	require.NotEqual(t, pr.ID, issue.ID)
	require.NoError(t, os.MkdirAll(filepath.Dir(repo.RepoPath()), 0o755))
	sourceTestGit(t, fixture.work, nil, "clone", "--bare", fixture.work, repo.RepoPath())
	sourceTestGit(t, repo.RepoPath(), nil, "update-ref", "refs/heads/master", fixture.base)
	sourceTestGit(t, repo.RepoPath(), nil, "update-ref", pr.GetGitRefName(), fixture.tip)
	if os.Getenv("SODA_FOUNTAIN_REVIEW_REQUEST_PRIMARY") == "1" || os.Getenv("SODA_FOUNTAIN_REVIEW_REQUEST_NATIVE") == "1" {
		runPreparedHumanReviewRequestPrimary(t, fixture, repo, issue, pr)
		return
	}
	if probe := os.Getenv("SODA_FOUNTAIN_REVIEW_REQUEST_SDK_PROBE"); probe != "" {
		runHumanReviewSDK(t, fixture, repo, issue, pr, probe)
		return
	}

	if probe := os.Getenv("SODA_FOUNTAIN_REVIEW_REQUEST_SNAPSHOT_PROBE"); probe != "" {
		runReviewRequestSnapshot(t, fixture, repo, issue, pr, probe)
		return
	}
	if inlineProbe := os.Getenv("SODA_FOUNTAIN_INLINE_SNAPSHOT_PROBE"); os.Getenv("SODA_FOUNTAIN_THREAD_SDK_PROBE") != "" || os.Getenv("SODA_FOUNTAIN_THREAD_NATIVE") == "1" || os.Getenv("SODA_FOUNTAIN_THREAD_PRIMARY") == "1" || os.Getenv("SODA_FOUNTAIN_THREAD_SNAPSHOT_PROBE") != "" || inlineProbe != "" || os.Getenv("SODA_FOUNTAIN_INLINE_PRIMARY") == "1" || os.Getenv("SODA_FOUNTAIN_INLINE_GROUPS") == "1" || os.Getenv("SODA_FOUNTAIN_INLINE_NATIVE") == "1" || os.Getenv("SODA_FOUNTAIN_INLINE_SDK_PROBE") != "" {
		runInlineSnapshot(t, fixture, repo, issue, pr, inlineProbe)
		return
	}
	if probe := os.Getenv("SODA_FOUNTAIN_HUMAN_REVIEW_SDK_PROBE"); probe != "" {
		runHumanReviewSDK(t, fixture, repo, issue, pr, probe)
		return
	}
	if os.Getenv("SODA_FOUNTAIN_HUMAN_REVIEW_NATIVE") == "1" {
		runHumanReviewNative(t, fixture, repo, issue, pr)
		return
	}
	if os.Getenv("SODA_FOUNTAIN_HUMAN_REVIEW_PRIMARY") == "1" {
		runPreparedHumanReviewPrimary(t, fixture, repo, issue, pr)
		return
	}
	require.NoError(t, nativeoperation_service.WithAuthorityOwnership(ctx, "review-preparation-fixture", repo.ID, func(context.Context) error { return nil }))
	root := shortWitnessRoot(t)
	socket := filepath.Join(root, "r")
	listener, err := net.Listen("unix", socket)
	require.NoError(t, err)
	server := &http.Server{Handler: CallbackHandlerForInstance("source-test")}
	go func() { _ = server.Serve(listener) }()
	t.Cleanup(func() { _ = server.Close() })
	var own *issues_model.Review
	counts := func() [3]int64 {
		var result [3]int64
		for i, row := range []any{new(issues_model.Review), new(issues_model.Comment), new(nativeoperation_model.Operation)} {
			result[i], err = db.GetEngine(ctx).Count(row)
			require.NoError(t, err)
		}
		return result
	}
	run := func(mode string) {
		t.Helper()
		pending := ""
		if own != nil {
			pending = strconv.FormatInt(own.ID, 10)
		}
		binding, err := json.Marshal(struct {
			Authority                                                       extension.Authority
			Admission, Socket, Repository, Pull, Issue, Base, Head, Pending string
		}{fixture.authority, fixture.token, socket, strconv.FormatInt(repo.ID, 10), strconv.FormatInt(pr.ID, 10), strconv.FormatInt(issue.ID, 10), fixture.base, fixture.tip, pending})
		require.NoError(t, err)
		path := filepath.Join(root, "review.json")
		require.NoError(t, os.WriteFile(path, binding, 0o600))
		before := counts()
		command := exec.CommandContext(ctx, probe, mode)
		command.Env = append(os.Environ(), "SODA_FOUNTAIN_READ_BINDING="+path)
		out, err := command.CombinedOutput()
		require.NotContains(t, string(out), fixture.token)
		t.Log(string(out))
		require.NoError(t, err)
		if mode == "changed-draft" {
			// The fixture itself inserts one draft during this race.
			before[0]++
		}
		require.Equal(t, before, counts(), "review preparation allocated native rows")
	}
	run("reader")
	for _, row := range []any{&access_model.Access{Mode: perm.AccessModeWrite}, &repo_model.Collaboration{Mode: perm.AccessModeWrite}} {
		_, err = db.GetEngine(ctx).Where("repo_id=? AND user_id=?", repo.ID, 2).Cols("mode").Update(row)
		require.NoError(t, err)
	}
	run("writer")
	_, err = db.GetEngine(ctx).ID(issue.ID).Cols("poster_id").Update(&issues_model.Issue{PosterID: 2})
	require.NoError(t, err)
	run("self")
	_, err = db.GetEngine(ctx).ID(issue.ID).Cols("original_author_id").Update(&issues_model.Issue{OriginalAuthorID: 12345})
	require.NoError(t, err)
	run("imported-poster")
	_, err = db.GetEngine(ctx).ID(issue.ID).Cols("poster_id", "original_author_id").Update(&issues_model.Issue{PosterID: 1})
	require.NoError(t, err)
	_, err = db.GetEngine(ctx).ID(issue.ID).Cols("is_locked").Update(&issues_model.Issue{IsLocked: true})
	require.NoError(t, err)
	run("locked")
	_, err = db.GetEngine(ctx).ID(issue.ID).Cols("is_locked").Update(&issues_model.Issue{})
	require.NoError(t, err)
	_, err = db.GetEngine(ctx).ID(issue.ID).Cols("is_closed").Update(&issues_model.Issue{IsClosed: true})
	require.NoError(t, err)
	run("closed")
	_, err = db.GetEngine(ctx).ID(pr.ID).Cols("has_merged").Update(&issues_model.PullRequest{HasMerged: true})
	require.NoError(t, err)
	run("merged")
	_, err = db.GetEngine(ctx).ID(issue.ID).Cols("is_closed").Update(&issues_model.Issue{})
	require.NoError(t, err)
	_, err = db.GetEngine(ctx).ID(pr.ID).Cols("has_merged").Update(&issues_model.PullRequest{})
	require.NoError(t, err)
	foreign := &issues_model.Review{IssueID: issue.ID, ReviewerID: 4, Type: issues_model.ReviewTypePending, CommitID: fixture.tip, Content: "foreign-private-draft"}
	_, err = db.GetEngine(ctx).Insert(foreign)
	require.NoError(t, err)
	run("foreign-draft")
	own = &issues_model.Review{IssueID: issue.ID, ReviewerID: 2, Type: issues_model.ReviewTypePending, CommitID: fixture.base, Content: "own-private-draft"}
	_, err = db.GetEngine(ctx).Insert(own)
	require.NoError(t, err)
	run("own-draft")
	_, err = db.GetEngine(ctx).ID(own.ID).Delete(new(issues_model.Review))
	require.NoError(t, err)
	own = nil
	block := &user_model.BlockedUser{UserID: 1, BlockID: 2}
	_, err = db.GetEngine(ctx).Insert(block)
	require.NoError(t, err)
	run("blocked")
	_, err = db.GetEngine(ctx).ID(block.ID).Delete(new(user_model.BlockedUser))
	require.NoError(t, err)
	_, err = db.GetEngine(ctx).ID(repo.ID).Cols("is_archived").Update(&repo_model.Repository{IsArchived: true})
	require.NoError(t, err)
	run("archived")
	_, err = db.GetEngine(ctx).ID(repo.ID).Cols("is_archived").Update(&repo_model.Repository{})
	require.NoError(t, err)
	disabled := append([]unit.Type(nil), unit.DisabledRepoUnitsGet()...)
	t.Cleanup(func() { unit.DisabledRepoUnitsSet(disabled) })
	for _, kind := range []unit.Type{unit.TypeCode, unit.TypePullRequests} {
		unit.DisabledRepoUnitsSet(append(append([]unit.Type(nil), disabled...), kind))
		run("missing")
		unit.DisabledRepoUnitsSet(disabled)
	}
	for _, kind := range []unit.Type{unit.TypeCode, unit.TypePullRequests} {
		_, err = db.GetEngine(ctx).ID(units[kind].ID).Delete(new(repo_model.RepoUnit))
		require.NoError(t, err)
		run("missing")
		_, err = db.GetEngine(ctx).Insert(units[kind])
		require.NoError(t, err)
	}
	setPermission := func(mode perm.AccessMode) {
		for _, row := range []any{&access_model.Access{Mode: mode}, &repo_model.Collaboration{Mode: mode}} {
			_, err = db.GetEngine(ctx).Where("repo_id=? AND user_id=?", repo.ID, 2).Cols("mode").Update(row)
			require.NoError(t, err)
		}
	}
	setPermission(perm.AccessModeNone)
	run("missing")
	setPermission(perm.AccessModeRead)
	sourceTestGit(t, repo.RepoPath(), nil, "update-ref", "-d", pr.GetGitRefName())
	run("unavailable")
	sourceTestGit(t, repo.RepoPath(), nil, "update-ref", pr.GetGitRefName(), fixture.tip)
	require.NoError(t, nativeoperation_service.WithAuthorityOwnership(ctx, "review-preparation-fixture", repo.ID, func(context.Context) error { run("unavailable"); return nil }))
	for _, race := range []string{"head", "base", "draft", "parent", "private-source", "author", "archive", "block", "permission", "unit", "revision", "actor"} {
		start := fixture.session.reads
		changed := false
		fixture.session.onRead = func(n int) {
			if n != start+4 {
				return
			}
			changed = true
			switch race {
			case "head":
				sourceTestGit(t, repo.RepoPath(), nil, "update-ref", pr.GetGitRefName(), fixture.base)
			case "base":
				sourceTestGit(t, repo.RepoPath(), nil, "update-ref", "refs/heads/master", fixture.tip)
			case "draft":
				own = &issues_model.Review{IssueID: issue.ID, ReviewerID: 2, Type: issues_model.ReviewTypePending, CommitID: fixture.base}
				_, err = db.GetEngine(ctx).Insert(own)
			case "parent":
				_, err = db.GetEngine(ctx).ID(pr.ID).Cols("issue_id").Update(&issues_model.PullRequest{IssueID: otherIssue.ID})
			case "private-source":
				_, err = db.GetEngine(ctx).ID(pr.ID).Cols("head_branch").Update(&issues_model.PullRequest{HeadBranch: "changed-private-source-secret"})
			case "author":
				_, err = db.GetEngine(ctx).ID(issue.ID).Cols("poster_id").Update(&issues_model.Issue{PosterID: 2})
			case "archive":
				_, err = db.GetEngine(ctx).ID(repo.ID).Cols("is_archived").Update(&repo_model.Repository{IsArchived: true})
			case "block":
				block.ID = 0
				_, err = db.GetEngine(ctx).Insert(block)
			case "permission":
				setPermission(perm.AccessModeNone)
			case "unit":
				_, err = db.GetEngine(ctx).ID(units[unit.TypePullRequests].ID).Delete(new(repo_model.RepoUnit))
			case "revision":
				err = nativeoperation_service.WithAuthorityOwnership(ctx, "review-preparation-race", repo.ID, func(context.Context) error { return nil })
			case "actor":
				fixture.session.uid = 4
			}
			require.NoError(t, err)
		}
		mode := "changed"
		if race == "parent" {
			mode = "unavailable"
		}
		if race == "actor" {
			mode = "actor-race"
		}
		if race == "draft" {
			mode = "changed-draft"
		}
		run(mode)
		require.True(t, changed, "review race did not run")
		fixture.session.onRead = nil
		fixture.session.uid = 2
		sourceTestGit(t, repo.RepoPath(), nil, "update-ref", pr.GetGitRefName(), fixture.tip)
		sourceTestGit(t, repo.RepoPath(), nil, "update-ref", "refs/heads/master", fixture.base)
		_, err = db.GetEngine(ctx).ID(pr.ID).Cols("issue_id", "head_branch").Update(&issues_model.PullRequest{IssueID: issue.ID, HeadBranch: pr.HeadBranch})
		require.NoError(t, err)
		_, err = db.GetEngine(ctx).ID(issue.ID).Cols("poster_id").Update(&issues_model.Issue{PosterID: 1})
		require.NoError(t, err)
		_, err = db.GetEngine(ctx).ID(repo.ID).Cols("is_archived").Update(&repo_model.Repository{})
		require.NoError(t, err)
		if own != nil {
			_, err = db.GetEngine(ctx).ID(own.ID).Delete(new(issues_model.Review))
			require.NoError(t, err)
			own = nil
		}
		if race == "block" {
			_, err = db.GetEngine(ctx).ID(block.ID).Delete(new(user_model.BlockedUser))
			require.NoError(t, err)
		}
		if race == "unit" {
			_, err = db.GetEngine(ctx).Insert(units[unit.TypePullRequests])
			require.NoError(t, err)
		}
		setPermission(perm.AccessModeRead)
	}
	entry := nativeAdmissions.get(fixture.token)
	delete(entry.capabilities, extension.CapabilityRepositoryRead)
	run("refused")
	entry.capabilities[extension.CapabilityRepositoryRead] = struct{}{}
	run("reader")
	t.Log("PASS: actual SDK/private callback human review preparation, exact PR/issue and live Git head/base/derived merge-base, own draft privacy, native reader/self/imported/block/archive policy, private source without leakage, Git/draft/identity/permission/revision/session races and no read effects")
}

const humanMergeProcessInstallation = "11111111-1111-4111-8111-111111111111"

const (
	humanMergeProcessBeforeAdmission = "human-merge-hook-before-admission"
	humanMergeProcessAfterAdmission  = "human-merge-hook-after-admission"
	humanMergeProcessAfterCommit     = "human-merge-hook-after-commit"
)

func openHumanMergeProcessDatabase(t *testing.T, root string) *xorm.Engine {
	t.Helper()
	engine, err := xorm.NewEngine("sqlite3", "file:"+filepath.Join(root, "native.sqlite")+"?_txlock=immediate&_busy_timeout=10000")
	require.NoError(t, err)
	engine.SetMapper(names.GonicMapper{})
	db.SetDefaultEngine(context.Background(), engine)
	return engine
}

// This trusted fixture principal reads the actual current native user. The
// callback journey separately qualifies session withdrawal; no PAT is involved.
func humanMergeProcessAdmission(ctx context.Context) error {
	actor, err := user_model.GetUserByID(ctx, 2)
	if err != nil || !actor.IsAccessAllowed(ctx) {
		return nativeoperation_service.ErrAuthorityLost
	}
	return nil
}

// Attach to the parent's existing database and Git repositories. Never load
// fixtures here: the parent must observe exactly what this process persisted.
func runHumanMergeProcessWorker(t *testing.T, root string) {
	t.Helper()
	engine := openHumanMergeProcessDatabase(t, root)
	t.Cleanup(func() { _ = engine.Close() })
	setting.AppDataPath, setting.RepoRootPath = filepath.Join(root, "appdata"), filepath.Join(root, "repositories")
	setting.AppPath = os.Getenv("SODA_FOUNTAIN_MERGE_HOOK_EXECUTABLE")
	require.NotEmpty(t, setting.AppPath, "needs the current native hook executable")
	setting.CustomConf = filepath.Join(root, "app.ini")
	setting.LFS.StartServer = false // Actual LFS payload qualification is separate.
	secret := make([]byte, 32)
	_, err := rand.Read(secret)
	require.NoError(t, err)
	setting.InternalToken = fmt.Sprintf("%x", secret)
	privateHandler := http.StripPrefix("/api/internal", private_router.Routes())
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		r = r.WithContext(web_middleware.WithContextData(r.Context()))
		if os.Getenv("SODA_FOUNTAIN_MERGE_ACTIVE_PROCESS") == "1" && strings.Contains(r.URL.Path, "/reference-transaction/") {
			raw, err := io.ReadAll(io.LimitReader(r.Body, 1<<20))
			if err != nil {
				http.Error(w, "fixture transaction read failed", 500)
				return
			}
			r.Body = io.NopCloser(bytes.NewReader(raw))
			var options private_api.TransactionOptions
			if json.Unmarshal(raw, &options) != nil {
				http.Error(w, "fixture transaction decode failed", 400)
				return
			}
			point := os.Getenv("NATIVEOP_TEST_CRASH_POINT")
			if point == humanMergeProcessBeforeAdmission && options.Phase == nativeoperation_service.PhasePrepared {
				if err := nativeoperation_service.TestCrashBarrier(point); err != nil {
					http.Error(w, "fixture active barrier failed", 500)
					return
				}
			}
			if point == humanMergeProcessAfterAdmission && options.Phase == nativeoperation_service.PhasePrepared || point == humanMergeProcessAfterCommit && options.Phase == nativeoperation_service.PhaseCommitted {
				// Execute the real native decision, then withhold its reply while
				// Git/receive/the generated hook remain live descendants.
				recorded := httptest.NewRecorder()
				privateHandler.ServeHTTP(recorded, r)
				if recorded.Code != 200 {
					http.Error(w, "fixture native decision refused", 500)
					return
				}
				if err := nativeoperation_service.TestCrashBarrier(point); err != nil {
					http.Error(w, "fixture active barrier failed", 500)
					return
				}
				for key, values := range recorded.Header() {
					w.Header()[key] = values
				}
				w.WriteHeader(recorded.Code)
				_, _ = w.Write(recorded.Body.Bytes())
				return
			}
		}
		privateHandler.ServeHTTP(w, r)
	}))
	t.Cleanup(server.Close)
	currentUser, err := osuser.Current()
	require.NoError(t, err)
	config := fmt.Sprintf("RUN_USER = %s\nRUN_MODE = prod\n[server]\nPROTOCOL = http\nLOCAL_ROOT_URL = %s/\nAPP_DATA_PATH = %s\n[repository]\nROOT = %s\n[security]\nINSTALL_LOCK = true\nINTERNAL_TOKEN = %s\n[log]\nMODE = console\nLEVEL = fatal\n", currentUser.Username, server.URL, setting.AppDataPath, setting.RepoRootPath, setting.InternalToken)
	require.NoError(t, os.WriteFile(setting.CustomConf, []byte(config), 0o600))
	raw, err := os.ReadFile(filepath.Join(root, "merge.json"))
	require.NoError(t, err)
	var q extension.HumanMergeRequest
	require.NoError(t, json.Unmarshal(raw, &q))
	repoID, err := strconv.ParseInt(q.Expected.RepositoryID, 10, 64)
	require.NoError(t, err)
	repository, err := repo_model.GetRepositoryByID(t.Context(), repoID)
	require.NoError(t, err)
	require.NoError(t, repo_module.CreateDelegateHooks(repository.RepoPath()))
	for _, notifier := range []notify_service.Notifier{uinotification.NewNotifier(), feed.NewNotifier()} {
		notify_service.RegisterNotifier(notifier)
	}
	require.NoError(t, pull_service.InitPullRequestTaskQueue())
	pull_service.StartPullRequestTasks()
	// The shipping repository join uses ProcessPushUpdates, not a test dispatcher.
	// Its private prepared hook must use the same default service/witness owner.
	record, err := repo_service.SubmitHumanMerge(t.Context(), nativeoperation_service.Default(), humanMergeProcessInstallation, q, humanMergeProcessAdmission)
	if os.Getenv("SODA_FOUNTAIN_MERGE_PROCESS_COMPLETE") == "1" {
		result := humanMergeProcessCompletion{Record: record, Busy: errors.Is(err, nativeoperation_service.ErrBusy)}
		if err != nil {
			result.Failure = err.Error()
		}
		require.NoError(t, queue.GetManager().FlushAll(t.Context(), 30*time.Second))
		raw, err := json.Marshal(result)
		require.NoError(t, err)
		require.NoError(t, os.WriteFile(filepath.Join(root, "merge-completion.json"), raw, 0o600))
		return
	}
	t.Fatalf("owned merge worker returned before SIGKILL: %v", err)
}

type humanMergeProcessCompletion struct {
	Record  extension.OperationRecord
	Busy    bool
	Failure string
}

func checkHumanMergeProcessReentry(t *testing.T, root string, original extension.HumanMergeRequest, committed, blocked bool) {
	t.Helper()
	engine := openHumanMergeProcessDatabase(t, root)
	t.Cleanup(func() {
		if engine != nil {
			require.NoError(t, engine.Close())
		}
	})
	ctx := t.Context()
	old, err := nativeoperation_model.LookupOperation(ctx, humanMergeProcessInstallation, original.OperationID)
	require.NoError(t, err)
	held, err := nativeoperation_model.ReadReservation(ctx)
	require.NoError(t, err)
	if blocked {
		require.NotEmpty(t, held.Owner)
	} else {
		require.Empty(t, held.Owner)
	}
	q := original
	q.OperationID, err = extension.HumanMergeOperationID(q.Expected.ActorID, q.Expected.RepositoryID, "fresh-reentry")
	require.NoError(t, err)
	q.NotAfter = time.Now().Add(time.Minute).Unix()
	q.Message = "Fresh human operation after stopped recovery 完整 🌋\n"
	revision, err := nativeoperation_service.NewService().ReadNativeRevision(ctx)
	require.NoError(t, err)
	q.Expected.NativeRevision = revision.Revision
	repo, err := repo_model.GetRepositoryByID(ctx, old.RepositoryID)
	require.NoError(t, err)
	oldTip := sourceTestGit(t, repo.RepoPath(), nil, "rev-parse", "refs/heads/main")
	if raw, err := os.ReadFile(filepath.Join(repo.RepoPath(), "refs", "heads", "main.lock")); err == nil {
		t.Logf("target Git ref lock remains after stopped recovery: %q", raw)
	}
	if committed {
		// Fixture input for a genuinely different PR on the recovered branch.
		// These fixed setup commands bypass only fixture hooks; the product
		// operation below installs and executes the actual native hooks again.
		work := filepath.Join(root, "work")
		sourceTestGit(t, work, nil, "fetch", repo.RepoPath(), "refs/heads/main")
		sourceTestGit(t, work, nil, "reset", "--hard", "FETCH_HEAD")
		require.NoError(t, os.WriteFile(filepath.Join(work, "README"), []byte("fresh candidate after native recovery\n"), 0o600))
		sourceTestGit(t, work, nil, "add", "README")
		sourceTestGit(t, work, nil, "commit", "-m", "fresh candidate")
		head := sourceTestGit(t, work, nil, "rev-parse", "HEAD")
		oldPullID, err := strconv.ParseInt(original.Expected.PullID, 10, 64)
		require.NoError(t, err)
		oldPR, err := issues_model.GetPullRequestByID(ctx, oldPullID)
		require.NoError(t, err)
		source, err := repo_model.GetRepositoryByID(ctx, oldPR.HeadRepoID)
		require.NoError(t, err)
		hooks := filepath.Join(root, "fixture-hooks")
		require.NoError(t, os.Mkdir(hooks, 0o700))
		sourceTestGit(t, source.RepoPath(), nil, "-c", "core.hooksPath="+hooks, "fetch", work, "+refs/heads/work:refs/heads/work")
		if source.ID != repo.ID {
			sourceTestGit(t, repo.RepoPath(), nil, "-c", "core.hooksPath="+hooks, "fetch", work, "refs/heads/work")
		}
		sourceTestGit(t, repo.RepoPath(), nil, "-c", "core.hooksPath="+hooks, "update-ref", "refs/pull/3/head", head)
		issue := &issues_model.Issue{RepoID: repo.ID, Index: 3, PosterID: 1, IsPull: true, Title: "fresh PR after stopped merge", Content: "A fresh human operation."}
		_, err = db.GetEngine(ctx).Insert(issue)
		require.NoError(t, err)
		pr := &issues_model.PullRequest{IssueID: issue.ID, Index: 3, BaseRepoID: repo.ID, HeadRepoID: source.ID, BaseBranch: "main", HeadBranch: "work", MergeBase: oldTip, Status: issues_model.PullRequestStatusMergeable, Flow: issues_model.PullRequestFlowGithub}
		_, err = db.GetEngine(ctx).Insert(pr)
		require.NoError(t, err)
		q.Expected.PullID, q.Expected.IssueID, q.Expected.Index = strconv.FormatInt(pr.ID, 10), strconv.FormatInt(issue.ID, 10), "3"
		q.Expected.BaseOID, q.Expected.MergeBaseOID, q.Expected.HeadOID = oldTip, oldTip, head
	}
	raw, err := json.Marshal(q)
	require.NoError(t, err)
	require.NoError(t, os.WriteFile(filepath.Join(root, "merge.json"), raw, 0o600))
	if _, err := os.Stat(nativeoperation_model.OfflineMarkerPath()); err == nil {
		require.NoError(t, os.Remove(nativeoperation_model.OfflineMarkerPath()))
	}
	require.NoError(t, engine.Close())
	engine = nil
	logFile, err := os.Create(filepath.Join(root, "reentry.log"))
	require.NoError(t, err)
	t.Cleanup(func() { _ = logFile.Close() })
	worker := exec.CommandContext(ctx, os.Args[0], "-test.run=^TestRepositoryIssuesCallbackUsesHumanAccessWithoutFactoryBinding$", "-test.v", "-test.timeout=90s")
	worker.Env = append(os.Environ(), "SODA_FOUNTAIN_MERGE_PROCESS_WORKER="+root, "SODA_FOUNTAIN_MERGE_PROCESS_COMPLETE=1", "SODA_FOUNTAIN_MERGE_ACTIVE_PROCESS=", "NATIVEOP_TEST_CRASH_POINT=", "TMPDIR="+filepath.Join(root, "worker-tmp"))
	worker.Stdout, worker.Stderr = logFile, logFile
	err = worker.Run()
	if err != nil {
		output, _ := os.ReadFile(filepath.Join(root, "reentry.log"))
		t.Fatalf("fresh native worker failed: %v\n%s", err, output)
	}
	engine = openHumanMergeProcessDatabase(t, root)
	raw, err = os.ReadFile(filepath.Join(root, "merge-completion.json"))
	require.NoError(t, err)
	var result humanMergeProcessCompletion
	require.NoError(t, json.Unmarshal(raw, &result))
	after, err := nativeoperation_model.LookupOperation(ctx, humanMergeProcessInstallation, original.OperationID)
	require.NoError(t, err)
	require.Equal(t, old, after, "fresh operation rewrote historical retained truth")
	fresh, err := nativeoperation_model.LookupOperation(ctx, humanMergeProcessInstallation, q.OperationID)
	require.NoError(t, err)
	reservation, err := nativeoperation_model.ReadReservation(ctx)
	require.NoError(t, err)
	if blocked {
		require.True(t, result.Busy, "%+v", result)
		require.Nil(t, fresh)
		require.Equal(t, held, reservation)
		require.Equal(t, oldTip, sourceTestGit(t, repo.RepoPath(), nil, "rev-parse", "refs/heads/main"))
		t.Log("fresh native operation refused busy after uncertain recovery; original operation/reservation/ref retained")
		return
	}
	require.Empty(t, result.Failure)
	if result.Record.EffectState != nativeoperation_model.EffectCommitted {
		require.NotNil(t, fresh)
		t.Logf("fresh native effect=%s admitted=%t reason=%s current target=%s", fresh.EffectState, fresh.Admitted, fresh.Reason, sourceTestGit(t, repo.RepoPath(), nil, "rev-parse", "refs/heads/main"))
		output, _ := os.ReadFile(filepath.Join(root, "reentry.log"))
		t.Logf("fresh native worker log:\n%s", output)
	}
	require.Equal(t, nativeoperation_model.EffectCommitted, result.Record.EffectState, "%+v", result.Record)
	require.Equal(t, nativeoperation_model.CompletionComplete, result.Record.CompletionState)
	require.NotNil(t, fresh)
	require.Equal(t, nativeoperation_model.EffectCommitted, fresh.EffectState)
	require.Equal(t, nativeoperation_model.CompletionComplete, fresh.Completion)
	var receipt extension.HumanMergeReceipt
	require.NoError(t, json.Unmarshal([]byte(fresh.Receipt), &receipt))
	require.True(t, extension.ValidHumanMergeReceipt(receipt, q))
	require.Equal(t, receipt.ResultOID, sourceTestGit(t, repo.RepoPath(), nil, "rev-parse", "refs/heads/main"))
	require.NotEqual(t, oldTip, receipt.ResultOID)
	merged, err := issues_model.GetPullRequestByID(ctx, receipt.PullID)
	require.NoError(t, err)
	require.NoError(t, merged.LoadIssue(ctx))
	require.True(t, merged.HasMerged)
	require.True(t, merged.Issue.IsClosed)
	require.Equal(t, receipt.ActorID, merged.MergerID)
	require.Equal(t, receipt.ResultOID, merged.MergedCommitID)
	branch, err := git_model.GetBranch(ctx, repo.ID, "main")
	require.NoError(t, err)
	require.Equal(t, receipt.ResultOID, branch.CommitID)
	history, err := db.GetEngine(ctx).Where("issue_id=? AND type=?", receipt.IssueID, issues_model.CommentTypeMergePull).Count(new(issues_model.Comment))
	require.NoError(t, err)
	require.EqualValues(t, 1, history)
	require.Empty(t, reservation.Owner)
	require.Greater(t, reservation.Generation, held.Generation)
	files, err := filepath.Glob(filepath.Join(setting.AppDataPath, "nativeop-exec", "*"))
	require.NoError(t, err)
	require.Empty(t, files)
	replay, err := repo_service.SubmitHumanMerge(ctx, nativeoperation_service.NewService(), humanMergeProcessInstallation, original, humanMergeProcessAdmission)
	require.NoError(t, err)
	require.Equal(t, old.EffectState, replay.EffectState)
	require.Equal(t, old.Completion, replay.CompletionState)
	require.Equal(t, old.Receipt, string(replay.Receipt))
	require.Equal(t, receipt.ResultOID, sourceTestGit(t, repo.RepoPath(), nil, "rev-parse", "refs/heads/main"))
	t.Logf("fresh native %s operation completed after stopped recovery; historical receipt/replay retained and new generation released", q.Expected.Method)
}

func runHumanMergeProcessRecovery(t *testing.T) {
	t.Helper()
	if runtime.GOOS != "linux" {
		t.Skip("owned SIGKILL/reap and /proc qualification runs on Linux")
	}
	points := []string{nativeoperation_service.CrashPointHumanMergeBeforePush, nativeoperation_service.CrashPointHumanMergeAfterPush, nativeoperation_service.CrashPointHumanMergeAfterFinish, nativeoperation_service.CrashPointHumanMergeBeforeRelease}
	reentry := os.Getenv("SODA_FOUNTAIN_MERGE_REENTRY") == "1"
	active := os.Getenv("SODA_FOUNTAIN_MERGE_ACTIVE_PROCESS") == "1" || reentry
	if active {
		points = []string{humanMergeProcessBeforeAdmission, humanMergeProcessAfterAdmission, humanMergeProcessAfterCommit}
	}
	for _, method := range []string{"merge", "rebase", "rebase-merge", "squash", "fast-forward-only", "private-fork"} {
		for _, point := range points {
			t.Run(method+"/"+point, func(t *testing.T) {
				root := t.TempDir()
				for _, name := range []string{"appdata", "repositories", "work", "barrier", "worker-tmp"} {
					require.NoError(t, os.Mkdir(filepath.Join(root, name), 0o700))
				}
				ctx := t.Context()
				previous := db.DefaultContext.(db.Engined).Engine()
				previousData, previousRepos := setting.AppDataPath, setting.RepoRootPath
				setting.AppDataPath, setting.RepoRootPath = filepath.Join(root, "appdata"), filepath.Join(root, "repositories")
				engine := openHumanMergeProcessDatabase(t, root)
				t.Cleanup(func() {
					if engine != nil {
						require.NoError(t, engine.Close())
					}
					db.SetDefaultEngine(context.Background(), previous)
					setting.AppDataPath, setting.RepoRootPath = previousData, previousRepos
					require.NoError(t, unittest.InitFixtures(unittest.FixturesOptions{Dir: unittest.FixturesDir()}))
				})
				require.NoError(t, db.SyncAllTables())
				require.NoError(t, unittest.InitFixtures(unittest.FixturesOptions{Dir: unittest.FixturesDir()}))
				require.NoError(t, unittest.LoadFixtures())
				owner := unittest.AssertExistsAndLoadBean(t, &user_model.User{ID: 1})
				actor := unittest.AssertExistsAndLoadBean(t, &user_model.User{ID: 2})
				repo := &repo_model.Repository{OwnerID: owner.ID, OwnerName: owner.Name, Name: "merge-process", LowerName: "merge-process", IsPrivate: true, DefaultBranch: "main"}
				_, err := db.GetEngine(ctx).Insert(repo)
				require.NoError(t, err)
				prUnit := &repo_model.RepoUnit{RepoID: repo.ID, Type: unit.TypePullRequests, Config: &repo_model.PullRequestsConfig{AllowMerge: true, AllowRebase: true, AllowRebaseMerge: true, AllowSquash: true, AllowFastForwardOnly: true}}
				_, err = db.GetEngine(ctx).Insert(prUnit, &repo_model.RepoUnit{RepoID: repo.ID, Type: unit.TypeCode}, &repo_model.RepoUnit{RepoID: repo.ID, Type: unit.TypeIssues}, &access_model.Access{RepoID: repo.ID, UserID: actor.ID, Mode: perm.AccessModeWrite}, &repo_model.Collaboration{RepoID: repo.ID, UserID: actor.ID, Mode: perm.AccessModeWrite}, &access_model.Access{RepoID: repo.ID, UserID: 4, Mode: perm.AccessModeRead}, &repo_model.Collaboration{RepoID: repo.ID, UserID: 4, Mode: perm.AccessModeRead}, &repo_model.Watch{RepoID: repo.ID, UserID: 4, Mode: repo_model.WatchModeNormal})
				require.NoError(t, err)
				work := filepath.Join(root, "work")
				sourceTestGit(t, work, nil, "init", "--initial-branch=main")
				commit := func(content, message string) string {
					t.Helper()
					require.NoError(t, os.WriteFile(filepath.Join(work, "README"), []byte(content), 0o600))
					sourceTestGit(t, work, nil, "add", "README")
					sourceTestGit(t, work, nil, "commit", "-m", message)
					return sourceTestGit(t, work, nil, "rev-parse", "HEAD")
				}
				base := commit("base\n", "base")
				sourceTestGit(t, work, nil, "checkout", "-b", "work")
				head := commit("candidate\n", "candidate")
				require.NoError(t, os.MkdirAll(filepath.Dir(repo.RepoPath()), 0o700))
				sourceTestGit(t, work, nil, "clone", "--bare", work, repo.RepoPath())
				sourceTestGit(t, repo.RepoPath(), nil, "update-ref", "refs/heads/main", base)
				sourceTestGit(t, repo.RepoPath(), nil, "update-ref", "refs/pull/1/head", head)
				repo.ObjectFormatName = sourceTestGit(t, repo.RepoPath(), nil, "rev-parse", "--show-object-format")
				_, err = db.GetEngine(ctx).ID(repo.ID).Cols("object_format_name").Update(repo)
				require.NoError(t, err)
				issue := &issues_model.Issue{RepoID: repo.ID, Index: 1, PosterID: owner.ID, IsPull: true, Title: "persistent native merge", Content: "closes #2"}
				referenced := &issues_model.Issue{RepoID: repo.ID, Index: 2, PosterID: owner.ID, Title: "persistent referenced issue"}
				_, err = db.GetEngine(ctx).Insert(issue, referenced)
				require.NoError(t, err)
				pr := &issues_model.PullRequest{IssueID: issue.ID, Index: 1, BaseRepoID: repo.ID, HeadRepoID: repo.ID, BaseBranch: "main", HeadBranch: "work", MergeBase: base, Status: issues_model.PullRequestStatusMergeable, Flow: issues_model.PullRequestFlowGithub}
				selectedMethod := method
				if method == "private-fork" {
					selectedMethod = "squash"
					fork := &repo_model.Repository{OwnerID: owner.ID, OwnerName: owner.Name, Name: "merge-process-fork", LowerName: "merge-process-fork", IsPrivate: true, DefaultBranch: "work", ObjectFormatName: repo.ObjectFormatName}
					_, err := db.GetEngine(ctx).Insert(fork)
					require.NoError(t, err)
					_, err = db.GetEngine(ctx).Insert(&repo_model.RepoUnit{RepoID: fork.ID, Type: unit.TypeCode}, &access_model.Access{RepoID: fork.ID, UserID: actor.ID, Mode: perm.AccessModeRead}, &repo_model.Collaboration{RepoID: fork.ID, UserID: actor.ID, Mode: perm.AccessModeRead})
					require.NoError(t, err)
					sourceTestGit(t, work, nil, "clone", "--bare", work, fork.RepoPath())
					pr.HeadRepoID = fork.ID
				}
				_, err = db.GetEngine(ctx).Insert(pr)
				require.NoError(t, err)
				origin, err := issues_model.GetIssueByID(ctx, issue.ID)
				require.NoError(t, err)
				origin.Repo = repo
				require.NoError(t, origin.AddCrossReferences(ctx, actor, false))
				_, err = db.GetEngine(ctx).Insert(&activities_model.Notification{IssueID: issue.ID, RepoID: repo.ID, UserID: 4, Status: activities_model.NotificationStatusRead, Source: activities_model.NotificationSourcePullRequest, CreatedUnix: 1, UpdatedUnix: 2})
				require.NoError(t, err)
				revision, err := nativeoperation_service.NewService().ReadNativeRevision(ctx)
				require.NoError(t, err)
				require.True(t, revision.Idle)
				want := extension.RepositoryMergeSnapshot{RepositoryID: strconv.FormatInt(repo.ID, 10), ActorID: "2", PullID: strconv.FormatInt(pr.ID, 10), IssueID: strconv.FormatInt(issue.ID, 10), Index: "1", Method: selectedMethod, BaseBranch: "main", HeadOID: head, BaseOID: base, MergeBaseOID: base, NativeRevision: revision.Revision, Action: extension.RepositoryActionCapability{State: "allowed", Reason: "native process fixture"}}
				operation, err := extension.HumanMergeOperationID(want.ActorID, want.RepositoryID, "process-"+method+"-"+point)
				require.NoError(t, err)
				q := extension.HumanMergeRequest{OperationID: operation, Expected: want, Message: "Persistent native merge 完整 🌋\n\nExact human message.\n", NotAfter: time.Now().Add(time.Minute).Unix()}
				canonical, digest, err := extension.CanonicalHumanMergeIntent(q)
				require.NoError(t, err)
				raw, err := json.Marshal(q)
				require.NoError(t, err)
				require.NoError(t, os.WriteFile(filepath.Join(root, "merge.json"), raw, 0o600))
				require.NoError(t, engine.Close())
				engine = nil
				logFile, err := os.Create(filepath.Join(root, "worker.log"))
				require.NoError(t, err)
				t.Cleanup(func() { _ = logFile.Close() })
				child := exec.CommandContext(ctx, os.Args[0], "-test.run=^TestRepositoryIssuesCallbackUsesHumanAccessWithoutFactoryBinding$", "-test.v", "-test.timeout=90s")
				child.Env = append(os.Environ(), "SODA_FOUNTAIN_MERGE_PROCESS_WORKER="+root, "TMPDIR="+filepath.Join(root, "worker-tmp"), "NATIVEOP_TEST_CRASH_POINT="+point, "NATIVEOP_TEST_CRASH_BARRIER_DIR="+filepath.Join(root, "barrier"), "NATIVEOP_TEST_CRASH_TIMEOUT_SECONDS=60")
				if active {
					supervisor := os.Getenv("SODA_FOUNTAIN_MERGE_PROCESS_SUPERVISOR")
					require.NotEmpty(t, supervisor, "needs the existing Linux native-operation test executable")
					workerEnv := child.Env
					child = exec.CommandContext(ctx, supervisor, "-test.run=^TestIssueGraphProcessDeathRecovery$", "-test.v", "-test.timeout=75s")
					child.Env = append(workerEnv, "SODA_FOUNTAIN_MERGE_ACTIVE_PROCESS=1", "FOUNTAIN_MERGE_PROCESS_SUPERVISOR_ROOT="+root, "FOUNTAIN_MERGE_PROCESS_WORKER_EXECUTABLE="+os.Args[0])
				}
				child.Stdout, child.Stderr = logFile, logFile
				require.NoError(t, child.Start())
				exited := make(chan error, 1)
				go func() { exited <- child.Wait() }()
				reaped := false
				t.Cleanup(func() {
					if !reaped {
						_ = child.Process.Kill()
						<-exited
					}
				})
				if active {
					select {
					case err := <-exited:
						reaped = true
						output, _ := os.ReadFile(filepath.Join(root, "worker.log"))
						require.NoError(t, err, string(output))
					case <-time.After(60 * time.Second):
						t.Fatal("owned Linux process-tree supervisor did not finish")
					}
					raw, err := os.ReadFile(filepath.Join(root, "tree-reaped.json"))
					require.NoError(t, err)
					var proof []struct {
						PID    int
						Name   string
						Reaped bool
					}
					require.NoError(t, json.Unmarshal(raw, &proof))
					require.GreaterOrEqual(t, len(proof), 4)
					for _, process := range proof {
						require.True(t, process.Reaped)
					}
					t.Logf("native %s at %s: SIGKILL/reaped owned process tree %s", method, point, raw)
				} else {
					deadline := time.After(30 * time.Second)
					tick := time.NewTicker(10 * time.Millisecond)
					defer tick.Stop()
					enteredPath := filepath.Join(root, "barrier", point+".entered")
					for entered := false; !entered; {
						select {
						case err := <-exited:
							reaped = true
							output, _ := os.ReadFile(filepath.Join(root, "worker.log"))
							t.Fatalf("owned merge worker exited before %s: %v\n%s", point, err, output)
						case <-deadline:
							output, _ := os.ReadFile(filepath.Join(root, "worker.log"))
							t.Fatalf("owned merge worker never reached %s\n%s", point, output)
						case <-tick.C:
							_, err := os.Stat(enteredPath)
							entered = err == nil
						}
					}
					entered, err := os.ReadFile(enteredPath)
					require.NoError(t, err)
					require.Equal(t, strconv.Itoa(child.Process.Pid), strings.TrimSpace(string(entered)))
					// These checkpoints are outside synchronous Git. Check every Go
					// thread's child list rather than infer that from the barrier alone.
					children, err := filepath.Glob(fmt.Sprintf("/proc/%d/task/*/children", child.Process.Pid))
					require.NoError(t, err)
					require.NotEmpty(t, children)
					for _, path := range children {
						data, err := os.ReadFile(path)
						if os.IsNotExist(err) { // A Go runtime thread can retire during inspection.
							continue
						}
						require.NoError(t, err)
						require.Empty(t, strings.TrimSpace(string(data)), "active Git/hook descendants require a separate stop gate")
					}
					require.NoError(t, child.Process.Kill())
					select {
					case err := <-exited:
						reaped = true
						var killed *exec.ExitError
						require.ErrorAs(t, err, &killed)
						require.Equal(t, "signal: killed", killed.ProcessState.String())
					case <-time.After(10 * time.Second):
						t.Fatal("owned merge worker did not exit after SIGKILL")
					}
					t.Logf("owned pid=%d reached %s without active children, SIGKILL received and reaped; reopening same native file and Git", child.Process.Pid, point)
				}
				engine = openHumanMergeProcessDatabase(t, root)
				held, err := nativeoperation_model.ReadReservation(ctx)
				require.NoError(t, err)
				require.Equal(t, "cond:"+humanMergeProcessInstallation+"/"+q.OperationID, held.Owner)
				require.Positive(t, held.Generation)
				op, err := nativeoperation_model.LookupOperation(ctx, humanMergeProcessInstallation, q.OperationID)
				require.NoError(t, err)
				require.NotNil(t, op)
				require.Equal(t, canonical, op.Intent)
				require.Equal(t, digest, op.IntentDigest)
				require.Zero(t, op.TokenID)
				require.Empty(t, op.CredentialFingerprint)
				committed := !active && point != nativeoperation_service.CrashPointHumanMergeBeforePush || point == humanMergeProcessAfterCommit
				admitted := committed || point == humanMergeProcessAfterAdmission
				require.Equal(t, admitted, op.Admitted)
				var scope nativeoperation_service.Scope
				require.NoError(t, json.Unmarshal([]byte(held.Scope), &scope))
				tip := sourceTestGit(t, repo.RepoPath(), nil, "rev-parse", "refs/heads/main")
				if committed {
					require.Equal(t, scope.NewOID, tip)
					require.NotEqual(t, base, tip)
				} else {
					require.Equal(t, base, tip)
				}
				switch point {
				case humanMergeProcessBeforeAdmission, humanMergeProcessAfterAdmission, humanMergeProcessAfterCommit:
					require.Empty(t, op.Receipt)
					require.Empty(t, scope.CompletionPhase)
				case nativeoperation_service.CrashPointHumanMergeBeforePush, nativeoperation_service.CrashPointHumanMergeAfterPush:
					require.Empty(t, op.Receipt)
					require.Empty(t, scope.CompletionPhase)
				case nativeoperation_service.CrashPointHumanMergeAfterFinish:
					require.Equal(t, nativeoperation_service.HumanMergeFinishDone, scope.CompletionPhase)
				case nativeoperation_service.CrashPointHumanMergeBeforeRelease:
					require.Equal(t, nativeoperation_service.HumanMergePushEventDone, scope.CompletionPhase)
				}
				observeDispatch := func() string {
					t.Helper()
					var notices []activities_model.Notification
					var actions []activities_model.Action
					var comments []issues_model.Comment
					require.NoError(t, db.GetEngine(ctx).Where("repo_id=?", repo.ID).OrderBy("id").Find(&notices))
					require.NoError(t, db.GetEngine(ctx).Where("repo_id=?", repo.ID).OrderBy("id").Find(&actions))
					// Merge-history SQL is legitimately repaired. Cross-reference
					// dispatch and all other comment rows must remain untouched.
					require.NoError(t, db.GetEngine(ctx).Where("(issue_id=? OR issue_id=?) AND type<>?", issue.ID, referenced.ID, issues_model.CommentTypeMergePull).OrderBy("id").Find(&comments))
					raw, err := json.Marshal([]any{notices, actions, comments})
					require.NoError(t, err)
					return string(raw)
				}
				dispatchBefore := observeDispatch()
				stopped := nativeoperation_service.NewService()
				_, err = stopped.Recover(ctx, held.Owner, held.Generation)
				require.ErrorIs(t, err, nativeoperation_service.ErrNotInhibited)
				// Inhibition is set only after the actual owned process was reaped.
				require.NoError(t, os.WriteFile(nativeoperation_model.OfflineMarkerPath(), []byte("owned merge writer domain stopped, SIGKILLed and reaped\n"), 0o600))
				wrong, err := stopped.Recover(ctx, held.Owner, held.Generation+1)
				require.NoError(t, err)
				require.Equal(t, nativeoperation_service.RecoveryFenced, wrong.Verdict)
				if reentry && point == humanMergeProcessBeforeAdmission {
					lock := filepath.Join(repo.RepoPath(), "refs", "heads", "main.lock")
					raw, err := os.ReadFile(lock)
					require.NoError(t, err)
					require.Equal(t, scope.NewOID+"\n", string(raw))
					for _, mode := range []string{"foreign", "symlink"} {
						if mode == "foreign" {
							require.NoError(t, os.WriteFile(lock, []byte("foreign lock\n"), 0o600))
						} else {
							require.NoError(t, os.Remove(lock))
							target := filepath.Join(root, "foreign-ref-lock")
							require.NoError(t, os.WriteFile(target, raw, 0o600))
							require.NoError(t, os.Symlink(target, lock))
						}
						fenced, err := stopped.Recover(ctx, held.Owner, held.Generation)
						require.NoError(t, err)
						require.Equal(t, nativeoperation_service.RecoveryFenced, fenced.Verdict)
						after, err := nativeoperation_model.LookupOperation(ctx, humanMergeProcessInstallation, q.OperationID)
						require.NoError(t, err)
						require.Equal(t, op, after)
						reservation, err := nativeoperation_model.ReadReservation(ctx)
						require.NoError(t, err)
						require.Equal(t, held, reservation)
						require.FileExists(t, lock)
						if mode == "symlink" {
							saved, err := os.ReadFile(filepath.Join(root, "foreign-ref-lock"))
							require.NoError(t, err)
							require.Equal(t, raw, saved)
							require.NoError(t, os.Remove(lock))
						}
					}
					require.NoError(t, os.WriteFile(lock, raw, 0o600))
				}
				assessment, err := stopped.Recover(ctx, held.Owner, held.Generation)
				require.NoError(t, err)
				if point == humanMergeProcessAfterAdmission {
					require.Equal(t, nativeoperation_service.RecoveryFenced, assessment.Verdict)
					after, err := nativeoperation_model.LookupOperation(ctx, humanMergeProcessInstallation, q.OperationID)
					require.NoError(t, err)
					require.Equal(t, op, after, "uncertain admitted old tip changed the retained operation")
					reservation, err := nativeoperation_model.ReadReservation(ctx)
					require.NoError(t, err)
					require.Equal(t, held, reservation)
					files, err := filepath.Glob(filepath.Join(setting.AppDataPath, "nativeop-exec", "*"))
					require.NoError(t, err)
					require.Len(t, files, 1)
					if reentry {
						lock, err := os.ReadFile(filepath.Join(repo.RepoPath(), "refs", "heads", "main.lock"))
						require.NoError(t, err)
						require.Equal(t, scope.NewOID+"\n", string(lock), "uncertain writer lost its retained Git lock")
					}
					require.NoError(t, engine.Close())
					engine = openHumanMergeProcessDatabase(t, root)
					replay, err := repo_service.SubmitHumanMerge(ctx, nativeoperation_service.NewService(), humanMergeProcessInstallation, q, humanMergeProcessAdmission)
					require.NoError(t, err)
					require.Equal(t, op.EffectState, replay.EffectState)
					require.Empty(t, replay.Receipt)
					require.Equal(t, base, sourceTestGit(t, repo.RepoPath(), nil, "rev-parse", "refs/heads/main"))
					require.Equal(t, dispatchBefore, observeDispatch())
					again, err := nativeoperation_service.NewService().Recover(ctx, held.Owner, held.Generation)
					require.NoError(t, err)
					require.Equal(t, nativeoperation_service.RecoveryFenced, again.Verdict)
					t.Log("admitted old target remains fenced after full process-tree death, database reopen and submit replay; no effect/dispatch invented")
					if reentry {
						require.NoError(t, engine.Close())
						engine = nil
						checkHumanMergeProcessReentry(t, root, q, false, true)
					}
					return
				}
				require.Equal(t, nativeoperation_service.RecoveryReleased, assessment.Verdict, "%+v", assessment)
				require.Equal(t, "conditional-human-merge", assessment.Family)
				after, err := nativeoperation_model.LookupOperation(ctx, humanMergeProcessInstallation, q.OperationID)
				require.NoError(t, err)
				if committed {
					require.Equal(t, nativeoperation_model.EffectCommitted, after.EffectState)
					completion := nativeoperation_model.CompletionNeedsIntervention
					if point == nativeoperation_service.CrashPointHumanMergeBeforeRelease {
						completion = nativeoperation_model.CompletionComplete
					}
					require.Equal(t, completion, after.Completion)
					var receipt extension.HumanMergeReceipt
					require.NoError(t, json.Unmarshal([]byte(after.Receipt), &receipt))
					require.True(t, extension.ValidHumanMergeReceipt(receipt, q))
					require.Equal(t, tip, receipt.ResultOID)
					require.Equal(t, sourceTestGit(t, repo.RepoPath(), nil, "rev-parse", tip+"^{tree}"), receipt.TreeOID)
					if op.Receipt != "" {
						require.Equal(t, op.Receipt, after.Receipt)
					}
					merged, err := issues_model.GetPullRequestByID(ctx, pr.ID)
					require.NoError(t, err)
					require.True(t, merged.HasMerged)
					require.Equal(t, actor.ID, merged.MergerID)
					require.Equal(t, tip, merged.MergedCommitID)
					branch, err := git_model.GetBranch(ctx, repo.ID, "main")
					require.NoError(t, err)
					require.Equal(t, tip, branch.CommitID)
				} else {
					require.Equal(t, nativeoperation_model.EffectNotCommitted, after.EffectState)
					require.Empty(t, after.Receipt)
				}
				history, err := db.GetEngine(ctx).Where("issue_id=? AND type=?", issue.ID, issues_model.CommentTypeMergePull).Count(new(issues_model.Comment))
				require.NoError(t, err)
				if committed {
					require.EqualValues(t, 1, history)
				} else {
					require.Zero(t, history)
				}
				idle, err := nativeoperation_model.ReadReservation(ctx)
				require.NoError(t, err)
				require.Empty(t, idle.Owner)
				require.Equal(t, held.Generation, idle.Generation)
				files, err := filepath.Glob(filepath.Join(setting.AppDataPath, "nativeop-exec", "*"))
				require.NoError(t, err)
				require.Empty(t, files)
				require.Equal(t, dispatchBefore, observeDispatch(), "recovery replayed native dispatch")
				require.NoError(t, os.Remove(nativeoperation_model.OfflineMarkerPath()))
				// Reopen again, then exercise the shipping submit replay path. Its
				// private HTTP server and original witness died with the worker.
				require.NoError(t, engine.Close())
				engine = openHumanMergeProcessDatabase(t, root)
				replay, err := repo_service.SubmitHumanMerge(ctx, nativeoperation_service.NewService(), humanMergeProcessInstallation, q, humanMergeProcessAdmission)
				require.NoError(t, err)
				require.Equal(t, after.EffectState, replay.EffectState)
				require.Equal(t, after.Completion, replay.CompletionState)
				require.Equal(t, after.Receipt, string(replay.Receipt))
				require.Equal(t, tip, sourceTestGit(t, repo.RepoPath(), nil, "rev-parse", "refs/heads/main"))
				require.Equal(t, dispatchBefore, observeDispatch(), "replay repeated native dispatch")
				require.NoError(t, os.WriteFile(nativeoperation_model.OfflineMarkerPath(), []byte("same stopped domain after database reopen\n"), 0o600))
				again, err := nativeoperation_service.NewService().Recover(ctx, held.Owner, held.Generation)
				require.NoError(t, err)
				require.Equal(t, nativeoperation_service.RecoveryIdle, again.Verdict)
				t.Logf("persistent recovery %s: effect=%s completion=%s; receipt/history/catalog correct, dispatch unchanged, capability retired, second reopen/replay idle", method, after.EffectState, after.Completion)
				if reentry {
					require.NoError(t, engine.Close())
					engine = nil
					checkHumanMergeProcessReentry(t, root, q, committed, false)
				}
			})
		}
	}
}

// Interventions run after a real local-store Stat, never replace its result.
// This lets native cancellation/session changes race actual payload inspection.
type humanMergeLFSStorage struct {
	storage.ObjectStorage
	once      sync.Once
	statCalls atomic.Int64
	afterStat func()
}

func (s *humanMergeLFSStorage) Stat(path string) (os.FileInfo, error) {
	s.statCalls.Add(1)
	info, err := s.ObjectStorage.Stat(path)
	if s.afterStat != nil {
		s.once.Do(s.afterStat)
	}
	return info, err
}

func runHumanMergeLFS(t *testing.T) {
	t.Helper()
	require.NoError(t, pull_service.InitPullRequestTaskQueue())
	pull_service.StartPullRequestTasks()
	for _, notifier := range []notify_service.Notifier{uinotification.NewNotifier(), feed.NewNotifier()} {
		notify_service.RegisterNotifier(notifier)
		t.Cleanup(func() { notify_service.UnregisterNotifier(notifier) })
	}
	for _, mode := range []string{"valid", "same-repo", "ordinary", "missing-content", "missing-source", "wrong-size", "source-size", "storage-error", "sql-failure", "partial-sql", "cancel-at-store", "session-at-store", "context-at-store"} {
		methods := []string{"squash"}
		if mode == "valid" {
			methods = []string{"merge", "rebase", "rebase-merge", "squash", "fast-forward-only"}
		}
		for _, method := range methods {
			t.Run(mode+"/"+method, func(t *testing.T) {
				fixture := newSourceTestFixture(t)
				ctx, cancel := context.WithCancel(t.Context())
				t.Cleanup(cancel)
				owner := unittest.AssertExistsAndLoadBean(t, &user_model.User{ID: 1})
				payload := bytes.Repeat([]byte("native LFS payload 🌋\x00\n"), 8192)
				pointer, err := lfs.GeneratePointer(bytes.NewReader(payload))
				require.NoError(t, err)
				require.NoError(t, os.WriteFile(filepath.Join(fixture.work, "payload.bin"), []byte(pointer.StringContent()), 0o600))
				secondPayload := []byte("second real native LFS object 🌋\x00\n")
				secondPointer, err := lfs.GeneratePointer(bytes.NewReader(secondPayload))
				require.NoError(t, err)
				if mode == "partial-sql" {
					require.NoError(t, os.WriteFile(filepath.Join(fixture.work, "second.bin"), []byte(secondPointer.StringContent()), 0o600))
					sourceTestGit(t, fixture.work, nil, "add", "second.bin")
				}
				sourceTestGit(t, fixture.work, nil, "add", "payload.bin")
				sourceTestGit(t, fixture.work, nil, "commit", "-m", "actual LFS candidate")
				head := sourceTestGit(t, fixture.work, nil, "rev-parse", "HEAD")
				base := &repo_model.Repository{OwnerID: 1, OwnerName: owner.Name, Name: "human-lfs-base", LowerName: "human-lfs-base", IsPrivate: true, DefaultBranch: "main"}
				_, err = db.GetEngine(ctx).Insert(base)
				require.NoError(t, err)
				require.NoError(t, os.MkdirAll(filepath.Dir(base.RepoPath()), 0o700))
				sourceTestGit(t, fixture.work, nil, "clone", "--bare", fixture.work, base.RepoPath())
				sourceTestGit(t, base.RepoPath(), nil, "update-ref", "refs/heads/main", fixture.base)
				sourceTestGit(t, base.RepoPath(), nil, "update-ref", "refs/heads/work", head)
				sourceTestGit(t, base.RepoPath(), nil, "update-ref", "refs/pull/1/head", head)
				base.ObjectFormatName = sourceTestGit(t, base.RepoPath(), nil, "rev-parse", "--show-object-format")
				_, err = db.GetEngine(ctx).ID(base.ID).Cols("object_format_name").Update(base)
				require.NoError(t, err)
				_, err = db.GetEngine(ctx).Insert(&repo_model.RepoUnit{RepoID: base.ID, Type: unit.TypeCode}, &repo_model.RepoUnit{RepoID: base.ID, Type: unit.TypeIssues}, &repo_model.RepoUnit{RepoID: base.ID, Type: unit.TypePullRequests, Config: &repo_model.PullRequestsConfig{AllowMerge: true, AllowRebase: true, AllowRebaseMerge: true, AllowSquash: true, AllowFastForwardOnly: true}}, &access_model.Access{RepoID: base.ID, UserID: 2, Mode: perm.AccessModeWrite}, &repo_model.Collaboration{RepoID: base.ID, UserID: 2, Mode: perm.AccessModeWrite})
				require.NoError(t, err)
				source := base
				if mode != "same-repo" {
					source = &repo_model.Repository{OwnerID: 1, OwnerName: owner.Name, Name: "human-lfs-private-source", LowerName: "human-lfs-private-source", IsPrivate: true, DefaultBranch: "work", ObjectFormatName: base.ObjectFormatName}
					_, err = db.GetEngine(ctx).Insert(source)
					require.NoError(t, err)
					sourceTestGit(t, fixture.work, nil, "clone", "--bare", fixture.work, source.RepoPath())
					sourceTestGit(t, source.RepoPath(), nil, "update-ref", "refs/heads/work", head)
					_, err = db.GetEngine(ctx).Insert(&repo_model.RepoUnit{RepoID: source.ID, Type: unit.TypeCode}, &access_model.Access{RepoID: source.ID, UserID: 2, Mode: perm.AccessModeRead}, &repo_model.Collaboration{RepoID: source.ID, UserID: 2, Mode: perm.AccessModeRead})
					require.NoError(t, err)
				}
				issue := &issues_model.Issue{RepoID: base.ID, Index: 1, PosterID: 1, IsPull: true, Title: "actual LFS human merge"}
				_, err = db.GetEngine(ctx).Insert(issue)
				require.NoError(t, err)
				pr := &issues_model.PullRequest{IssueID: issue.ID, Index: 1, BaseRepoID: base.ID, HeadRepoID: source.ID, BaseBranch: "main", HeadBranch: "work", MergeBase: fixture.base, Status: issues_model.PullRequestStatusMergeable, Flow: issues_model.PullRequestFlowGithub}
				_, err = db.GetEngine(ctx).Insert(pr)
				require.NoError(t, err)
				oldApp, oldConf, oldToken, oldLFS, oldStore := setting.AppPath, setting.CustomConf, setting.InternalToken, setting.LFS.StartServer, storage.LFS
				t.Cleanup(func() {
					setting.AppPath, setting.CustomConf, setting.InternalToken, setting.LFS.StartServer, storage.LFS = oldApp, oldConf, oldToken, oldLFS, oldStore
				})
				setting.AppPath = os.Getenv("SODA_FOUNTAIN_MERGE_HOOK_EXECUTABLE")
				require.NotEmpty(t, setting.AppPath)
				setting.CustomConf = filepath.Join(t.TempDir(), "app.ini")
				secret := make([]byte, 32)
				_, err = rand.Read(secret)
				require.NoError(t, err)
				setting.InternalToken = fmt.Sprintf("%x", secret)
				setting.LFS.StartServer = true
				storeRoot := t.TempDir()
				realStore, err := storage.NewLocalStorage(ctx, &setting.Storage{Path: storeRoot})
				require.NoError(t, err)
				storage.LFS = realStore
				if mode != "missing-content" {
					require.NoError(t, lfs.NewContentStore().Put(pointer, bytes.NewReader(payload)))
				}
				if mode != "missing-source" {
					metaPointer := pointer
					if mode == "source-size" {
						metaPointer.Size--
					}
					_, err = git_model.NewLFSMetaObject(ctx, source.ID, metaPointer)
					require.NoError(t, err)
				}
				if mode == "partial-sql" {
					require.NoError(t, lfs.NewContentStore().Put(secondPointer, bytes.NewReader(secondPayload)))
					_, err := git_model.NewLFSMetaObject(ctx, source.ID, secondPointer)
					require.NoError(t, err)
					_, err = db.GetEngine(ctx).Exec(fmt.Sprintf("CREATE TRIGGER refuse_lfs_base BEFORE INSERT ON lfs_meta_object WHEN NEW.repository_id=%d AND EXISTS(SELECT 1 FROM lfs_meta_object WHERE repository_id=%d) BEGIN SELECT RAISE(ABORT, 'second LFS association failure'); END", base.ID, base.ID))
					require.NoError(t, err)
					t.Cleanup(func() {
						_, err := db.GetEngine(context.WithoutCancel(t.Context())).Exec("DROP TRIGGER refuse_lfs_base")
						require.NoError(t, err)
					})
				}
				if mode == "wrong-size" {
					require.NoError(t, os.WriteFile(filepath.Join(storeRoot, pointer.RelativePath()), payload[:len(payload)-1], 0o600))
				}
				if mode == "storage-error" {
					prefix := filepath.Join(storeRoot, pointer.Oid[:2])
					require.NoError(t, os.RemoveAll(prefix))
					require.NoError(t, os.WriteFile(prefix, []byte("not a directory"), 0o600))
				}
				if mode == "sql-failure" {
					_, err := db.GetEngine(ctx).Exec(fmt.Sprintf("CREATE TRIGGER refuse_lfs_base BEFORE INSERT ON lfs_meta_object WHEN NEW.repository_id=%d BEGIN SELECT RAISE(ABORT, 'actual LFS association failure'); END", base.ID))
					require.NoError(t, err)
					t.Cleanup(func() {
						_, err := db.GetEngine(context.WithoutCancel(t.Context())).Exec("DROP TRIGGER refuse_lfs_base")
						require.NoError(t, err)
					})
				}
				var hookCalls atomic.Int64
				privateHandler := http.StripPrefix("/api/internal", private_router.Routes())
				server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
					hookCalls.Add(1)
					privateHandler.ServeHTTP(w, r.WithContext(web_middleware.WithContextData(r.Context())))
				}))
				t.Cleanup(server.Close)
				currentUser, err := osuser.Current()
				require.NoError(t, err)
				config := fmt.Sprintf("RUN_USER = %s\nRUN_MODE = prod\n[server]\nPROTOCOL = http\nLOCAL_ROOT_URL = %s/\nAPP_DATA_PATH = %s\n[repository]\nROOT = %s\n[security]\nINSTALL_LOCK = true\nINTERNAL_TOKEN = %s\n[log]\nMODE = console\nLEVEL = fatal\n", currentUser.Username, server.URL, setting.AppDataPath, setting.RepoRootPath, setting.InternalToken)
				require.NoError(t, os.WriteFile(setting.CustomConf, []byte(config), 0o600))
				require.NoError(t, repo_module.CreateDelegateHooks(base.RepoPath()))
				t.Cleanup(func() {
					require.NoError(t, queue.GetManager().FlushAll(context.WithoutCancel(t.Context()), 30*time.Second))
				})
				body, err := json.Marshal(extension.CallbackRequest{Operation: extension.OperationRepositoryMergeSnapshot, RepositoryID: strconv.FormatInt(base.ID, 10), Authority: fixture.authority, MergeSnapshot: &extension.RepositoryMergeSnapshotRequest{Index: "1", Method: method}})
				require.NoError(t, err)
				r := httptest.NewRequest("POST", extension.NativeCallbackPath, bytes.NewReader(body))
				r.Header.Set("Content-Type", "application/json")
				r.Header.Set(extension.AdmissionHeader, fixture.token)
				w := httptest.NewRecorder()
				CallbackHandlerForInstance("source-test").ServeHTTP(w, r)
				require.Equal(t, 200, w.Code, w.Body.String())
				var response extension.CallbackResponse
				require.NoError(t, json.Unmarshal(w.Body.Bytes(), &response))
				require.NotNil(t, response.MergeSnapshot)
				require.Equal(t, "allowed", response.MergeSnapshot.Action.State)
				operation, err := extension.HumanMergeOperationID("2", strconv.FormatInt(base.ID, 10), "lfs-"+method+"-"+mode)
				require.NoError(t, err)
				q := extension.HumanMergeRequest{OperationID: operation, Expected: *response.MergeSnapshot, Message: "Native LFS human merge 🌋\n", NotAfter: time.Now().Add(time.Minute).Unix()}
				svc := nativeoperation_service.Default()
				if mode == "ordinary" {
					// The ordinary post-receive hook enqueues native push work.
					// Initialize that actual service with owned disposable paths.
					oldUploads := setting.Repository.Upload.TempPath
					setting.Repository.Upload.TempPath = filepath.Join(t.TempDir(), "uploads")
					t.Cleanup(func() { setting.Repository.Upload.TempPath = oldUploads })
					require.NoError(t, repo_service.Init(ctx))
					actor := unittest.AssertExistsAndLoadBean(t, &user_model.User{ID: 2})
					native, err := git.OpenRepository(ctx, base.RepoPath())
					require.NoError(t, err)
					defer native.Close()
					require.NoError(t, pull_service.Merge(ctx, pr, actor, native, repo_model.MergeStyleSquash, head, "Ordinary native LFS merge\n", false))
					meta, err := git_model.GetLFSMetaObjectByOid(ctx, base.ID, pointer.Oid)
					require.NoError(t, err)
					require.Equal(t, pointer, meta.Pointer)
					merged, err := issues_model.GetPullRequestByID(ctx, pr.ID)
					require.NoError(t, err)
					require.True(t, merged.HasMerged)
					require.Equal(t, merged.MergedCommitID, sourceTestGit(t, base.RepoPath(), nil, "rev-parse", "refs/heads/main"))
					require.NoError(t, queue.GetManager().FlushAll(context.WithoutCancel(t.Context()), 30*time.Second))
					reservation, err := nativeoperation_model.ReadReservation(ctx)
					require.NoError(t, err)
					require.Empty(t, reservation.Owner)
					t.Log("ordinary native merge uses the same LFS payload/association engine under its held execution and releases ownership")
					return
				}
				var intervention atomic.Bool
				var partialStore *humanMergeLFSStorage
				if mode == "partial-sql" {
					partialStore = &humanMergeLFSStorage{ObjectStorage: realStore}
					storage.LFS = partialStore
				}
				if strings.HasSuffix(mode, "-at-store") {
					storage.LFS = &humanMergeLFSStorage{ObjectStorage: realStore, afterStat: func() {
						intervention.Store(true)
						switch mode {
						case "cancel-at-store":
							_, err := svc.Cancel(t.Context(), humanMergeProcessInstallation, operation)
							require.NoError(t, err)
						case "session-at-store":
							fixture.session.uid = 1
						case "context-at-store":
							cancel()
						}
					}}
				}
				admit := func(ctx context.Context) error {
					_, status := resolveCurrentUser(ctx, nativeAdmissions.get(fixture.token))
					if status != 200 {
						return nativeoperation_service.ErrAuthorityLost
					}
					return nil
				}
				_, submitErr := repo_service.SubmitHumanMerge(ctx, svc, humanMergeProcessInstallation, q, admit)
				require.NoError(t, queue.GetManager().FlushAll(context.WithoutCancel(t.Context()), 30*time.Second))
				if mode == "session-at-store" || mode == "context-at-store" {
					require.ErrorIs(t, submitErr, nativeoperation_service.ErrAuthorityLost)
				} else {
					require.NoError(t, submitErr)
				}
				if strings.HasSuffix(mode, "-at-store") {
					require.True(t, intervention.Load())
				}
				fixture.session.uid = 2
				op, err := nativeoperation_model.LookupOperation(t.Context(), humanMergeProcessInstallation, operation)
				require.NoError(t, err)
				require.NotNil(t, op)
				meta, metaErr := git_model.GetLFSMetaObjectByOid(t.Context(), base.ID, pointer.Oid)
				success := mode == "valid" || mode == "same-repo"
				if success {
					require.Equal(t, nativeoperation_model.EffectCommitted, op.EffectState)
					require.Equal(t, nativeoperation_model.CompletionComplete, op.Completion)
					require.NoError(t, metaErr)
					require.Equal(t, pointer, meta.Pointer)
					require.Positive(t, hookCalls.Load())
					var receipt extension.HumanMergeReceipt
					require.NoError(t, json.Unmarshal([]byte(op.Receipt), &receipt))
					require.True(t, extension.ValidHumanMergeReceipt(receipt, q))
					require.Equal(t, receipt.ResultOID, sourceTestGit(t, base.RepoPath(), nil, "rev-parse", "refs/heads/main"))
					require.Equal(t, pointer.StringContent(), sourceTestGit(t, base.RepoPath(), nil, "show", receipt.ResultOID+":payload.bin")+"\n")
					object, err := lfs.NewContentStore().Get(pointer)
					require.NoError(t, err)
					actual, err := io.ReadAll(object)
					require.NoError(t, err)
					require.NoError(t, object.Close())
					require.Equal(t, payload, actual)
				} else {
					require.Equal(t, nativeoperation_model.EffectNotCommitted, op.EffectState, "missing/refused LFS must stop before native admission")
					require.False(t, op.Admitted)
					require.Empty(t, op.Receipt)
					require.Empty(t, op.Completion)
					if mode == "partial-sql" {
						var associated []git_model.LFSMetaObject
						require.NoError(t, db.GetEngine(t.Context()).Where("repository_id=?", base.ID).Find(&associated))
						require.Len(t, associated, 1)
						require.True(t, associated[0].Pointer == pointer || associated[0].Pointer == secondPointer)
						require.GreaterOrEqual(t, partialStore.statCalls.Load(), int64(2))
					} else {
						require.ErrorIs(t, metaErr, git_model.ErrLFSObjectNotExist)
					}
					require.Zero(t, hookCalls.Load(), "native Git hooks ran after an LFS refusal")
					require.Equal(t, fixture.base, sourceTestGit(t, base.RepoPath(), nil, "rev-parse", "refs/heads/main"))
				}
				reservation, err := nativeoperation_model.ReadReservation(t.Context())
				require.NoError(t, err)
				require.Empty(t, reservation.Owner)
				beforeHooks := hookCalls.Load()
				var beforeStat int64
				if partialStore != nil {
					beforeStat = partialStore.statCalls.Load()
				}
				replay, err := repo_service.SubmitHumanMerge(t.Context(), svc, humanMergeProcessInstallation, q, admit)
				require.NoError(t, err)
				require.Equal(t, op.EffectState, replay.EffectState)
				require.Equal(t, op.Completion, replay.CompletionState)
				require.Equal(t, op.Receipt, string(replay.Receipt))
				require.Equal(t, beforeHooks, hookCalls.Load())
				if partialStore != nil {
					require.Equal(t, beforeStat, partialStore.statCalls.Load(), "replay repeated LFS storage I/O")
					count, err := db.GetEngine(t.Context()).Where("repository_id=?", base.ID).Count(new(git_model.LFSMetaObject))
					require.NoError(t, err)
					require.EqualValues(t, 1, count)
				}
				t.Logf("native LFS %s/%s: effect=%s completion=%s payload=%d bytes; native hooks=%d and replay unchanged", mode, method, op.EffectState, op.Completion, pointer.Size, hookCalls.Load())
			})
		}
	}
}

func runManualMergeSnapshot(t *testing.T, primaryCase string) {
	t.Helper()
	// Keep the selected commit far from wall-clock time so ORM timestamp
	// substitution cannot pass when both operations happen in the same second.
	t.Setenv("GIT_AUTHOR_DATE", "2001-02-03T04:05:06Z")
	t.Setenv("GIT_COMMITTER_DATE", "2001-02-03T04:05:06Z")
	fixture := newSourceTestFixture(t)
	ctx := t.Context()
	owner := unittest.AssertExistsAndLoadBean(t, &user_model.User{ID: 1})
	repo := &repo_model.Repository{OwnerID: owner.ID, OwnerName: owner.Name, Name: "manual-merge-preparation", LowerName: "manual-merge-preparation", IsPrivate: true, DefaultBranch: "main", ObjectFormatName: "sha1"}
	_, err := db.GetEngine(ctx).Insert(repo)
	require.NoError(t, err)
	require.NoError(t, os.MkdirAll(filepath.Dir(repo.RepoPath()), 0o700))
	sourceTestGit(t, fixture.work, nil, "clone", "--bare", fixture.work, repo.RepoPath())
	ref := func(name, value string) {
		t.Helper()
		sourceTestGit(t, repo.RepoPath(), nil, "update-ref", name, value)
	}
	ref("refs/heads/main", fixture.tip)
	ref("refs/heads/alternate", fixture.tip)
	prUnit := &repo_model.RepoUnit{RepoID: repo.ID, Type: unit.TypePullRequests, Config: &repo_model.PullRequestsConfig{AllowManualMerge: true}}
	codeUnit := &repo_model.RepoUnit{RepoID: repo.ID, Type: unit.TypeCode}
	access := &access_model.Access{RepoID: repo.ID, UserID: 2, Mode: perm.AccessModeWrite}
	collab := &repo_model.Collaboration{RepoID: repo.ID, UserID: 2, Mode: perm.AccessModeWrite}
	_, err = db.GetEngine(ctx).Insert(prUnit, codeUnit, access, collab)
	require.NoError(t, err)
	issue := &issues_model.Issue{RepoID: repo.ID, Index: 1, PosterID: 1, IsPull: true, Title: "manual metadata preparation"}
	other := &issues_model.Issue{RepoID: repo.ID, Index: 2, PosterID: 1, Title: "ordinary issue"}
	_, err = db.GetEngine(ctx).Insert(issue, other)
	require.NoError(t, err)
	// No PR head ref is created. The source is deliberately private/unreadable.
	pr := &issues_model.PullRequest{IssueID: issue.ID, Index: 1, BaseRepoID: repo.ID, HeadRepoID: 6, BaseBranch: "main", HeadBranch: "manual-source-secret", MergeBase: fixture.base, Status: issues_model.PullRequestStatusMergeable, Flow: issues_model.PullRequestFlowGithub}
	_, err = db.GetEngine(ctx).Insert(pr)
	require.NoError(t, err)
	require.NotEqual(t, pr.ID, issue.ID)
	setMode := func(mode perm.AccessMode) {
		t.Helper()
		_, err := db.GetEngine(ctx).ID(access.ID).Cols("mode").Update(&access_model.Access{Mode: mode})
		require.NoError(t, err)
		_, err = db.GetEngine(ctx).ID(collab.ID).Cols("mode").Update(&repo_model.Collaboration{Mode: mode})
		require.NoError(t, err)
	}
	// Exercise the public SDK over its actual pinned private Unix transport.
	dir, err := os.MkdirTemp("", "fmms-")
	require.NoError(t, err)
	t.Cleanup(func() { _ = os.RemoveAll(dir) })
	socket := filepath.Join(dir, "native.sock")
	listener, err := net.Listen("unix", socket)
	require.NoError(t, err)
	server := &http.Server{Handler: CallbackHandlerForInstance("source-test")}
	go func() { _ = server.Serve(listener) }()
	t.Cleanup(func() { _ = server.Close() })
	t.Setenv(extension.CallbackEnv, socket)
	t.Setenv(extension.ServiceCallbackEnv, "")
	raw, err := json.Marshal(fixture.authority)
	require.NoError(t, err)
	request := httptest.NewRequest("GET", "/manual-preparation", nil)
	request.Header.Set(extension.ContextHeader, string(raw))
	request.Header.Set(extension.AdmissionHeader, fixture.token)
	authority, err := extension.RequestContext(request)
	require.NoError(t, err)
	repository := strconv.FormatInt(repo.ID, 10)
	q := extension.RepositoryManualMergeSnapshotRequest{Index: "1", CommitOID: fixture.base}
	_, err = nativeoperation_service.Default().ReadNativeRevision(ctx)
	require.NoError(t, err)
	counts := func() [4]int64 {
		t.Helper()
		var n [4]int64
		for i, bean := range []any{new(nativeoperation_model.Operation), new(issues_model.Comment), new(activities_model.Notification), new(activities_model.Action)} {
			n[i], err = db.GetEngine(ctx).Count(bean)
			require.NoError(t, err)
		}
		return n
	}
	before := counts()
	take := func(want string) extension.RepositoryManualMergeSnapshot {
		t.Helper()
		p, err := authority.RepositoryManualMergeSnapshot(ctx, repository, q)
		require.NoError(t, err)
		require.Equal(t, want, p.Action.State)
		require.Equal(t, repository, p.RepositoryID)
		require.Equal(t, "2", p.ActorID)
		require.Equal(t, strconv.FormatInt(pr.ID, 10), p.PullID)
		require.Equal(t, strconv.FormatInt(issue.ID, 10), p.IssueID)
		require.Equal(t, q.CommitOID, p.CommitOID)
		require.Positive(t, p.NativeRevision)
		raw, err := json.Marshal(p)
		require.NoError(t, err)
		require.NotContains(t, string(raw), "manual-source-secret")
		require.NotContains(t, string(raw), fixture.token)
		return p
	}
	start := fixture.session.reads
	p := take("allowed")
	if strings.HasPrefix(primaryCase, "merge-sdk:") {
		checkHumanManualMergeCompletion(t, fixture, repo, pr, issue, p, primaryCase)
		return
	}
	if strings.HasPrefix(primaryCase, "sdk:") {
		checkHumanManualMergeCompletion(t, fixture, repo, pr, issue, p, primaryCase)
		return
	}
	if strings.HasPrefix(primaryCase, "submit:") {
		checkHumanManualMergeCompletion(t, fixture, repo, pr, issue, p, primaryCase)
		return
	}
	if strings.HasPrefix(primaryCase, "process:") {
		checkHumanManualMergeCompletion(t, fixture, repo, pr, issue, p, primaryCase)
		return
	}
	if strings.HasPrefix(primaryCase, "complete:") {
		checkHumanManualMergeCompletion(t, fixture, repo, pr, issue, p, strings.TrimPrefix(primaryCase, "complete:"))
		return
	}
	if primaryCase != "" {
		checkHumanManualMergePrimary(t, fixture, repo, pr, issue, p, primaryCase)
		return
	}
	readCount := fixture.session.reads - start
	require.Equal(t, fixture.tip, p.BaseOID)
	require.NotEqual(t, p.BaseOID, p.CommitOID, "manual marking may select an older reachable commit")
	q.CommitOID = fixture.tip
	take("allowed")
	q.CommitOID = fixture.base
	for _, invalid := range []string{"HEAD", fixture.base[:12], strings.ToUpper(fixture.base), ""} {
		_, err := authority.RepositoryManualMergeSnapshot(ctx, repository, extension.RepositoryManualMergeSnapshotRequest{Index: "1", CommitOID: invalid})
		require.ErrorIs(t, err, extension.ErrManualMergeSnapshotQuery)
	}
	_, err = authority.RepositoryMergeSnapshot(ctx, repository, extension.RepositoryMergeSnapshotRequest{Index: "1", Method: string(repo_model.MergeStyleManuallyMerged)})
	require.ErrorIs(t, err, extension.ErrMergeSnapshotQuery, "manual marking must not enter the ref-push request type")
	for _, invalid := range []string{strings.Repeat("f", len(fixture.base)), sourceTestGit(t, repo.RepoPath(), nil, "rev-parse", fixture.tip+"^{tree}")} {
		_, err := authority.RepositoryManualMergeSnapshot(ctx, repository, extension.RepositoryManualMergeSnapshotRequest{Index: "1", CommitOID: invalid})
		require.ErrorIs(t, err, extension.ErrManualMergeSnapshotCommit)
	}
	require.NoError(t, os.WriteFile(filepath.Join(fixture.work, "README"), []byte("off-target commit\n"), 0o600))
	sourceTestGit(t, fixture.work, nil, "add", "README")
	sourceTestGit(t, fixture.work, nil, "commit", "-m", "off target")
	offTarget := sourceTestGit(t, fixture.work, nil, "rev-parse", "HEAD")
	sourceTestGit(t, repo.RepoPath(), nil, "fetch", fixture.work, "HEAD:refs/heads/off-target")
	_, err = authority.RepositoryManualMergeSnapshot(ctx, repository, extension.RepositoryManualMergeSnapshotRequest{Index: "1", CommitOID: offTarget})
	require.ErrorIs(t, err, extension.ErrManualMergeSnapshotCommit)
	sourceTestGit(t, repo.RepoPath(), nil, "tag", "-a", "manual-marker", "-m", "native annotated tag", fixture.base)
	tag := sourceTestGit(t, repo.RepoPath(), nil, "rev-parse", "refs/tags/manual-marker")
	_, err = authority.RepositoryManualMergeSnapshot(ctx, repository, extension.RepositoryManualMergeSnapshotRequest{Index: "1", CommitOID: tag})
	require.ErrorIs(t, err, extension.ErrManualMergeSnapshotCommit, "the SDK selects a commit OID, never a tag object")
	_, err = authority.RepositoryManualMergeSnapshot(ctx, repository, extension.RepositoryManualMergeSnapshotRequest{Index: "2", CommitOID: fixture.base})
	require.ErrorIs(t, err, extension.ErrRepositoryNotVisible)
	setMode(perm.AccessModeRead)
	take("denied")
	setMode(perm.AccessModeWrite)
	prUnit.PullRequestsConfig().AllowManualMerge = false
	_, err = db.GetEngine(ctx).ID(prUnit.ID).Cols("config").Update(prUnit)
	require.NoError(t, err)
	take("unsupported")
	prUnit.PullRequestsConfig().AllowManualMerge = true
	_, err = db.GetEngine(ctx).ID(prUnit.ID).Cols("config").Update(prUnit)
	require.NoError(t, err)
	_, err = db.GetEngine(ctx).ID(issue.ID).Cols("name").Update(&issues_model.Issue{Title: "WIP: manual metadata"})
	require.NoError(t, err)
	_, err = db.GetEngine(ctx).ID(pr.ID).Cols("status").Update(&issues_model.PullRequest{Status: issues_model.PullRequestStatusChecking})
	require.NoError(t, err)
	protection := &git_model.ProtectedBranch{RepoID: repo.ID, RuleName: "main", EnableStatusCheck: true, StatusCheckContexts: []string{"ci"}}
	_, err = db.GetEngine(ctx).Insert(protection)
	require.NoError(t, err)
	take("allowed") // Native manual marking skips draft/check/status gates.
	protection.EnableMergeWhitelist, protection.MergeWhitelistUserIDs = true, []int64{4}
	_, err = db.GetEngine(ctx).ID(protection.ID).Cols("enable_merge_whitelist", "merge_whitelist_user_i_ds").Update(protection)
	require.NoError(t, err)
	take("denied")
	_, err = db.GetEngine(ctx).ID(protection.ID).Delete(new(git_model.ProtectedBranch))
	require.NoError(t, err)
	_, err = db.GetEngine(ctx).ID(issue.ID).Cols("is_closed").Update(&issues_model.Issue{IsClosed: true})
	require.NoError(t, err)
	take("denied")
	_, err = db.GetEngine(ctx).ID(pr.ID).Cols("has_merged").Update(&issues_model.PullRequest{HasMerged: true})
	require.NoError(t, err)
	take("denied")
	_, err = db.GetEngine(ctx).ID(pr.ID).Cols("has_merged").Update(&issues_model.PullRequest{})
	require.NoError(t, err)
	_, err = db.GetEngine(ctx).ID(issue.ID).Cols("is_closed").Update(&issues_model.Issue{})
	require.NoError(t, err)
	_, err = db.GetEngine(ctx).ID(repo.ID).Cols("is_archived").Update(&repo_model.Repository{IsArchived: true})
	require.NoError(t, err)
	take("denied")
	_, err = db.GetEngine(ctx).ID(repo.ID).Cols("is_archived").Update(&repo_model.Repository{})
	require.NoError(t, err)
	require.NoError(t, nativeoperation_service.WithAuthorityOwnership(ctx, "manual-snapshot-busy", repo.ID, func(context.Context) error {
		_, err := authority.RepositoryManualMergeSnapshot(ctx, repository, q)
		require.ErrorIs(t, err, extension.ErrManualMergeSnapshotUnavailable)
		return nil
	}))
	for _, race := range []string{"ref", "branch", "permission", "revision", "session"} {
		start := fixture.session.reads
		changed := false
		fixture.session.onRead = func(n int) {
			if changed || n != start+readCount/2+1 {
				return
			}
			changed = true
			switch race {
			case "ref":
				ref("refs/heads/main", fixture.base)
			case "branch":
				_, err = db.GetEngine(ctx).ID(pr.ID).Cols("base_branch").Update(&issues_model.PullRequest{BaseBranch: "alternate"})
				require.NoError(t, err)
			case "permission":
				setMode(perm.AccessModeRead)
			case "revision":
				require.NoError(t, nativeoperation_service.WithAuthorityOwnership(ctx, "manual-snapshot-race", repo.ID, func(context.Context) error { return nil }))
			case "session":
				fixture.session.uid = 1
			}
		}
		_, err := authority.RepositoryManualMergeSnapshot(ctx, repository, q)
		if race == "session" {
			require.ErrorIs(t, err, extension.ErrManualMergeSnapshotAdmission)
		} else {
			require.ErrorIs(t, err, extension.ErrManualMergeSnapshotChanged, race)
		}
		require.True(t, changed, race)
		fixture.session.onRead, fixture.session.uid = nil, 2
		ref("refs/heads/main", fixture.tip)
		_, err = db.GetEngine(ctx).ID(pr.ID).Cols("base_branch").Update(pr)
		require.NoError(t, err)
		setMode(perm.AccessModeWrite)
	}
	sourceTestGit(t, repo.RepoPath(), nil, "update-ref", "-d", "refs/heads/main")
	_, err = authority.RepositoryManualMergeSnapshot(ctx, repository, q)
	require.ErrorIs(t, err, extension.ErrManualMergeSnapshotUnavailable)
	ref("refs/heads/main", fixture.tip)
	_, err = db.GetEngine(ctx).ID(codeUnit.ID).Delete(new(repo_model.RepoUnit))
	require.NoError(t, err)
	_, err = authority.RepositoryManualMergeSnapshot(ctx, repository, q)
	require.ErrorIs(t, err, extension.ErrRepositoryNotVisible)
	_, err = db.GetEngine(ctx).Insert(codeUnit)
	require.NoError(t, err)
	delete(nativeAdmissions.get(fixture.token).capabilities, extension.CapabilityRepositoryRead)
	_, err = authority.RepositoryManualMergeSnapshot(ctx, repository, q)
	require.ErrorIs(t, err, extension.ErrManualMergeSnapshotAdmission)
	nativeAdmissions.get(fixture.token).capabilities[extension.CapabilityRepositoryRead] = struct{}{}
	take("allowed")
	require.Equal(t, before, counts(), "manual preparation created operation/history/notification/feed effects")
	require.Equal(t, fixture.tip, sourceTestGit(t, repo.RepoPath(), nil, "rev-parse", "refs/heads/main"))
	current, err := issues_model.GetPullRequestByID(ctx, pr.ID)
	require.NoError(t, err)
	require.False(t, current.HasMerged)
	t.Log("actual SDK/private Unix manual preparation: exact PR/issue/target/reachable commit, native manual eligibility without source/head/draft/CI prerequisites, permission/policy/closed/archive/busy and Git/identity/revision/session races; no write/ref effects")
	// Regression for the existing defining writer after extracting its commit
	// rule. Its ordinary full tag-object selection still resolves canonically;
	// the new SDK intentionally selects only an explicit commit OID.
	actor := unittest.AssertExistsAndLoadBean(t, &user_model.User{ID: 2})
	permission, err := access_model.GetUserRepoPermission(ctx, repo, actor)
	require.NoError(t, err)
	require.NoError(t, pull_service.CheckPullMergeable(ctx, actor, &permission, current, pull_service.MergeCheckTypeManually, false))
	native, err := git.OpenRepository(ctx, repo.RepoPath())
	require.NoError(t, err)
	defer native.Close()
	selected, err := native.GetCommit(fixture.base)
	require.NoError(t, err)
	require.NoError(t, pull_service.MergedManually(ctx, current, actor, native, tag))
	marked, err := issues_model.GetPullRequestByID(ctx, pr.ID)
	require.NoError(t, err)
	require.NoError(t, marked.LoadIssue(ctx))
	require.True(t, marked.HasMerged)
	require.True(t, marked.Issue.IsClosed)
	require.Equal(t, issues_model.PullRequestStatusManuallyMerged, marked.Status)
	require.Equal(t, fixture.base, marked.MergedCommitID)
	require.Equal(t, actor.ID, marked.MergerID)
	require.EqualValues(t, selected.Author.When.Unix(), marked.MergedUnix)
	history, err := db.GetEngine(ctx).Where("issue_id=? AND type=?", issue.ID, issues_model.CommentTypeMergePull).Count(new(issues_model.Comment))
	require.NoError(t, err)
	require.EqualValues(t, 1, history)
	reservation, err := nativeoperation_model.ReadReservation(ctx)
	require.NoError(t, err)
	require.Empty(t, reservation.Owner)
	require.Equal(t, fixture.tip, sourceTestGit(t, repo.RepoPath(), nil, "rev-parse", "refs/heads/main"))
	take("denied")
	t.Log("ordinary manual writer retains shared native commit resolution, commit-author timestamp, manual status/history, closed PR and unchanged Git target")
}

func checkHumanManualMergePrimary(t *testing.T, fixture sourceTestFixture, repo *repo_model.Repository, pr *issues_model.PullRequest, issue *issues_model.Issue, p extension.RepositoryManualMergeSnapshot, mode string) {
	t.Helper()
	oldData := setting.AppDataPath
	setting.AppDataPath = t.TempDir()
	t.Cleanup(func() { setting.AppDataPath = oldData })
	ctx, cancel := context.WithCancel(t.Context())
	t.Cleanup(cancel)
	svc := nativeoperation_service.NewService()
	operation, err := extension.HumanManualMergeOperationID(p.ActorID, p.RepositoryID, "manual-primary-"+mode)
	require.NoError(t, err)
	q := extension.HumanManualMergeRequest{OperationID: operation, Expected: p, NotAfter: time.Now().Add(time.Minute).Unix()}
	canonical, digest, err := extension.CanonicalHumanManualMergeIntent(q)
	require.NoError(t, err)
	owner := "cond:" + humanMergeProcessInstallation + "/" + operation
	t.Cleanup(func() {
		held, err := nativeoperation_model.ReadReservation(context.WithoutCancel(t.Context()))
		require.NoError(t, err)
		if held.Owner == owner {
			require.NoError(t, nativeoperation_model.ReleaseExactOwner(context.WithoutCancel(t.Context()), owner, held.Generation))
		}
	}) // Disposal of this owned fixture only; not product recovery/completion.
	beforeTip := sourceTestGit(t, repo.RepoPath(), nil, "rev-parse", "refs/heads/main")
	if mode == "stale-ref" {
		sourceTestGit(t, repo.RepoPath(), nil, "update-ref", "refs/heads/main", fixture.base)
	}
	if mode == "reader" {
		_, err := db.GetEngine(t.Context()).Where("repo_id=? AND user_id=?", repo.ID, 2).Cols("mode").Update(&access_model.Access{Mode: perm.AccessModeRead})
		require.NoError(t, err)
		_, err = db.GetEngine(t.Context()).Where("repo_id=? AND user_id=?", repo.ID, 2).Cols("mode").Update(&repo_model.Collaboration{Mode: perm.AccessModeRead})
		require.NoError(t, err)
	}
	if mode == "disabled" {
		unit, err := repo.GetUnit(t.Context(), unit.TypePullRequests)
		require.NoError(t, err)
		unit.PullRequestsConfig().AllowManualMerge = false
		_, err = db.GetEngine(t.Context()).ID(unit.ID).Cols("config").Update(unit)
		require.NoError(t, err)
	}
	if mode == "sql-rollback" {
		_, err := db.GetEngine(t.Context()).Exec(fmt.Sprintf("CREATE TRIGGER fail_manual_primary BEFORE UPDATE OF has_merged ON pull_request WHEN NEW.id=%d BEGIN SELECT RAISE(ABORT, 'manual primary rollback'); END", pr.ID))
		require.NoError(t, err)
		t.Cleanup(func() {
			_, err := db.GetEngine(context.WithoutCancel(t.Context())).Exec("DROP TRIGGER fail_manual_primary")
			require.NoError(t, err)
		})
	}
	if mode == "cancel-before-submit" {
		_, err := svc.Cancel(t.Context(), humanMergeProcessInstallation, operation)
		require.NoError(t, err)
	}
	if mode == "expiry" {
		q.NotAfter = time.Now().Add(2 * time.Second).Unix()
		canonical, digest, err = extension.CanonicalHumanManualMergeIntent(q)
		require.NoError(t, err)
	}
	var intervened bool
	admit := func(c context.Context) error {
		op, err := nativeoperation_model.LookupOperation(c, humanMergeProcessInstallation, operation)
		if err != nil {
			return err
		}
		if op != nil && op.Submitted && !intervened {
			current, err := issues_model.GetPullRequestByID(c, pr.ID)
			if err != nil {
				return err
			}
			switch {
			case !db.InTransaction(c) && mode == "cancel":
				intervened = true
				_, err = svc.Cancel(c, humanMergeProcessInstallation, operation)
			case !db.InTransaction(c) && mode == "expiry":
				intervened = true
				time.Sleep(time.Until(time.Unix(q.NotAfter, 0)))
			case !db.InTransaction(c) && mode == "context":
				intervened = true
				cancel()
			case !db.InTransaction(c) && mode == "tamper":
				intervened = true
				_, err = db.GetEngine(c).ID(op.ID).Cols("intent_digest").Update(&nativeoperation_model.Operation{IntentDigest: "tampered"})
			case !db.InTransaction(c) && mode == "generation":
				intervened = true
				held, e := nativeoperation_model.ReadReservation(c)
				if e != nil {
					return e
				}
				_, err = db.GetEngine(c).ID(1).Cols("generation").Update(&nativeoperation_model.Reservation{Generation: held.Generation + 1})
			case db.InTransaction(c) && current.HasMerged && mode == "session-in-primary":
				intervened = true
				fixture.session.uid = 1
			case db.InTransaction(c) && current.HasMerged && mode == "ref-in-primary":
				intervened = true
				sourceTestGit(t, repo.RepoPath(), nil, "update-ref", "refs/heads/main", fixture.base)
			}
			if err != nil {
				return err
			}
		}
		_, status := resolveCurrentUser(c, nativeAdmissions.get(fixture.token))
		if status != 200 {
			return nativeoperation_service.ErrAuthorityLost
		}
		return nil
	}
	if mode == "session-before-submit" {
		fixture.session.uid = 1
	}
	var submitErr error
	if mode == "outer-transaction" {
		require.NoError(t, db.WithTx(ctx, func(tx context.Context) error {
			_, err := svc.SubmitHumanManualMergePrimary(tx, humanMergeProcessInstallation, q, admit)
			require.ErrorIs(t, err, nativeoperation_service.ErrInvalidIntent)
			return nil
		}))
	} else {
		_, submitErr = svc.SubmitHumanManualMergePrimary(ctx, humanMergeProcessInstallation, q, admit)
	}
	fixture.session.uid = 2
	op, err := nativeoperation_model.LookupOperation(t.Context(), humanMergeProcessInstallation, operation)
	require.NoError(t, err)
	if mode == "session-before-submit" || mode == "outer-transaction" {
		if mode == "session-before-submit" {
			require.ErrorIs(t, submitErr, nativeoperation_service.ErrAuthorityLost)
		}
		require.Nil(t, op)
		return
	}
	require.NotNil(t, op)
	if mode == "cancel-before-submit" {
		require.ErrorIs(t, submitErr, nativeoperation_service.ErrCancelledBeforeSubmit)
		require.False(t, op.Submitted)
		return
	}
	if mode != "tamper" {
		require.Equal(t, digest, op.IntentDigest)
	}
	require.Equal(t, canonical, op.Intent)
	require.Equal(t, nativeoperation_model.KindHumanManualMerge, op.Kind)
	require.Zero(t, op.TokenID)
	require.Empty(t, op.CredentialFingerprint)
	held, err := nativeoperation_model.ReadReservation(t.Context())
	require.NoError(t, err)
	current, err := issues_model.GetPullRequestByID(t.Context(), pr.ID)
	require.NoError(t, err)
	currentIssue, err := issues_model.GetIssueByID(t.Context(), issue.ID)
	require.NoError(t, err)
	history, err := db.GetEngine(t.Context()).Where("issue_id=? AND type=?", issue.ID, issues_model.CommentTypeMergePull).Count(new(issues_model.Comment))
	require.NoError(t, err)
	files, err := filepath.Glob(filepath.Join(setting.AppDataPath, "nativeop-exec", "*"))
	require.NoError(t, err)
	if mode == "valid" {
		require.NoError(t, submitErr)
		require.Equal(t, nativeoperation_model.EffectCommitted, op.EffectState)
		require.True(t, op.Admitted)
		require.Equal(t, nativeoperation_model.CompletionPending, op.Completion)
		require.Equal(t, owner, held.Owner)
		require.Len(t, files, 1)
		require.True(t, current.HasMerged)
		require.True(t, currentIssue.IsClosed)
		require.Equal(t, issues_model.PullRequestStatusManuallyMerged, current.Status)
		require.EqualValues(t, 1, history)
		var receipt extension.HumanManualMergeReceipt
		require.NoError(t, json.Unmarshal([]byte(op.Receipt), &receipt))
		require.True(t, extension.ValidHumanManualMergeReceipt(receipt, q))
		require.Equal(t, q.Expected.CommitOID, current.MergedCommitID)
		native, err := git.OpenRepository(t.Context(), repo.RepoPath())
		require.NoError(t, err)
		selected, err := native.GetCommit(q.Expected.CommitOID)
		require.NoError(t, err)
		native.Close()
		t.Logf("manual timestamps: Git=%d receipt=%d stored=%d", selected.Author.When.Unix(), receipt.MergedUnix, current.MergedUnix)
		require.EqualValues(t, time.Date(2001, 2, 3, 4, 5, 6, 0, time.UTC).Unix(), receipt.MergedUnix)
		require.EqualValues(t, receipt.MergedUnix, current.MergedUnix)
		require.EqualValues(t, receipt.ClosedUnix, currentIssue.ClosedUnix)
		comment, err := issues_model.GetCommentByID(t.Context(), receipt.HistoryID)
		require.NoError(t, err)
		require.EqualValues(t, 2, comment.PosterID)
		require.Equal(t, issue.ID, comment.IssueID)
		require.Equal(t, issues_model.CommentTypeMergePull, comment.Type)
		_, err = svc.Submit(t.Context(), extensionauth_model.SubmissionDecision{}, humanMergeProcessInstallation, &nativeoperation_service.ValidIntent{Kind: nativeoperation_model.KindHumanManualMerge})
		require.ErrorIs(t, err, nativeoperation_service.ErrKindUnavailable)
		changed := q
		changed.Expected.CommitOID = fixture.tip
		_, err = svc.SubmitHumanManualMergePrimary(t.Context(), humanMergeProcessInstallation, changed, admit)
		require.ErrorIs(t, err, nativeoperation_service.ErrIntentConflict)
		cancelled, err := svc.Cancel(t.Context(), humanMergeProcessInstallation, operation)
		require.NoError(t, err)
		require.Equal(t, nativeoperation_model.CancellationTooLate, cancelled.CancellationStatus)
		op, err = nativeoperation_model.LookupOperation(t.Context(), humanMergeProcessInstallation, operation)
		require.NoError(t, err)
		require.True(t, op.Revoked)
	} else {
		require.False(t, current.HasMerged)
		require.False(t, currentIssue.IsClosed)
		require.Zero(t, history)
		require.False(t, op.Admitted)
		require.Empty(t, op.Receipt)
		retained := mode == "sql-rollback" || mode == "tamper" || mode == "generation"
		if retained {
			require.Error(t, submitErr)
			require.Equal(t, nativeoperation_model.EffectPending, op.EffectState)
			require.Equal(t, owner, held.Owner)
			require.Len(t, files, 1)
		} else {
			if mode == "context" || mode == "session-in-primary" {
				require.ErrorIs(t, submitErr, nativeoperation_service.ErrAuthorityLost)
			} else {
				require.NoError(t, submitErr)
			}
			require.Equal(t, nativeoperation_model.EffectNotCommitted, op.EffectState)
			require.Empty(t, held.Owner)
			require.Empty(t, files)
		}
		if mode == "cancel" {
			require.Equal(t, nativeoperation_model.CancellationCancelled, op.Cancellation)
		}
	}
	expectedTip := beforeTip
	if mode == "stale-ref" || mode == "ref-in-primary" {
		expectedTip = fixture.base
	}
	require.Equal(t, expectedTip, sourceTestGit(t, repo.RepoPath(), nil, "rev-parse", "refs/heads/main"))
	if mode != "tamper" {
		replay, err := svc.SubmitHumanManualMergePrimary(t.Context(), humanMergeProcessInstallation, q, admit)
		require.NoError(t, err)
		require.Equal(t, op.Receipt, string(replay.Receipt))
		require.Equal(t, op.EffectState, replay.EffectState)
		require.Equal(t, op.Completion, replay.CompletionState)
	}
	afterHistory, err := db.GetEngine(t.Context()).Where("issue_id=? AND type=?", issue.ID, issues_model.CommentTypeMergePull).Count(new(issues_model.Comment))
	require.NoError(t, err)
	require.Equal(t, history, afterHistory)
	if mode == "cancel" || mode == "expiry" || mode == "context" || mode == "tamper" || mode == "generation" || mode == "session-in-primary" || mode == "ref-in-primary" {
		require.True(t, intervened)
	}
	t.Logf("native manual primary %s: effect=%s completion=%s; exact SQL/history/receipt, retained replay and unchanged command-owned Git", mode, op.EffectState, op.Completion)
}

func checkHumanManualMergeCompletion(t *testing.T, fixture sourceTestFixture, repo *repo_model.Repository, pr *issues_model.PullRequest, issue *issues_model.Issue, p extension.RepositoryManualMergeSnapshot, mode string) {
	t.Helper()
	ctx := t.Context()
	oldData := setting.AppDataPath
	setting.AppDataPath = t.TempDir()
	t.Cleanup(func() { setting.AppDataPath = oldData })
	actor := unittest.AssertExistsAndLoadBean(t, &user_model.User{ID: 2})
	_, err := db.GetEngine(ctx).Insert(&repo_model.RepoUnit{RepoID: repo.ID, Type: unit.TypeIssues}, &access_model.Access{RepoID: repo.ID, UserID: 4, Mode: perm.AccessModeRead}, &repo_model.Collaboration{RepoID: repo.ID, UserID: 4, Mode: perm.AccessModeRead}, &repo_model.Watch{UserID: 4, RepoID: repo.ID, Mode: repo_model.WatchModeNormal})
	require.NoError(t, err)
	var target issues_model.Issue
	found, err := db.GetEngine(ctx).Where("repo_id=? AND `index`=?", repo.ID, 2).Get(&target)
	require.NoError(t, err)
	require.True(t, found)
	_, err = db.GetEngine(ctx).ID(issue.ID).Cols("content").Update(&issues_model.Issue{Content: "closes #2"})
	require.NoError(t, err)
	origin, err := issues_model.GetIssueByID(ctx, issue.ID)
	require.NoError(t, err)
	origin.Repo = repo
	require.NoError(t, origin.AddCrossReferences(ctx, actor, false))
	pr.Issue = origin
	refs, err := pr.ResolveCrossReferences(ctx)
	require.NoError(t, err)
	require.Len(t, refs, 1)
	require.Equal(t, target.ID, refs[0].IssueID)
	if !strings.HasPrefix(mode, "process:") {
		// The owned process fixture starts the sole native queue writer in its
		// child; opening that same queue store here would hold its LevelDB lock.
		for _, notifier := range []notify_service.Notifier{uinotification.NewNotifier(), feed.NewNotifier()} {
			notify_service.RegisterNotifier(notifier)
			t.Cleanup(func() { notify_service.UnregisterNotifier(notifier) })
		}
	}
	t.Cleanup(func() { require.NoError(t, queue.GetManager().FlushAll(context.WithoutCancel(ctx), 5*time.Second)) })
	var reopen func()
	if strings.HasPrefix(mode, "recovery:") {
		// Save the native fixture before executing the actual primary. All writes
		// below land in this private file, which recovery will close and reopen.
		require.NoError(t, queue.GetManager().FlushAll(ctx, 5*time.Second))
		root := t.TempDir()
		_, err := db.GetEngine(ctx).Exec("VACUUM INTO ?", filepath.Join(root, "native.sqlite"))
		require.NoError(t, err)
		previous := db.DefaultContext.(db.Engined).Engine()
		engine := openHumanMergeProcessDatabase(t, root)
		t.Cleanup(func() { db.SetDefaultEngine(context.Background(), previous); require.NoError(t, engine.Close()) })
		reopen = func() {
			require.NoError(t, queue.GetManager().FlushAll(ctx, 5*time.Second))
			require.NoError(t, engine.Close())
			engine = openHumanMergeProcessDatabase(t, root)
		}
	}
	svc := nativeoperation_service.NewService()
	operation, err := extension.HumanManualMergeOperationID(p.ActorID, p.RepositoryID, "manual-complete-"+mode)
	require.NoError(t, err)
	q := extension.HumanManualMergeRequest{OperationID: operation, Expected: p, NotAfter: time.Now().Add(time.Minute).Unix()}
	if mode == "expired-after-primary" {
		q.NotAfter = time.Now().Add(2 * time.Second).Unix()
	}
	admit := func(c context.Context) error {
		_, status := resolveCurrentUser(c, nativeAdmissions.get(fixture.token))
		if status != 200 {
			return nativeoperation_service.ErrAuthorityLost
		}
		return nil
	}
	if strings.HasPrefix(mode, "submit:") {
		checkHumanManualMergeSubmit(t, fixture, repo, pr, issue, &target, q, admit, strings.TrimPrefix(mode, "submit:"))
		return
	}
	if strings.HasPrefix(mode, "sdk:") {
		checkHumanManualMergeSDK(t, fixture, repo, pr, issue, &target, q, strings.TrimPrefix(mode, "sdk:"))
		return
	}
	if strings.HasPrefix(mode, "merge-sdk:") {
		parts := strings.SplitN(strings.TrimPrefix(mode, "merge-sdk:"), ":", 2)
		require.Len(t, parts, 2)
		prepareHumanMergeSDK(t, fixture, repo, pr, issue, &target, parts[0], parts[1])
		return
	}
	if strings.HasPrefix(mode, "process:") {
		checkHumanManualMergeProcess(t, fixture, repo, pr, issue, &target, q, strings.TrimPrefix(mode, "process:"))
		return
	}
	pending := mode == "recovery:pending" || mode == "recovery:pending-cancelled" || mode == "recovery:pending-contradiction"
	if pending {
		_, err := db.GetEngine(ctx).Exec(fmt.Sprintf("CREATE TRIGGER fail_recovered_manual_primary BEFORE UPDATE OF has_merged ON pull_request WHEN NEW.id=%d BEGIN SELECT RAISE(ABORT, 'stopped manual primary rollback'); END", pr.ID))
		require.NoError(t, err)
	}
	primary, err := svc.SubmitHumanManualMergePrimary(ctx, humanMergeProcessInstallation, q, admit)
	if pending {
		require.Error(t, err)
		_, err := db.GetEngine(ctx).Exec("DROP TRIGGER fail_recovered_manual_primary")
		require.NoError(t, err)
		lookup, err := svc.Get(ctx, humanMergeProcessInstallation, operation)
		require.NoError(t, err)
		require.NotNil(t, lookup.Record)
		primary = *lookup.Record
		require.Equal(t, nativeoperation_model.EffectPending, primary.EffectState)
	} else {
		require.NoError(t, err)
		require.Equal(t, nativeoperation_model.CompletionPending, primary.CompletionState)
	}
	held, err := nativeoperation_model.ReadReservation(ctx)
	require.NoError(t, err)
	t.Cleanup(func() {
		current, err := nativeoperation_model.ReadReservation(context.WithoutCancel(ctx))
		require.NoError(t, err)
		if current.Owner == held.Owner {
			require.NoError(t, nativeoperation_model.ReleaseExactOwner(context.WithoutCancel(ctx), current.Owner, current.Generation))
		}
	}) // Disposal of this owned fixture only, never product recovery.
	files, err := filepath.Glob(filepath.Join(setting.AppDataPath, "nativeop-exec", "*"))
	require.NoError(t, err)
	require.Len(t, files, 1)
	x := &execcontext.Execution{Owner: held.Owner, Generation: held.Generation, CapabilityPath: files[0]}
	owned := execcontext.NewContext(ctx, x)
	if strings.HasPrefix(mode, "recovery:") {
		checkHumanManualMergeRecovery(t, fixture, repo, pr, issue, &target, q, primary, held, x, reopen, strings.TrimPrefix(mode, "recovery:"))
		return
	}
	_, err = svc.CompleteHumanManualMerge(owned, humanMergeProcessInstallation, q)
	require.ErrorIs(t, err, nativeoperation_service.ErrHumanManualMergeCompletionNotReady)
	changed := q
	changed.Expected.CommitOID = fixture.tip
	_, err = svc.FinishHumanManualMerge(owned, humanMergeProcessInstallation, changed)
	require.Error(t, err)
	require.NoError(t, db.WithTx(owned, func(tx context.Context) error {
		_, err := svc.FinishHumanManualMerge(tx, humanMergeProcessInstallation, q)
		require.ErrorIs(t, err, nativeoperation_service.ErrInvalidIntent)
		_, err = svc.CompleteHumanManualMerge(tx, humanMergeProcessInstallation, q)
		require.ErrorIs(t, err, nativeoperation_service.ErrInvalidIntent)
		return nil
	}))
	var receipt extension.HumanManualMergeReceipt
	require.NoError(t, json.Unmarshal(primary.Receipt, &receipt))
	err = nil
	switch mode {
	case "stale-target":
		sourceTestGit(t, repo.RepoPath(), nil, "update-ref", "refs/heads/main", fixture.base)
	case "changed-metadata":
		_, err = db.GetEngine(ctx).ID(pr.ID).Cols("status").Update(&issues_model.PullRequest{Status: issues_model.PullRequestStatusMergeable})
	case "changed-history":
		_, err = db.GetEngine(ctx).ID(receipt.HistoryID).Cols("poster_id").Update(&issues_model.Comment{PosterID: 1})
	case "changed-receipt":
		receipt.ClosedUnix++
		raw, e := json.Marshal(receipt)
		require.NoError(t, e)
		_, err = db.GetEngine(ctx).Where("operation_id=?", operation).Cols("receipt").Update(&nativeoperation_model.Operation{Receipt: string(raw)})
	case "wrong-generation":
		copy := *x
		copy.Generation++
		owned = execcontext.NewContext(ctx, &copy)
	case "missing-proof":
		err = os.Remove(files[0])
	case "scope-tamper":
		var scope nativeoperation_service.Scope
		require.NoError(t, json.Unmarshal([]byte(held.Scope), &scope))
		scope.Ref = "refs/heads/main"
		raw, e := json.Marshal(scope)
		require.NoError(t, e)
		_, err = db.GetEngine(ctx).ID(1).Cols("scope").Update(&nativeoperation_model.Reservation{Scope: string(raw)})
	case "cancelled-after-primary":
		cancelled, e := svc.Cancel(ctx, humanMergeProcessInstallation, operation)
		require.NoError(t, e)
		require.Equal(t, nativeoperation_model.CancellationTooLate, cancelled.CancellationStatus)
	case "expired-after-primary":
		time.Sleep(time.Until(time.Unix(q.NotAfter, 0)))
	case "partial":
		_, err = db.GetEngine(ctx).Exec(fmt.Sprintf("CREATE TRIGGER fail_manual_finish BEFORE UPDATE OF is_closed ON issue WHEN NEW.id=%d BEGIN SELECT RAISE(ABORT, 'manual finish partial failure'); END", target.ID))
		t.Cleanup(func() {
			_, e := db.GetEngine(context.WithoutCancel(ctx)).Exec("DROP TRIGGER fail_manual_finish")
			require.NoError(t, e)
		})
	}
	require.NoError(t, err)
	var finished extension.OperationRecord
	if mode == "concurrent" {
		start := make(chan struct{})
		results, failures := make([]extension.OperationRecord, 8), make([]error, 8)
		var wg sync.WaitGroup
		for i := range results {
			wg.Go(func() {
				<-start
				results[i], failures[i] = svc.FinishHumanManualMerge(owned, humanMergeProcessInstallation, q)
			})
		}
		close(start)
		wg.Wait()
		winners := 0
		for i, e := range failures {
			if e == nil {
				winners++
				finished = results[i]
			}
		}
		require.Equal(t, 1, winners)
	} else {
		finished, err = svc.FinishHumanManualMerge(owned, humanMergeProcessInstallation, q)
	}
	refused := mode == "stale-target" || mode == "changed-metadata" || mode == "changed-history" || mode == "changed-receipt" || mode == "wrong-generation" || mode == "missing-proof" || mode == "scope-tamper"
	if refused {
		require.Error(t, err)
		_, err = svc.CompleteHumanManualMerge(owned, humanMergeProcessInstallation, q)
		require.Error(t, err)
	} else if mode == "partial" {
		require.Error(t, err)
		require.Equal(t, nativeoperation_model.CompletionNeedsIntervention, finished.CompletionState)
	} else {
		require.NoError(t, err)
		require.Equal(t, nativeoperation_model.CompletionPending, finished.CompletionState)
	}
	require.NoError(t, queue.GetManager().FlushAll(ctx, 5*time.Second))
	closed, err := issues_model.GetIssueByID(ctx, target.ID)
	require.NoError(t, err)
	require.Equal(t, !refused && mode != "partial", closed.IsClosed)
	statusCount, err := db.GetEngine(ctx).Where("issue_id=? AND type=?", target.ID, issues_model.CommentTypeClose).Count(new(issues_model.Comment))
	require.NoError(t, err)
	if closed.IsClosed {
		require.EqualValues(t, 1, statusCount)
	} else {
		require.Zero(t, statusCount)
	}
	notice := new(activities_model.Notification)
	exists, err := db.GetEngine(ctx).Where("issue_id=? AND user_id=?", issue.ID, 4).Get(notice)
	require.NoError(t, err)
	require.Equal(t, !refused, exists)
	if exists {
		reader := unittest.AssertExistsAndLoadBean(t, &user_model.User{ID: 4})
		_, err = activities_model.SetNotificationStatus(ctx, notice.ID, reader, activities_model.NotificationStatusRead)
		require.NoError(t, err)
	}
	mergeActions, err := db.GetEngine(ctx).Where("repo_id=? AND op_type=?", repo.ID, activities_model.ActionMergePullRequest).Count(new(activities_model.Action))
	require.NoError(t, err)
	if refused {
		require.Zero(t, mergeActions)
	} else {
		require.Positive(t, mergeActions)
	}
	if !refused {
		require.Equal(t, primary.Receipt, finished.Receipt)
		_, err = nativeoperation_service.NewService().FinishHumanManualMerge(owned, humanMergeProcessInstallation, q)
		require.ErrorIs(t, err, nativeoperation_service.ErrHumanManualMergeFinishClaimed)
		if mode == "partial" {
			_, err = svc.CompleteHumanManualMerge(owned, humanMergeProcessInstallation, q)
			require.ErrorIs(t, err, nativeoperation_service.ErrHumanManualMergeCompletionNotReady)
		} else {
			if mode == "release-evidence" {
				// Mutate only merger attribution; ordinary ORM updates also replace
				// MergedUnix, which would make the later explicit restoration partial.
				_, err := db.GetEngine(ctx).NoAutoTime().ID(pr.ID).Cols("merger_id").Update(&issues_model.PullRequest{MergerID: 1})
				require.NoError(t, err)
				_, err = svc.CompleteHumanManualMerge(owned, humanMergeProcessInstallation, q)
				require.ErrorIs(t, err, nativeoperation_service.ErrHumanManualMergeEvidence)
				current, err := nativeoperation_model.ReadReservation(ctx)
				require.NoError(t, err)
				require.Equal(t, held.Owner, current.Owner)
				_, err = execcontext.ReadCapabilityFile(files[0])
				require.NoError(t, err)
				_, err = db.GetEngine(ctx).NoAutoTime().ID(pr.ID).Cols("merger_id").Update(&issues_model.PullRequest{MergerID: actor.ID})
				require.NoError(t, err)
			}
			if mode == "release-rollback" {
				_, err := db.GetEngine(ctx).Exec("CREATE TRIGGER fail_manual_release BEFORE UPDATE OF owner ON reservation WHEN NEW.owner='' BEGIN SELECT RAISE(ABORT, 'manual completion release rollback'); END")
				require.NoError(t, err)
				_, err = svc.CompleteHumanManualMerge(owned, humanMergeProcessInstallation, q)
				require.Error(t, err)
				lookup, e := svc.Get(ctx, humanMergeProcessInstallation, operation)
				require.NoError(t, e)
				require.Equal(t, nativeoperation_model.CompletionPending, lookup.Record.CompletionState)
				current, e := nativeoperation_model.ReadReservation(ctx)
				require.NoError(t, e)
				require.Equal(t, held.Owner, current.Owner)
				_, err = db.GetEngine(ctx).Exec("DROP TRIGGER fail_manual_release")
				require.NoError(t, err)
			}
			if mode == "concurrent" {
				start := make(chan struct{})
				failures := make([]error, 8)
				var wg sync.WaitGroup
				for i := range failures {
					wg.Go(func() {
						<-start
						_, failures[i] = svc.CompleteHumanManualMerge(owned, humanMergeProcessInstallation, q)
					})
				}
				close(start)
				wg.Wait()
				winners := 0
				for _, e := range failures {
					if e == nil {
						winners++
					}
				}
				require.Equal(t, 1, winners)
			} else {
				completed, err := svc.CompleteHumanManualMerge(owned, humanMergeProcessInstallation, q)
				require.NoError(t, err)
				require.Equal(t, nativeoperation_model.CompletionComplete, completed.CompletionState)
				require.Equal(t, primary.Receipt, completed.Receipt)
			}
			_, err = os.Stat(files[0])
			require.True(t, os.IsNotExist(err))
			_, err = svc.CompleteHumanManualMerge(owned, humanMergeProcessInstallation, q)
			require.ErrorIs(t, err, nativeoperation_model.ErrWrongOwner)
		}
	}
	current, err := nativeoperation_model.ReadReservation(ctx)
	require.NoError(t, err)
	if refused || mode == "partial" {
		require.Equal(t, held.Owner, current.Owner)
	} else {
		require.Empty(t, current.Owner)
	}
	lookup, err := nativeoperation_service.NewService().Get(ctx, humanMergeProcessInstallation, operation)
	require.NoError(t, err)
	require.Equal(t, nativeoperation_model.EffectCommitted, lookup.Record.EffectState)
	if mode != "changed-receipt" {
		require.Equal(t, primary.Receipt, lookup.Record.Receipt)
	}
	if !refused && mode != "partial" {
		require.Equal(t, nativeoperation_model.CompletionComplete, lookup.Record.CompletionState)
	}
	replayed, err := svc.SubmitHumanManualMergePrimary(ctx, humanMergeProcessInstallation, q, admit)
	require.NoError(t, err)
	require.Equal(t, *lookup.Record, replayed)
	require.NoError(t, queue.GetManager().FlushAll(ctx, 5*time.Second))
	afterActions, err := db.GetEngine(ctx).Where("repo_id=? AND op_type=?", repo.ID, activities_model.ActionMergePullRequest).Count(new(activities_model.Action))
	require.NoError(t, err)
	require.Equal(t, mergeActions, afterActions)
	if exists {
		read := new(activities_model.Notification)
		found, e := db.GetEngine(ctx).ID(notice.ID).Get(read)
		require.NoError(t, e)
		require.True(t, found)
		require.Equal(t, activities_model.NotificationStatusRead, read.Status, "replay resent the merge notification")
	}
	pushActions, err := db.GetEngine(ctx).Where("repo_id=? AND op_type=?", repo.ID, activities_model.ActionCommitRepo).Count(new(activities_model.Action))
	require.NoError(t, err)
	require.Zero(t, pushActions)
	wantTip := fixture.tip
	if mode == "stale-target" {
		wantTip = fixture.base
	}
	require.Equal(t, wantTip, sourceTestGit(t, repo.RepoPath(), nil, "rev-parse", "refs/heads/main"))
	historyCount, err := db.GetEngine(ctx).Where("issue_id=? AND type=?", issue.ID, issues_model.CommentTypeMergePull).Count(new(issues_model.Comment))
	require.NoError(t, err)
	require.EqualValues(t, 1, historyCount)
	t.Logf("native manual completion %s: effect=%s completion=%s; notifications/cross-reference actions once, no push effects", mode, lookup.Record.EffectState, lookup.Record.CompletionState)
}

func checkHumanManualMergeRecovery(t *testing.T, fixture sourceTestFixture, repo *repo_model.Repository, pr *issues_model.PullRequest, issue, target *issues_model.Issue, q extension.HumanManualMergeRequest, primary extension.OperationRecord, held *nativeoperation_model.Reservation, x *execcontext.Execution, reopen func(), mode string) {
	t.Helper()
	ctx := t.Context()
	svc := nativeoperation_service.NewService()
	owned := execcontext.NewContext(ctx, x)
	switch mode {
	case "finished", "partial", "uncertain-dispatch":
		if mode == "partial" {
			_, err := db.GetEngine(ctx).Exec(fmt.Sprintf("CREATE TRIGGER fail_recovery_finish BEFORE UPDATE OF is_closed ON issue WHEN NEW.id=%d BEGIN SELECT RAISE(ABORT, 'stopped partial manual finishing'); END", target.ID))
			require.NoError(t, err)
		}
		if mode == "uncertain-dispatch" {
			_, err := db.GetEngine(ctx).Exec("CREATE TRIGGER fail_recovery_dispatch_record BEFORE UPDATE OF scope ON reservation WHEN NEW.scope LIKE '%human-manual-merge-finish-done%' BEGIN SELECT RAISE(ABORT, 'stopped manual dispatch record'); END")
			require.NoError(t, err)
		}
		finished, err := svc.FinishHumanManualMerge(owned, humanMergeProcessInstallation, q)
		if mode == "finished" {
			require.NoError(t, err)
		} else {
			require.Error(t, err)
		}
		if mode == "partial" {
			require.Equal(t, nativeoperation_model.CompletionNeedsIntervention, finished.CompletionState)
			_, err := db.GetEngine(ctx).Exec("DROP TRIGGER fail_recovery_finish")
			require.NoError(t, err)
		}
		if mode == "uncertain-dispatch" {
			_, err := db.GetEngine(ctx).Exec("DROP TRIGGER fail_recovery_dispatch_record")
			require.NoError(t, err)
		}
	case "pending-cancelled":
		_, err := svc.Cancel(ctx, humanMergeProcessInstallation, q.OperationID)
		require.NoError(t, err)
	case "pending-contradiction":
		_, err := db.GetEngine(ctx).NoAutoTime().ID(pr.ID).Cols("has_merged").Update(&issues_model.PullRequest{HasMerged: true})
		require.NoError(t, err)
	case "missing-proof":
		require.NoError(t, os.Remove(x.CapabilityPath))
	case "intent-tamper":
		_, err := db.GetEngine(ctx).Where("operation_id=?", q.OperationID).Cols("intent_digest").Update(&nativeoperation_model.Operation{IntentDigest: "changed"})
		require.NoError(t, err)
	case "scope-tamper":
		var scope nativeoperation_service.Scope
		require.NoError(t, json.Unmarshal([]byte(held.Scope), &scope))
		scope.Ref = "refs/heads/main"
		raw, err := json.Marshal(scope)
		require.NoError(t, err)
		_, err = db.GetEngine(ctx).ID(1).Cols("scope").Update(&nativeoperation_model.Reservation{Scope: string(raw)})
		require.NoError(t, err)
	case "receipt-tamper":
		var receipt extension.HumanManualMergeReceipt
		require.NoError(t, json.Unmarshal(primary.Receipt, &receipt))
		receipt.ClosedUnix++
		raw, err := json.Marshal(receipt)
		require.NoError(t, err)
		_, err = db.GetEngine(ctx).Where("operation_id=?", q.OperationID).Cols("receipt").Update(&nativeoperation_model.Operation{Receipt: string(raw)})
		require.NoError(t, err)
	case "metadata-tamper":
		_, err := db.GetEngine(ctx).NoAutoTime().ID(pr.ID).Cols("merger_id").Update(&issues_model.PullRequest{MergerID: 1})
		require.NoError(t, err)
	case "history-missing":
		var receipt extension.HumanManualMergeReceipt
		require.NoError(t, json.Unmarshal(primary.Receipt, &receipt))
		_, err := db.GetEngine(ctx).ID(receipt.HistoryID).Delete(new(issues_model.Comment))
		require.NoError(t, err)
	case "target-moved":
		sourceTestGit(t, repo.RepoPath(), nil, "update-ref", "refs/heads/main", fixture.base)
	}
	require.NoError(t, queue.GetManager().FlushAll(ctx, 5*time.Second))
	// Mark any real delivered notification read; recovery must not resend it.
	var notice activities_model.Notification
	found, err := db.GetEngine(ctx).Where("issue_id=? AND user_id=?", issue.ID, 4).Get(&notice)
	require.NoError(t, err)
	if found {
		reader := unittest.AssertExistsAndLoadBean(t, &user_model.User{ID: 4})
		_, err := activities_model.SetNotificationStatus(ctx, notice.ID, reader, activities_model.NotificationStatusRead)
		require.NoError(t, err)
	}
	nativeState := func() string {
		t.Helper()
		var stored issues_model.PullRequest
		var parent, referenced issues_model.Issue
		var comments []*issues_model.Comment
		var notices []*activities_model.Notification
		var actions []*activities_model.Action
		found, err := db.GetEngine(ctx).ID(pr.ID).Get(&stored)
		require.NoError(t, err)
		require.True(t, found)
		found, err = db.GetEngine(ctx).ID(issue.ID).Get(&parent)
		require.NoError(t, err)
		require.True(t, found)
		found, err = db.GetEngine(ctx).ID(target.ID).Get(&referenced)
		require.NoError(t, err)
		require.True(t, found)
		require.NoError(t, db.GetEngine(ctx).Where("issue_id=? OR issue_id=?", issue.ID, target.ID).OrderBy("id").Find(&comments))
		require.NoError(t, db.GetEngine(ctx).Where("issue_id=? OR issue_id=?", issue.ID, target.ID).OrderBy("id").Find(&notices))
		require.NoError(t, db.GetEngine(ctx).Where("repo_id=?", repo.ID).OrderBy("id").Find(&actions))
		raw, err := json.Marshal([]any{stored, parent, referenced, comments, notices, actions})
		require.NoError(t, err)
		return string(raw)
	}
	beforeNative := nativeState()
	before, err := svc.Get(ctx, humanMergeProcessInstallation, q.OperationID)
	require.NoError(t, err)
	beforeTip := sourceTestGit(t, repo.RepoPath(), nil, "rev-parse", "refs/heads/main")
	// Both synchronous writers returned and their queues drained. This slice
	// qualifies retained SQL reopen; owned-process SIGKILL/reap remains separate.
	reopen()
	require.Equal(t, beforeNative, nativeState())
	stopped := nativeoperation_service.NewService()
	_, err = stopped.Recover(ctx, held.Owner, held.Generation)
	require.ErrorIs(t, err, nativeoperation_service.ErrNotInhibited)
	require.NoError(t, os.WriteFile(nativeoperation_model.OfflineMarkerPath(), []byte("owned synchronous manual writers returned; restart inhibited\n"), 0o600))
	t.Cleanup(func() {
		err := os.Remove(nativeoperation_model.OfflineMarkerPath())
		require.True(t, err == nil || os.IsNotExist(err))
	})
	wrong, err := stopped.Recover(ctx, held.Owner, held.Generation+1)
	require.NoError(t, err)
	require.Equal(t, nativeoperation_service.RecoveryFenced, wrong.Verdict)
	wrong, err = stopped.Recover(ctx, "ord:foreign", held.Generation)
	require.NoError(t, err)
	require.Equal(t, nativeoperation_service.RecoveryFenced, wrong.Verdict)
	require.NoError(t, db.WithTx(ctx, func(tx context.Context) error {
		_, err := stopped.Recover(tx, held.Owner, held.Generation)
		require.ErrorIs(t, err, nativeoperation_service.ErrInvalidIntent)
		return nil
	}))
	if mode == "release-rollback" {
		_, err := db.GetEngine(ctx).Exec("CREATE TRIGGER fail_manual_recovery_release BEFORE UPDATE OF owner ON reservation WHEN NEW.owner='' BEGIN SELECT RAISE(ABORT, 'manual recovery atomic release rollback'); END")
		require.NoError(t, err)
		_, err = stopped.Recover(ctx, held.Owner, held.Generation)
		require.Error(t, err)
		unchanged, err := stopped.Get(ctx, humanMergeProcessInstallation, q.OperationID)
		require.NoError(t, err)
		require.Equal(t, before, unchanged)
		stillHeld, err := nativeoperation_model.ReadReservation(ctx)
		require.NoError(t, err)
		require.Equal(t, held.Owner, stillHeld.Owner)
		_, err = execcontext.ReadCapabilityFile(x.CapabilityPath)
		require.NoError(t, err)
		_, err = db.GetEngine(ctx).Exec("DROP TRIGGER fail_manual_recovery_release")
		require.NoError(t, err)
	}
	assessment, err := stopped.Recover(ctx, held.Owner, held.Generation)
	require.NoError(t, err)
	fenced := mode == "pending-contradiction" || mode == "intent-tamper" || mode == "scope-tamper" || mode == "receipt-tamper" || mode == "metadata-tamper" || mode == "history-missing" || mode == "target-moved"
	current, err := nativeoperation_model.ReadReservation(ctx)
	require.NoError(t, err)
	after, err := stopped.Get(ctx, humanMergeProcessInstallation, q.OperationID)
	require.NoError(t, err)
	if fenced {
		require.Equal(t, nativeoperation_service.RecoveryFenced, assessment.Verdict)
		if mode == "history-missing" {
			require.Equal(t, nativeoperation_service.ReasonRecoveryMissingEvidence, assessment.Reason)
		}
		require.Equal(t, held.Owner, current.Owner)
		require.Equal(t, before, after)
		_, err = execcontext.ReadCapabilityFile(x.CapabilityPath)
		require.NoError(t, err)
	} else {
		require.Equal(t, nativeoperation_service.RecoveryReleased, assessment.Verdict)
		require.Empty(t, current.Owner)
		require.Equal(t, held.Revision, current.Revision)
		require.Equal(t, before.Record.Receipt, after.Record.Receipt)
		if mode == "pending" || mode == "pending-cancelled" {
			require.Equal(t, nativeoperation_model.EffectNotCommitted, after.Record.EffectState)
			require.Empty(t, after.Record.CompletionState)
			if mode == "pending-cancelled" {
				require.Equal(t, nativeoperation_model.CancellationCancelled, after.Record.CancellationStatus)
			}
		} else {
			require.Equal(t, nativeoperation_model.EffectCommitted, after.Record.EffectState)
			completion := nativeoperation_model.CompletionNeedsIntervention
			if mode == "finished" {
				completion = nativeoperation_model.CompletionComplete
			}
			require.Equal(t, completion, after.Record.CompletionState)
		}
		_, err = os.Stat(x.CapabilityPath)
		require.True(t, os.IsNotExist(err))
	}
	require.Equal(t, beforeNative, nativeState(), "recovery changed native metadata/history or replayed delivery")
	require.Equal(t, beforeTip, sourceTestGit(t, repo.RepoPath(), nil, "rev-parse", "refs/heads/main"))
	reopen()
	again, err := nativeoperation_service.NewService().Recover(ctx, held.Owner, held.Generation)
	require.NoError(t, err)
	if fenced {
		require.Equal(t, nativeoperation_service.RecoveryFenced, again.Verdict)
	} else {
		require.Equal(t, nativeoperation_service.RecoveryIdle, again.Verdict)
	}
	retained, err := stopped.Get(ctx, humanMergeProcessInstallation, q.OperationID)
	require.NoError(t, err)
	require.Equal(t, after, retained)
	require.Equal(t, beforeNative, nativeState())
	t.Logf("manual recovery %s after retained database reopen: verdict=%s effect=%s completion=%s; native rows/dispatch/Git unchanged", mode, assessment.Verdict, after.Record.EffectState, after.Record.CompletionState)
}

func checkHumanManualMergeSubmit(t *testing.T, fixture sourceTestFixture, repo *repo_model.Repository, pr *issues_model.PullRequest, issue, target *issues_model.Issue, q extension.HumanManualMergeRequest, admit nativeoperation_service.HumanReviewAdmission, mode string) {
	t.Helper()
	ctx := t.Context()
	requestCtx, cancel := context.WithCancel(ctx)
	t.Cleanup(cancel)
	svc := nativeoperation_service.NewService()
	owner := "cond:" + humanMergeProcessInstallation + "/" + q.OperationID
	t.Cleanup(func() {
		current, err := nativeoperation_model.ReadReservation(context.WithoutCancel(ctx))
		require.NoError(t, err)
		if current.Owner == owner {
			require.NoError(t, nativeoperation_model.ReleaseExactOwner(context.WithoutCancel(ctx), owner, current.Generation))
		}
	}) // Disposal of this owned fixture only, never product recovery.
	if mode == "expiry" {
		q.NotAfter = time.Now().Add(2 * time.Second).Unix()
	}
	if mode == "early-cancel" {
		_, err := svc.Cancel(ctx, humanMergeProcessInstallation, q.OperationID)
		require.NoError(t, err)
	}
	if mode == "stale-target" {
		sourceTestGit(t, repo.RepoPath(), nil, "update-ref", "refs/heads/main", fixture.base)
	}
	if mode == "session-before" {
		fixture.session.uid = 1
	}
	if mode == "partial" {
		_, err := db.GetEngine(ctx).Exec(fmt.Sprintf("CREATE TRIGGER fail_manual_submit_finish BEFORE UPDATE OF is_closed ON issue WHEN NEW.id=%d BEGIN SELECT RAISE(ABORT, 'manual submit partial finishing'); END", target.ID))
		require.NoError(t, err)
		t.Cleanup(func() {
			_, err := db.GetEngine(context.WithoutCancel(ctx)).Exec("DROP TRIGGER fail_manual_submit_finish")
			require.NoError(t, err)
		})
	}
	if mode == "sql-rollback" {
		_, err := db.GetEngine(ctx).Exec(fmt.Sprintf("CREATE TRIGGER fail_manual_submit_primary BEFORE UPDATE OF has_merged ON pull_request WHEN NEW.id=%d BEGIN SELECT RAISE(ABORT, 'manual submit primary rollback'); END", pr.ID))
		require.NoError(t, err)
		t.Cleanup(func() {
			_, err := db.GetEngine(context.WithoutCancel(ctx)).Exec("DROP TRIGGER fail_manual_submit_primary")
			require.NoError(t, err)
		})
	}
	if mode == "dispatch-unknown" {
		_, err := db.GetEngine(ctx).Exec("CREATE TRIGGER fail_manual_submit_dispatch BEFORE UPDATE OF scope ON reservation WHEN NEW.scope LIKE '%human-manual-merge-finish-done%' BEGIN SELECT RAISE(ABORT, 'manual submit dispatch result unknown'); END")
		require.NoError(t, err)
		t.Cleanup(func() {
			_, err := db.GetEngine(context.WithoutCancel(ctx)).Exec("DROP TRIGGER fail_manual_submit_dispatch")
			require.NoError(t, err)
		})
	}
	if mode == "release-rollback" {
		_, err := db.GetEngine(ctx).Exec("CREATE TRIGGER fail_manual_submit_release BEFORE UPDATE OF owner ON reservation WHEN NEW.owner='' BEGIN SELECT RAISE(ABORT, 'manual submit release rollback'); END")
		require.NoError(t, err)
		t.Cleanup(func() {
			_, err := db.GetEngine(context.WithoutCancel(ctx)).Exec("DROP TRIGGER fail_manual_submit_release")
			require.NoError(t, err)
		})
	}
	gate := func(c context.Context) error {
		if mode == "session-in-primary" && db.InTransaction(c) {
			current, err := issues_model.GetPullRequestByID(c, pr.ID)
			if err != nil {
				return err
			}
			if current.HasMerged {
				fixture.session.uid = 1
			}
		}
		return admit(c)
	}
	point := ""
	switch mode {
	case "concurrent", "cancel", "expiry":
		point = nativeoperation_service.CrashPointHumanManualMergeBeforePrimary
	case "session-after-commit", "context-after-commit", "late-cancel":
		point = nativeoperation_service.CrashPointHumanManualMergeAfterPrimary
	case "lost-reply":
		point = nativeoperation_service.CrashPointHumanManualMergeAfterRelease
	}
	var record extension.OperationRecord
	var submitErr error
	if point != "" {
		dir := t.TempDir()
		t.Setenv("NATIVEOP_TEST_CRASH_POINT", point)
		t.Setenv("NATIVEOP_TEST_CRASH_BARRIER_DIR", dir)
		t.Setenv("NATIVEOP_TEST_CRASH_TIMEOUT_SECONDS", "20")
		type result struct {
			record extension.OperationRecord
			err    error
		}
		done := make(chan result, 1)
		go func() {
			r, e := svc.SubmitHumanManualMerge(requestCtx, humanMergeProcessInstallation, q, gate)
			done <- result{r, e}
		}()
		require.Eventually(t, func() bool { _, err := os.Stat(filepath.Join(dir, point+".entered")); return err == nil }, 10*time.Second, 10*time.Millisecond)
		switch mode {
		case "concurrent":
			duplicate, err := nativeoperation_service.NewService().SubmitHumanManualMerge(ctx, humanMergeProcessInstallation, q, admit)
			require.NoError(t, err)
			require.Equal(t, nativeoperation_model.EffectPending, duplicate.EffectState)
			changed := q
			changed.Expected.CommitOID = fixture.tip
			_, err = svc.SubmitHumanManualMerge(ctx, humanMergeProcessInstallation, changed, admit)
			require.ErrorIs(t, err, nativeoperation_service.ErrIntentConflict)
			other := q
			other.OperationID, err = extension.HumanManualMergeOperationID(q.Expected.ActorID, q.Expected.RepositoryID, "other-captured-manual")
			require.NoError(t, err)
			_, err = svc.SubmitHumanManualMerge(ctx, humanMergeProcessInstallation, other, admit)
			require.ErrorIs(t, err, nativeoperation_service.ErrBusy)
			missing, err := svc.Get(ctx, humanMergeProcessInstallation, other.OperationID)
			require.NoError(t, err)
			require.Nil(t, missing.Record)
			files, err := filepath.Glob(filepath.Join(setting.AppDataPath, "nativeop-exec", "*"))
			require.NoError(t, err)
			require.Len(t, files, 1)
		case "cancel", "late-cancel":
			cancelled, err := svc.Cancel(ctx, humanMergeProcessInstallation, q.OperationID)
			require.NoError(t, err)
			if mode == "late-cancel" {
				require.Equal(t, nativeoperation_model.CancellationTooLate, cancelled.CancellationStatus)
			}
		case "expiry":
			time.Sleep(time.Until(time.Unix(q.NotAfter, 0)))
		case "session-after-commit":
			fixture.session.uid = 1
		case "context-after-commit":
			cancel()
		}
		require.NoError(t, os.WriteFile(filepath.Join(dir, point+".release"), []byte("continue\n"), 0o600))
		select {
		case result := <-done:
			record, submitErr = result.record, result.err
		case <-time.After(15 * time.Second):
			t.Fatal("manual submit did not finish after releasing native checkpoint")
		}
	} else {
		record, submitErr = svc.SubmitHumanManualMerge(requestCtx, humanMergeProcessInstallation, q, gate)
	}
	fixture.session.uid = 2
	lookup, err := nativeoperation_service.NewService().Get(ctx, humanMergeProcessInstallation, q.OperationID)
	require.NoError(t, err)
	if mode == "session-before" {
		require.ErrorIs(t, submitErr, nativeoperation_service.ErrAuthorityLost)
		require.Nil(t, lookup.Record)
		return
	}
	require.NotNil(t, lookup.Record)
	if mode == "early-cancel" {
		require.ErrorIs(t, submitErr, nativeoperation_service.ErrCancelledBeforeSubmit)
		return
	}
	infraFailure := mode == "sql-rollback" || mode == "dispatch-unknown" || mode == "release-rollback"
	if infraFailure {
		require.Error(t, submitErr)
	} else if mode == "session-in-primary" || mode == "session-after-commit" || mode == "context-after-commit" {
		require.ErrorIs(t, submitErr, nativeoperation_service.ErrAuthorityLost)
	} else {
		require.NoError(t, submitErr)
	}
	committed := mode != "cancel" && mode != "expiry" && mode != "stale-target" && mode != "session-in-primary" && mode != "sql-rollback"
	if committed {
		require.Equal(t, nativeoperation_model.EffectCommitted, lookup.Record.EffectState)
		var receipt extension.HumanManualMergeReceipt
		require.NoError(t, json.Unmarshal(lookup.Record.Receipt, &receipt))
		require.True(t, extension.ValidHumanManualMergeReceipt(receipt, q))
		require.EqualValues(t, time.Date(2001, 2, 3, 4, 5, 6, 0, time.UTC).Unix(), receipt.MergedUnix)
		completion := nativeoperation_model.CompletionComplete
		if mode == "partial" {
			completion = nativeoperation_model.CompletionNeedsIntervention
		}
		if mode == "dispatch-unknown" || mode == "release-rollback" {
			completion = nativeoperation_model.CompletionPending
		}
		require.Equal(t, completion, lookup.Record.CompletionState)
	} else if mode == "sql-rollback" {
		require.Equal(t, nativeoperation_model.EffectPending, lookup.Record.EffectState)
	} else {
		require.Equal(t, nativeoperation_model.EffectNotCommitted, lookup.Record.EffectState)
	}
	if mode == "cancel" {
		require.Equal(t, nativeoperation_model.CancellationCancelled, lookup.Record.CancellationStatus)
	}
	if mode == "late-cancel" {
		require.Equal(t, nativeoperation_model.CancellationTooLate, lookup.Record.CancellationStatus)
	}
	retained := infraFailure || mode == "partial"
	held, err := nativeoperation_model.ReadReservation(ctx)
	require.NoError(t, err)
	files, err := filepath.Glob(filepath.Join(setting.AppDataPath, "nativeop-exec", "*"))
	require.NoError(t, err)
	if retained {
		require.Equal(t, owner, held.Owner)
		require.Len(t, files, 1)
	} else {
		require.Empty(t, held.Owner)
		require.Empty(t, files)
	}
	require.NoError(t, queue.GetManager().FlushAll(ctx, 5*time.Second))
	current, err := issues_model.GetPullRequestByID(ctx, pr.ID)
	require.NoError(t, err)
	parent, err := issues_model.GetIssueByID(ctx, issue.ID)
	require.NoError(t, err)
	reference, err := issues_model.GetIssueByID(ctx, target.ID)
	require.NoError(t, err)
	require.Equal(t, committed, current.HasMerged)
	require.Equal(t, committed, parent.IsClosed)
	require.Equal(t, committed && mode != "partial", reference.IsClosed)
	history, err := db.GetEngine(ctx).Where("issue_id=? AND type=?", issue.ID, issues_model.CommentTypeMergePull).Count(new(issues_model.Comment))
	require.NoError(t, err)
	if committed {
		require.EqualValues(t, 1, history)
	} else {
		require.Zero(t, history)
	}
	var notice activities_model.Notification
	found, err := db.GetEngine(ctx).Where("issue_id=? AND user_id=?", issue.ID, 4).Get(&notice)
	require.NoError(t, err)
	require.Equal(t, committed, found)
	if found {
		reader := unittest.AssertExistsAndLoadBean(t, &user_model.User{ID: 4})
		_, err = activities_model.SetNotificationStatus(ctx, notice.ID, reader, activities_model.NotificationStatusRead)
		require.NoError(t, err)
	}
	mergeActions, err := db.GetEngine(ctx).Where("repo_id=? AND op_type=?", repo.ID, activities_model.ActionMergePullRequest).Count(new(activities_model.Action))
	require.NoError(t, err)
	if committed {
		require.Positive(t, mergeActions)
	} else {
		require.Zero(t, mergeActions)
	}
	// Discarding the successful result models loss at this native service seam;
	// an HTTP/SDK reply-loss check belongs to the later transport consumer.
	if mode == "lost-reply" {
		record = extension.OperationRecord{}
	}
	if !infraFailure && mode != "session-in-primary" && mode != "session-after-commit" && mode != "context-after-commit" && mode != "lost-reply" {
		require.Equal(t, *lookup.Record, record)
	}
	replayed, err := nativeoperation_service.NewService().SubmitHumanManualMerge(ctx, humanMergeProcessInstallation, q, admit)
	require.NoError(t, err)
	require.Equal(t, *lookup.Record, replayed)
	require.NoError(t, queue.GetManager().FlushAll(ctx, 5*time.Second))
	if found {
		read := new(activities_model.Notification)
		exists, err := db.GetEngine(ctx).ID(notice.ID).Get(read)
		require.NoError(t, err)
		require.True(t, exists)
		require.Equal(t, activities_model.NotificationStatusRead, read.Status, "submit replay resent native notification")
	}
	afterHistory, err := db.GetEngine(ctx).Where("issue_id=? AND type=?", issue.ID, issues_model.CommentTypeMergePull).Count(new(issues_model.Comment))
	require.NoError(t, err)
	require.Equal(t, history, afterHistory)
	afterActions, err := db.GetEngine(ctx).Where("repo_id=? AND op_type=?", repo.ID, activities_model.ActionMergePullRequest).Count(new(activities_model.Action))
	require.NoError(t, err)
	require.Equal(t, mergeActions, afterActions)
	pushes, err := db.GetEngine(ctx).Where("repo_id=? AND op_type=?", repo.ID, activities_model.ActionCommitRepo).Count(new(activities_model.Action))
	require.NoError(t, err)
	require.Zero(t, pushes)
	wantTip := fixture.tip
	if mode == "stale-target" {
		wantTip = fixture.base
	}
	require.Equal(t, wantTip, sourceTestGit(t, repo.RepoPath(), nil, "rev-parse", "refs/heads/main"))
	t.Logf("manual submit %s: effect=%s completion=%s retained=%t; one primary/finishing, replay unchanged and no Git/push effects", mode, lookup.Record.EffectState, lookup.Record.CompletionState, retained)
}

func checkHumanManualMergeSDK(t *testing.T, fixture sourceTestFixture, repo *repo_model.Repository, pr *issues_model.PullRequest, issue, target *issues_model.Issue, q extension.HumanManualMergeRequest, mode string) {
	t.Helper()
	ctx := t.Context()
	root := shortWitnessRoot(t)
	backend := os.Getenv("SODA_FOUNTAIN_MANUAL_MERGE_BACKEND")
	require.True(t, filepath.IsAbs(backend))
	packageDir := filepath.Join(root, "soda")
	writePackage := func() {
		require.NoError(t, os.Mkdir(packageDir, 0o700))
		require.NoError(t, os.WriteFile(filepath.Join(packageDir, "run"), []byte(fmt.Sprintf("#!/bin/sh\nexec %q\n", backend)), 0o700))
		if os.Getenv("SODA_FOUNTAIN_MERGE_HTTP_MANIFEST") != "" {
			require.NoError(t, os.WriteFile(filepath.Join(packageDir, "run"), []byte(fmt.Sprintf("#!/bin/sh\nexec %q --package-id soda --soda-socket %q --factory-socket %q\n", backend, filepath.Join(root, "soda-http"), filepath.Join(root, "factory-http"))), 0o700))
		}
		require.NoError(t, os.WriteFile(filepath.Join(packageDir, "extension.json"), []byte(`{"protocol":1,"id":"soda","name":"ManualMergeSDK","version":"1.0","executable":"run","capabilities":["native.actor.read","native.repository.read","native.repository.merges.write"]}`), 0o600))
		if manifest := os.Getenv("SODA_FOUNTAIN_MERGE_HTTP_MANIFEST"); manifest != "" {
			raw, err := os.ReadFile(manifest)
			require.NoError(t, err)
			require.NoError(t, os.WriteFile(filepath.Join(packageDir, "extension.json"), raw, 0o600))
		}
	}
	writePackage()
	previous := extensions_service.GetManager()
	t.Cleanup(func() { extensions_service.SetDefault(previous) })
	var dropped atomic.Bool
	var mutation atomic.Value
	mutation.Store("")
	factory := func(instance string) http.Handler {
		handler := CallbackHandlerForInstance(instance)
		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			body, err := io.ReadAll(r.Body)
			require.NoError(t, err)
			r.Body = io.NopCloser(bytes.NewReader(body))
			var request extension.CallbackRequest
			require.NoError(t, json.Unmarshal(body, &request))
			change := mutation.Load().(string)
			if request.Operation != extension.OperationHumanManualMergeSubmit && request.Operation != extension.OperationHumanManualMergeGet && request.Operation != extension.OperationHumanManualMergeCancel {
				change = ""
			}
			intercept := mode == "lost-reply" && request.Operation == extension.OperationHumanManualMergeSubmit || change != ""
			if !intercept {
				handler.ServeHTTP(w, r)
				return
			}
			recorder := httptest.NewRecorder()
			handler.ServeHTTP(recorder, r)
			if mode == "lost-reply" && request.Operation == extension.OperationHumanManualMergeSubmit && recorder.Code == http.StatusOK && dropped.CompareAndSwap(false, true) {
				connection, _, err := w.(http.Hijacker).Hijack()
				require.NoError(t, err)
				require.NoError(t, connection.Close())
				return
			}
			data := recorder.Body.Bytes()
			if change != "" && recorder.Code == http.StatusOK {
				var result extension.CallbackResponse
				require.NoError(t, json.Unmarshal(data, &result))
				record := result.HumanManualMerge.Record
				if record == nil {
					change = ""
				}
				switch change {
				case "actor":
					record.ActorID = "1"
				case "repository":
					record.RepositoryID = "1"
				case "kind":
					record.Kind = extension.OperationKindHumanReview
				case "digest":
					record.IntentDigest = strings.Repeat("f", 64)
				case "completion":
					record.CompletionState = "unknown-completion"
				case "installation":
					result.HumanManualMerge.InstallationID = "11111111-2222-4333-8444-555555555555"
				case "extra":
					result.Actor = &extension.Actor{ID: "2"}
				case "receipt", "receipt-digest", "submit-commit", "unknown-receipt":
					var receipt extension.HumanManualMergeReceipt
					require.NoError(t, json.Unmarshal(record.Receipt, &receipt))
					if change == "receipt" {
						receipt.CommitOID = "HEAD"
					}
					if change == "receipt-digest" {
						receipt.IntentDigest = strings.Repeat("a", 64)
					}
					if change == "submit-commit" {
						receipt.CommitOID = fixture.tip
					}
					raw, err := json.Marshal(receipt)
					require.NoError(t, err)
					if change == "unknown-receipt" {
						raw = append(raw[:len(raw)-1], []byte(`,"unexpected":true}`)...)
					}
					record.Receipt = raw
				}
				data, err = json.Marshal(result)
				require.NoError(t, err)
			}
			for key, values := range recorder.Header() {
				for _, value := range values {
					w.Header().Add(key, value)
				}
			}
			w.WriteHeader(recorder.Code)
			_, _ = w.Write(data)
		})
	}
	start := func() (*extensions_service.Manager, extensions_service.Descriptor, string, string) {
		store, err := packages.OpenPackageStore(root)
		require.NoError(t, err)
		_, err = store.SetDesired("soda", true)
		require.NoError(t, err)
		require.NoError(t, store.Close())
		manager := extensions_service.NewManager(root)
		if os.Getenv("SODA_FOUNTAIN_MERGE_HTTP_MANIFEST") != "" {
			require.NoError(t, manager.SetServiceCallbackEndpoint(filepath.Join(root, "svc"), CallbackHandlerForService()))
		}
		require.NoError(t, manager.SetCallbackHandlerFactory(factory))
		extensions_service.SetDefault(manager)
		t.Cleanup(func() { require.NoError(t, manager.Close()) })
		require.NoError(t, manager.Start(ctx))
		var descriptor extensions_service.Descriptor
		require.Eventually(t, func() bool { var ready bool; descriptor, _, ready = manager.Lookup("soda"); return ready }, 15*time.Second, 20*time.Millisecond)
		installation, ok := manager.AdmittedInstallation("soda", descriptor.InstanceID)
		require.True(t, ok)
		sockets, err := filepath.Glob(filepath.Join(root, ".runtime", "*", "c"))
		require.NoError(t, err)
		require.Len(t, sockets, 1)
		return manager, descriptor, installation, sockets[0]
	}
	manager, descriptor, installation, socket := start()
	bind := func(descriptor extensions_service.Descriptor, socket string) (extension.Authority, *callbackAdmission, string) {
		authority := fixture.authority
		authority.InstanceID = descriptor.InstanceID
		if os.Getenv("SODA_FOUNTAIN_MERGE_HTTP_MANIFEST") != "" {
			authority.Contribution.ID = "feed"
		}
		requestCtx, cancel := context.WithCancel(ctx)
		t.Cleanup(cancel)
		entry := &callbackAdmission{method: http.MethodPost, instanceID: descriptor.InstanceID, actorID: 2, sessionID: "source-test-session", session: fixture.session, authority: authority, capabilities: map[string]struct{}{extension.CapabilityActorRead: {}, extension.CapabilityRepositoryRead: {}, extension.CapabilityHumanMerges: {}}, requestCtx: requestCtx, cancel: cancel}
		token, err := nativeAdmissions.issue(entry)
		require.NoError(t, err)
		t.Cleanup(func() { nativeAdmissions.revoke(token) })
		t.Setenv(extension.CallbackEnv, socket)
		t.Setenv(extension.ServiceCallbackEnv, "")
		raw, err := json.Marshal(authority)
		require.NoError(t, err)
		request := httptest.NewRequest(http.MethodPost, "/manual-sdk", nil)
		request.Header.Set(extension.ContextHeader, string(raw))
		request.Header.Set(extension.AdmissionHeader, token)
		a, err := extension.RequestContext(request)
		require.NoError(t, err)
		return a, entry, token
	}
	a, entry, token := bind(descriptor, socket)
	repository := strconv.FormatInt(repo.ID, 10)
	snapshot, err := a.RepositoryManualMergeSnapshot(ctx, repository, extension.RepositoryManualMergeSnapshotRequest{Index: q.Expected.Index, CommitOID: q.Expected.CommitOID})
	require.NoError(t, err)
	q.Expected = snapshot
	if os.Getenv("SODA_FOUNTAIN_MERGE_ADAPTER_PROBE") != "" {
		checkCanonicalHumanMergeAdapter(t, fixture, repo, issue, target, a, entry, token, socket, installation, "manual", "", q.Expected.CommitOID, q.Expected.Index, mode, nil, nil, func(v string) { mutation.Store(v) }, func() (extension.Authority, *callbackAdmission, string, string, string) {
			require.NoError(t, manager.Close())
			store, err := packages.OpenPackageStore(root)
			require.NoError(t, err)
			require.NoError(t, store.Remove("soda"))
			require.NoError(t, store.Close())
			writePackage()
			_, fresh, newInstallation, newSocket := start()
			freshAuthority, newEntry, newToken := bind(fresh, newSocket)
			return freshAuthority, newEntry, newToken, newSocket, newInstallation
		})
		return
	}
	observationCommand := ""
	if os.Getenv("SODA_FOUNTAIN_MERGE_OBSERVATION_EXPORT") != "" {
		nonce := make([]byte, 16)
		_, err := rand.Read(nonce)
		require.NoError(t, err)
		observationCommand = fmt.Sprintf("%x", nonce)
		q.OperationID, err = extension.HumanManualMergeOperationID(q.Expected.ActorID, q.Expected.RepositoryID, observationCommand)
		require.NoError(t, err)
	}
	t.Cleanup(func() {
		held, err := nativeoperation_model.ReadReservation(context.WithoutCancel(ctx))
		require.NoError(t, err)
		if held.Owner == "cond:"+installation+"/"+q.OperationID {
			require.NoError(t, nativeoperation_model.ReleaseExactOwner(context.WithoutCancel(ctx), held.Owner, held.Generation))
		}
	}) // Disposal of an owned incomplete fixture, never product recovery.
	absent, err := a.GetHumanManualMerge(ctx, repository, q.OperationID)
	require.NoError(t, err)
	require.Equal(t, installation, absent.InstallationID)
	require.Nil(t, absent.Record)
	rawCall := func(request extension.CallbackRequest) int {
		t.Helper()
		request.Authority = entry.authority
		body, err := json.Marshal(request)
		require.NoError(t, err)
		transport := &http.Transport{DialContext: func(c context.Context, _, _ string) (net.Conn, error) {
			return (&net.Dialer{}).DialContext(c, "unix", socket)
		}}
		defer transport.CloseIdleConnections()
		r, err := http.NewRequestWithContext(ctx, http.MethodPost, "http://native"+extension.NativeCallbackPath, bytes.NewReader(body))
		require.NoError(t, err)
		r.Header.Set("Content-Type", "application/json")
		r.Header.Set(extension.AdmissionHeader, token)
		response, err := (&http.Client{Transport: transport}).Do(r)
		require.NoError(t, err)
		defer response.Body.Close()
		return response.StatusCode
	}
	if mode == "invalid-envelope" {
		base := extension.CallbackRequest{Operation: extension.OperationHumanManualMergeSubmit, RepositoryID: repository, HumanManualMerge: &q, ManualMergeInstallationID: installation}
		for _, change := range []string{"mixed", "operation-id", "installation", "actor", "repository", "selector"} {
			request := base
			capture := q
			request.HumanManualMerge = &capture
			switch change {
			case "mixed":
				request.HumanThread = &extension.HumanThreadRequest{}
			case "operation-id":
				request.ManualMergeOperationID = q.OperationID
			case "installation":
				request.ManualMergeInstallationID = "bad"
			case "actor":
				capture.Expected.ActorID = "1"
			case "repository":
				capture.Expected.RepositoryID = "1"
			case "selector":
				request.ManualMergeSnapshot = &extension.RepositoryManualMergeSnapshotRequest{Index: "1", CommitOID: fixture.base}
			}
			require.Equal(t, http.StatusBadRequest, rawCall(request), change)
		}
		require.Equal(t, http.StatusBadRequest, rawCall(extension.CallbackRequest{Operation: extension.OperationCurrentActor, HumanManualMerge: &q}))
		unchanged, err := a.GetHumanManualMerge(ctx, repository, q.OperationID)
		require.NoError(t, err)
		require.Nil(t, unchanged.Record)
		return
	}
	if mode == "foreign-record" {
		_, err := db.GetEngine(ctx).Insert(&nativeoperation_model.Operation{InstallationID: installation, OperationID: q.OperationID, Kind: nativeoperation_model.KindHumanManualMerge, ActorID: 1, RepositoryID: repo.ID, Submitted: true, EffectState: nativeoperation_model.EffectNotCommitted, IntentDigest: strings.Repeat("a", 64)})
		require.NoError(t, err)
		_, err = a.GetHumanManualMerge(ctx, repository, q.OperationID)
		require.ErrorIs(t, err, extension.ErrHumanManualMergeAdmission)
		return
	}
	if mode == "missing-cap" {
		delete(entry.capabilities, extension.CapabilityHumanMerges)
		entry.capabilities[extension.CapabilityHumanReviews] = struct{}{}
	}
	if mode == "read-method" {
		entry.method = http.MethodGet
	}
	if mode == "session-before" {
		fixture.session.uid = 1
	}
	if mode == "early-cancel" {
		cancelled, err := a.CancelHumanManualMerge(ctx, installation, repository, q.OperationID)
		require.NoError(t, err)
		require.Equal(t, extension.CancellationCancelled, cancelled.CancellationStatus)
	}
	if mode == "partial" {
		_, err := db.GetEngine(ctx).Exec(fmt.Sprintf("CREATE TRIGGER fail_manual_sdk_finish BEFORE UPDATE OF is_closed ON issue WHEN NEW.id=%d BEGIN SELECT RAISE(ABORT, 'manual SDK partial finishing'); END", target.ID))
		require.NoError(t, err)
		t.Cleanup(func() {
			_, err := db.GetEngine(context.WithoutCancel(ctx)).Exec("DROP TRIGGER fail_manual_sdk_finish")
			require.NoError(t, err)
		})
	}
	if mode == "reader" {
		_, err := db.GetEngine(ctx).Where("repo_id=? AND user_id=?", repo.ID, 2).Cols("mode").Update(&access_model.Access{Mode: perm.AccessModeRead})
		require.NoError(t, err)
		_, err = db.GetEngine(ctx).Where("repo_id=? AND user_id=?", repo.ID, 2).Cols("mode").Update(&repo_model.Collaboration{Mode: perm.AccessModeRead})
		require.NoError(t, err)
	}
	if mode == "submit-result-binding" {
		mutation.Store("submit-commit")
	}
	var record extension.OperationRecord
	var submitErr error
	if mode == "session-after-commit" || mode == "concurrent" || mode == "observation-pending" {
		point := nativeoperation_service.CrashPointHumanManualMergeAfterPrimary
		if mode == "concurrent" {
			point = nativeoperation_service.CrashPointHumanManualMergeBeforePrimary
		}
		if mode == "observation-pending" {
			point = nativeoperation_service.CrashPointHumanManualMergeAfterPrimary
		}
		dir := t.TempDir()
		t.Setenv("NATIVEOP_TEST_CRASH_POINT", point)
		t.Setenv("NATIVEOP_TEST_CRASH_BARRIER_DIR", dir)
		t.Setenv("NATIVEOP_TEST_CRASH_TIMEOUT_SECONDS", "10")
		type result struct {
			record extension.OperationRecord
			err    error
		}
		done := make(chan result, 1)
		go func() { r, e := a.SubmitHumanManualMerge(ctx, installation, q); done <- result{r, e} }()
		require.Eventually(t, func() bool { _, err := os.Stat(filepath.Join(dir, point+".entered")); return err == nil }, 3*time.Second, 10*time.Millisecond)
		if mode == "observation-pending" {
			pending, err := a.GetHumanManualMerge(ctx, repository, q.OperationID)
			require.NoError(t, err)
			require.NotNil(t, pending.Record)
			require.Equal(t, extension.EffectCommitted, pending.Record.EffectState)
			require.Equal(t, extension.CompletionPending, pending.Record.CompletionState)
			preparation, err := json.Marshal(q)
			require.NoError(t, err)
			exportHumanMergeObservation(t, "manual", mode, observationCommand, "manual", "", q.Expected.CommitOID, q.Expected.Index, q.Expected.RepositoryID, q.Expected.ActorID, preparation, *pending.Record)
		} else if mode == "session-after-commit" {
			fixture.session.uid = 1
		} else {
			duplicate, err := a.SubmitHumanManualMerge(ctx, installation, q)
			require.NoError(t, err)
			require.Equal(t, extension.EffectPending, duplicate.EffectState)
			changed := q
			changed.Expected.CommitOID = fixture.tip
			_, err = a.SubmitHumanManualMerge(ctx, installation, changed)
			require.ErrorIs(t, err, extension.ErrHumanManualMergeConflict)
		}
		require.NoError(t, os.WriteFile(filepath.Join(dir, point+".release"), []byte("continue\n"), 0o600))
		select {
		case result := <-done:
			record, submitErr = result.record, result.err
		case <-time.After(8 * time.Second):
			t.Fatal("manual SDK callback did not return")
		}
	} else {
		record, submitErr = a.SubmitHumanManualMerge(ctx, installation, q)
	}
	mutation.Store("")
	fixture.session.uid = 2
	switch mode {
	case "missing-cap", "session-before", "session-after-commit":
		require.ErrorIs(t, submitErr, extension.ErrHumanManualMergeAdmission)
	case "read-method":
		require.ErrorIs(t, submitErr, extension.ErrHumanManualMergeQuery)
	case "lost-reply", "submit-result-binding":
		require.Error(t, submitErr)
	default:
		require.NoError(t, submitErr)
	}
	if mode == "missing-cap" {
		entry.capabilities[extension.CapabilityHumanMerges] = struct{}{}
	}
	entry.method = http.MethodPost
	lookup, err := a.GetHumanManualMerge(ctx, repository, q.OperationID)
	require.NoError(t, err)
	require.Equal(t, installation, lookup.InstallationID)
	if mode == "missing-cap" || mode == "read-method" || mode == "session-before" {
		require.Nil(t, lookup.Record)
		return
	}
	require.NotNil(t, lookup.Record)
	committed := mode != "early-cancel" && mode != "reader"
	if committed {
		require.Equal(t, extension.EffectCommitted, lookup.Record.EffectState)
		completion := extension.CompletionComplete
		if mode == "partial" {
			completion = extension.CompletionNeedsIntervention
		}
		require.Equal(t, completion, lookup.Record.CompletionState)
		var receipt extension.HumanManualMergeReceipt
		require.NoError(t, json.Unmarshal(lookup.Record.Receipt, &receipt))
		require.True(t, extension.ValidHumanManualMergeReceipt(receipt, q))
	} else {
		require.Equal(t, extension.EffectNotCommitted, lookup.Record.EffectState)
	}
	require.NoError(t, queue.GetManager().FlushAll(ctx, 5*time.Second))
	current, err := issues_model.GetPullRequestByID(ctx, pr.ID)
	require.NoError(t, err)
	require.Equal(t, committed, current.HasMerged)
	reference, err := issues_model.GetIssueByID(ctx, target.ID)
	require.NoError(t, err)
	require.Equal(t, committed && mode != "partial", reference.IsClosed)
	if mode == "lost-reply" {
		require.True(t, dropped.Load())
	}
	if submitErr == nil {
		require.Equal(t, *lookup.Record, record)
	}
	history, err := db.GetEngine(ctx).Where("issue_id=? AND type=?", issue.ID, issues_model.CommentTypeMergePull).Count(new(issues_model.Comment))
	require.NoError(t, err)
	if committed {
		require.EqualValues(t, 1, history)
	} else {
		require.Zero(t, history)
	}
	if mode == "result-binding" {
		for _, change := range []string{"actor", "repository", "kind", "digest", "completion", "installation", "extra", "receipt", "receipt-digest", "unknown-receipt"} {
			mutation.Store(change)
			_, err := a.GetHumanManualMerge(ctx, repository, q.OperationID)
			require.Error(t, err, change)
		}
		mutation.Store("")
	}
	if mode == "installation" {
		require.NoError(t, manager.Close())
		store, err := packages.OpenPackageStore(root)
		require.NoError(t, err)
		require.NoError(t, store.Remove("soda"))
		require.NoError(t, store.Close())
		writePackage()
		_, fresh, newInstallation, newSocket := start()
		require.NotEqual(t, installation, newInstallation)
		freshAuthority, _, _ := bind(fresh, newSocket)
		absent, err := freshAuthority.GetHumanManualMerge(ctx, repository, q.OperationID)
		require.NoError(t, err)
		require.Equal(t, newInstallation, absent.InstallationID)
		require.Nil(t, absent.Record)
		_, err = freshAuthority.SubmitHumanManualMerge(ctx, installation, q)
		require.ErrorIs(t, err, extension.ErrHumanManualMergeAdmission)
		_, err = freshAuthority.CancelHumanManualMerge(ctx, installation, repository, q.OperationID)
		require.ErrorIs(t, err, extension.ErrHumanManualMergeAdmission)
		original, err := nativeoperation_service.Default().Get(ctx, installation, q.OperationID)
		require.NoError(t, err)
		require.Equal(t, *lookup.Record, *original.Record)
		missing, err := nativeoperation_service.Default().Get(ctx, newInstallation, q.OperationID)
		require.NoError(t, err)
		require.Nil(t, missing.Record)
		return
	}
	replayed, err := a.SubmitHumanManualMerge(ctx, installation, q)
	require.NoError(t, err)
	require.Equal(t, *lookup.Record, replayed)
	if observationCommand != "" && mode != "observation-pending" {
		preparation, err := json.Marshal(q)
		require.NoError(t, err)
		exportHumanMergeObservation(t, "manual", mode, observationCommand, "manual", "", q.Expected.CommitOID, q.Expected.Index, q.Expected.RepositoryID, q.Expected.ActorID, preparation, *lookup.Record)
	}
	if mode == "valid" {
		changed := q
		changed.Expected.CommitOID = fixture.tip
		_, err = a.SubmitHumanManualMerge(ctx, installation, changed)
		require.ErrorIs(t, err, extension.ErrHumanManualMergeConflict)
		cancelled, err := a.CancelHumanManualMerge(ctx, installation, repository, q.OperationID)
		require.NoError(t, err)
		require.Equal(t, extension.CancellationTooLate, cancelled.CancellationStatus)
	}
	require.NoError(t, queue.GetManager().FlushAll(ctx, 5*time.Second))
	afterHistory, err := db.GetEngine(ctx).Where("issue_id=? AND type=?", issue.ID, issues_model.CommentTypeMergePull).Count(new(issues_model.Comment))
	require.NoError(t, err)
	require.Equal(t, history, afterHistory)
	require.Equal(t, fixture.tip, sourceTestGit(t, repo.RepoPath(), nil, "rev-parse", "refs/heads/main"))
	pushes, err := db.GetEngine(ctx).Where("repo_id=? AND op_type=?", repo.ID, activities_model.ActionCommitRepo).Count(new(activities_model.Action))
	require.NoError(t, err)
	require.Zero(t, pushes)
	t.Logf("manual SDK %s: actual manager/private socket, effect=%s completion=%s; exact retained replay and unchanged Git", mode, lookup.Record.EffectState, lookup.Record.CompletionState)
}

func prepareHumanMergeSDK(t *testing.T, fixture sourceTestFixture, repo *repo_model.Repository, pr *issues_model.PullRequest, issue, target *issues_model.Issue, method, mode string) {
	t.Helper()
	ctx := t.Context()
	headRepoID := repo.ID
	if method == "private-fork" {
		fork := &repo_model.Repository{OwnerID: repo.OwnerID, OwnerName: repo.OwnerName, Name: "merge-sdk-fork", LowerName: "merge-sdk-fork", IsPrivate: true, DefaultBranch: "work", ObjectFormatName: "sha1"}
		_, err := db.GetEngine(ctx).Insert(fork)
		require.NoError(t, err)
		_, err = db.GetEngine(ctx).Insert(&repo_model.RepoUnit{RepoID: fork.ID, Type: unit.TypeCode}, &access_model.Access{RepoID: fork.ID, UserID: 2, Mode: perm.AccessModeRead}, &repo_model.Collaboration{RepoID: fork.ID, UserID: 2, Mode: perm.AccessModeRead})
		require.NoError(t, err)
		sourceTestGit(t, fixture.work, nil, "clone", "--bare", fixture.work, fork.RepoPath())
		sourceTestGit(t, fork.RepoPath(), nil, "update-ref", "refs/heads/work", fixture.tip)
		headRepoID = fork.ID
		method = "squash"
	}
	sourceTestGit(t, repo.RepoPath(), nil, "update-ref", "refs/heads/main", fixture.base)
	sourceTestGit(t, repo.RepoPath(), nil, "update-ref", "refs/heads/work", fixture.tip)
	sourceTestGit(t, repo.RepoPath(), nil, "update-ref", "refs/pull/1/head", fixture.tip)
	_, err := db.GetEngine(ctx).NoAutoTime().ID(pr.ID).Cols("head_repo_id", "head_branch", "status").Update(&issues_model.PullRequest{HeadRepoID: headRepoID, HeadBranch: "work", Status: issues_model.PullRequestStatusMergeable})
	require.NoError(t, err)
	pullUnit, err := repo.GetUnit(ctx, unit.TypePullRequests)
	require.NoError(t, err)
	config := pullUnit.PullRequestsConfig()
	config.AllowMerge, config.AllowRebase, config.AllowRebaseMerge, config.AllowSquash, config.AllowFastForwardOnly = true, true, true, true, true
	_, err = db.GetEngine(ctx).ID(pullUnit.ID).Cols("config").Update(pullUnit)
	require.NoError(t, err)
	oldApp, oldConf, oldToken, oldLFS := setting.AppPath, setting.CustomConf, setting.InternalToken, setting.LFS.StartServer
	t.Cleanup(func() {
		setting.AppPath, setting.CustomConf, setting.InternalToken, setting.LFS.StartServer = oldApp, oldConf, oldToken, oldLFS
	})
	setting.AppPath = os.Getenv("SODA_FOUNTAIN_MERGE_HOOK_EXECUTABLE")
	require.True(t, filepath.IsAbs(setting.AppPath))
	setting.CustomConf = filepath.Join(t.TempDir(), "app.ini")
	secret := make([]byte, 32)
	_, err = rand.Read(secret)
	require.NoError(t, err)
	setting.InternalToken = fmt.Sprintf("%x", secret)
	setting.LFS.StartServer = true
	var preparedCalls, committedCalls atomic.Int64
	privateHandler := http.StripPrefix("/api/internal", private_router.Routes())
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		r = r.WithContext(web_middleware.WithContextData(r.Context()))
		if strings.Contains(r.URL.Path, "/reference-transaction/") {
			body, err := io.ReadAll(io.LimitReader(r.Body, 1<<20))
			require.NoError(t, err)
			r.Body = io.NopCloser(bytes.NewReader(body))
			var options private_api.TransactionOptions
			require.NoError(t, json.Unmarshal(body, &options))
			if options.Phase == nativeoperation_service.PhasePrepared {
				preparedCalls.Add(1)
				if mode == "session-at-hook" {
					fixture.session.uid = 1
				}
			}
			if options.Phase == nativeoperation_service.PhaseCommitted {
				committedCalls.Add(1)
			}
		}
		privateHandler.ServeHTTP(w, r)
	}))
	t.Cleanup(server.Close)
	currentUser, err := osuser.Current()
	require.NoError(t, err)
	ini := fmt.Sprintf("RUN_USER = %s\nRUN_MODE = prod\n[server]\nPROTOCOL = http\nLOCAL_ROOT_URL = %s/\nAPP_DATA_PATH = %s\n[repository]\nROOT = %s\n[security]\nINSTALL_LOCK = true\nINTERNAL_TOKEN = %s\n[log]\nMODE = console\nLEVEL = fatal\n", currentUser.Username, server.URL, setting.AppDataPath, setting.RepoRootPath, setting.InternalToken)
	require.NoError(t, os.WriteFile(setting.CustomConf, []byte(ini), 0o600))
	require.NoError(t, repo_module.CreateDelegateHooks(repo.RepoPath()))
	require.NoError(t, pull_service.InitPullRequestTaskQueue())
	pull_service.StartPullRequestTasks()
	operation, err := extension.HumanMergeOperationID("2", strconv.FormatInt(repo.ID, 10), "sdk-merge-"+method+"-"+mode)
	require.NoError(t, err)
	q := extension.HumanMergeRequest{OperationID: operation, Expected: extension.RepositoryMergeSnapshot{Index: strconv.FormatInt(pr.Index, 10), Method: method}, Message: "SDK native merge 完整 🌋\r\n\r\nCaptured human message.\n", NotAfter: time.Now().Add(time.Minute).Unix()}
	checkHumanMergeSDK(t, fixture, repo, pr, issue, target, q, mode, &preparedCalls, &committedCalls)
}

func checkHumanMergeSDK(t *testing.T, fixture sourceTestFixture, repo *repo_model.Repository, pr *issues_model.PullRequest, issue, target *issues_model.Issue, q extension.HumanMergeRequest, mode string, preparedCalls, committedCalls *atomic.Int64) {
	t.Helper()
	ctx := t.Context()
	root := shortWitnessRoot(t)
	backend := os.Getenv("SODA_FOUNTAIN_MERGE_SDK_BACKEND")
	require.True(t, filepath.IsAbs(backend))
	packageDir := filepath.Join(root, "soda")
	writePackage := func() {
		require.NoError(t, os.Mkdir(packageDir, 0o700))
		require.NoError(t, os.WriteFile(filepath.Join(packageDir, "run"), []byte(fmt.Sprintf("#!/bin/sh\nexec %q\n", backend)), 0o700))
		if os.Getenv("SODA_FOUNTAIN_MERGE_HTTP_MANIFEST") != "" {
			require.NoError(t, os.WriteFile(filepath.Join(packageDir, "run"), []byte(fmt.Sprintf("#!/bin/sh\nexec %q --package-id soda --soda-socket %q --factory-socket %q\n", backend, filepath.Join(root, "soda-http"), filepath.Join(root, "factory-http"))), 0o700))
		}
		require.NoError(t, os.WriteFile(filepath.Join(packageDir, "extension.json"), []byte(`{"protocol":1,"id":"soda","name":"MergeSDK","version":"1.0","executable":"run","capabilities":["native.actor.read","native.repository.read","native.repository.merges.write"]}`), 0o600))
		if manifest := os.Getenv("SODA_FOUNTAIN_MERGE_HTTP_MANIFEST"); manifest != "" {
			raw, err := os.ReadFile(manifest)
			require.NoError(t, err)
			require.NoError(t, os.WriteFile(filepath.Join(packageDir, "extension.json"), raw, 0o600))
		}
	}
	writePackage()
	previous := extensions_service.GetManager()
	t.Cleanup(func() { extensions_service.SetDefault(previous) })
	var dropped atomic.Bool
	var mutation atomic.Value
	mutation.Store("")
	factory := func(instance string) http.Handler {
		handler := CallbackHandlerForInstance(instance)
		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			body, err := io.ReadAll(r.Body)
			require.NoError(t, err)
			r.Body = io.NopCloser(bytes.NewReader(body))
			var request extension.CallbackRequest
			require.NoError(t, json.Unmarshal(body, &request))
			change := mutation.Load().(string)
			if request.Operation != extension.OperationHumanMergeSubmit && request.Operation != extension.OperationHumanMergeGet && request.Operation != extension.OperationHumanMergeCancel {
				change = ""
			}
			intercept := mode == "lost-reply" && request.Operation == extension.OperationHumanMergeSubmit || change != ""
			if !intercept {
				handler.ServeHTTP(w, r)
				return
			}
			recorder := httptest.NewRecorder()
			handler.ServeHTTP(recorder, r)
			if mode == "lost-reply" && request.Operation == extension.OperationHumanMergeSubmit && recorder.Code == http.StatusOK && dropped.CompareAndSwap(false, true) {
				connection, _, err := w.(http.Hijacker).Hijack()
				require.NoError(t, err)
				require.NoError(t, connection.Close())
				return
			}
			data := recorder.Body.Bytes()
			if change != "" && recorder.Code == http.StatusOK {
				var result extension.CallbackResponse
				require.NoError(t, json.Unmarshal(data, &result))
				record := result.HumanMerge.Record
				if record == nil {
					change = ""
				}
				switch change {
				case "actor":
					record.ActorID = "1"
				case "repository":
					record.RepositoryID = "1"
				case "kind":
					record.Kind = extension.OperationKindHumanReview
				case "digest":
					record.IntentDigest = strings.Repeat("f", 64)
				case "completion":
					record.CompletionState = "unknown-completion"
				case "installation":
					result.HumanMerge.InstallationID = "11111111-2222-4333-8444-555555555555"
				case "extra":
					result.Actor = &extension.Actor{ID: "2"}
				case "receipt", "receipt-digest", "submit-commit", "unknown-receipt":
					var receipt extension.HumanMergeReceipt
					require.NoError(t, json.Unmarshal(record.Receipt, &receipt))
					if change == "receipt" {
						receipt.ResultOID = "HEAD"
					}
					if change == "receipt-digest" {
						receipt.IntentDigest = strings.Repeat("a", 64)
					}
					if change == "submit-commit" {
						receipt.BaseBranch = "different-target"
					}
					raw, err := json.Marshal(receipt)
					require.NoError(t, err)
					if change == "unknown-receipt" {
						raw = append(raw[:len(raw)-1], []byte(`,"unexpected":true}`)...)
					}
					record.Receipt = raw
				}
				data, err = json.Marshal(result)
				require.NoError(t, err)
			}
			for key, values := range recorder.Header() {
				for _, value := range values {
					w.Header().Add(key, value)
				}
			}
			w.WriteHeader(recorder.Code)
			_, _ = w.Write(data)
		})
	}
	start := func() (*extensions_service.Manager, extensions_service.Descriptor, string, string) {
		store, err := packages.OpenPackageStore(root)
		require.NoError(t, err)
		_, err = store.SetDesired("soda", true)
		require.NoError(t, err)
		require.NoError(t, store.Close())
		manager := extensions_service.NewManager(root)
		if os.Getenv("SODA_FOUNTAIN_MERGE_HTTP_MANIFEST") != "" {
			require.NoError(t, manager.SetServiceCallbackEndpoint(filepath.Join(root, "svc"), CallbackHandlerForService()))
		}
		require.NoError(t, manager.SetCallbackHandlerFactory(factory))
		extensions_service.SetDefault(manager)
		t.Cleanup(func() { require.NoError(t, manager.Close()) })
		require.NoError(t, manager.Start(ctx))
		var descriptor extensions_service.Descriptor
		require.Eventually(t, func() bool { var ready bool; descriptor, _, ready = manager.Lookup("soda"); return ready }, 15*time.Second, 20*time.Millisecond)
		installation, ok := manager.AdmittedInstallation("soda", descriptor.InstanceID)
		require.True(t, ok)
		sockets, err := filepath.Glob(filepath.Join(root, ".runtime", "*", "c"))
		require.NoError(t, err)
		require.Len(t, sockets, 1)
		return manager, descriptor, installation, sockets[0]
	}
	manager, descriptor, installation, socket := start()
	bind := func(descriptor extensions_service.Descriptor, socket string) (extension.Authority, *callbackAdmission, string) {
		authority := fixture.authority
		authority.InstanceID = descriptor.InstanceID
		if os.Getenv("SODA_FOUNTAIN_MERGE_HTTP_MANIFEST") != "" {
			authority.Contribution.ID = "feed"
		}
		requestCtx, cancel := context.WithCancel(ctx)
		t.Cleanup(cancel)
		entry := &callbackAdmission{method: http.MethodPost, instanceID: descriptor.InstanceID, actorID: 2, sessionID: "source-test-session", session: fixture.session, authority: authority, capabilities: map[string]struct{}{extension.CapabilityActorRead: {}, extension.CapabilityRepositoryRead: {}, extension.CapabilityHumanMerges: {}}, requestCtx: requestCtx, cancel: cancel}
		token, err := nativeAdmissions.issue(entry)
		require.NoError(t, err)
		t.Cleanup(func() { nativeAdmissions.revoke(token) })
		t.Setenv(extension.CallbackEnv, socket)
		t.Setenv(extension.ServiceCallbackEnv, "")
		raw, err := json.Marshal(authority)
		require.NoError(t, err)
		request := httptest.NewRequest(http.MethodPost, "/merge-sdk", nil)
		request.Header.Set(extension.ContextHeader, string(raw))
		request.Header.Set(extension.AdmissionHeader, token)
		a, err := extension.RequestContext(request)
		require.NoError(t, err)
		return a, entry, token
	}
	a, entry, token := bind(descriptor, socket)
	repository := strconv.FormatInt(repo.ID, 10)
	snapshot, err := a.RepositoryMergeSnapshot(ctx, repository, extension.RepositoryMergeSnapshotRequest{Index: q.Expected.Index, Method: q.Expected.Method})
	require.NoError(t, err)
	q.Expected = snapshot
	if os.Getenv("SODA_FOUNTAIN_MERGE_ADAPTER_PROBE") != "" {
		checkCanonicalHumanMergeAdapter(t, fixture, repo, issue, target, a, entry, token, socket, installation, q.Expected.Method, q.Message, "", q.Expected.Index, mode, preparedCalls, committedCalls, func(v string) { mutation.Store(v) }, func() (extension.Authority, *callbackAdmission, string, string, string) {
			require.NoError(t, manager.Close())
			store, err := packages.OpenPackageStore(root)
			require.NoError(t, err)
			require.NoError(t, store.Remove("soda"))
			require.NoError(t, store.Close())
			writePackage()
			_, fresh, newInstallation, newSocket := start()
			freshAuthority, newEntry, newToken := bind(fresh, newSocket)
			return freshAuthority, newEntry, newToken, newSocket, newInstallation
		})
		return
	}
	observationCommand := ""
	if os.Getenv("SODA_FOUNTAIN_MERGE_OBSERVATION_EXPORT") != "" {
		nonce := make([]byte, 16)
		_, err := rand.Read(nonce)
		require.NoError(t, err)
		observationCommand = fmt.Sprintf("%x", nonce)
		q.OperationID, err = extension.HumanMergeOperationID(q.Expected.ActorID, q.Expected.RepositoryID, observationCommand)
		require.NoError(t, err)
	}
	t.Cleanup(func() {
		held, err := nativeoperation_model.ReadReservation(context.WithoutCancel(ctx))
		require.NoError(t, err)
		if held.Owner == "cond:"+installation+"/"+q.OperationID {
			require.NoError(t, nativeoperation_model.ReleaseExactOwner(context.WithoutCancel(ctx), held.Owner, held.Generation))
		}
	}) // Disposal of an owned incomplete fixture, never product recovery.
	absent, err := a.GetHumanMerge(ctx, repository, q.OperationID)
	require.NoError(t, err)
	require.Equal(t, installation, absent.InstallationID)
	require.Nil(t, absent.Record)
	rawCall := func(request extension.CallbackRequest) int {
		t.Helper()
		request.Authority = entry.authority
		body, err := json.Marshal(request)
		require.NoError(t, err)
		transport := &http.Transport{DialContext: func(c context.Context, _, _ string) (net.Conn, error) {
			return (&net.Dialer{}).DialContext(c, "unix", socket)
		}}
		defer transport.CloseIdleConnections()
		r, err := http.NewRequestWithContext(ctx, http.MethodPost, "http://native"+extension.NativeCallbackPath, bytes.NewReader(body))
		require.NoError(t, err)
		r.Header.Set("Content-Type", "application/json")
		r.Header.Set(extension.AdmissionHeader, token)
		response, err := (&http.Client{Transport: transport}).Do(r)
		require.NoError(t, err)
		defer response.Body.Close()
		return response.StatusCode
	}
	if mode == "invalid-envelope" {
		base := extension.CallbackRequest{Operation: extension.OperationHumanMergeSubmit, RepositoryID: repository, HumanMerge: &q, MergeInstallationID: installation}
		for _, change := range []string{"mixed", "operation-id", "installation", "actor", "repository", "selector"} {
			request := base
			capture := q
			request.HumanMerge = &capture
			switch change {
			case "mixed":
				request.HumanThread = &extension.HumanThreadRequest{}
			case "operation-id":
				request.MergeOperationID = q.OperationID
			case "installation":
				request.MergeInstallationID = "bad"
			case "actor":
				capture.Expected.ActorID = "1"
			case "repository":
				capture.Expected.RepositoryID = "1"
			case "selector":
				request.MergeSnapshot = &extension.RepositoryMergeSnapshotRequest{Index: "1", Method: q.Expected.Method}
			}
			require.Equal(t, http.StatusBadRequest, rawCall(request), change)
		}
		require.Equal(t, http.StatusBadRequest, rawCall(extension.CallbackRequest{Operation: extension.OperationCurrentActor, HumanMerge: &q}))
		unchanged, err := a.GetHumanMerge(ctx, repository, q.OperationID)
		require.NoError(t, err)
		require.Nil(t, unchanged.Record)
		return
	}
	if mode == "foreign-record" {
		_, err := db.GetEngine(ctx).Insert(&nativeoperation_model.Operation{InstallationID: installation, OperationID: q.OperationID, Kind: nativeoperation_model.KindHumanMerge, ActorID: 1, RepositoryID: repo.ID, Submitted: true, EffectState: nativeoperation_model.EffectNotCommitted, IntentDigest: strings.Repeat("a", 64)})
		require.NoError(t, err)
		_, err = a.GetHumanMerge(ctx, repository, q.OperationID)
		require.ErrorIs(t, err, extension.ErrHumanMergeAdmission)
		return
	}
	if mode == "missing-cap" {
		delete(entry.capabilities, extension.CapabilityHumanMerges)
		entry.capabilities[extension.CapabilityHumanReviews] = struct{}{}
	}
	if mode == "read-method" {
		entry.method = http.MethodGet
	}
	if mode == "session-before" {
		fixture.session.uid = 1
	}
	if mode == "early-cancel" {
		cancelled, err := a.CancelHumanMerge(ctx, installation, repository, q.OperationID)
		require.NoError(t, err)
		require.Equal(t, extension.CancellationCancelled, cancelled.CancellationStatus)
	}
	if mode == "partial" {
		_, err := db.GetEngine(ctx).Exec(fmt.Sprintf("CREATE TRIGGER fail_merge_sdk_finish BEFORE UPDATE OF is_closed ON issue WHEN NEW.id=%d BEGIN SELECT RAISE(ABORT, 'merge SDK partial finishing'); END", target.ID))
		require.NoError(t, err)
		t.Cleanup(func() {
			_, err := db.GetEngine(context.WithoutCancel(ctx)).Exec("DROP TRIGGER fail_merge_sdk_finish")
			require.NoError(t, err)
		})
	}
	if mode == "reader" {
		_, err := db.GetEngine(ctx).Where("repo_id=? AND user_id=?", repo.ID, 2).Cols("mode").Update(&access_model.Access{Mode: perm.AccessModeRead})
		require.NoError(t, err)
		_, err = db.GetEngine(ctx).Where("repo_id=? AND user_id=?", repo.ID, 2).Cols("mode").Update(&repo_model.Collaboration{Mode: perm.AccessModeRead})
		require.NoError(t, err)
	}
	if mode == "submit-result-binding" {
		mutation.Store("submit-commit")
	}
	var record extension.OperationRecord
	var submitErr error
	if mode == "session-after-commit" || mode == "concurrent" || mode == "observation-pending" {
		point := nativeoperation_service.CrashPointHumanMergeAfterPush
		if mode == "concurrent" {
			point = nativeoperation_service.CrashPointHumanMergeBeforePush
		}
		if mode == "observation-pending" {
			point = nativeoperation_service.CrashPointHumanMergeAfterFinish
		}
		dir := t.TempDir()
		t.Setenv("NATIVEOP_TEST_CRASH_POINT", point)
		t.Setenv("NATIVEOP_TEST_CRASH_BARRIER_DIR", dir)
		t.Setenv("NATIVEOP_TEST_CRASH_TIMEOUT_SECONDS", "10")
		type result struct {
			record extension.OperationRecord
			err    error
		}
		done := make(chan result, 1)
		go func() { r, e := a.SubmitHumanMerge(ctx, installation, q); done <- result{r, e} }()
		require.Eventually(t, func() bool { _, err := os.Stat(filepath.Join(dir, point+".entered")); return err == nil }, 3*time.Second, 10*time.Millisecond)
		if mode == "observation-pending" {
			pending, err := a.GetHumanMerge(ctx, repository, q.OperationID)
			require.NoError(t, err)
			require.NotNil(t, pending.Record)
			require.Equal(t, extension.EffectCommitted, pending.Record.EffectState)
			require.Equal(t, extension.CompletionPending, pending.Record.CompletionState)
			preparation, err := json.Marshal(q)
			require.NoError(t, err)
			exportHumanMergeObservation(t, "push", mode, observationCommand, q.Expected.Method, q.Message, "", q.Expected.Index, q.Expected.RepositoryID, q.Expected.ActorID, preparation, *pending.Record)
		} else if mode == "session-after-commit" {
			fixture.session.uid = 1
		} else {
			duplicate, err := a.SubmitHumanMerge(ctx, installation, q)
			require.NoError(t, err)
			require.Equal(t, extension.EffectPending, duplicate.EffectState)
			changed := q
			changed.Message += "\nchanged captured message"
			_, err = a.SubmitHumanMerge(ctx, installation, changed)
			require.ErrorIs(t, err, extension.ErrHumanMergeConflict)
		}
		require.NoError(t, os.WriteFile(filepath.Join(dir, point+".release"), []byte("continue\n"), 0o600))
		select {
		case result := <-done:
			record, submitErr = result.record, result.err
		case <-time.After(8 * time.Second):
			t.Fatal("merge SDK callback did not return")
		}
	} else {
		record, submitErr = a.SubmitHumanMerge(ctx, installation, q)
	}
	mutation.Store("")
	fixture.session.uid = 2
	switch mode {
	case "missing-cap", "session-before", "session-after-commit", "session-at-hook":
		require.ErrorIs(t, submitErr, extension.ErrHumanMergeAdmission)
	case "read-method":
		require.ErrorIs(t, submitErr, extension.ErrHumanMergeQuery)
	case "lost-reply", "submit-result-binding":
		require.Error(t, submitErr)
	default:
		require.NoError(t, submitErr)
	}
	if mode == "missing-cap" {
		entry.capabilities[extension.CapabilityHumanMerges] = struct{}{}
	}
	entry.method = http.MethodPost
	lookup, err := a.GetHumanMerge(ctx, repository, q.OperationID)
	require.NoError(t, err)
	require.Equal(t, installation, lookup.InstallationID)
	if mode == "missing-cap" || mode == "read-method" || mode == "session-before" {
		require.Nil(t, lookup.Record)
		return
	}
	require.NotNil(t, lookup.Record)
	committed := mode != "early-cancel" && mode != "reader" && mode != "session-at-hook"
	if committed {
		require.Equal(t, extension.EffectCommitted, lookup.Record.EffectState)
		completion := extension.CompletionComplete
		if mode == "partial" {
			completion = extension.CompletionNeedsIntervention
		}
		require.Equal(t, completion, lookup.Record.CompletionState)
		var receipt extension.HumanMergeReceipt
		require.NoError(t, json.Unmarshal(lookup.Record.Receipt, &receipt))
		require.True(t, extension.ValidHumanMergeReceipt(receipt, q))
	} else {
		require.Equal(t, extension.EffectNotCommitted, lookup.Record.EffectState)
	}
	require.NoError(t, queue.GetManager().FlushAll(ctx, 5*time.Second))
	current, err := issues_model.GetPullRequestByID(ctx, pr.ID)
	require.NoError(t, err)
	require.Equal(t, committed, current.HasMerged)
	reference, err := issues_model.GetIssueByID(ctx, target.ID)
	require.NoError(t, err)
	require.Equal(t, committed && mode != "partial", reference.IsClosed)
	if mode == "lost-reply" {
		require.True(t, dropped.Load())
	}
	if submitErr == nil {
		require.Equal(t, *lookup.Record, record)
	}
	history, err := db.GetEngine(ctx).Where("issue_id=? AND type=?", issue.ID, issues_model.CommentTypeMergePull).Count(new(issues_model.Comment))
	require.NoError(t, err)
	if committed {
		require.EqualValues(t, 1, history)
	} else {
		require.Zero(t, history)
	}
	if mode == "result-binding" {
		for _, change := range []string{"actor", "repository", "kind", "digest", "completion", "installation", "extra", "receipt", "receipt-digest", "unknown-receipt"} {
			mutation.Store(change)
			_, err := a.GetHumanMerge(ctx, repository, q.OperationID)
			require.Error(t, err, change)
		}
		mutation.Store("")
	}
	if mode == "installation" {
		require.NoError(t, manager.Close())
		store, err := packages.OpenPackageStore(root)
		require.NoError(t, err)
		require.NoError(t, store.Remove("soda"))
		require.NoError(t, store.Close())
		writePackage()
		_, fresh, newInstallation, newSocket := start()
		require.NotEqual(t, installation, newInstallation)
		freshAuthority, _, _ := bind(fresh, newSocket)
		absent, err := freshAuthority.GetHumanMerge(ctx, repository, q.OperationID)
		require.NoError(t, err)
		require.Equal(t, newInstallation, absent.InstallationID)
		require.Nil(t, absent.Record)
		_, err = freshAuthority.SubmitHumanMerge(ctx, installation, q)
		require.ErrorIs(t, err, extension.ErrHumanMergeAdmission)
		_, err = freshAuthority.CancelHumanMerge(ctx, installation, repository, q.OperationID)
		require.ErrorIs(t, err, extension.ErrHumanMergeAdmission)
		original, err := nativeoperation_service.Default().Get(ctx, installation, q.OperationID)
		require.NoError(t, err)
		require.Equal(t, *lookup.Record, *original.Record)
		missing, err := nativeoperation_service.Default().Get(ctx, newInstallation, q.OperationID)
		require.NoError(t, err)
		require.Nil(t, missing.Record)
		return
	}
	beforePrepared, beforeCommitted := preparedCalls.Load(), committedCalls.Load()
	beforeTarget := sourceTestGit(t, repo.RepoPath(), nil, "rev-parse", "refs/heads/main")
	replayed, err := a.SubmitHumanMerge(ctx, installation, q)
	require.NoError(t, err)
	require.Equal(t, *lookup.Record, replayed)
	if observationCommand != "" && mode != "observation-pending" {
		preparation, err := json.Marshal(q)
		require.NoError(t, err)
		exportHumanMergeObservation(t, "push", mode, observationCommand, q.Expected.Method, q.Message, "", q.Expected.Index, q.Expected.RepositoryID, q.Expected.ActorID, preparation, *lookup.Record)
	}
	if mode == "valid" {
		changed := q
		changed.Message += "\nchanged captured message"
		_, err = a.SubmitHumanMerge(ctx, installation, changed)
		require.ErrorIs(t, err, extension.ErrHumanMergeConflict)
		cancelled, err := a.CancelHumanMerge(ctx, installation, repository, q.OperationID)
		require.NoError(t, err)
		require.Equal(t, extension.CancellationTooLate, cancelled.CancellationStatus)
	}
	require.NoError(t, queue.GetManager().FlushAll(ctx, 5*time.Second))
	afterHistory, err := db.GetEngine(ctx).Where("issue_id=? AND type=?", issue.ID, issues_model.CommentTypeMergePull).Count(new(issues_model.Comment))
	require.NoError(t, err)
	require.Equal(t, history, afterHistory)
	require.Equal(t, beforeTarget, sourceTestGit(t, repo.RepoPath(), nil, "rev-parse", "refs/heads/main"))
	require.Equal(t, beforePrepared, preparedCalls.Load())
	require.Equal(t, beforeCommitted, committedCalls.Load())
	if committed {
		var receipt extension.HumanMergeReceipt
		require.NoError(t, json.Unmarshal(lookup.Record.Receipt, &receipt))
		require.Equal(t, receipt.ResultOID, beforeTarget)
		require.NotEqual(t, fixture.base, beforeTarget)
		require.EqualValues(t, 1, preparedCalls.Load())
		require.EqualValues(t, 1, committedCalls.Load())
	} else {
		require.Equal(t, fixture.base, beforeTarget)
	}
	pushes, err := db.GetEngine(ctx).Where("repo_id=? AND op_type=?", repo.ID, activities_model.ActionCommitRepo).Count(new(activities_model.Action))
	require.NoError(t, err)
	if committed && mode != "partial" {
		require.Positive(t, pushes)
	} else {
		require.Zero(t, pushes)
	}
	t.Logf("merge SDK %s: actual manager/private socket, effect=%s completion=%s; exact retained replay and single native push", mode, lookup.Record.EffectState, lookup.Record.CompletionState)
}

// The separate consumer imports Factory's internal adapter from its own module.
// It uses this actual admitted manager/socket and real canonical PostgreSQL;
// native effects below are observed independently in this host's SQL and Git.
func checkCanonicalHumanMergeAdapter(t *testing.T, fixture sourceTestFixture, repo *repo_model.Repository, issue, target *issues_model.Issue, a extension.Authority, entry *callbackAdmission, token, socket, installation, method, message, commit, number, mode string, preparedCalls, committedCalls *atomic.Int64, mutate func(string), replace func() (extension.Authority, *callbackAdmission, string, string, string)) {
	t.Helper()
	ctx := t.Context()
	probe := os.Getenv("SODA_FOUNTAIN_MERGE_ADAPTER_PROBE")
	require.True(t, filepath.IsAbs(probe))
	dir := shortWitnessRoot(t)
	binding := struct {
		Authority                                                                                    extension.Authority
		Admission, Socket, Repository, Installation, State, Method, Message, CommitOID, Number, Mode string
	}{a, token, socket, strconv.FormatInt(repo.ID, 10), installation, filepath.Join(dir, "capture.json"), method, message, commit, number, mode}
	bindingPath := filepath.Join(dir, "binding.json")
	writeBinding := func() {
		raw, err := json.Marshal(binding)
		require.NoError(t, err)
		if os.Getenv("SODA_FOUNTAIN_MERGE_HTTP") == "1" {
			readAuthority := binding.Authority
			readAuthority.Contribution.Action = "get"
			readCtx, readCancel := context.WithCancel(ctx)
			t.Cleanup(readCancel)
			readEntry := &callbackAdmission{method: http.MethodGet, instanceID: binding.Authority.InstanceID, actorID: 2, sessionID: "source-test-session", session: fixture.session, authority: readAuthority, capabilities: entry.capabilities, requestCtx: readCtx, cancel: readCancel}
			readToken, err := nativeAdmissions.issue(readEntry)
			require.NoError(t, err)
			t.Cleanup(func() { nativeAdmissions.revoke(readToken) })
			var fields map[string]any
			require.NoError(t, json.Unmarshal(raw, &fields))
			fields["ReadAuthority"], fields["ReadAdmission"] = readAuthority, readToken
			raw, err = json.Marshal(fields)
			require.NoError(t, err)
		}
		require.NoError(t, os.WriteFile(bindingPath, raw, 0o600))
	}
	writeBinding()
	run := func(action string) {
		t.Helper()
		command := exec.CommandContext(ctx, probe, action)
		command.Env = append(os.Environ(), "SODA_FOUNTAIN_READ_BINDING="+bindingPath)
		output, err := command.CombinedOutput()
		require.NoError(t, err, "adapter %s: %s", action, output)
	}
	readOnly := func() {
		_, err := db.GetEngine(ctx).Where("repo_id=? AND user_id=?", repo.ID, 2).Cols("mode").Update(&access_model.Access{Mode: perm.AccessModeRead})
		require.NoError(t, err)
		_, err = db.GetEngine(ctx).Where("repo_id=? AND user_id=?", repo.ID, 2).Cols("mode").Update(&repo_model.Collaboration{Mode: perm.AccessModeRead})
		require.NoError(t, err)
	}
	if mode == "prepare-reader" {
		readOnly()
		run("prepare-error")
		return
	}
	run("prepare")
	var capture struct {
		OperationID string `json:"operation_id"`
	}
	raw, err := os.ReadFile(binding.State)
	require.NoError(t, err)
	require.NoError(t, json.Unmarshal(raw, &capture))
	t.Cleanup(func() {
		held, err := nativeoperation_model.ReadReservation(context.WithoutCancel(ctx))
		require.NoError(t, err)
		if held.Owner == "cond:"+installation+"/"+capture.OperationID {
			require.NoError(t, nativeoperation_model.ReleaseExactOwner(context.WithoutCancel(ctx), held.Owner, held.Generation))
		}
	}) // Fixture disposal only; production recovery is never inferred here.
	get := func() extension.OperationLookup {
		t.Helper()
		var o extension.OperationLookup
		var err error
		if method == "manual" {
			o, err = a.GetHumanManualMerge(ctx, binding.Repository, capture.OperationID)
		} else {
			o, err = a.GetHumanMerge(ctx, binding.Repository, capture.OperationID)
		}
		require.NoError(t, err)
		return o
	}
	require.Nil(t, get().Record)
	if mode == "capture-rollback" {
		run("rollback")
		require.Nil(t, get().Record)
		history, err := db.GetEngine(ctx).Where("issue_id=? AND type=?", issue.ID, issues_model.CommentTypeMergePull).Count(new(issues_model.Comment))
		require.NoError(t, err)
		require.Zero(t, history)
		tip := fixture.base
		if method == "manual" {
			tip = fixture.tip
		}
		require.Equal(t, tip, sourceTestGit(t, repo.RepoPath(), nil, "rev-parse", "refs/heads/main"))
		return
	}
	if mode == "invalid-envelope" {
		run("invalid")
		require.Nil(t, get().Record)
		return
	}
	if mode == "early-cancel" {
		run("cancel")
	}
	if mode == "reader" {
		readOnly()
	}
	if mode == "stale" {
		require.NoError(t, nativeoperation_service.Default().WithOrdinaryOwnership(ctx, nativeoperation_service.FamilyRepoSettings, "canonical-merge-stale", nativeoperation_service.Scope{RepositoryID: repo.ID}, func(context.Context) error { return nil }))
	}
	if mode == "partial" {
		_, err := db.GetEngine(ctx).Exec(fmt.Sprintf("CREATE TRIGGER fail_canonical_merge_finish BEFORE UPDATE OF is_closed ON issue WHEN NEW.id=%d BEGIN SELECT RAISE(ABORT, 'canonical merge finishing'); END", target.ID))
		require.NoError(t, err)
		t.Cleanup(func() {
			_, err := db.GetEngine(context.WithoutCancel(ctx)).Exec("DROP TRIGGER fail_canonical_merge_finish")
			require.NoError(t, err)
		})
	}
	if mode == "missing-cap" {
		delete(entry.capabilities, extension.CapabilityHumanMerges)
		entry.capabilities[extension.CapabilityHumanReviews] = struct{}{}
	}
	if mode == "read-method" {
		entry.method = http.MethodGet
	}
	if mode == "session-before" {
		fixture.session.uid = 1
	}
	denied := mode == "missing-cap" || mode == "read-method" || mode == "session-before"
	if denied {
		run("submit-denied")
		run("cancel-denied")
		if mode != "read-method" {
			run("lookup-denied")
		}
		fixture.session.uid = 2
		entry.method = http.MethodPost
		entry.capabilities[extension.CapabilityHumanMerges] = struct{}{}
		require.Nil(t, get().Record)
		return
	}
	if mode == "session-after-commit" || mode == "observation-pending" {
		point := nativeoperation_service.CrashPointHumanMergeAfterFinish
		if method == "manual" {
			point = nativeoperation_service.CrashPointHumanManualMergeAfterPrimary
		}
		barrier := t.TempDir()
		t.Setenv("NATIVEOP_TEST_CRASH_POINT", point)
		t.Setenv("NATIVEOP_TEST_CRASH_BARRIER_DIR", barrier)
		t.Setenv("NATIVEOP_TEST_CRASH_TIMEOUT_SECONDS", "10")
		command := exec.CommandContext(ctx, probe, "submit")
		if mode == "session-after-commit" {
			command = exec.CommandContext(ctx, probe, "submit-error")
		}
		command.Env = append(os.Environ(), "SODA_FOUNTAIN_READ_BINDING="+bindingPath)
		var output bytes.Buffer
		command.Stdout = &output
		command.Stderr = &output
		require.NoError(t, command.Start())
		t.Cleanup(func() {
			if command.ProcessState == nil {
				_ = command.Process.Kill()
				_ = command.Wait()
			}
		})
		require.Eventually(t, func() bool { _, err := os.Stat(filepath.Join(barrier, point+".entered")); return err == nil }, 5*time.Second, 10*time.Millisecond)
		if mode == "session-after-commit" {
			fixture.session.uid = 1
		} else {
			run("lookup-pending")
		}
		require.NoError(t, os.WriteFile(filepath.Join(barrier, point+".release"), []byte("continue\n"), 0o600))
		require.NoError(t, command.Wait(), "adapter async: %s", output.String())
		fixture.session.uid = 2
	} else {
		action := "submit"
		if mode == "concurrent" && os.Getenv("SODA_FOUNTAIN_MERGE_SERVICE") == "1" {
			action = "concurrent"
		}
		if mode == "lost-reply" || mode == "session-at-hook" || mode == "submit-result-binding" {
			action = "submit-error"
		}
		if mode == "submit-result-binding" {
			mutate("submit-commit")
		}
		run(action)
		mutate("")
	}
	fixture.session.uid = 2
	o := get()
	require.NotNil(t, o.Record)
	committed := o.Record.EffectState == extension.EffectCommitted
	if mode == "early-cancel" || mode == "reader" || mode == "stale" || mode == "session-at-hook" {
		require.Equal(t, extension.EffectNotCommitted, o.Record.EffectState)
	} else {
		require.True(t, committed)
	}
	if mode == "partial" {
		require.Equal(t, extension.CompletionNeedsIntervention, o.Record.CompletionState)
		run("lookup-intervention")
	} else {
		run("lookup")
	}
	if mode == "result-binding" {
		mutate("submit-commit")
		run("lookup-conflict")
		mutate("")
	}
	history, err := db.GetEngine(ctx).Where("issue_id=? AND type=?", issue.ID, issues_model.CommentTypeMergePull).Count(new(issues_model.Comment))
	require.NoError(t, err)
	if committed {
		require.EqualValues(t, 1, history)
	} else {
		require.Zero(t, history)
	}
	if mode == "installation" {
		fresh, newEntry, newToken, newSocket, newInstallation := replace()
		require.NotEqual(t, installation, newInstallation)
		binding.Authority, binding.Admission, binding.Socket, binding.Installation = fresh, newToken, newSocket, newInstallation
		entry = newEntry
		writeBinding()
		run("namespace")
		original, err := nativeoperation_service.Default().Get(ctx, installation, capture.OperationID)
		require.NoError(t, err)
		require.Equal(t, *o.Record, *original.Record)
		missing, err := nativeoperation_service.Default().Get(ctx, newInstallation, capture.OperationID)
		require.NoError(t, err)
		require.Nil(t, missing.Record)
		_ = newEntry
		return
	}
	if mode == "permission-loss" {
		readOnly()
		run("prepare-error")
		run("lookup")
		run("cancel")
	} else {
		run("submit")
		run("lookup")
		if mode == "valid" {
			run("cancel")
		}
	}
	afterHistory, err := db.GetEngine(ctx).Where("issue_id=? AND type=?", issue.ID, issues_model.CommentTypeMergePull).Count(new(issues_model.Comment))
	require.NoError(t, err)
	require.Equal(t, history, afterHistory)
	tip := sourceTestGit(t, repo.RepoPath(), nil, "rev-parse", "refs/heads/main")
	if method == "manual" {
		require.Equal(t, fixture.tip, tip)
	} else if committed {
		var receipt extension.HumanMergeReceipt
		require.NoError(t, json.Unmarshal(o.Record.Receipt, &receipt))
		require.Equal(t, receipt.ResultOID, tip)
		require.EqualValues(t, 1, preparedCalls.Load())
		require.EqualValues(t, 1, committedCalls.Load())
	} else {
		require.Equal(t, fixture.base, tip)
	}
	pushes, err := db.GetEngine(ctx).Where("repo_id=? AND op_type=?", repo.ID, activities_model.ActionCommitRepo).Count(new(activities_model.Action))
	require.NoError(t, err)
	if method == "manual" || !committed || mode == "partial" {
		require.Zero(t, pushes)
	} else {
		require.Positive(t, pushes)
	}
	t.Logf("PASS canonical merge adapter %s/%s: real private SDK/native SQL/Git and PostgreSQL capture; effect=%s completion=%s; exact receipts/replay, one primary", method, mode, o.Record.EffectState, o.Record.CompletionState)
}

// Credential-free evidence from actual SDK calls, consumed by the separate
// canonical store integration. This file export is a test boundary, not an API.
func exportHumanMergeObservation(t *testing.T, family, mode, command, method, message, commit, number, repository, actor string, preparation []byte, record extension.OperationRecord) {
	t.Helper()
	directory := os.Getenv("SODA_FOUNTAIN_MERGE_OBSERVATION_EXPORT")
	raw, err := json.Marshal(struct {
		CommandID, Method, Message, CommitOID, Number, Repository, Actor string
		ProviderIntent                                                   []byte
		Record                                                           extension.OperationRecord
	}{command, method, message, commit, number, repository, actor, preparation, record})
	require.NoError(t, err)
	require.NoError(t, os.WriteFile(filepath.Join(directory, family+"-"+mode+".json"), raw, 0o600))
}

type humanManualMergeProcessBinding struct {
	Request        extension.HumanManualMergeRequest
	DataPath       string
	RepositoryRoot string
}

func runHumanManualMergeProcessWorker(t *testing.T, root string) {
	t.Helper()
	raw, err := os.ReadFile(filepath.Join(root, "manual.json"))
	require.NoError(t, err)
	var binding humanManualMergeProcessBinding
	require.NoError(t, json.Unmarshal(raw, &binding))
	engine := openHumanMergeProcessDatabase(t, root)
	t.Cleanup(func() { require.NoError(t, engine.Close()) })
	setting.AppDataPath, setting.RepoRootPath = binding.DataPath, binding.RepositoryRoot
	for _, notifier := range []notify_service.Notifier{uinotification.NewNotifier(), feed.NewNotifier()} {
		notify_service.RegisterNotifier(notifier)
	}
	// Trusted native fixture principal, backed by the actual retained actor.
	// Current browser session transport was qualified separately.
	_, err = nativeoperation_service.NewService().SubmitHumanManualMerge(t.Context(), humanMergeProcessInstallation, binding.Request, humanMergeProcessAdmission)
	t.Fatalf("owned manual worker returned before its process checkpoint: %v", err)
}

func checkHumanManualMergeProcess(t *testing.T, fixture sourceTestFixture, repo *repo_model.Repository, pr *issues_model.PullRequest, issue, target *issues_model.Issue, q extension.HumanManualMergeRequest, mode string) {
	t.Helper()
	if runtime.GOOS != "linux" {
		t.Skip("owned SIGKILL/reap and /proc qualification runs on Linux")
	}
	ctx := t.Context()
	root := t.TempDir()
	for _, name := range []string{"barrier", "worker-tmp"} {
		require.NoError(t, os.Mkdir(filepath.Join(root, name), 0o700))
	}
	require.NoError(t, queue.GetManager().FlushAll(ctx, 5*time.Second))
	_, err := db.GetEngine(ctx).Exec("VACUUM INTO ?", filepath.Join(root, "native.sqlite"))
	require.NoError(t, err)
	raw, err := json.Marshal(humanManualMergeProcessBinding{q, setting.AppDataPath, setting.RepoRootPath})
	require.NoError(t, err)
	require.NoError(t, os.WriteFile(filepath.Join(root, "manual.json"), raw, 0o600))
	point := strings.TrimSuffix(mode, "-altered-receipt")
	altered := mode != point
	logFile, err := os.Create(filepath.Join(root, "worker.log"))
	require.NoError(t, err)
	t.Cleanup(func() { _ = logFile.Close() })
	child := exec.CommandContext(ctx, os.Args[0], "-test.run=^TestRepositoryIssuesCallbackUsesHumanAccessWithoutFactoryBinding$", "-test.v", "-test.timeout=75s")
	child.Env = append(os.Environ(), "SODA_FOUNTAIN_MANUAL_MERGE_PROCESS_WORKER="+root, "TMPDIR="+filepath.Join(root, "worker-tmp"), "NATIVEOP_TEST_CRASH_POINT="+point, "NATIVEOP_TEST_CRASH_BARRIER_DIR="+filepath.Join(root, "barrier"), "NATIVEOP_TEST_CRASH_TIMEOUT_SECONDS=60")
	child.Stdout, child.Stderr = logFile, logFile
	require.NoError(t, child.Start())
	exited := make(chan error, 1)
	go func() { exited <- child.Wait() }()
	reaped := false
	t.Cleanup(func() {
		if !reaped {
			_ = child.Process.Kill()
			select {
			case <-exited:
			case <-time.After(10 * time.Second):
				t.Error("owned manual worker was not reaped during fixture cleanup")
			}
		}
	})
	deadline := time.After(30 * time.Second)
	tick := time.NewTicker(10 * time.Millisecond)
	defer tick.Stop()
	enteredPath := filepath.Join(root, "barrier", point+".entered")
	for entered := false; !entered; {
		select {
		case err := <-exited:
			reaped = true
			output, _ := os.ReadFile(filepath.Join(root, "worker.log"))
			t.Fatalf("owned manual worker exited before %s: %v\n%s", point, err, output)
		case <-deadline:
			output, _ := os.ReadFile(filepath.Join(root, "worker.log"))
			t.Fatalf("owned manual worker never reached %s\n%s", point, output)
		case <-tick.C:
			_, err := os.Stat(enteredPath)
			entered = err == nil
		}
	}
	entered, err := os.ReadFile(enteredPath)
	require.NoError(t, err)
	require.Equal(t, strconv.Itoa(child.Process.Pid), strings.TrimSpace(string(entered)))
	finished := point == nativeoperation_service.CrashPointHumanManualMergeAfterFinish || point == nativeoperation_service.CrashPointHumanManualMergeAfterRelease
	if finished {
		// Wait for the actual native queued UI notification before killing this
		// finishing checkpoint; recovery must preserve it rather than resend.
		observer, err := xorm.NewEngine("sqlite3", "file:"+filepath.Join(root, "native.sqlite")+"?_busy_timeout=10000")
		require.NoError(t, err)
		observer.SetMapper(names.GonicMapper{})
		require.Eventually(t, func() bool {
			found, err := observer.Where("issue_id=? AND user_id=?", issue.ID, 4).Exist(new(activities_model.Notification))
			return err == nil && found
		}, 10*time.Second, 10*time.Millisecond)
		require.NoError(t, observer.Close())
	}
	children, err := filepath.Glob(fmt.Sprintf("/proc/%d/task/*/children", child.Process.Pid))
	require.NoError(t, err)
	require.NotEmpty(t, children)
	for _, path := range children {
		data, err := os.ReadFile(path)
		if os.IsNotExist(err) {
			continue
		}
		require.NoError(t, err)
		require.Empty(t, strings.TrimSpace(string(data)), "manual checkpoint still has active native Git readers")
	}
	require.NoError(t, child.Process.Kill())
	select {
	case err := <-exited:
		reaped = true
		var killed *exec.ExitError
		require.ErrorAs(t, err, &killed)
		require.Equal(t, "signal: killed", killed.ProcessState.String())
	case <-time.After(10 * time.Second):
		t.Fatal("owned manual worker did not exit after SIGKILL")
	}
	t.Logf("owned pid=%d reached %s, /proc showed no descendants, SIGKILL received and reaped; reopening same database/Git", child.Process.Pid, point)
	previous := db.DefaultContext.(db.Engined).Engine()
	engine := openHumanMergeProcessDatabase(t, root)
	t.Cleanup(func() { db.SetDefaultEngine(context.Background(), previous); require.NoError(t, engine.Close()) })
	reopen := func() { require.NoError(t, engine.Close()); engine = openHumanMergeProcessDatabase(t, root) }
	svc := nativeoperation_service.NewService()
	owner := "cond:" + humanMergeProcessInstallation + "/" + q.OperationID
	held, err := nativeoperation_model.ReadReservation(ctx)
	require.NoError(t, err)
	t.Cleanup(func() {
		current, err := nativeoperation_model.ReadReservation(context.WithoutCancel(ctx))
		require.NoError(t, err)
		if current.Owner == owner {
			require.NoError(t, nativeoperation_model.ReleaseExactOwner(context.WithoutCancel(ctx), owner, current.Generation))
		}
	})
	op, err := nativeoperation_model.LookupOperation(ctx, humanMergeProcessInstallation, q.OperationID)
	require.NoError(t, err)
	require.NotNil(t, op)
	canonical, digest, err := extension.CanonicalHumanManualMergeIntent(q)
	require.NoError(t, err)
	require.Equal(t, canonical, op.Intent)
	require.Equal(t, digest, op.IntentDigest)
	require.Zero(t, op.TokenID)
	require.Empty(t, op.CredentialFingerprint)
	committed := point != nativeoperation_service.CrashPointHumanManualMergeBeforePrimary && point != nativeoperation_service.CrashPointHumanManualMergeInPrimary
	released := point == nativeoperation_service.CrashPointHumanManualMergeAfterRelease
	require.Equal(t, committed, op.Admitted)
	if committed {
		require.Equal(t, nativeoperation_model.EffectCommitted, op.EffectState)
		var receipt extension.HumanManualMergeReceipt
		require.NoError(t, json.Unmarshal([]byte(op.Receipt), &receipt))
		require.True(t, extension.ValidHumanManualMergeReceipt(receipt, q))
		require.EqualValues(t, time.Date(2001, 2, 3, 4, 5, 6, 0, time.UTC).Unix(), receipt.MergedUnix)
	} else {
		require.Equal(t, nativeoperation_model.EffectPending, op.EffectState)
		require.Empty(t, op.Receipt)
		require.Empty(t, op.Completion)
	}
	files, err := filepath.Glob(filepath.Join(setting.AppDataPath, "nativeop-exec", "*"))
	require.NoError(t, err)
	if released {
		require.Empty(t, held.Owner)
		require.Empty(t, files)
		require.Equal(t, nativeoperation_model.CompletionComplete, op.Completion)
	} else {
		require.Equal(t, owner, held.Owner)
		require.Len(t, files, 1)
	}
	var current issues_model.PullRequest
	found, err := db.GetEngine(ctx).ID(pr.ID).Get(&current)
	require.NoError(t, err)
	require.True(t, found)
	require.Equal(t, committed, current.HasMerged)
	parent, err := issues_model.GetIssueByID(ctx, issue.ID)
	require.NoError(t, err)
	require.Equal(t, committed, parent.IsClosed)
	reference, err := issues_model.GetIssueByID(ctx, target.ID)
	require.NoError(t, err)
	require.Equal(t, finished, reference.IsClosed)
	history, err := db.GetEngine(ctx).Where("issue_id=? AND type=?", issue.ID, issues_model.CommentTypeMergePull).Count(new(issues_model.Comment))
	require.NoError(t, err)
	if committed {
		require.EqualValues(t, 1, history)
	} else {
		require.Zero(t, history)
	}
	if finished {
		var notice activities_model.Notification
		found, err := db.GetEngine(ctx).Where("issue_id=? AND user_id=?", issue.ID, 4).Get(&notice)
		require.NoError(t, err)
		require.True(t, found)
		reader := unittest.AssertExistsAndLoadBean(t, &user_model.User{ID: 4})
		_, err = activities_model.SetNotificationStatus(ctx, notice.ID, reader, activities_model.NotificationStatusRead)
		require.NoError(t, err)
	}
	if altered {
		var receipt extension.HumanManualMergeReceipt
		require.NoError(t, json.Unmarshal([]byte(op.Receipt), &receipt))
		receipt.ClosedUnix++
		raw, err := json.Marshal(receipt)
		require.NoError(t, err)
		_, err = db.GetEngine(ctx).ID(op.ID).Cols("receipt").Update(&nativeoperation_model.Operation{Receipt: string(raw)})
		require.NoError(t, err)
	}
	nativeState := func() string {
		t.Helper()
		var pull issues_model.PullRequest
		var parent, reference issues_model.Issue
		var comments []issues_model.Comment
		var notices []activities_model.Notification
		var actions []activities_model.Action
		found, err := db.GetEngine(ctx).ID(pr.ID).Get(&pull)
		require.NoError(t, err)
		require.True(t, found)
		found, err = db.GetEngine(ctx).ID(issue.ID).Get(&parent)
		require.NoError(t, err)
		require.True(t, found)
		found, err = db.GetEngine(ctx).ID(target.ID).Get(&reference)
		require.NoError(t, err)
		require.True(t, found)
		require.NoError(t, db.GetEngine(ctx).Where("issue_id=? OR issue_id=?", issue.ID, target.ID).OrderBy("id").Find(&comments))
		require.NoError(t, db.GetEngine(ctx).Where("repo_id=?", repo.ID).OrderBy("id").Find(&notices))
		require.NoError(t, db.GetEngine(ctx).Where("repo_id=?", repo.ID).OrderBy("id").Find(&actions))
		raw, err := json.Marshal([]any{pull, parent, reference, comments, notices, actions})
		require.NoError(t, err)
		return string(raw)
	}
	beforeNative := nativeState()
	before, err := svc.Get(ctx, humanMergeProcessInstallation, q.OperationID)
	require.NoError(t, err)
	_, err = svc.Recover(ctx, owner, held.Generation)
	require.ErrorIs(t, err, nativeoperation_service.ErrNotInhibited)
	// Inhibit only after the actual owned worker has been killed and reaped.
	require.NoError(t, os.WriteFile(nativeoperation_model.OfflineMarkerPath(), []byte("owned manual writer SIGKILLed and reaped; restart inhibited\n"), 0o600))
	t.Cleanup(func() {
		err := os.Remove(nativeoperation_model.OfflineMarkerPath())
		require.True(t, err == nil || os.IsNotExist(err))
	})
	if !released {
		wrong, err := svc.Recover(ctx, owner, held.Generation+1)
		require.NoError(t, err)
		require.Equal(t, nativeoperation_service.RecoveryFenced, wrong.Verdict)
	}
	assessment, err := svc.Recover(ctx, owner, held.Generation)
	require.NoError(t, err)
	after, err := svc.Get(ctx, humanMergeProcessInstallation, q.OperationID)
	require.NoError(t, err)
	if altered {
		require.Equal(t, nativeoperation_service.RecoveryFenced, assessment.Verdict)
		require.Equal(t, before, after)
	} else {
		if released {
			require.Equal(t, nativeoperation_service.RecoveryIdle, assessment.Verdict)
		} else {
			require.Equal(t, nativeoperation_service.RecoveryReleased, assessment.Verdict)
		}
		require.Equal(t, before.Record.Receipt, after.Record.Receipt)
		if committed {
			require.Equal(t, nativeoperation_model.EffectCommitted, after.Record.EffectState)
			completion := nativeoperation_model.CompletionNeedsIntervention
			if finished {
				completion = nativeoperation_model.CompletionComplete
			}
			require.Equal(t, completion, after.Record.CompletionState)
		} else {
			require.Equal(t, nativeoperation_model.EffectNotCommitted, after.Record.EffectState)
			require.Empty(t, after.Record.Receipt)
		}
	}
	require.Equal(t, beforeNative, nativeState(), "stopped manual recovery changed native rows or repeated dispatch")
	require.Equal(t, fixture.tip, sourceTestGit(t, repo.RepoPath(), nil, "rev-parse", "refs/heads/main"))
	currentHeld, err := nativeoperation_model.ReadReservation(ctx)
	require.NoError(t, err)
	files, err = filepath.Glob(filepath.Join(setting.AppDataPath, "nativeop-exec", "*"))
	require.NoError(t, err)
	if altered {
		require.Equal(t, owner, currentHeld.Owner)
		require.Len(t, files, 1)
	} else {
		require.Empty(t, currentHeld.Owner)
		require.Empty(t, files)
	}
	reopen()
	again, err := nativeoperation_service.NewService().Recover(ctx, owner, held.Generation)
	require.NoError(t, err)
	if altered {
		require.Equal(t, nativeoperation_service.RecoveryFenced, again.Verdict)
	} else {
		require.Equal(t, nativeoperation_service.RecoveryIdle, again.Verdict)
	}
	replayed, err := svc.SubmitHumanManualMerge(ctx, humanMergeProcessInstallation, q, humanMergeProcessAdmission)
	require.NoError(t, err)
	require.Equal(t, *after.Record, replayed)
	require.Equal(t, beforeNative, nativeState())
	pushes, err := db.GetEngine(ctx).Where("repo_id=? AND op_type=?", repo.ID, activities_model.ActionCommitRepo).Count(new(activities_model.Action))
	require.NoError(t, err)
	require.Zero(t, pushes)
	t.Logf("manual process %s: verdict=%s effect=%s completion=%s; same database/Git reopened, receipt retained and no native/dispatch replay", mode, assessment.Verdict, after.Record.EffectState, after.Record.CompletionState)
}

const (
	humanPullCreateHookBeforeAdmission = "human-pull-create-ref-before-admission"
	humanPullCreateHookAfterAdmission  = "human-pull-create-ref-after-admission"
	humanPullCreateHookAfterCommit     = "human-pull-create-ref-after-commit"
)

func setupHumanPullCreateHooks(t *testing.T, base, head *repo_model.Repository, root string, onPrepared func()) (*atomic.Int64, *atomic.Int64) {
	t.Helper()
	oldApp, oldConf, oldToken := setting.AppPath, setting.CustomConf, setting.InternalToken
	t.Cleanup(func() { setting.AppPath, setting.CustomConf, setting.InternalToken = oldApp, oldConf, oldToken })
	setting.AppPath = os.Getenv("SODA_FOUNTAIN_PULL_CREATE_REF_HOOK_EXECUTABLE")
	require.True(t, filepath.IsAbs(setting.AppPath))
	setting.CustomConf = filepath.Join(root, "app.ini")
	secret := make([]byte, 32)
	_, err := rand.Read(secret)
	require.NoError(t, err)
	setting.InternalToken = fmt.Sprintf("%x", secret)
	privateHandler := http.StripPrefix("/api/internal", private_router.Routes())
	var prepared, committed atomic.Int64
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		r = r.WithContext(web_middleware.WithContextData(r.Context()))
		if strings.Contains(r.URL.Path, "/reference-transaction/") {
			body, err := io.ReadAll(r.Body)
			require.NoError(t, err)
			r.Body = io.NopCloser(bytes.NewReader(body))
			var options private_api.TransactionOptions
			require.NoError(t, json.Unmarshal(body, &options))
			if len(options.RefFullNames) > 0 && options.Phase == nativeoperation_service.PhasePrepared {
				prepared.Add(1)
				onPrepared()
			}
			if len(options.RefFullNames) > 0 && options.Phase == nativeoperation_service.PhaseCommitted {
				committed.Add(1)
			}
			if os.Getenv("SODA_FOUNTAIN_PULL_CREATE_ACTIVE_PROCESS") == "1" && len(options.RefFullNames) == 1 {
				point := os.Getenv("NATIVEOP_TEST_CRASH_POINT")
				before := point == humanPullCreateHookBeforeAdmission && options.Phase == nativeoperation_service.PhasePrepared
				after := point == humanPullCreateHookAfterAdmission && options.Phase == nativeoperation_service.PhasePrepared || point == humanPullCreateHookAfterCommit && options.Phase == nativeoperation_service.PhaseCommitted
				if before || after {
					var response *httptest.ResponseRecorder
					if after {
						response = httptest.NewRecorder()
						privateHandler.ServeHTTP(response, r)
						if response.Code != http.StatusOK {
							http.Error(w, "native PR ref decision refused", 500)
							return
						}
					}
					raw, err := json.Marshal(struct {
						Prepared, Committed int64
						Phase               string
						Recorded            bool
					}{prepared.Load(), committed.Load(), string(options.Phase), after})
					if err != nil || os.WriteFile(filepath.Join(root, "hook-observed.json"), raw, 0o600) != nil {
						http.Error(w, "native hook observation unavailable", 500)
						return
					}
					if err := nativeoperation_service.TestCrashBarrier(point); err != nil {
						http.Error(w, "active PR hook barrier failed", 500)
						return
					}
					if response != nil {
						for key, values := range response.Header() {
							w.Header()[key] = values
						}
						w.WriteHeader(response.Code)
						_, _ = w.Write(response.Body.Bytes())
						return
					}
				}
			}
		}
		privateHandler.ServeHTTP(w, r)
	}))
	t.Cleanup(server.Close)
	currentUser, err := osuser.Current()
	require.NoError(t, err)
	config := fmt.Sprintf("RUN_USER = %s\nRUN_MODE = prod\n[server]\nPROTOCOL = http\nLOCAL_ROOT_URL = %s/\nAPP_DATA_PATH = %s\n[repository]\nROOT = %s\n[security]\nINSTALL_LOCK = true\nINTERNAL_TOKEN = %s\n[log]\nMODE = console\nLEVEL = fatal\n", currentUser.Username, server.URL, setting.AppDataPath, setting.RepoRootPath, setting.InternalToken)
	require.NoError(t, os.WriteFile(setting.CustomConf, []byte(config), 0o600))
	for _, repo := range []*repo_model.Repository{base, head} {
		require.NoError(t, repo_module.CreateDelegateHooks(repo.RepoPath()))
	}
	return &prepared, &committed
}

func checkHumanPullCreateSDK(t *testing.T, fixture sourceTestFixture, base, head *repo_model.Repository, q extension.HumanPullCreateRequest, mode string) {
	t.Helper()
	ctx := t.Context()
	if mode == "max-body" {
		q.Body = strings.Repeat("<", extension.MaxHumanPullCreateBodyBytes)
		q.Title = strings.Repeat("t", extension.MaxHumanPullCreateTitleBytes)
	}
	if mode == "empty-body" {
		q.Body = ""
	}
	root := shortWitnessRoot(t)
	backend := os.Getenv("SODA_FOUNTAIN_PULL_CREATE_SDK_BACKEND")
	require.True(t, filepath.IsAbs(backend))
	packageDir := filepath.Join(root, "soda")
	writePackage := func() {
		require.NoError(t, os.Mkdir(packageDir, 0o700))
		require.NoError(t, os.WriteFile(filepath.Join(packageDir, "run"), []byte(fmt.Sprintf("#!/bin/sh\nexec %q\n", backend)), 0o700))
		require.NoError(t, os.WriteFile(filepath.Join(packageDir, "extension.json"), []byte(`{"protocol":1,"id":"soda","name":"PullCreateSDK","version":"1.0","executable":"run","capabilities":["native.actor.read","native.repository.read","native.repository.pulls.create"]}`), 0o600))
		if manifest := os.Getenv("SODA_FOUNTAIN_PULL_CREATE_HTTP_MANIFEST"); manifest != "" {
			require.NoError(t, os.WriteFile(filepath.Join(packageDir, "run"), []byte(fmt.Sprintf("#!/bin/sh\nexec %q --package-id soda --soda-socket %q --factory-socket %q\n", backend, filepath.Join(root, "soda-http"), filepath.Join(root, "factory-http"))), 0o700))
			raw, err := os.ReadFile(manifest)
			require.NoError(t, err)
			require.NoError(t, os.WriteFile(filepath.Join(packageDir, "extension.json"), raw, 0o600))
		}
	}
	writePackage()
	previous := extensions_service.GetManager()
	t.Cleanup(func() { extensions_service.SetDefault(previous) })
	var dropped atomic.Bool
	var mutation atomic.Value
	mutation.Store("")
	factory := func(instance string) http.Handler {
		handler := CallbackHandlerForInstance(instance)
		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			body, err := io.ReadAll(r.Body)
			require.NoError(t, err)
			r.Body = io.NopCloser(bytes.NewReader(body))
			var request extension.CallbackRequest
			require.NoError(t, json.Unmarshal(body, &request))
			isPull := request.Operation == extension.OperationHumanPullCreateSubmit || request.Operation == extension.OperationHumanPullCreateGet || request.Operation == extension.OperationHumanPullCreateCancel
			change := mutation.Load().(string)
			if !isPull {
				change = ""
			}
			if mode != "lost-reply" && change == "" || !isPull {
				handler.ServeHTTP(w, r)
				return
			}
			response := httptest.NewRecorder()
			handler.ServeHTTP(response, r)
			if mode == "lost-reply" && request.Operation == extension.OperationHumanPullCreateSubmit && response.Code == http.StatusOK && dropped.CompareAndSwap(false, true) {
				connection, _, err := w.(http.Hijacker).Hijack()
				require.NoError(t, err)
				require.NoError(t, connection.Close())
				return
			}
			data := response.Body.Bytes()
			if change != "" && response.Code == http.StatusOK {
				var result extension.CallbackResponse
				require.NoError(t, json.Unmarshal(data, &result))
				record := result.HumanPullCreate.Record
				if record != nil {
					switch change {
					case "actor":
						record.ActorID = "1"
					case "repository":
						record.RepositoryID = "1"
					case "kind":
						record.Kind = extension.OperationKindHumanIssueCreate
					case "operation":
						result.HumanPullCreate.OperationID = "other"
					case "digest":
						record.IntentDigest = "not-a-digest"
					case "completion":
						record.CompletionState = "unknown"
					case "cancellation":
						record.CancellationStatus = "unknown"
					case "installation":
						result.HumanPullCreate.InstallationID = "11111111-2222-4333-8444-555555555555"
					case "extra":
						result.Actor = &extension.Actor{ID: "2"}
					default:
						var receipt extension.HumanPullCreateReceipt
						require.NoError(t, json.Unmarshal(record.Receipt, &receipt))
						switch change {
						case "head":
							receipt.HeadOID = "HEAD"
						case "head-repository":
							receipt.HeadRepositoryID = 0
						case "branch":
							receipt.HeadBranch = "work~1"
						case "body":
							receipt.BodyDigest = "invalid"
						case "receipt-digest":
							receipt.IntentDigest = strings.Repeat("a", 64)
						case "submit-head":
							receipt.HeadOID = q.Expected.BaseOID
						case "capture-source":
							receipt.HeadRepositoryID = base.ID
						case "capture-branch":
							receipt.HeadBranch = "another-valid-branch"
						case "capture-title":
							receipt.Title = "Another valid title"
						case "capture-body":
							receipt.BodyDigest = strings.Repeat("a", 64)
						case "capture-maintainer":
							receipt.AllowMaintainerEdit = !receipt.AllowMaintainerEdit
						}
						raw, err := json.Marshal(receipt)
						require.NoError(t, err)
						if change == "unknown-receipt" {
							raw = append(raw[:len(raw)-1], []byte(`,"unexpected":true}`)...)
						}
						record.Receipt = raw
					}
				}
				data, err = json.Marshal(result)
				require.NoError(t, err)
			}
			for key, values := range response.Header() {
				for _, value := range values {
					w.Header().Add(key, value)
				}
			}
			w.WriteHeader(response.Code)
			_, _ = w.Write(data)
		})
	}
	start := func() (*extensions_service.Manager, extensions_service.Descriptor, string, string) {
		store, err := packages.OpenPackageStore(root)
		require.NoError(t, err)
		_, err = store.SetDesired("soda", true)
		require.NoError(t, err)
		require.NoError(t, store.Close())
		manager := extensions_service.NewManager(root)
		if os.Getenv("SODA_FOUNTAIN_PULL_CREATE_HTTP_MANIFEST") != "" {
			require.NoError(t, manager.SetServiceCallbackEndpoint(filepath.Join(root, "svc"), CallbackHandlerForService()))
		}
		require.NoError(t, manager.SetCallbackHandlerFactory(factory))
		extensions_service.SetDefault(manager)
		t.Cleanup(func() { require.NoError(t, manager.Close()) })
		require.NoError(t, manager.Start(ctx))
		var descriptor extensions_service.Descriptor
		require.Eventually(t, func() bool { var ready bool; descriptor, _, ready = manager.Lookup("soda"); return ready }, 15*time.Second, 20*time.Millisecond)
		installation, ok := manager.AdmittedInstallation("soda", descriptor.InstanceID)
		require.True(t, ok)
		sockets, err := filepath.Glob(filepath.Join(root, ".runtime", "*", "c"))
		require.NoError(t, err)
		require.Len(t, sockets, 1)
		return manager, descriptor, installation, sockets[0]
	}
	manager, descriptor, installation, socket := start()
	bind := func(descriptor extensions_service.Descriptor, socket string) (extension.Authority, *callbackAdmission, string) {
		authority := fixture.authority
		authority.InstanceID = descriptor.InstanceID
		if os.Getenv("SODA_FOUNTAIN_PULL_CREATE_HTTP_MANIFEST") != "" {
			authority.Contribution.ID = "feed"
		}
		requestCtx, cancel := context.WithCancel(ctx)
		t.Cleanup(cancel)
		entry := &callbackAdmission{method: http.MethodPost, instanceID: descriptor.InstanceID, actorID: 2, sessionID: "source-test-session", session: fixture.session, authority: authority, capabilities: map[string]struct{}{extension.CapabilityActorRead: {}, extension.CapabilityRepositoryRead: {}, extension.CapabilityHumanPullCreate: {}}, requestCtx: requestCtx, cancel: cancel}
		token, err := nativeAdmissions.issue(entry)
		require.NoError(t, err)
		t.Cleanup(func() { nativeAdmissions.revoke(token) })
		t.Setenv(extension.CallbackEnv, socket)
		t.Setenv(extension.ServiceCallbackEnv, "")
		raw, err := json.Marshal(authority)
		require.NoError(t, err)
		request := httptest.NewRequest(http.MethodPost, "/pull-create-sdk", nil)
		request.Header.Set(extension.ContextHeader, string(raw))
		request.Header.Set(extension.AdmissionHeader, token)
		a, err := extension.RequestContext(request)
		require.NoError(t, err)
		return a, entry, token
	}
	a, entry, token := bind(descriptor, socket)
	repository := strconv.FormatInt(base.ID, 10)
	p, err := a.RepositoryPullCreateSnapshot(ctx, repository, extension.RepositoryPullCreateSnapshotRequest{HeadRepositoryID: strconv.FormatInt(head.ID, 10), BaseBranch: q.Expected.BaseBranch, HeadBranch: q.Expected.HeadBranch})
	require.NoError(t, err)
	require.Equal(t, "allowed", p.Action.State)
	q.Expected = p
	observationCommand := ""
	if os.Getenv("SODA_FOUNTAIN_PULL_CREATE_OBSERVATION_EXPORT") != "" {
		nonce := make([]byte, 16)
		_, err := rand.Read(nonce)
		require.NoError(t, err)
		observationCommand = fmt.Sprintf("%x", nonce)
	}
	command := "sdk-" + mode
	if observationCommand != "" {
		command = observationCommand
	}
	q.OperationID, err = extension.HumanPullCreateOperationID(p.ActorID, p.RepositoryID, command)
	require.NoError(t, err)
	t.Cleanup(func() {
		held, err := nativeoperation_model.ReadReservation(context.WithoutCancel(ctx))
		require.NoError(t, err)
		if held.Owner == "cond:"+installation+"/"+q.OperationID {
			require.NoError(t, nativeoperation_model.ReleaseExactOwner(context.WithoutCancel(ctx), held.Owner, held.Generation))
		}
	})
	absent, err := a.GetHumanPullCreate(ctx, repository, q.OperationID)
	require.NoError(t, err)
	require.Equal(t, installation, absent.InstallationID)
	require.Nil(t, absent.Record)
	rawCall := func(request extension.CallbackRequest) int {
		request.Authority = entry.authority
		body, err := json.Marshal(request)
		require.NoError(t, err)
		transport := &http.Transport{DialContext: func(c context.Context, _, _ string) (net.Conn, error) {
			return (&net.Dialer{}).DialContext(c, "unix", socket)
		}}
		defer transport.CloseIdleConnections()
		r, err := http.NewRequestWithContext(ctx, http.MethodPost, "http://native"+extension.NativeCallbackPath, bytes.NewReader(body))
		require.NoError(t, err)
		r.Header.Set("Content-Type", "application/json")
		r.Header.Set(extension.AdmissionHeader, token)
		response, err := (&http.Client{Transport: transport}).Do(r)
		require.NoError(t, err)
		defer response.Body.Close()
		return response.StatusCode
	}
	counts := func() [7]int64 {
		require.NoError(t, queue.GetManager().FlushAll(ctx, 5*time.Second))
		var n [7]int64
		for i, row := range []any{new(issues_model.Issue), new(issues_model.PullRequest), new(issues_model.Comment), new(issues_model.Review), new(activities_model.Notification), new(activities_model.Action), new(nativeoperation_model.Operation)} {
			n[i], err = db.GetEngine(ctx).Count(row)
			require.NoError(t, err)
		}
		return n
	}
	if os.Getenv("SODA_FOUNTAIN_PULL_CREATE_ADAPTER_PROBE") != "" {
		checkCanonicalHumanPullCreateAdapter(t, fixture, base, head, q, a, entry, token, socket, installation, mode, func(v string) { mutation.Store(v) }, func() (extension.Authority, *callbackAdmission, string, string, string) {
			require.NoError(t, manager.Close())
			store, err := packages.OpenPackageStore(root)
			require.NoError(t, err)
			require.NoError(t, store.Remove("soda"))
			require.NoError(t, store.Close())
			writePackage()
			_, fresh, freshInstallation, freshSocket := start()
			freshAuthority, freshEntry, freshToken := bind(fresh, freshSocket)
			return freshAuthority, freshEntry, freshToken, freshSocket, freshInstallation
		})
		return
	}
	before := counts()
	if mode == "observation-refused" {
		_, err := db.GetEngine(ctx).ID(base.ID).Cols("is_archived").Update(&repo_model.Repository{IsArchived: true})
		require.NoError(t, err)
	}
	if mode == "invalid-envelope" {
		baseRequest := extension.CallbackRequest{Operation: extension.OperationHumanPullCreateSubmit, RepositoryID: repository, HumanPullCreate: &q, PullCreateInstallationID: installation}
		for _, change := range []func(*extension.CallbackRequest){func(r *extension.CallbackRequest) { r.PullCreateOperationID = q.OperationID }, func(r *extension.CallbackRequest) { r.Query = "1" }, func(r *extension.CallbackRequest) {
			r.PullCreateSnapshot = &extension.RepositoryPullCreateSnapshotRequest{HeadRepositoryID: p.HeadRepositoryID, BaseBranch: p.BaseBranch, HeadBranch: p.HeadBranch}
		}, func(r *extension.CallbackRequest) { r.HumanIssueCreate = &extension.HumanIssueCreateRequest{} }, func(r *extension.CallbackRequest) { r.PullCreateInstallationID = "" }, func(r *extension.CallbackRequest) { r.Operation = extension.OperationHumanPullCreateGet }} {
			r := baseRequest
			change(&r)
			require.Equal(t, http.StatusBadRequest, rawCall(r))
		}
		require.Equal(t, http.StatusRequestEntityTooLarge, rawCall(extension.CallbackRequest{Operation: extension.OperationHumanPullCreateGet, RepositoryID: repository, PullCreateOperationID: q.OperationID, Query: strings.Repeat("x", 70<<10)}))
		require.Equal(t, http.StatusRequestEntityTooLarge, rawCall(extension.CallbackRequest{Operation: extension.OperationHumanPullCreateSubmit, RepositoryID: repository, HumanPullCreate: &q, PullCreateInstallationID: installation, Query: strings.Repeat("x", extension.MaxHumanPullCreateCallbackBytes)}))
		require.Equal(t, before, counts())
		return
	}
	if mode == "missing-cap" {
		delete(entry.capabilities, extension.CapabilityHumanPullCreate)
	}
	if mode == "read-method" {
		entry.method = http.MethodGet
	}
	if mode == "session-before" {
		fixture.session.uid = 1
	}
	if mode == "early-cancel" {
		cancelled, err := a.CancelHumanPullCreate(ctx, installation, repository, q.OperationID)
		require.NoError(t, err)
		require.Equal(t, extension.CancellationCancelled, cancelled.CancellationStatus)
	}
	if mode == "partial" {
		_, err := db.GetEngine(ctx).Exec("CREATE TRIGGER fail_sdk_pull_finish BEFORE INSERT ON review BEGIN SELECT RAISE(ABORT, 'SDK code owners failure'); END")
		require.NoError(t, err)
		t.Cleanup(func() {
			_, err := db.GetEngine(context.WithoutCancel(ctx)).Exec("DROP TRIGGER fail_sdk_pull_finish")
			require.NoError(t, err)
		})
	}
	prepared, committed := setupHumanPullCreateHooks(t, base, head, root, func() {
		if mode == "session-after-commit" {
			fixture.session.uid = 1
		}
	})
	if mode == "submit-result-binding" {
		mutation.Store("submit-head")
	}
	var record extension.OperationRecord
	var submitErr error
	if mode == "observation-pending" {
		point := nativeoperation_service.CrashPointHumanPullCreateAfterFinish
		dir := t.TempDir()
		t.Setenv("NATIVEOP_TEST_CRASH_POINT", point)
		t.Setenv("NATIVEOP_TEST_CRASH_BARRIER_DIR", dir)
		t.Setenv("NATIVEOP_TEST_CRASH_TIMEOUT_SECONDS", "10")
		type result struct {
			record extension.OperationRecord
			err    error
		}
		done := make(chan result, 1)
		go func() { r, e := a.SubmitHumanPullCreate(ctx, installation, q); done <- result{r, e} }()
		require.Eventually(t, func() bool { _, e := os.Stat(filepath.Join(dir, point+".entered")); return e == nil }, 5*time.Second, 10*time.Millisecond)
		pending, err := a.GetHumanPullCreate(ctx, repository, q.OperationID)
		require.NoError(t, err)
		require.NotNil(t, pending.Record)
		require.Equal(t, extension.EffectCommitted, pending.Record.EffectState)
		require.Equal(t, extension.CompletionPending, pending.Record.CompletionState)
		exportHumanPullCreateObservation(t, mode, observationCommand, q, *pending.Record)
		require.NoError(t, os.WriteFile(filepath.Join(dir, point+".release"), []byte("continue\n"), 0o600))
		r := <-done
		record, submitErr = r.record, r.err
	} else if mode == "concurrent" {
		start := make(chan struct{})
		results := make([]extension.OperationRecord, 4)
		failures := make([]error, len(results))
		var wg sync.WaitGroup
		for i := range results {
			wg.Go(func() { <-start; results[i], failures[i] = a.SubmitHumanPullCreate(ctx, installation, q) })
		}
		close(start)
		wg.Wait()
		complete := 0
		for i, e := range failures {
			if e == nil && results[i].CompletionState == extension.CompletionComplete {
				complete++
				record = results[i]
			}
		}
		require.Positive(t, complete)
	} else {
		record, submitErr = a.SubmitHumanPullCreate(ctx, installation, q)
	}
	mutation.Store("")
	fixture.session.uid = 2
	if mode == "missing-cap" || mode == "read-method" || mode == "session-before" {
		require.Error(t, submitErr)
		if mode == "missing-cap" {
			_, err := a.GetHumanPullCreate(ctx, repository, q.OperationID)
			require.ErrorIs(t, err, extension.ErrHumanPullCreateAdmission)
			_, err = a.CancelHumanPullCreate(ctx, installation, repository, q.OperationID)
			require.ErrorIs(t, err, extension.ErrHumanPullCreateAdmission)
		}
		if mode == "read-method" {
			lookup, err := a.GetHumanPullCreate(ctx, repository, q.OperationID)
			require.NoError(t, err)
			require.Nil(t, lookup.Record)
			_, err = a.CancelHumanPullCreate(ctx, installation, repository, q.OperationID)
			require.ErrorIs(t, err, extension.ErrHumanPullCreateQuery)
		}
		require.Equal(t, before, counts())
		return
	}
	if mode == "early-cancel" {
		require.NoError(t, submitErr)
		require.Equal(t, extension.CancellationCancelled, record.CancellationStatus)
		require.Empty(t, record.Kind)
		exportHumanPullCreateObservation(t, mode, observationCommand, q, record)
		return
	}
	if mode == "lost-reply" || mode == "session-after-commit" || mode == "submit-result-binding" {
		require.Error(t, submitErr)
	} else {
		require.NoError(t, submitErr)
	}
	lookup, err := a.GetHumanPullCreate(ctx, repository, q.OperationID)
	require.NoError(t, err)
	require.NotNil(t, lookup.Record)
	require.Equal(t, installation, lookup.InstallationID)
	if mode == "observation-refused" {
		require.Equal(t, extension.EffectNotCommitted, lookup.Record.EffectState)
		require.Empty(t, lookup.Record.Receipt)
		require.Equal(t, before[0], counts()[0])
		require.Equal(t, before[1], counts()[1])
		exportHumanPullCreateObservation(t, mode, observationCommand, q, *lookup.Record)
		return
	}
	require.Equal(t, extension.EffectCommitted, lookup.Record.EffectState)
	completion := extension.CompletionComplete
	if mode == "partial" {
		completion = extension.CompletionNeedsIntervention
	}
	require.Equal(t, completion, lookup.Record.CompletionState)
	var receipt extension.HumanPullCreateReceipt
	require.NoError(t, json.Unmarshal(lookup.Record.Receipt, &receipt))
	require.True(t, extension.ValidHumanPullCreateReceipt(receipt, q))
	if mode != "observation-pending" {
		exportHumanPullCreateObservation(t, mode, observationCommand, q, *lookup.Record)
	}
	issue, err := issues_model.GetIssueByID(ctx, receipt.IssueID)
	require.NoError(t, err)
	require.Equal(t, q.Title, issue.Title)
	require.Equal(t, q.Body, issue.Content)
	require.Equal(t, q.Expected.HeadOID, sourceTestGit(t, base.RepoPath(), nil, "rev-parse", fmt.Sprintf("refs/pull/%d/head", receipt.Index)))
	require.EqualValues(t, 1, prepared.Load())
	require.EqualValues(t, 1, committed.Load())
	after := counts()
	require.Equal(t, before[0]+1, after[0])
	require.Equal(t, before[1]+1, after[1])
	if mode == "result-binding" {
		for _, change := range []string{"actor", "repository", "kind", "operation", "digest", "completion", "cancellation", "installation", "extra", "head", "head-repository", "branch", "body", "receipt-digest", "unknown-receipt"} {
			mutation.Store(change)
			_, err := a.GetHumanPullCreate(ctx, repository, q.OperationID)
			require.Error(t, err, "SDK accepted altered %s", change)
		}
		mutation.Store("")
	}
	if mode == "foreign-record" {
		n, err := db.GetEngine(ctx).Where("installation_id=? AND operation_id=?", installation, q.OperationID).Cols("actor_id").Update(&nativeoperation_model.Operation{ActorID: 1})
		require.NoError(t, err)
		require.EqualValues(t, 1, n)
		_, err = a.GetHumanPullCreate(ctx, repository, q.OperationID)
		require.ErrorIs(t, err, extension.ErrHumanPullCreateAdmission)
		_, err = a.CancelHumanPullCreate(ctx, installation, repository, q.OperationID)
		require.ErrorIs(t, err, extension.ErrHumanPullCreateAdmission)
		_, err = a.SubmitHumanPullCreate(ctx, installation, q)
		require.ErrorIs(t, err, extension.ErrHumanPullCreateAdmission)
		require.Equal(t, after, counts())
		return
	}
	if mode == "permission-after" {
		for _, row := range []any{new(access_model.Access), new(repo_model.Collaboration)} {
			_, err := db.GetEngine(ctx).Where("repo_id=? AND user_id=?", base.ID, 2).Cols("mode").Update(row)
			require.NoError(t, err)
		}
		_, err = a.GetHumanPullCreate(ctx, repository, q.OperationID)
		require.ErrorIs(t, err, extension.ErrRepositoryNotVisible)
		_, err = a.CancelHumanPullCreate(ctx, installation, repository, q.OperationID)
		require.ErrorIs(t, err, extension.ErrRepositoryNotVisible)
		require.Equal(t, after, counts())
		return
	}
	if mode == "installation" {
		require.NoError(t, manager.Close())
		store, err := packages.OpenPackageStore(root)
		require.NoError(t, err)
		require.NoError(t, store.Remove("soda"))
		require.NoError(t, store.Close())
		writePackage()
		_, fresh, newInstallation, newSocket := start()
		require.NotEqual(t, installation, newInstallation)
		freshAuthority, _, _ := bind(fresh, newSocket)
		absent, err := freshAuthority.GetHumanPullCreate(ctx, repository, q.OperationID)
		require.NoError(t, err)
		require.Equal(t, newInstallation, absent.InstallationID)
		require.Nil(t, absent.Record)
		_, err = freshAuthority.SubmitHumanPullCreate(ctx, installation, q)
		require.ErrorIs(t, err, extension.ErrHumanPullCreateAdmission)
		_, err = freshAuthority.CancelHumanPullCreate(ctx, installation, repository, q.OperationID)
		require.ErrorIs(t, err, extension.ErrHumanPullCreateAdmission)
		retained, err := nativeoperation_service.NewService().Get(ctx, installation, q.OperationID)
		require.NoError(t, err)
		require.Equal(t, *lookup.Record, *retained.Record)
		require.Equal(t, after, counts())
		return
	}
	var notice activities_model.Notification
	found, err := db.GetEngine(ctx).Where("issue_id=? AND user_id=?", receipt.IssueID, 4).Get(&notice)
	require.NoError(t, err)
	if found {
		reader := unittest.AssertExistsAndLoadBean(t, &user_model.User{ID: 4})
		_, err := activities_model.SetNotificationStatus(ctx, notice.ID, reader, activities_model.NotificationStatusRead)
		require.NoError(t, err)
	}
	replay, err := a.SubmitHumanPullCreate(ctx, installation, q)
	require.NoError(t, err)
	require.Equal(t, *lookup.Record, replay)
	changed := q
	if mode == "max-body" {
		changed.Body = "x" + changed.Body[1:]
	} else {
		changed.Body += "changed"
	}
	_, err = a.SubmitHumanPullCreate(ctx, installation, changed)
	require.ErrorIs(t, err, extension.ErrHumanPullCreateConflict)
	cancelled, err := a.CancelHumanPullCreate(ctx, installation, repository, q.OperationID)
	require.NoError(t, err)
	require.Equal(t, extension.CancellationTooLate, cancelled.CancellationStatus)
	require.Equal(t, lookup.Record.Receipt, cancelled.Receipt)
	require.Equal(t, after, counts())
	if found {
		stored, err := activities_model.GetNotificationByID(ctx, notice.ID)
		require.NoError(t, err)
		require.Equal(t, activities_model.NotificationStatusRead, stored.Status)
	}
	t.Logf("human PR SDK %s: actual manager/independent consumer/private Unix/native Git and SQL, effect=%s completion=%s; exact retained replay and no duplicate notifications", mode, lookup.Record.EffectState, lookup.Record.CompletionState)
}

func checkCanonicalHumanPullCreateAdapter(t *testing.T, fixture sourceTestFixture, base, head *repo_model.Repository, q extension.HumanPullCreateRequest, a extension.Authority, entry *callbackAdmission, token, socket, installation, mode string, mutate func(string), replace func() (extension.Authority, *callbackAdmission, string, string, string)) {
	t.Helper()
	ctx := t.Context()
	application := os.Getenv("SODA_FOUNTAIN_PULL_CREATE_SERVICE") == "1"
	dir := shortWitnessRoot(t)
	prepared, committed := setupHumanPullCreateHooks(t, base, head, dir, func() {
		if mode == "session-after-commit" {
			fixture.session.uid = 1
		}
	})
	if mode == "maintainer" || mode == "maintainer-denied" {
		q.AllowMaintainerEdit = true
	}
	if mode == "maintainer" {
		_, err := db.GetEngine(ctx).Where("repo_id=? AND user_id=?", head.ID, 2).Cols("mode").Update(&access_model.Access{Mode: perm.AccessModeWrite})
		require.NoError(t, err)
		_, err = db.GetEngine(ctx).Where("repo_id=? AND user_id=?", head.ID, 2).Cols("mode").Update(&repo_model.Collaboration{Mode: perm.AccessModeWrite})
		require.NoError(t, err)
	}
	if mode == "valid" {
		q.Body = "## Human writing 完整 🌋\r\n\nPlease review @user4.\n"
	}
	binding := struct {
		Authority                                                                                               extension.Authority
		Admission, Socket, Repository, HeadRepository, Installation, State, BaseBranch, HeadBranch, Title, Body string
		AllowMaintainerEdit                                                                                     bool
		Mode                                                                                                    string
	}{a, token, socket, strconv.FormatInt(base.ID, 10), strconv.FormatInt(head.ID, 10), installation, filepath.Join(dir, "capture.json"), q.Expected.BaseBranch, q.Expected.HeadBranch, q.Title, q.Body, q.AllowMaintainerEdit, mode}
	path := filepath.Join(dir, "binding.json")
	write := func() {
		raw, err := json.Marshal(binding)
		require.NoError(t, err)
		if os.Getenv("SODA_FOUNTAIN_PULL_CREATE_HTTP_MANIFEST") != "" {
			readAuthority := binding.Authority
			readAuthority.Contribution.Action = "get"
			readCtx, readCancel := context.WithCancel(ctx)
			t.Cleanup(readCancel)
			readEntry := &callbackAdmission{method: http.MethodGet, instanceID: binding.Authority.InstanceID, actorID: 2, sessionID: "source-test-session", session: fixture.session, authority: readAuthority, capabilities: entry.capabilities, requestCtx: readCtx, cancel: readCancel}
			readToken, err := nativeAdmissions.issue(readEntry)
			require.NoError(t, err)
			t.Cleanup(func() { nativeAdmissions.revoke(readToken) })
			var fields map[string]any
			require.NoError(t, json.Unmarshal(raw, &fields))
			fields["ReadAuthority"], fields["ReadAdmission"] = readAuthority, readToken
			raw, err = json.Marshal(fields)
			require.NoError(t, err)
		}
		require.NoError(t, os.WriteFile(path, raw, 0o600))
	}
	write()
	probe := os.Getenv("SODA_FOUNTAIN_PULL_CREATE_ADAPTER_PROBE")
	require.True(t, filepath.IsAbs(probe))
	run := func(action string) {
		t.Helper()
		command := exec.CommandContext(ctx, probe, action)
		command.Env = append(os.Environ(), "SODA_FOUNTAIN_READ_BINDING="+path)
		output, err := command.CombinedOutput()
		require.NoError(t, err, "canonical PR adapter %s: %s", action, output)
	}
	counts := func() [7]int64 {
		require.NoError(t, queue.GetManager().FlushAll(ctx, 5*time.Second))
		var n [7]int64
		for i, row := range []any{new(issues_model.Issue), new(issues_model.PullRequest), new(issues_model.Comment), new(issues_model.Review), new(activities_model.Notification), new(activities_model.Action), new(nativeoperation_model.Operation)} {
			var err error
			n[i], err = db.GetEngine(ctx).Count(row)
			require.NoError(t, err)
		}
		return n
	}
	withdraw := func(repository int64) {
		for _, row := range []any{new(access_model.Access), new(repo_model.Collaboration)} {
			_, err := db.GetEngine(ctx).Where("repo_id=? AND user_id=?", repository, 2).Cols("mode").Update(row)
			require.NoError(t, err)
		}
	}
	before := counts()
	if mode == "prepare-denied" {
		withdraw(head.ID)
		run("prepare-error")
		require.Equal(t, before, counts())
		return
	}
	run("prepare")
	var capture struct {
		OperationID string `json:"operation_id"`
	}
	raw, err := os.ReadFile(binding.State)
	require.NoError(t, err)
	require.NoError(t, json.Unmarshal(raw, &capture))
	t.Cleanup(func() {
		held, err := nativeoperation_model.ReadReservation(context.WithoutCancel(ctx))
		require.NoError(t, err)
		if held.Owner == "cond:"+installation+"/"+capture.OperationID {
			require.NoError(t, nativeoperation_model.ReleaseExactOwner(context.WithoutCancel(ctx), held.Owner, held.Generation))
		}
	}) // Fixture disposal; recovery behavior is qualified by its existing owner.
	get := func() extension.OperationLookup {
		t.Helper()
		o, err := a.GetHumanPullCreate(ctx, binding.Repository, capture.OperationID)
		require.NoError(t, err)
		return o
	}
	require.Nil(t, get().Record)
	if application && mode == "capture-rollback" {
		run("rollback")
		require.Nil(t, get().Record)
		require.Equal(t, before, counts())
		return
	}
	if mode == "invalid-capture" {
		run("invalid")
		require.Nil(t, get().Record)
		require.Equal(t, before, counts())
		return
	}
	if mode == "early-cancel" {
		run("cancel")
	}
	if mode == "stale" {
		require.NoError(t, nativeoperation_service.Default().WithOrdinaryOwnership(ctx, nativeoperation_service.FamilyRepoSettings, "canonical-pull-create-stale", nativeoperation_service.Scope{RepositoryID: base.ID}, func(context.Context) error { return nil }))
	}
	if mode == "partial" {
		_, err := db.GetEngine(ctx).Exec("CREATE TRIGGER fail_canonical_pull_finish BEFORE INSERT ON review BEGIN SELECT RAISE(ABORT, 'canonical PR code owners failure'); END")
		require.NoError(t, err)
		t.Cleanup(func() {
			_, err := db.GetEngine(context.WithoutCancel(ctx)).Exec("DROP TRIGGER fail_canonical_pull_finish")
			require.NoError(t, err)
		})
	}
	if mode == "session-before" {
		fixture.session.uid = 1
	}
	if mode == "missing-cap" {
		delete(entry.capabilities, extension.CapabilityHumanPullCreate)
	}
	if mode == "read-method" {
		entry.method = http.MethodGet
	}
	if mode == "session-before" || mode == "missing-cap" || mode == "read-method" {
		run("submit-denied")
		run("cancel-denied")
		if mode != "read-method" {
			run("lookup-denied")
		}
		fixture.session.uid = 2
		entry.method = http.MethodPost
		entry.capabilities[extension.CapabilityHumanPullCreate] = struct{}{}
		require.Nil(t, get().Record)
		require.Equal(t, before, counts())
		return
	}
	if application && mode == "concurrent" {
		run("concurrent")
	} else if mode == "observation-pending" {
		point := nativeoperation_service.CrashPointHumanPullCreateAfterFinish
		barrier := t.TempDir()
		t.Setenv("NATIVEOP_TEST_CRASH_POINT", point)
		t.Setenv("NATIVEOP_TEST_CRASH_BARRIER_DIR", barrier)
		t.Setenv("NATIVEOP_TEST_CRASH_TIMEOUT_SECONDS", "10")
		command := exec.CommandContext(ctx, probe, "submit")
		command.Env = append(os.Environ(), "SODA_FOUNTAIN_READ_BINDING="+path)
		var output bytes.Buffer
		command.Stdout, command.Stderr = &output, &output
		require.NoError(t, command.Start())
		t.Cleanup(func() {
			if command.ProcessState == nil {
				_ = command.Process.Kill()
				_ = command.Wait()
			}
		})
		require.Eventually(t, func() bool { _, err := os.Stat(filepath.Join(barrier, point+".entered")); return err == nil }, 5*time.Second, 10*time.Millisecond)
		run("lookup-pending")
		require.NoError(t, os.WriteFile(filepath.Join(barrier, point+".release"), []byte("continue\n"), 0o600))
		require.NoError(t, command.Wait(), "async PR adapter: %s", output.String())
	} else if mode == "lost-reply" || mode == "session-after-commit" {
		run("submit-error")
	} else {
		run("submit")
	}
	fixture.session.uid = 2
	o := get()
	require.NotNil(t, o.Record)
	created := o.Record.EffectState == extension.EffectCommitted
	if mode == "stale" || mode == "early-cancel" || mode == "maintainer-denied" {
		require.Equal(t, extension.EffectNotCommitted, o.Record.EffectState)
	} else {
		require.True(t, created)
	}
	if mode == "partial" {
		require.Equal(t, extension.CompletionNeedsIntervention, o.Record.CompletionState)
		run("lookup-intervention")
	} else {
		run("lookup")
	}
	if created {
		var receipt extension.HumanPullCreateReceipt
		require.NoError(t, json.Unmarshal(o.Record.Receipt, &receipt))
		issue, err := issues_model.GetIssueByID(ctx, receipt.IssueID)
		require.NoError(t, err)
		require.Equal(t, q.Title, issue.Title)
		require.Equal(t, q.Body, issue.Content)
		require.Equal(t, q.AllowMaintainerEdit, receipt.AllowMaintainerEdit)
		require.Equal(t, q.Expected.HeadOID, sourceTestGit(t, base.RepoPath(), nil, "rev-parse", fmt.Sprintf("refs/pull/%d/head", receipt.Index)))
		require.EqualValues(t, 1, prepared.Load())
		require.EqualValues(t, 1, committed.Load())
	}
	after := counts()
	if created {
		require.Equal(t, before[0]+1, after[0])
		require.Equal(t, before[1]+1, after[1])
	} else {
		require.Equal(t, before[0], after[0])
		require.Equal(t, before[1], after[1])
		require.Zero(t, prepared.Load())
	}
	if mode == "result-binding" {
		for _, change := range []string{"submit-head", "capture-source", "capture-branch", "capture-title", "capture-body", "capture-maintainer"} {
			mutate(change)
			run("lookup-conflict")
			mutate("")
		}
	}
	if mode == "installation" {
		fresh, freshEntry, freshToken, freshSocket, freshInstallation := replace()
		require.NotEqual(t, installation, freshInstallation)
		binding.Authority, binding.Admission, binding.Socket, binding.Installation = fresh, freshToken, freshSocket, freshInstallation
		_ = freshEntry
		write()
		run("namespace")
		retained, err := nativeoperation_service.Default().Get(ctx, installation, capture.OperationID)
		require.NoError(t, err)
		require.Equal(t, *o.Record, *retained.Record)
		require.Equal(t, after, counts())
		return
	}
	if mode == "head-permission-loss" {
		withdraw(head.ID)
		run("prepare-error")
		run("lookup")
		run("cancel")
	} else if mode == "base-permission-loss" {
		withdraw(base.ID)
		run("lookup-denied")
		run("cancel-denied")
		run("submit-denied")
	} else {
		if !application {
			run("prepare-existing")
		}
		run("submit")
		run("lookup")
		run("cancel")
	}
	require.Equal(t, after, counts())
	t.Logf("PASS canonical PR adapter %s: actual private SDK/native SQL/Git and PostgreSQL capture; effect=%s completion=%s; original writing/preparation/receipt retained without duplicate creation", mode, o.Record.EffectState, o.Record.CompletionState)
}

// Credential-free native evidence for the canonical Store integration. Export
// only actual admitted SDK observations; ordering mutations stay in that consumer.
func exportHumanPullCreateObservation(t *testing.T, mode, command string, q extension.HumanPullCreateRequest, record extension.OperationRecord) {
	t.Helper()
	directory := os.Getenv("SODA_FOUNTAIN_PULL_CREATE_OBSERVATION_EXPORT")
	if directory == "" {
		return
	}
	preparation, err := json.Marshal(q)
	require.NoError(t, err)
	raw, err := json.Marshal(struct {
		CommandID, Repository, HeadRepository, Actor, BaseBranch, HeadBranch, Title, Body string
		AllowMaintainerEdit                                                               bool
		ProviderIntent                                                                    []byte
		Record                                                                            extension.OperationRecord
	}{command, q.Expected.RepositoryID, q.Expected.HeadRepositoryID, q.Expected.ActorID, q.Expected.BaseBranch, q.Expected.HeadBranch, q.Title, q.Body, q.AllowMaintainerEdit, preparation, record})
	require.NoError(t, err)
	require.NoError(t, os.WriteFile(filepath.Join(directory, mode+".json"), raw, 0o600))
}

type humanPullCreateProcessBinding struct {
	Request                                       extension.HumanPullCreateRequest
	DataPath, RepositoryRoot, AppPath, ConfigPath string
}

type humanPullCreateProcessCompletion struct {
	Record  extension.OperationRecord
	Busy    bool
	Failure string
}

func runHumanPullCreateProcessWorker(t *testing.T, root string) {
	t.Helper()
	raw, err := os.ReadFile(filepath.Join(root, "pull-create.json"))
	require.NoError(t, err)
	var binding humanPullCreateProcessBinding
	require.NoError(t, json.Unmarshal(raw, &binding))
	engine := openHumanMergeProcessDatabase(t, root)
	t.Cleanup(func() { require.NoError(t, engine.Close()) })
	setting.AppDataPath, setting.RepoRootPath, setting.AppPath, setting.CustomConf = binding.DataPath, binding.RepositoryRoot, binding.AppPath, binding.ConfigPath
	for _, notifier := range []notify_service.Notifier{uinotification.NewNotifier(), feed.NewNotifier()} {
		notify_service.RegisterNotifier(notifier)
	}
	if os.Getenv("SODA_FOUNTAIN_PULL_CREATE_ACTIVE_PROCESS") == "1" || os.Getenv("SODA_FOUNTAIN_PULL_CREATE_PROCESS_COMPLETE") == "1" {
		baseID, err := strconv.ParseInt(binding.Request.Expected.RepositoryID, 10, 64)
		require.NoError(t, err)
		headID, err := strconv.ParseInt(binding.Request.Expected.HeadRepositoryID, 10, 64)
		require.NoError(t, err)
		base, err := repo_model.GetRepositoryByID(t.Context(), baseID)
		require.NoError(t, err)
		head, err := repo_model.GetRepositoryByID(t.Context(), headID)
		require.NoError(t, err)
		setupHumanPullCreateHooks(t, base, head, root, func() {})
	}
	// The process principal reads the actual retained native actor. Browser
	// session withdrawal was qualified by the composed submit consumer.
	record, err := nativeoperation_service.NewService().SubmitHumanPullCreate(t.Context(), humanMergeProcessInstallation, binding.Request, humanMergeProcessAdmission)
	if os.Getenv("SODA_FOUNTAIN_PULL_CREATE_PROCESS_COMPLETE") == "1" {
		result := humanPullCreateProcessCompletion{Record: record, Busy: errors.Is(err, nativeoperation_service.ErrBusy)}
		if err != nil {
			result.Failure = err.Error()
		}
		require.NoError(t, queue.GetManager().FlushAll(t.Context(), 30*time.Second))
		raw, err := json.Marshal(result)
		require.NoError(t, err)
		require.NoError(t, os.WriteFile(filepath.Join(root, "pull-create-completion.json"), raw, 0o600))
		return
	}
	t.Fatalf("owned PR worker returned before its checkpoint: %v", err)
}

func checkHumanPullCreateProcessReentry(t *testing.T, root string, fixture sourceTestFixture, base, head *repo_model.Repository, original extension.HumanPullCreateRequest, blocked bool) {
	t.Helper()
	ctx := t.Context()
	svc := nativeoperation_service.NewService()
	old, err := nativeoperation_model.LookupOperation(ctx, humanMergeProcessInstallation, original.OperationID)
	require.NoError(t, err)
	held, err := nativeoperation_model.ReadReservation(ctx)
	require.NoError(t, err)
	if blocked {
		require.NotEmpty(t, held.Owner)
	} else {
		require.Empty(t, held.Owner)
	}
	var oldReceipt extension.HumanPullCreateReceipt
	require.NoError(t, json.Unmarshal([]byte(old.Receipt), &oldReceipt))
	oldRef := fmt.Sprintf("refs/pull/%d/head", oldReceipt.Index)
	readOldPrimary := func() string {
		issue, err := issues_model.GetIssueByID(ctx, oldReceipt.IssueID)
		require.NoError(t, err)
		pull, err := issues_model.GetPullRequestByID(ctx, oldReceipt.PullID)
		require.NoError(t, err)
		var comments []*issues_model.Comment
		var notices []*activities_model.Notification
		require.NoError(t, db.GetEngine(ctx).Where("issue_id=?", oldReceipt.IssueID).OrderBy("id").Find(&comments))
		require.NoError(t, db.GetEngine(ctx).Where("issue_id=?", oldReceipt.IssueID).OrderBy("id").Find(&notices))
		raw, err := json.Marshal([]any{issue, pull, comments, notices})
		require.NoError(t, err)
		return string(raw)
	}
	oldPrimary := readOldPrimary()
	oldTip := sourceTestGit(t, base.RepoPath(), nil, "for-each-ref", "--format=%(refname) %(objectname)", oldRef)
	lockPath := filepath.Join(base.RepoPath(), filepath.FromSlash(oldRef)+".lock")
	lockBytes, lockErr := os.ReadFile(lockPath)
	require.True(t, lockErr == nil || os.IsNotExist(lockErr))
	counts := func() [6]int64 {
		var n [6]int64
		for i, row := range []any{new(issues_model.Issue), new(issues_model.PullRequest), new(issues_model.Comment), new(issues_model.Review), new(activities_model.Notification), new(activities_model.Action)} {
			var err error
			n[i], err = db.GetEngine(ctx).Count(row)
			require.NoError(t, err)
		}
		return n
	}
	before := counts()
	q := original
	q.OperationID, err = extension.HumanPullCreateOperationID(q.Expected.ActorID, q.Expected.RepositoryID, "fresh-reentry")
	require.NoError(t, err)
	q.NotAfter = time.Now().Add(time.Minute).Unix()
	q.Title = "Fresh PR after stopped recovery 完整"
	q.Body = "A new human change after stopped recovery.\r\nPlease review @user4.\n"
	require.NoError(t, os.Remove(nativeoperation_model.OfflineMarkerPath()))
	if blocked {
		revision, err := svc.ReadNativeRevision(ctx)
		require.NoError(t, err)
		require.False(t, revision.Idle)
		q.Expected.NativeRevision = revision.Revision
	} else {
		// Fixed fixture input for a genuinely new candidate. Product creation below
		// installs and executes the real native hooks; no product write bypasses them.
		branch := "factory-reentry"
		sourceTestGit(t, fixture.work, nil, "checkout", "-b", branch, original.Expected.HeadOID)
		require.NoError(t, os.WriteFile(filepath.Join(fixture.work, "fresh-reentry"), []byte("a new candidate after owned process-tree death\n"), 0o600))
		sourceTestGit(t, fixture.work, nil, "add", "fresh-reentry")
		sourceTestGit(t, fixture.work, nil, "commit", "-m", "fresh candidate after stopped PR recovery")
		freshHead := sourceTestGit(t, fixture.work, nil, "rev-parse", "HEAD")
		require.NotEqual(t, original.Expected.HeadOID, freshHead)
		hooks := filepath.Join(root, "fixture-hooks")
		require.NoError(t, os.Mkdir(hooks, 0o700))
		sourceTestGit(t, head.RepoPath(), nil, "-c", "core.hooksPath="+hooks, "fetch", "--no-tags", "--no-write-fetch-head", fixture.work, "refs/heads/"+branch+":refs/heads/"+branch)
		request := httptest.NewRequest(http.MethodPost, "/native/pr-reentry", nil)
		raw, err := json.Marshal(fixture.authority)
		require.NoError(t, err)
		request.Header.Set(extension.ContextHeader, string(raw))
		request.Header.Set(extension.AdmissionHeader, fixture.token)
		authority, err := extension.RequestContext(request)
		require.NoError(t, err)
		q.Expected, err = authority.RepositoryPullCreateSnapshot(ctx, original.Expected.RepositoryID, extension.RepositoryPullCreateSnapshotRequest{HeadRepositoryID: original.Expected.HeadRepositoryID, BaseBranch: original.Expected.BaseBranch, HeadBranch: branch})
		require.NoError(t, err)
		require.Equal(t, "allowed", q.Expected.Action.State)
		require.Equal(t, freshHead, q.Expected.HeadOID)
	}
	raw, err := json.Marshal(humanPullCreateProcessBinding{q, setting.AppDataPath, setting.RepoRootPath, setting.AppPath, setting.CustomConf})
	require.NoError(t, err)
	require.NoError(t, os.WriteFile(filepath.Join(root, "pull-create.json"), raw, 0o600))
	logFile, err := os.Create(filepath.Join(root, "reentry.log"))
	require.NoError(t, err)
	t.Cleanup(func() { _ = logFile.Close() })
	worker := exec.CommandContext(ctx, os.Args[0], "-test.run=^TestRepositoryIssuesCallbackUsesHumanAccessWithoutFactoryBinding$", "-test.v", "-test.timeout=90s")
	worker.Env = append(os.Environ(), "SODA_FOUNTAIN_PULL_CREATE_PROCESS_WORKER="+root, "SODA_FOUNTAIN_PULL_CREATE_PROCESS_COMPLETE=1", "SODA_FOUNTAIN_PULL_CREATE_ACTIVE_PROCESS=", "SODA_FOUNTAIN_PULL_CREATE_REENTRY=", "NATIVEOP_TEST_CRASH_POINT=", "TMPDIR="+filepath.Join(root, "worker-tmp"))
	worker.Stdout, worker.Stderr = logFile, logFile
	if err := worker.Run(); err != nil {
		output, _ := os.ReadFile(filepath.Join(root, "reentry.log"))
		t.Fatalf("fresh PR worker failed: %v\n%s", err, output)
	}
	raw, err = os.ReadFile(filepath.Join(root, "pull-create-completion.json"))
	require.NoError(t, err)
	var result humanPullCreateProcessCompletion
	require.NoError(t, json.Unmarshal(raw, &result))
	after, err := nativeoperation_model.LookupOperation(ctx, humanMergeProcessInstallation, original.OperationID)
	require.NoError(t, err)
	require.Equal(t, old, after)
	require.Equal(t, oldPrimary, readOldPrimary(), "fresh operation changed historical PR state or dispatch")
	require.Equal(t, oldTip, sourceTestGit(t, base.RepoPath(), nil, "for-each-ref", "--format=%(refname) %(objectname)", oldRef))
	currentLock, currentLockErr := os.ReadFile(lockPath)
	if lockErr == nil {
		require.NoError(t, currentLockErr)
		require.Equal(t, lockBytes, currentLock)
	} else {
		require.True(t, os.IsNotExist(currentLockErr))
	}
	fresh, err := nativeoperation_model.LookupOperation(ctx, humanMergeProcessInstallation, q.OperationID)
	require.NoError(t, err)
	reservation, err := nativeoperation_model.ReadReservation(ctx)
	require.NoError(t, err)
	if blocked {
		require.True(t, result.Busy, "%+v", result)
		require.Nil(t, fresh)
		require.Equal(t, held, reservation)
		require.Equal(t, before, counts())
		t.Log("fresh PR refused busy after contradictory stopped recovery; original operation, primary, ref, lock and reservation retained")
		return
	}
	require.Empty(t, result.Failure)
	require.Equal(t, extension.EffectCommitted, result.Record.EffectState)
	require.Equal(t, extension.CompletionComplete, result.Record.CompletionState)
	require.NotNil(t, fresh)
	var receipt extension.HumanPullCreateReceipt
	require.NoError(t, json.Unmarshal([]byte(fresh.Receipt), &receipt))
	require.True(t, extension.ValidHumanPullCreateReceipt(receipt, q))
	require.NotEqual(t, oldReceipt.PullID, receipt.PullID)
	require.NotEqual(t, oldReceipt.IssueID, receipt.IssueID)
	require.Greater(t, receipt.Index, oldReceipt.Index)
	issue, err := issues_model.GetIssueByID(ctx, receipt.IssueID)
	require.NoError(t, err)
	require.Equal(t, q.Title, issue.Title)
	require.Equal(t, q.Body, issue.Content)
	require.Equal(t, q.Expected.HeadOID, sourceTestGit(t, base.RepoPath(), nil, "rev-parse", fmt.Sprintf("refs/pull/%d/head", receipt.Index)))
	history, err := db.GetEngine(ctx).Where("issue_id=? AND type=?", receipt.IssueID, issues_model.CommentTypePullRequestPush).Count(new(issues_model.Comment))
	require.NoError(t, err)
	require.EqualValues(t, 1, history)
	reviews, err := db.GetEngine(ctx).Where("issue_id=? AND type=?", receipt.IssueID, issues_model.ReviewTypeRequest).Count(new(issues_model.Review))
	require.NoError(t, err)
	require.EqualValues(t, 1, reviews)
	var notice activities_model.Notification
	found, err := db.GetEngine(ctx).Where("issue_id=? AND user_id=?", receipt.IssueID, 4).Get(&notice)
	require.NoError(t, err)
	require.True(t, found)
	reader := unittest.AssertExistsAndLoadBean(t, &user_model.User{ID: 4})
	_, err = activities_model.SetNotificationStatus(ctx, notice.ID, reader, activities_model.NotificationStatusRead)
	require.NoError(t, err)
	completedCounts := counts()
	require.Equal(t, before[0]+1, completedCounts[0])
	require.Equal(t, before[1]+1, completedCounts[1])
	require.Empty(t, reservation.Owner)
	require.Greater(t, reservation.Generation, held.Generation)
	files, err := filepath.Glob(filepath.Join(setting.AppDataPath, "nativeop-exec", "*"))
	require.NoError(t, err)
	require.Empty(t, files)
	for _, request := range []extension.HumanPullCreateRequest{original, q} {
		replay, err := svc.SubmitHumanPullCreate(ctx, humanMergeProcessInstallation, request, humanMergeProcessAdmission)
		require.NoError(t, err)
		if request.OperationID == original.OperationID {
			require.Equal(t, old.EffectState, replay.EffectState)
			require.Equal(t, old.Completion, replay.CompletionState)
			require.Equal(t, old.Receipt, string(replay.Receipt))
		} else {
			require.Equal(t, result.Record, replay)
		}
	}
	require.Equal(t, completedCounts, counts())
	retained, err := activities_model.GetNotificationByID(ctx, notice.ID)
	require.NoError(t, err)
	require.Equal(t, activities_model.NotificationStatusRead, retained.Status)
	require.Equal(t, oldPrimary, readOldPrimary())
	t.Log("fresh native PR completed from new commit/branch after stopped recovery; exact historical receipt/ref/lock retained, new generation released, single history/review and read notification preserved on old/new replay")
}

func checkHumanPullCreateProcess(t *testing.T, fixture sourceTestFixture, base, head *repo_model.Repository, q extension.HumanPullCreateRequest, mode string) {
	t.Helper()
	if runtime.GOOS != "linux" {
		t.Skip("owned SIGKILL/reap and /proc qualification runs on Linux")
	}
	ctx := t.Context()
	reentry := os.Getenv("SODA_FOUNTAIN_PULL_CREATE_REENTRY") == "1"
	active := os.Getenv("SODA_FOUNTAIN_PULL_CREATE_ACTIVE_PROCESS") == "1" || reentry
	q.OperationID, _ = extension.HumanPullCreateOperationID(q.Expected.ActorID, q.Expected.RepositoryID, "process-"+mode)
	point := mode
	for _, suffix := range []string{"-cancelled", "-altered-receipt", "-altered-ref", "-missing-history"} {
		point = strings.TrimSuffix(point, suffix)
	}
	root := t.TempDir()
	for _, name := range []string{"barrier", "worker-tmp"} {
		require.NoError(t, os.Mkdir(filepath.Join(root, name), 0o700))
	}
	require.NoError(t, queue.GetManager().FlushAll(ctx, 5*time.Second))
	_, err := db.GetEngine(ctx).Exec("VACUUM INTO ?", filepath.Join(root, "native.sqlite"))
	require.NoError(t, err)
	previous := db.DefaultContext.(db.Engined).Engine()
	engine := openHumanMergeProcessDatabase(t, root)
	t.Cleanup(func() { db.SetDefaultEngine(context.Background(), previous); require.NoError(t, engine.Close()) })
	svc := nativeoperation_service.NewService()
	owner := "cond:" + humanMergeProcessInstallation + "/" + q.OperationID
	t.Cleanup(func() {
		current, err := nativeoperation_model.ReadReservation(context.WithoutCancel(ctx))
		require.NoError(t, err)
		if current.Owner == owner {
			require.NoError(t, nativeoperation_model.ReleaseExactOwner(context.WithoutCancel(ctx), owner, current.Generation))
		}
	})
	oldApp, oldConf, oldToken := setting.AppPath, setting.CustomConf, setting.InternalToken
	t.Cleanup(func() { setting.AppPath, setting.CustomConf, setting.InternalToken = oldApp, oldConf, oldToken })
	setting.AppPath = os.Getenv("SODA_FOUNTAIN_PULL_CREATE_REF_HOOK_EXECUTABLE")
	require.True(t, filepath.IsAbs(setting.AppPath))
	setting.CustomConf = filepath.Join(root, "app.ini")
	secret := make([]byte, 32)
	_, err = rand.Read(secret)
	require.NoError(t, err)
	setting.InternalToken = fmt.Sprintf("%x", secret)
	var prepared, committed atomic.Int64
	privateHandler := http.StripPrefix("/api/internal", private_router.Routes())
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		r = r.WithContext(web_middleware.WithContextData(r.Context()))
		if strings.Contains(r.URL.Path, "/reference-transaction/") {
			raw, err := io.ReadAll(io.LimitReader(r.Body, 1<<20))
			require.NoError(t, err)
			r.Body = io.NopCloser(bytes.NewReader(raw))
			var options private_api.TransactionOptions
			require.NoError(t, json.Unmarshal(raw, &options))
			if len(options.RefFullNames) > 0 && options.Phase == nativeoperation_service.PhasePrepared {
				prepared.Add(1)
			}
			if len(options.RefFullNames) > 0 && options.Phase == nativeoperation_service.PhaseCommitted {
				committed.Add(1)
			}
		}
		privateHandler.ServeHTTP(w, r)
	}))
	t.Cleanup(server.Close)
	currentUser, err := osuser.Current()
	require.NoError(t, err)
	config := fmt.Sprintf("RUN_USER = %s\nRUN_MODE = prod\n[server]\nPROTOCOL = http\nLOCAL_ROOT_URL = %s/\nAPP_DATA_PATH = %s\n[repository]\nROOT = %s\n[security]\nINSTALL_LOCK = true\nINTERNAL_TOKEN = %s\n[log]\nMODE = console\nLEVEL = fatal\n", currentUser.Username, server.URL, setting.AppDataPath, setting.RepoRootPath, setting.InternalToken)
	require.NoError(t, os.WriteFile(setting.CustomConf, []byte(config), 0o600))
	for _, repo := range []*repo_model.Repository{base, head} {
		require.NoError(t, repo_module.CreateDelegateHooks(repo.RepoPath()))
	}
	counts := func() [8]int64 {
		var n [8]int64
		for i, row := range []any{new(issues_model.Issue), new(issues_model.PullRequest), new(issues_model.Comment), new(issues_model.Review), new(activities_model.Notification), new(activities_model.Action), new(issues_model.IssueIndex), new(issues_model.IssueUser)} {
			n[i], err = db.GetEngine(ctx).Count(row)
			require.NoError(t, err)
		}
		return n
	}
	gitState := func() []string {
		var result []string
		for _, repo := range []*repo_model.Repository{base, head} {
			result = append(result, sourceTestGit(t, repo.RepoPath(), nil, "for-each-ref", "--format=%(refname) %(objectname)"))
			raw, err := os.ReadFile(filepath.Join(repo.RepoPath(), "config"))
			require.NoError(t, err)
			result = append(result, string(raw))
		}
		return result
	}
	baseline, initialGit := counts(), gitState()
	raw, err := json.Marshal(humanPullCreateProcessBinding{q, setting.AppDataPath, setting.RepoRootPath, setting.AppPath, setting.CustomConf})
	require.NoError(t, err)
	require.NoError(t, os.WriteFile(filepath.Join(root, "pull-create.json"), raw, 0o600))
	logFile, err := os.Create(filepath.Join(root, "worker.log"))
	require.NoError(t, err)
	t.Cleanup(func() { _ = logFile.Close() })
	child := exec.CommandContext(ctx, os.Args[0], "-test.run=^TestRepositoryIssuesCallbackUsesHumanAccessWithoutFactoryBinding$", "-test.v", "-test.timeout=75s")
	child.Env = append(os.Environ(), "SODA_FOUNTAIN_PULL_CREATE_PROCESS_WORKER="+root, "TMPDIR="+filepath.Join(root, "worker-tmp"), "NATIVEOP_TEST_CRASH_POINT="+point, "NATIVEOP_TEST_CRASH_BARRIER_DIR="+filepath.Join(root, "barrier"), "NATIVEOP_TEST_CRASH_TIMEOUT_SECONDS=60")
	if active {
		supervisor := os.Getenv("SODA_FOUNTAIN_PULL_CREATE_PROCESS_SUPERVISOR")
		require.True(t, filepath.IsAbs(supervisor))
		workerEnv := child.Env
		child = exec.CommandContext(ctx, supervisor, "-test.run=^TestIssueGraphProcessDeathRecovery$", "-test.v", "-test.timeout=75s")
		child.Env = append(workerEnv, "SODA_FOUNTAIN_PULL_CREATE_ACTIVE_PROCESS=1", "FOUNTAIN_PULL_CREATE_PROCESS_SUPERVISOR_ROOT="+root, "FOUNTAIN_PULL_CREATE_PROCESS_WORKER_EXECUTABLE="+os.Args[0])
	}
	child.Stdout, child.Stderr = logFile, logFile
	require.NoError(t, child.Start())
	exited := make(chan error, 1)
	go func() { exited <- child.Wait() }()
	reaped := false
	t.Cleanup(func() {
		if !reaped {
			_ = child.Process.Kill()
			select {
			case <-exited:
			case <-time.After(10 * time.Second):
				t.Error("owned PR worker was not reaped during cleanup")
			}
		}
	})
	finished := point == nativeoperation_service.CrashPointHumanPullCreateAfterFinish || point == nativeoperation_service.CrashPointHumanPullCreateAfterRelease
	observedPrepared, observedCommitted := prepared.Load(), committed.Load()
	if active {
		select {
		case err := <-exited:
			reaped = true
			output, _ := os.ReadFile(filepath.Join(root, "worker.log"))
			require.NoError(t, err, string(output))
		case <-time.After(60 * time.Second):
			t.Fatal("owned PR Git process-tree supervisor did not finish")
		}
		raw, err := os.ReadFile(filepath.Join(root, "tree-reaped.json"))
		require.NoError(t, err)
		var proof []struct {
			PID    int
			Name   string
			Reaped bool
		}
		require.NoError(t, json.Unmarshal(raw, &proof))
		require.GreaterOrEqual(t, len(proof), 3)
		for _, process := range proof {
			require.True(t, process.Reaped)
		}
		t.Logf("native PR at %s: SIGKILL/reaped owned process tree %s", point, raw)
		raw, err = os.ReadFile(filepath.Join(root, "hook-observed.json"))
		require.NoError(t, err)
		var hook struct {
			Prepared, Committed int64
			Phase               string
			Recorded            bool
		}
		require.NoError(t, json.Unmarshal(raw, &hook))
		require.Equal(t, point != humanPullCreateHookBeforeAdmission, hook.Recorded)
		phase := string(nativeoperation_service.PhasePrepared)
		if point == humanPullCreateHookAfterCommit {
			phase = string(nativeoperation_service.PhaseCommitted)
		}
		require.Equal(t, phase, hook.Phase)
		require.EqualValues(t, 1, hook.Prepared)
		observedPrepared, observedCommitted = hook.Prepared, hook.Committed
	} else {
		deadline := time.After(30 * time.Second)
		tick := time.NewTicker(10 * time.Millisecond)
		defer tick.Stop()
		enteredPath := filepath.Join(root, "barrier", point+".entered")
		for entered := false; !entered; {
			select {
			case err := <-exited:
				reaped = true
				output, _ := os.ReadFile(filepath.Join(root, "worker.log"))
				t.Fatalf("owned PR worker exited before %s: %v\n%s", point, err, output)
			case <-deadline:
				output, _ := os.ReadFile(filepath.Join(root, "worker.log"))
				t.Fatalf("owned PR worker never reached %s\n%s", point, output)
			case <-tick.C:
				_, err := os.Stat(enteredPath)
				entered = err == nil
			}
		}
		entered, err := os.ReadFile(enteredPath)
		require.NoError(t, err)
		require.Equal(t, strconv.Itoa(child.Process.Pid), strings.TrimSpace(string(entered)))
		if finished {
			// Prove actual queued UI delivery before the crash, so recovery must
			// preserve the read notification rather than silently resend it.
			require.Eventually(t, func() bool {
				found, err := db.GetEngine(ctx).Where("issue_id IN (SELECT id FROM issue WHERE repo_id=?) AND user_id=?", base.ID, 4).Exist(new(activities_model.Notification))
				return err == nil && found
			}, 10*time.Second, 10*time.Millisecond)
		}
		if strings.HasSuffix(mode, "-cancelled") {
			_, err := svc.Cancel(ctx, humanMergeProcessInstallation, q.OperationID)
			require.NoError(t, err)
		}
		children, err := filepath.Glob(fmt.Sprintf("/proc/%d/task/*/children", child.Process.Pid))
		require.NoError(t, err)
		require.NotEmpty(t, children)
		for _, path := range children {
			data, err := os.ReadFile(path)
			if os.IsNotExist(err) {
				continue
			}
			require.NoError(t, err)
			require.Empty(t, strings.TrimSpace(string(data)), "saved checkpoint still has active Git/hook descendants")
		}
		require.NoError(t, child.Process.Kill())
		select {
		case err := <-exited:
			reaped = true
			var killed *exec.ExitError
			require.ErrorAs(t, err, &killed)
			require.Equal(t, "signal: killed", killed.ProcessState.String())
		case <-time.After(10 * time.Second):
			t.Fatal("owned PR worker did not exit after SIGKILL")
		}
		_, err = os.Stat(fmt.Sprintf("/proc/%d", child.Process.Pid))
		require.True(t, os.IsNotExist(err))
		t.Logf("owned PR pid=%d reached %s; /proc proved no descendants; SIGKILL received and reaped", child.Process.Pid, point)
		observedPrepared, observedCommitted = prepared.Load(), committed.Load()
	}
	require.NoError(t, engine.Close())
	engine = openHumanMergeProcessDatabase(t, root)
	held, err := nativeoperation_model.ReadReservation(ctx)
	require.NoError(t, err)
	op, err := nativeoperation_model.LookupOperation(ctx, humanMergeProcessInstallation, q.OperationID)
	require.NoError(t, err)
	require.NotNil(t, op)
	canonical, digest, err := extension.CanonicalHumanPullCreateIntent(q)
	require.NoError(t, err)
	require.Equal(t, canonical, op.Intent)
	require.Equal(t, digest, op.IntentDigest)
	require.Zero(t, op.TokenID)
	require.Empty(t, op.CredentialFingerprint)
	primaryCommitted := point != nativeoperation_service.CrashPointHumanPullCreateBeforePrimary && point != nativeoperation_service.CrashPointHumanPullCreateInPrimary
	refCommitted := point == nativeoperation_service.CrashPointHumanPullCreateAfterRef || point == humanPullCreateHookAfterCommit || finished
	released := point == nativeoperation_service.CrashPointHumanPullCreateAfterRelease
	require.Equal(t, primaryCommitted, op.Admitted)
	var receipt extension.HumanPullCreateReceipt
	if primaryCommitted {
		require.Equal(t, extension.EffectCommitted, op.EffectState)
		require.NoError(t, json.Unmarshal([]byte(op.Receipt), &receipt))
		require.True(t, extension.ValidHumanPullCreateReceipt(receipt, q))
		issue, err := issues_model.GetIssueByID(ctx, receipt.IssueID)
		require.NoError(t, err)
		require.Equal(t, q.Title, issue.Title)
		require.Equal(t, q.Body, issue.Content)
		after := counts()
		require.Equal(t, baseline[0]+1, after[0])
		require.Equal(t, baseline[1]+1, after[1])
		if refCommitted {
			require.Equal(t, q.Expected.HeadOID, sourceTestGit(t, base.RepoPath(), nil, "rev-parse", fmt.Sprintf("refs/pull/%d/head", receipt.Index)))
			require.EqualValues(t, 1, observedPrepared)
			require.EqualValues(t, 1, observedCommitted)
		} else {
			require.Equal(t, initialGit, gitState())
		}
	} else {
		require.Equal(t, extension.EffectPending, op.EffectState)
		require.Empty(t, op.Receipt)
		require.Empty(t, op.Completion)
		require.Equal(t, baseline, counts())
		require.Equal(t, initialGit, gitState())
	}
	files, err := filepath.Glob(filepath.Join(setting.AppDataPath, "nativeop-exec", "*"))
	require.NoError(t, err)
	if released {
		require.Empty(t, held.Owner)
		require.Empty(t, files)
		require.Equal(t, extension.CompletionComplete, op.Completion)
	} else {
		require.Equal(t, owner, held.Owner)
		require.Len(t, files, 1)
	}
	if finished {
		history, err := db.GetEngine(ctx).Where("issue_id=? AND type=?", receipt.IssueID, issues_model.CommentTypePullRequestPush).Count(new(issues_model.Comment))
		require.NoError(t, err)
		require.EqualValues(t, 1, history)
		reviews, err := db.GetEngine(ctx).Where("issue_id=? AND type=?", receipt.IssueID, issues_model.ReviewTypeRequest).Count(new(issues_model.Review))
		require.NoError(t, err)
		require.EqualValues(t, 1, reviews)
		var notice activities_model.Notification
		found, err := db.GetEngine(ctx).Where("issue_id=? AND user_id=?", receipt.IssueID, 4).Get(&notice)
		require.NoError(t, err)
		require.True(t, found)
		reader := unittest.AssertExistsAndLoadBean(t, &user_model.User{ID: 4})
		_, err = activities_model.SetNotificationStatus(ctx, notice.ID, reader, activities_model.NotificationStatusRead)
		require.NoError(t, err)
	}
	altered := strings.HasSuffix(mode, "-altered-receipt") || strings.HasSuffix(mode, "-altered-ref") || strings.HasSuffix(mode, "-missing-history")
	if strings.HasSuffix(mode, "-altered-receipt") {
		n, err := db.GetEngine(ctx).ID(op.ID).Cols("receipt").Update(&nativeoperation_model.Operation{Receipt: op.Receipt + " "})
		require.NoError(t, err)
		require.EqualValues(t, 1, n)
	}
	if strings.HasSuffix(mode, "-altered-ref") {
		sourceTestGit(t, base.RepoPath(), nil, "update-ref", fmt.Sprintf("refs/pull/%d/head", receipt.Index), q.Expected.BaseOID)
	}
	if strings.HasSuffix(mode, "-missing-history") {
		n, err := db.GetEngine(ctx).Where("issue_id=? AND type=?", receipt.IssueID, issues_model.CommentTypePullRequestPush).Delete(new(issues_model.Comment))
		require.NoError(t, err)
		require.EqualValues(t, 1, n)
	}
	nativeState := func() string {
		var issues []*issues_model.Issue
		var pulls []*issues_model.PullRequest
		var comments []*issues_model.Comment
		var reviews []*issues_model.Review
		var notices []*activities_model.Notification
		var actions []*activities_model.Action
		var users []*issues_model.IssueUser
		var indices []*issues_model.IssueIndex
		for _, rows := range []any{&issues, &pulls, &comments, &reviews, &notices, &actions, &users} {
			require.NoError(t, db.GetEngine(ctx).OrderBy("id").Find(rows))
		}
		require.NoError(t, db.GetEngine(ctx).OrderBy("group_id").Find(&indices))
		raw, err := json.Marshal([]any{issues, pulls, comments, reviews, notices, actions, users, indices})
		require.NoError(t, err)
		return string(raw)
	}
	beforeNative, beforeGit := nativeState(), gitState()
	before, err := svc.Get(ctx, humanMergeProcessInstallation, q.OperationID)
	require.NoError(t, err)
	_, err = svc.Recover(ctx, owner, held.Generation)
	require.ErrorIs(t, err, nativeoperation_service.ErrNotInhibited)
	require.NoError(t, os.WriteFile(nativeoperation_model.OfflineMarkerPath(), []byte("owned PR worker SIGKILLed and reaped; restart inhibited\n"), 0o600))
	t.Cleanup(func() {
		err := os.Remove(nativeoperation_model.OfflineMarkerPath())
		require.True(t, err == nil || os.IsNotExist(err))
	})
	if !released {
		wrong, err := svc.Recover(ctx, owner, held.Generation+1)
		require.NoError(t, err)
		require.Equal(t, nativeoperation_service.RecoveryFenced, wrong.Verdict)
	}
	assessment, err := svc.Recover(ctx, owner, held.Generation)
	require.NoError(t, err)
	after, err := svc.Get(ctx, humanMergeProcessInstallation, q.OperationID)
	require.NoError(t, err)
	if altered {
		require.Equal(t, nativeoperation_service.RecoveryFenced, assessment.Verdict)
		require.Equal(t, before, after)
	} else {
		if released {
			require.Equal(t, nativeoperation_service.RecoveryIdle, assessment.Verdict)
		} else {
			require.Equal(t, nativeoperation_service.RecoveryReleased, assessment.Verdict)
		}
		require.Equal(t, before.Record.Receipt, after.Record.Receipt)
		if primaryCommitted {
			require.Equal(t, extension.EffectCommitted, after.Record.EffectState)
			completion := extension.CompletionNeedsIntervention
			if finished {
				completion = extension.CompletionComplete
			}
			require.Equal(t, completion, after.Record.CompletionState)
		} else {
			require.Equal(t, extension.EffectNotCommitted, after.Record.EffectState)
			require.Empty(t, after.Record.Receipt)
			if strings.HasSuffix(mode, "-cancelled") {
				require.Equal(t, extension.CancellationCancelled, after.Record.CancellationStatus)
			}
		}
	}
	require.Equal(t, beforeNative, nativeState(), "killed-worker recovery changed native rows or repeated dispatch")
	require.Equal(t, beforeGit, gitState(), "killed-worker recovery rewrote refs or remotes")
	current, err := nativeoperation_model.ReadReservation(ctx)
	require.NoError(t, err)
	files, err = filepath.Glob(filepath.Join(setting.AppDataPath, "nativeop-exec", "*"))
	require.NoError(t, err)
	if altered {
		require.Equal(t, owner, current.Owner)
		require.Len(t, files, 1)
	} else {
		require.Empty(t, current.Owner)
		require.Empty(t, current.Verifier)
		require.Empty(t, files)
	}
	require.NoError(t, engine.Close())
	engine = openHumanMergeProcessDatabase(t, root)
	again, err := nativeoperation_service.NewService().Recover(ctx, owner, held.Generation)
	require.NoError(t, err)
	if altered {
		require.Equal(t, nativeoperation_service.RecoveryFenced, again.Verdict)
	} else {
		require.Equal(t, nativeoperation_service.RecoveryIdle, again.Verdict)
	}
	replay, err := svc.SubmitHumanPullCreate(ctx, humanMergeProcessInstallation, q, humanMergeProcessAdmission)
	require.NoError(t, err)
	require.Equal(t, *after.Record, replay)
	require.Equal(t, beforeNative, nativeState())
	require.Equal(t, beforeGit, gitState())
	if reentry {
		checkHumanPullCreateProcessReentry(t, root, fixture, base, head, q, altered)
	}
	t.Logf("PR process %s: verdict=%s effect=%s completion=%s; same SQL/Git reopened after real SIGKILL/reap, no creation/ref/notification replay", mode, assessment.Verdict, after.Record.EffectState, after.Record.CompletionState)
}

func checkHumanPullCreateSubmit(t *testing.T, fixture sourceTestFixture, base, head *repo_model.Repository, q extension.HumanPullCreateRequest, mode string) {
	t.Helper()
	ctx, cancel := context.WithCancel(t.Context())
	defer cancel()
	svc := nativeoperation_service.NewService()
	var err error
	q.OperationID, err = extension.HumanPullCreateOperationID(q.Expected.ActorID, q.Expected.RepositoryID, "submit-"+mode)
	require.NoError(t, err)
	if mode == "draft" {
		q.Title = "WIP: " + q.Title
	}
	if mode == "allow-maintainer" {
		q.AllowMaintainerEdit = true
		for _, row := range []any{&access_model.Access{Mode: perm.AccessModeWrite}, &repo_model.Collaboration{Mode: perm.AccessModeWrite}} {
			_, err := db.GetEngine(ctx).Where("repo_id=? AND user_id=?", head.ID, 2).Cols("mode").Update(row)
			require.NoError(t, err)
		}
	}
	if mode == "stale-head" {
		sourceTestGit(t, head.RepoPath(), nil, "update-ref", "refs/heads/"+q.Expected.HeadBranch, fixture.base)
	}
	if mode == "archived" {
		_, err := db.GetEngine(ctx).ID(base.ID).Cols("is_archived").Update(&repo_model.Repository{IsArchived: true})
		require.NoError(t, err)
	}
	if mode == "duplicate" {
		actor := unittest.AssertExistsAndLoadBean(t, &user_model.User{ID: 2})
		issue := &issues_model.Issue{RepoID: base.ID, Repo: base, PosterID: actor.ID, Poster: actor, Title: "Existing native PR", IsPull: true}
		pr := &issues_model.PullRequest{BaseRepoID: base.ID, HeadRepoID: head.ID, BaseRepo: base, HeadRepo: head, BaseBranch: q.Expected.BaseBranch, HeadBranch: q.Expected.HeadBranch, Type: issues_model.PullRequestGitea, Flow: issues_model.PullRequestFlowGithub}
		require.NoError(t, issues_model.NewPullRequest(ctx, base, issue, nil, nil, pr))
	}
	if mode == "early-cancel" {
		_, err := svc.Cancel(ctx, humanMergeProcessInstallation, q.OperationID)
		require.NoError(t, err)
	}
	require.NoError(t, queue.GetManager().FlushAll(ctx, 5*time.Second))
	root := t.TempDir()
	_, err = db.GetEngine(ctx).Exec("VACUUM INTO ?", filepath.Join(root, "native.sqlite"))
	require.NoError(t, err)
	previous := db.DefaultContext.(db.Engined).Engine()
	engine := openHumanMergeProcessDatabase(t, root)
	t.Cleanup(func() { db.SetDefaultEngine(context.Background(), previous); require.NoError(t, engine.Close()) })
	t.Cleanup(func() {
		held, err := nativeoperation_model.ReadReservation(context.WithoutCancel(ctx))
		require.NoError(t, err)
		if held.Owner == "cond:"+humanMergeProcessInstallation+"/"+q.OperationID {
			require.NoError(t, nativeoperation_model.ReleaseExactOwner(context.WithoutCancel(ctx), held.Owner, held.Generation))
		}
	})
	var intervened bool
	admit := func(c context.Context) error {
		op, err := nativeoperation_model.LookupOperation(c, humanMergeProcessInstallation, q.OperationID)
		if err != nil {
			return err
		}
		if op != nil && op.Submitted && !intervened {
			if !db.InTransaction(c) && mode == "cancel-after-claim" {
				intervened = true
				_, err = svc.Cancel(c, humanMergeProcessInstallation, q.OperationID)
			}
			if !db.InTransaction(c) && mode == "expiry-after-claim" {
				intervened = true
				time.Sleep(time.Until(time.Unix(q.NotAfter, 0)))
			}
			if db.InTransaction(c) && mode == "session-in-primary" {
				n, err := db.GetEngine(c).Where("repo_id=? AND is_pull=?", base.ID, true).Count(new(issues_model.Issue))
				if err != nil {
					return err
				}
				if n > 0 {
					intervened = true
					fixture.session.uid = 1
				}
			}
		}
		if err != nil {
			return err
		}
		if c.Err() != nil {
			return nativeoperation_service.ErrAuthorityLost
		}
		_, status := resolveCurrentUser(c, nativeAdmissions.get(fixture.token))
		if status != http.StatusOK {
			return nativeoperation_service.ErrAuthorityLost
		}
		return nil
	}
	oldApp, oldConf, oldToken := setting.AppPath, setting.CustomConf, setting.InternalToken
	t.Cleanup(func() { setting.AppPath, setting.CustomConf, setting.InternalToken = oldApp, oldConf, oldToken })
	setting.AppPath = os.Getenv("SODA_FOUNTAIN_PULL_CREATE_REF_HOOK_EXECUTABLE")
	require.True(t, filepath.IsAbs(setting.AppPath))
	setting.CustomConf = filepath.Join(root, "app.ini")
	secret := make([]byte, 32)
	_, err = rand.Read(secret)
	require.NoError(t, err)
	setting.InternalToken = fmt.Sprintf("%x", secret)
	var prepared, committed atomic.Int64
	privateHandler := http.StripPrefix("/api/internal", private_router.Routes())
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		r = r.WithContext(web_middleware.WithContextData(r.Context()))
		if strings.Contains(r.URL.Path, "/reference-transaction/") {
			raw, err := io.ReadAll(io.LimitReader(r.Body, 1<<20))
			require.NoError(t, err)
			r.Body = io.NopCloser(bytes.NewReader(raw))
			var options private_api.TransactionOptions
			require.NoError(t, json.Unmarshal(raw, &options))
			if len(options.RefFullNames) > 0 && options.Phase == nativeoperation_service.PhasePrepared {
				prepared.Add(1)
				switch mode {
				case "session-after-primary":
					fixture.session.uid = 1
				case "context-after-primary":
					cancel()
				case "late-cancel":
					_, err := svc.Cancel(r.Context(), humanMergeProcessInstallation, q.OperationID)
					require.NoError(t, err)
				case "expiry-after-primary":
					time.Sleep(time.Until(time.Unix(q.NotAfter, 0)))
				}
			}
			if len(options.RefFullNames) > 0 && options.Phase == nativeoperation_service.PhaseCommitted {
				committed.Add(1)
			}
			if len(options.RefFullNames) > 0 && (options.Phase == nativeoperation_service.PhasePrepared && mode == "ref-reply-loss" || options.Phase == nativeoperation_service.PhaseCommitted && mode == "committed-hook-reply-loss") {
				response := httptest.NewRecorder()
				privateHandler.ServeHTTP(response, r)
				http.Error(w, "native hook reply withheld", 503)
				return
			}
		}
		privateHandler.ServeHTTP(w, r)
	}))
	t.Cleanup(server.Close)
	currentUser, err := osuser.Current()
	require.NoError(t, err)
	config := fmt.Sprintf("RUN_USER = %s\nRUN_MODE = prod\n[server]\nPROTOCOL = http\nLOCAL_ROOT_URL = %s/\nAPP_DATA_PATH = %s\n[repository]\nROOT = %s\n[security]\nINSTALL_LOCK = true\nINTERNAL_TOKEN = %s\n[log]\nMODE = console\nLEVEL = fatal\n", currentUser.Username, server.URL, setting.AppDataPath, setting.RepoRootPath, setting.InternalToken)
	require.NoError(t, os.WriteFile(setting.CustomConf, []byte(config), 0o600))
	require.NoError(t, repo_module.CreateDelegateHooks(base.RepoPath()))
	if base.ID != head.ID {
		require.NoError(t, repo_module.CreateDelegateHooks(head.RepoPath()))
	}
	var triggers []string
	addTrigger := func(name, body string) {
		_, err := db.GetEngine(ctx).Exec("CREATE TRIGGER " + name + " " + body)
		require.NoError(t, err)
		triggers = append(triggers, name)
	}
	switch mode {
	case "sql-primary-rollback":
		addTrigger("fail_submit_pull_primary", fmt.Sprintf("BEFORE INSERT ON pull_request WHEN NEW.base_repo_id=%d BEGIN SELECT RAISE(ABORT, 'submit primary rollback'); END", base.ID))
	case "finish-partial":
		addTrigger("fail_submit_pull_finish", "BEFORE INSERT ON review BEGIN SELECT RAISE(ABORT, 'submit code owners failure'); END")
	case "record-rollback":
		addTrigger("fail_submit_pull_record", "BEFORE UPDATE OF scope ON reservation WHEN instr(NEW.scope, 'human-pull-create-finish-done')>0 BEGIN SELECT RAISE(ABORT, 'submit finishing record failure'); END")
	case "release-rollback":
		addTrigger("fail_submit_pull_release", "BEFORE UPDATE OF owner ON reservation WHEN NEW.owner='' BEGIN SELECT RAISE(ABORT, 'submit release rollback'); END")
	}
	t.Cleanup(func() {
		for _, name := range triggers {
			_, err := db.GetEngine(context.WithoutCancel(ctx)).Exec("DROP TRIGGER IF EXISTS " + name)
			require.NoError(t, err)
		}
	})
	point := ""
	switch mode {
	case "after-primary-stop":
		point = nativeoperation_service.CrashPointHumanPullCreateAfterPrimary
	case "after-ref-stop":
		point = nativeoperation_service.CrashPointHumanPullCreateAfterRef
	case "after-finish-stop":
		point = nativeoperation_service.CrashPointHumanPullCreateAfterFinish
	case "lost-reply":
		point = nativeoperation_service.CrashPointHumanPullCreateAfterRelease
	}
	if point != "" {
		t.Setenv("NATIVEOP_TEST_CRASH_POINT", point)
		t.Setenv("NATIVEOP_TEST_CRASH_BARRIER_DIR", root)
		t.Setenv("NATIVEOP_TEST_CRASH_TIMEOUT_SECONDS", "1")
	}
	counts := func() [8]int64 {
		require.NoError(t, queue.GetManager().FlushAll(context.WithoutCancel(ctx), 5*time.Second))
		var n [8]int64
		for i, row := range []any{new(issues_model.Issue), new(issues_model.PullRequest), new(issues_model.Comment), new(issues_model.Review), new(activities_model.Notification), new(activities_model.Action), new(issues_model.IssueIndex), new(issues_model.IssueUser)} {
			n[i], err = db.GetEngine(context.WithoutCancel(ctx)).Count(row)
			require.NoError(t, err)
		}
		return n
	}
	gitState := func() []string {
		var result []string
		for _, repo := range []*repo_model.Repository{base, head} {
			result = append(result, sourceTestGit(t, repo.RepoPath(), nil, "for-each-ref", "--format=%(refname) %(objectname)"))
			raw, err := os.ReadFile(filepath.Join(repo.RepoPath(), "config"))
			require.NoError(t, err)
			result = append(result, string(raw))
		}
		return result
	}
	before, gitBefore := counts(), gitState()
	if mode == "session-before" {
		fixture.session.uid = 1
	}
	if mode == "context-before" {
		cancel()
	}
	if mode == "invalid" {
		q.Expected.HeadOID = "HEAD"
	}
	if mode == "expiry-after-claim" || mode == "expiry-after-primary" {
		q.NotAfter = time.Now().Add(2 * time.Second).Unix()
	}
	var result extension.OperationRecord
	var submitErr error
	if mode == "outer-transaction" {
		require.NoError(t, db.WithTx(ctx, func(tx context.Context) error {
			_, err := svc.SubmitHumanPullCreate(tx, humanMergeProcessInstallation, q, admit)
			require.ErrorIs(t, err, nativeoperation_service.ErrInvalidIntent)
			return nil
		}))
	} else if mode == "concurrent" {
		start := make(chan struct{})
		results := make([]extension.OperationRecord, 6)
		failures := make([]error, len(results))
		var wg sync.WaitGroup
		for i := range results {
			wg.Go(func() {
				<-start
				results[i], failures[i] = svc.SubmitHumanPullCreate(ctx, humanMergeProcessInstallation, q, admit)
			})
		}
		close(start)
		wg.Wait()
		complete := 0
		for i, e := range failures {
			if e == nil && results[i].CompletionState == extension.CompletionComplete {
				complete++
				result = results[i]
			}
		}
		require.Positive(t, complete)
	} else {
		result, submitErr = svc.SubmitHumanPullCreate(ctx, humanMergeProcessInstallation, q, admit)
	}
	fixture.session.uid = 2
	op, err := nativeoperation_model.LookupOperation(context.WithoutCancel(ctx), humanMergeProcessInstallation, q.OperationID)
	require.NoError(t, err)
	if mode == "session-before" || mode == "context-before" || mode == "outer-transaction" || mode == "invalid" {
		if mode != "outer-transaction" {
			require.Error(t, submitErr)
		}
		require.Nil(t, op)
		require.Equal(t, before, counts())
		require.Equal(t, gitBefore, gitState())
		return
	}
	require.NotNil(t, op)
	if mode == "early-cancel" {
		require.ErrorIs(t, submitErr, nativeoperation_service.ErrCancelledBeforeSubmit)
		require.False(t, op.Submitted)
		require.Equal(t, extension.CancellationCancelled, op.Cancellation)
		require.Equal(t, before, counts())
		return
	}
	refused := mode == "cancel-after-claim" || mode == "expiry-after-claim" || mode == "session-in-primary" || mode == "stale-head" || mode == "archived" || mode == "duplicate"
	held, err := nativeoperation_model.ReadReservation(context.WithoutCancel(ctx))
	require.NoError(t, err)
	after := counts()
	if refused {
		require.Equal(t, extension.EffectNotCommitted, op.EffectState)
		require.Equal(t, before, after)
		require.Empty(t, held.Owner)
		require.Equal(t, gitBefore, gitState())
		if mode == "session-in-primary" {
			require.ErrorIs(t, submitErr, nativeoperation_service.ErrAuthorityLost)
		} else {
			require.NoError(t, submitErr)
		}
		if mode == "cancel-after-claim" {
			require.Equal(t, extension.CancellationCancelled, op.Cancellation)
		}
	} else if mode == "sql-primary-rollback" {
		require.Error(t, submitErr)
		require.Equal(t, extension.EffectPending, op.EffectState)
		require.Empty(t, op.Receipt)
		require.NotEmpty(t, held.Owner)
		require.Equal(t, before, after)
		require.Equal(t, gitBefore, gitState())
	} else {
		require.Equal(t, extension.EffectCommitted, op.EffectState)
		require.Equal(t, before[0]+1, after[0])
		require.Equal(t, before[1]+1, after[1])
		var receipt extension.HumanPullCreateReceipt
		require.NoError(t, json.Unmarshal([]byte(op.Receipt), &receipt))
		require.True(t, extension.ValidHumanPullCreateReceipt(receipt, q))
		issue, err := issues_model.GetIssueByID(context.WithoutCancel(ctx), receipt.IssueID)
		require.NoError(t, err)
		require.Equal(t, q.Title, issue.Title)
		require.Equal(t, q.Body, issue.Content)
		pr, err := issues_model.GetPullRequestByID(context.WithoutCancel(ctx), receipt.PullID)
		require.NoError(t, err)
		require.Equal(t, q.AllowMaintainerEdit, pr.AllowMaintainerEdit)
		unfinished := mode == "ref-reply-loss" || mode == "finish-partial" || mode == "record-rollback" || mode == "release-rollback" || mode == "after-primary-stop" || mode == "after-ref-stop" || mode == "after-finish-stop"
		if unfinished {
			require.NotEmpty(t, held.Owner)
			completion := extension.CompletionPending
			if mode == "finish-partial" {
				completion = extension.CompletionNeedsIntervention
				require.NoError(t, submitErr)
			} else {
				require.Error(t, submitErr)
			}
			require.Equal(t, completion, op.Completion)
		} else {
			require.Equal(t, extension.CompletionComplete, op.Completion)
			require.Empty(t, held.Owner)
			require.Empty(t, held.Verifier)
			if mode == "session-after-primary" || mode == "context-after-primary" {
				require.ErrorIs(t, submitErr, nativeoperation_service.ErrAuthorityLost)
				require.Equal(t, extension.OperationRecord{}, result)
			} else if mode == "lost-reply" {
				require.Error(t, submitErr)
			} else {
				require.NoError(t, submitErr)
			}
			history, err := db.GetEngine(context.WithoutCancel(ctx)).Where("issue_id=? AND type=?", receipt.IssueID, issues_model.CommentTypePullRequestPush).Count(new(issues_model.Comment))
			require.NoError(t, err)
			if mode == "equal-tips" {
				require.Zero(t, history)
			} else {
				require.EqualValues(t, 1, history)
			}
			reviews, err := db.GetEngine(context.WithoutCancel(ctx)).Where("issue_id=? AND reviewer_id=? AND type=?", receipt.IssueID, 4, issues_model.ReviewTypeRequest).Count(new(issues_model.Review))
			require.NoError(t, err)
			if mode == "draft" || mode == "equal-tips" {
				require.Zero(t, reviews)
			} else {
				require.EqualValues(t, 1, reviews)
			}
			mentions, err := issues_model.GetIssueMentionIDs(context.WithoutCancel(ctx), receipt.IssueID)
			require.NoError(t, err)
			require.Contains(t, mentions, int64(4))
			notices, err := db.GetEngine(context.WithoutCancel(ctx)).Where("issue_id=? AND user_id=?", receipt.IssueID, 4).Count(new(activities_model.Notification))
			require.NoError(t, err)
			require.EqualValues(t, 1, notices)
		}
		if mode != "after-primary-stop" && mode != "ref-reply-loss" {
			require.Equal(t, q.Expected.HeadOID, sourceTestGit(t, base.RepoPath(), nil, "rev-parse", pr.GetGitRefName()))
			require.Equal(t, strings.TrimSpace(strings.ReplaceAll(gitState()[0], pr.GetGitRefName()+" "+q.Expected.HeadOID, "")), gitBefore[0])
		} else {
			require.Equal(t, gitBefore[0], gitState()[0])
		}
		currentGit := gitState()
		require.Equal(t, gitBefore[1], currentGit[1])
		require.Equal(t, gitBefore[3], currentGit[3])
		if base.ID != head.ID {
			require.Equal(t, gitBefore[2], currentGit[2])
		}
	}
	files, err := filepath.Glob(filepath.Join(setting.AppDataPath, "nativeop-exec", "*"))
	require.NoError(t, err)
	if held.Owner == "" {
		require.Empty(t, files)
	} else {
		require.Len(t, files, 1)
	}
	// Clear the actual failure before replay: the retained operation, rather
	// than a still-failing trigger, must prevent another execution.
	for _, name := range triggers {
		_, err := db.GetEngine(context.WithoutCancel(ctx)).Exec("DROP TRIGGER " + name)
		require.NoError(t, err)
	}
	var notice activities_model.Notification
	found, err := db.GetEngine(context.WithoutCancel(ctx)).Where("issue_id IN (SELECT id FROM issue WHERE repo_id=?) AND user_id=?", base.ID, 4).Get(&notice)
	require.NoError(t, err)
	if found {
		reader := unittest.AssertExistsAndLoadBean(t, &user_model.User{ID: 4})
		_, err := activities_model.SetNotificationStatus(context.WithoutCancel(ctx), notice.ID, reader, activities_model.NotificationStatusRead)
		require.NoError(t, err)
	}
	lookup, err := svc.Get(context.WithoutCancel(ctx), humanMergeProcessInstallation, q.OperationID)
	require.NoError(t, err)
	require.NoError(t, engine.Close())
	engine = openHumanMergeProcessDatabase(t, root)
	replay, err := nativeoperation_service.NewService().SubmitHumanPullCreate(context.WithoutCancel(ctx), humanMergeProcessInstallation, q, admit)
	require.NoError(t, err)
	require.Equal(t, *lookup.Record, replay)
	require.Equal(t, after, counts())
	if found {
		stored, err := activities_model.GetNotificationByID(context.WithoutCancel(ctx), notice.ID)
		require.NoError(t, err)
		require.Equal(t, activities_model.NotificationStatusRead, stored.Status)
	}
	changed := q
	changed.Body += "changed"
	_, err = svc.SubmitHumanPullCreate(context.WithoutCancel(ctx), humanMergeProcessInstallation, changed, admit)
	require.Error(t, err)
	require.Equal(t, after, counts())
	fixture.session.uid = 1
	_, err = svc.SubmitHumanPullCreate(context.WithoutCancel(ctx), humanMergeProcessInstallation, q, admit)
	require.ErrorIs(t, err, nativeoperation_service.ErrAuthorityLost)
	fixture.session.uid = 2
	t.Logf("human PR submit %s: effect=%s completion=%s, generated hooks prepared=%d committed=%d; exact retained replay/reopen, no duplicate primary/ref/notification", mode, op.EffectState, op.Completion, prepared.Load(), committed.Load())
}

func checkHumanPullCreateRecovery(t *testing.T, fixture sourceTestFixture, base, head *repo_model.Repository, q extension.HumanPullCreateRequest, held *nativeoperation_model.Reservation, x *execcontext.Execution, reopen func(), mode string) {
	t.Helper()
	ctx := t.Context()
	svc := nativeoperation_service.NewService()
	owned := execcontext.NewContext(ctx, x)
	lookup, err := svc.Get(ctx, humanMergeProcessInstallation, q.OperationID)
	require.NoError(t, err)
	var receipt extension.HumanPullCreateReceipt
	if len(lookup.Record.Receipt) > 0 {
		require.NoError(t, json.Unmarshal(lookup.Record.Receipt, &receipt))
	}
	if mode == "finished" || mode == "equal-tips" || mode == "partial" || mode == "uncertain-dispatch" || mode == "history-missing" || mode == "history-tamper" {
		if mode == "partial" {
			_, err := db.GetEngine(ctx).Exec(fmt.Sprintf("CREATE TRIGGER fail_stopped_pull_finish BEFORE INSERT ON review WHEN NEW.issue_id=%d BEGIN SELECT RAISE(ABORT, 'stopped code owners failure'); END", receipt.IssueID))
			require.NoError(t, err)
		}
		if mode == "uncertain-dispatch" {
			_, err := db.GetEngine(ctx).Exec("CREATE TRIGGER fail_stopped_pull_finish_record BEFORE UPDATE OF scope ON reservation WHEN instr(NEW.scope, 'human-pull-create-finish-done')>0 BEGIN SELECT RAISE(ABORT, 'stopped finish record'); END")
			require.NoError(t, err)
		}
		finished, err := svc.FinishHumanPullCreate(owned, humanMergeProcessInstallation, q)
		if mode == "partial" || mode == "uncertain-dispatch" {
			require.Error(t, err)
		} else {
			require.NoError(t, err)
		}
		if mode == "partial" {
			require.Equal(t, extension.CompletionNeedsIntervention, finished.CompletionState)
			_, err := db.GetEngine(ctx).Exec("DROP TRIGGER fail_stopped_pull_finish")
			require.NoError(t, err)
		}
		if mode == "uncertain-dispatch" {
			_, err := db.GetEngine(ctx).Exec("DROP TRIGGER fail_stopped_pull_finish_record")
			require.NoError(t, err)
		}
	}
	if mode == "pending-cancelled" || mode == "revoked" {
		_, err := svc.Cancel(ctx, humanMergeProcessInstallation, q.OperationID)
		require.NoError(t, err)
	}
	if mode == "missing-proof" {
		require.NoError(t, os.Remove(x.CapabilityPath))
	}
	if mode == "pending-contradiction" {
		actor := unittest.AssertExistsAndLoadBean(t, &user_model.User{ID: 2})
		issue := &issues_model.Issue{RepoID: base.ID, Repo: base, PosterID: actor.ID, Poster: actor, Title: q.Title, Content: q.Body, IsPull: true}
		pr := &issues_model.PullRequest{BaseRepoID: base.ID, HeadRepoID: head.ID, BaseRepo: base, HeadRepo: head, BaseBranch: q.Expected.BaseBranch, HeadBranch: q.Expected.HeadBranch, MergeBase: q.Expected.BaseOID, Type: issues_model.PullRequestGitea, Flow: issues_model.PullRequestFlowGithub}
		require.NoError(t, issues_model.NewPullRequest(owned, base, issue, nil, nil, pr))
	}
	if mode == "intent-tamper" || mode == "receipt-tamper" || mode == "terminal-contradiction" {
		column, update := "intent_digest", &nativeoperation_model.Operation{IntentDigest: "changed"}
		if mode == "receipt-tamper" {
			column, update = "receipt", &nativeoperation_model.Operation{Receipt: string(lookup.Record.Receipt) + " "}
		}
		if mode == "terminal-contradiction" {
			column, update = "completion", &nativeoperation_model.Operation{Completion: nativeoperation_model.CompletionComplete}
		}
		n, err := db.GetEngine(ctx).Where("operation_id=?", q.OperationID).Cols(column).Update(update)
		require.NoError(t, err)
		require.EqualValues(t, 1, n)
	}
	if mode == "scope-tamper" {
		var scope nativeoperation_service.Scope
		require.NoError(t, json.Unmarshal([]byte(held.Scope), &scope))
		scope.HeadRepositoryID++
		raw, err := json.Marshal(scope)
		require.NoError(t, err)
		require.NoError(t, nativeoperation_model.UpdateScopeWhere(ctx, held.Owner, string(raw)))
	}
	if mode == "parent-tamper" {
		n, err := db.GetEngine(ctx).ID(receipt.IssueID).Cols("name").Update(&issues_model.Issue{Title: "different native primary"})
		require.NoError(t, err)
		require.EqualValues(t, 1, n)
	}
	if mode == "history-missing" || mode == "history-tamper" {
		query := db.GetEngine(ctx).Where("issue_id=? AND type=?", receipt.IssueID, issues_model.CommentTypePullRequestPush)
		var n int64
		if mode == "history-missing" {
			n, err = query.Delete(new(issues_model.Comment))
		} else {
			n, err = query.Cols("content").Update(&issues_model.Comment{Content: "changed native history"})
		}
		require.NoError(t, err)
		require.EqualValues(t, 1, n)
	}
	if mode == "head-moved" || mode == "base-moved" || mode == "derived-moved" {
		repo, ref := head, "refs/heads/"+q.Expected.HeadBranch
		if mode == "base-moved" {
			repo, ref = base, "refs/heads/"+q.Expected.BaseBranch
		}
		if mode == "derived-moved" {
			repo, ref = base, fmt.Sprintf("refs/pull/%d/head", receipt.Index)
		}
		if _, err := os.Stat(filepath.Join(repo.RepoPath(), "hooks", "reference-transaction")); err == nil {
			require.NoError(t, os.Remove(filepath.Join(repo.RepoPath(), "hooks", "reference-transaction")))
		}
		sourceTestGit(t, repo.RepoPath(), nil, "update-ref", ref, fixture.base)
	}
	require.NoError(t, queue.GetManager().FlushAll(ctx, 5*time.Second))
	var notice activities_model.Notification
	found, err := db.GetEngine(ctx).Where("issue_id=? AND user_id=?", receipt.IssueID, 4).Get(&notice)
	require.NoError(t, err)
	if found {
		reader := unittest.AssertExistsAndLoadBean(t, &user_model.User{ID: 4})
		_, err := activities_model.SetNotificationStatus(ctx, notice.ID, reader, activities_model.NotificationStatusRead)
		require.NoError(t, err)
	}
	nativeState := func() string {
		// Complete native collaboration rows, not just counts: recovery cannot
		// alter delivered/read notices, history, content, reviews or indices.
		var issues []*issues_model.Issue
		var pulls []*issues_model.PullRequest
		var comments []*issues_model.Comment
		var reviews []*issues_model.Review
		var notifications []*activities_model.Notification
		var actions []*activities_model.Action
		var indices []*issues_model.IssueIndex
		var users []*issues_model.IssueUser
		for _, rows := range []any{&issues, &pulls, &comments, &reviews, &notifications, &actions, &users} {
			require.NoError(t, db.GetEngine(ctx).OrderBy("id").Find(rows))
		}
		require.NoError(t, db.GetEngine(ctx).OrderBy("group_id").Find(&indices))
		raw, err := json.Marshal([]any{issues, pulls, comments, reviews, notifications, actions, indices, users})
		require.NoError(t, err)
		return string(raw)
	}
	gitState := func() []string {
		var result []string
		for _, repo := range []*repo_model.Repository{base, head} {
			result = append(result, sourceTestGit(t, repo.RepoPath(), nil, "for-each-ref", "--format=%(refname) %(objectname)"))
			raw, err := os.ReadFile(filepath.Join(repo.RepoPath(), "config"))
			require.NoError(t, err)
			result = append(result, string(raw))
		}
		return result
	}
	beforeNative, beforeGit := nativeState(), gitState()
	before, err := svc.Get(ctx, humanMergeProcessInstallation, q.OperationID)
	require.NoError(t, err)
	// All owned synchronous writers returned and native queues drained. Close
	// and reopen the actual saved database; SIGKILL/reap remains a later slice.
	reopen()
	require.Equal(t, beforeNative, nativeState())
	stopped := nativeoperation_service.NewService()
	_, err = stopped.Recover(ctx, held.Owner, held.Generation)
	require.ErrorIs(t, err, nativeoperation_service.ErrNotInhibited)
	require.NoError(t, os.WriteFile(nativeoperation_model.OfflineMarkerPath(), []byte("owned synchronous PR writers returned; restart inhibited\n"), 0o600))
	t.Cleanup(func() {
		err := os.Remove(nativeoperation_model.OfflineMarkerPath())
		require.True(t, err == nil || os.IsNotExist(err))
	})
	for _, wrong := range []struct {
		owner      string
		generation int64
	}{{held.Owner, held.Generation + 1}, {"ord:foreign", held.Generation}} {
		assessment, err := stopped.Recover(ctx, wrong.owner, wrong.generation)
		require.NoError(t, err)
		require.Equal(t, nativeoperation_service.RecoveryFenced, assessment.Verdict)
	}
	require.NoError(t, db.WithTx(ctx, func(tx context.Context) error {
		_, err := stopped.Recover(tx, held.Owner, held.Generation)
		require.ErrorIs(t, err, nativeoperation_service.ErrInvalidIntent)
		return nil
	}))
	if mode == "release-rollback" || mode == "pending-release-rollback" {
		_, err := db.GetEngine(ctx).Exec("CREATE TRIGGER fail_pull_recovery_release BEFORE UPDATE OF owner ON reservation WHEN NEW.owner='' BEGIN SELECT RAISE(ABORT, 'recovery atomic release rollback'); END")
		require.NoError(t, err)
		_, err = stopped.Recover(ctx, held.Owner, held.Generation)
		require.Error(t, err)
		unchanged, err := stopped.Get(ctx, humanMergeProcessInstallation, q.OperationID)
		require.NoError(t, err)
		require.Equal(t, before, unchanged)
		current, err := nativeoperation_model.ReadReservation(ctx)
		require.NoError(t, err)
		require.Equal(t, held.Owner, current.Owner)
		_, err = os.Stat(x.CapabilityPath)
		require.NoError(t, err)
		_, err = db.GetEngine(ctx).Exec("DROP TRIGGER fail_pull_recovery_release")
		require.NoError(t, err)
	}
	assessment, err := stopped.Recover(ctx, held.Owner, held.Generation)
	require.NoError(t, err)
	fenced := mode == "pending-contradiction" || mode == "scope-tamper" || mode == "intent-tamper" || mode == "receipt-tamper" || mode == "parent-tamper" || mode == "head-moved" || mode == "base-moved" || mode == "derived-moved" || mode == "history-missing" || mode == "history-tamper" || mode == "terminal-contradiction"
	current, err := nativeoperation_model.ReadReservation(ctx)
	require.NoError(t, err)
	after, err := stopped.Get(ctx, humanMergeProcessInstallation, q.OperationID)
	require.NoError(t, err)
	if fenced {
		require.Equal(t, nativeoperation_service.RecoveryFenced, assessment.Verdict)
		require.Equal(t, held.Owner, current.Owner)
		require.Equal(t, before, after)
		_, err = os.Stat(x.CapabilityPath)
		require.NoError(t, err)
	} else {
		require.Equal(t, nativeoperation_service.RecoveryReleased, assessment.Verdict)
		require.Empty(t, current.Owner)
		require.Empty(t, current.Verifier)
		require.Equal(t, held.Revision, current.Revision)
		require.Equal(t, before.Record.Receipt, after.Record.Receipt)
		if strings.HasPrefix(mode, "pending") {
			require.Equal(t, extension.EffectNotCommitted, after.Record.EffectState)
			require.Empty(t, after.Record.CompletionState)
			if mode == "pending-cancelled" {
				require.Equal(t, extension.CancellationCancelled, after.Record.CancellationStatus)
			}
		} else {
			require.Equal(t, extension.EffectCommitted, after.Record.EffectState)
			completion := extension.CompletionNeedsIntervention
			if mode == "finished" || mode == "equal-tips" {
				completion = extension.CompletionComplete
			}
			require.Equal(t, completion, after.Record.CompletionState)
		}
		_, err = os.Stat(x.CapabilityPath)
		require.True(t, os.IsNotExist(err))
		idle, err := stopped.Recover(ctx, held.Owner, held.Generation)
		require.NoError(t, err)
		require.Equal(t, nativeoperation_service.RecoveryIdle, idle.Verdict)
		reopen()
		retained, err := nativeoperation_service.NewService().Get(ctx, humanMergeProcessInstallation, q.OperationID)
		require.NoError(t, err)
		require.Equal(t, after, retained)
	}
	require.NoError(t, queue.GetManager().FlushAll(ctx, 5*time.Second))
	require.Equal(t, beforeNative, nativeState(), "recovery changed native collaboration state or resent notifications")
	require.Equal(t, beforeGit, gitState(), "recovery wrote refs or configured remotes")
	t.Logf("human PR stopped recovery %s: verdict=%s effect=%s completion=%s; actual retained SQL reopen and native Git, no creation/ref/notification replay", mode, assessment.Verdict, after.Record.EffectState, after.Record.CompletionState)
}

func checkHumanPullCreateCompletion(t *testing.T, fixture sourceTestFixture, base, head *repo_model.Repository, q extension.HumanPullCreateRequest, primary extension.OperationRecord, held *nativeoperation_model.Reservation, x *execcontext.Execution, mode string) {
	t.Helper()
	ctx := t.Context()
	owned := execcontext.NewContext(ctx, x)
	svc := nativeoperation_service.NewService()
	var receipt extension.HumanPullCreateReceipt
	require.NoError(t, json.Unmarshal(primary.Receipt, &receipt))
	pr, err := issues_model.GetPullRequestByID(ctx, receipt.PullID)
	require.NoError(t, err)
	counts := func() [8]int64 {
		require.NoError(t, queue.GetManager().FlushAll(context.WithoutCancel(ctx), 5*time.Second))
		var result [8]int64
		for i, row := range []any{new(issues_model.Issue), new(issues_model.PullRequest), new(issues_model.Comment), new(issues_model.Review), new(activities_model.Notification), new(activities_model.Action), new(issues_model.IssueIndex), new(issues_model.IssueUser)} {
			result[i], err = db.GetEngine(ctx).Count(row)
			require.NoError(t, err)
		}
		return result
	}
	refs := func() []string {
		return []string{sourceTestGit(t, base.RepoPath(), nil, "for-each-ref", "--format=%(refname) %(objectname)"), sourceTestGit(t, head.RepoPath(), nil, "for-each-ref", "--format=%(refname) %(objectname)")}
	}
	before := counts()
	_, err = svc.CompleteHumanPullCreate(owned, humanMergeProcessInstallation, q)
	require.ErrorIs(t, err, nativeoperation_service.ErrHumanPullCreateCompletionNotReady)
	changed := q
	changed.Body += "changed"
	_, err = svc.FinishHumanPullCreate(owned, humanMergeProcessInstallation, changed)
	require.Error(t, err)
	require.Equal(t, before, counts())
	if mode == "outer-transaction" {
		require.NoError(t, db.WithTx(owned, func(tx context.Context) error {
			_, err := svc.FinishHumanPullCreate(tx, humanMergeProcessInstallation, q)
			require.ErrorIs(t, err, nativeoperation_service.ErrInvalidIntent)
			_, err = svc.CompleteHumanPullCreate(tx, humanMergeProcessInstallation, q)
			require.ErrorIs(t, err, nativeoperation_service.ErrInvalidIntent)
			return nil
		}))
		require.Equal(t, before, counts())
		return
	}
	if mode == "missing-proof" {
		owned = ctx
	}
	if mode == "session-after" {
		fixture.session.uid = 1
	}
	if mode == "late-cancel" {
		cancelled, err := svc.Cancel(ctx, humanMergeProcessInstallation, q.OperationID)
		require.NoError(t, err)
		require.Equal(t, extension.CancellationTooLate, cancelled.CancellationStatus)
	}
	if mode == "parent-tamper" {
		n, err := db.GetEngine(ctx).ID(receipt.IssueID).Cols("content").Update(&issues_model.Issue{Content: "different saved body"})
		require.NoError(t, err)
		require.EqualValues(t, 1, n)
	}
	if mode == "ref-tamper" {
		require.NoError(t, os.Remove(filepath.Join(base.RepoPath(), "hooks", "reference-transaction")))
		sourceTestGit(t, base.RepoPath(), nil, "update-ref", pr.GetGitRefName(), q.Expected.BaseOID)
		require.NoError(t, repo_module.CreateDelegateHooks(base.RepoPath()))
	}
	var triggers []string
	addTrigger := func(name, body string) {
		_, err := db.GetEngine(ctx).Exec("CREATE TRIGGER " + name + " " + body)
		require.NoError(t, err)
		triggers = append(triggers, name)
	}
	if mode == "claim-rollback" || mode == "record-rollback" {
		phase := nativeoperation_service.HumanPullCreateFinishStarted
		if mode == "record-rollback" {
			phase = nativeoperation_service.HumanPullCreateFinishDone
		}
		addTrigger("fail_pull_finish_phase", fmt.Sprintf("BEFORE UPDATE OF scope ON reservation WHEN instr(NEW.scope, '%s')>0 BEGIN SELECT RAISE(ABORT, 'native finishing phase rollback'); END", phase))
	}
	if mode == "history-failure" {
		addTrigger("fail_pull_finish_history", fmt.Sprintf("BEFORE INSERT ON comment WHEN NEW.issue_id=%d AND NEW.type=%d BEGIN SELECT RAISE(ABORT, 'native history failure'); END", receipt.IssueID, issues_model.CommentTypePullRequestPush))
	}
	if mode == "codeowners-failure" {
		addTrigger("fail_pull_finish_codeowners", fmt.Sprintf("BEFORE INSERT ON review WHEN NEW.issue_id=%d BEGIN SELECT RAISE(ABORT, 'native code owners failure'); END", receipt.IssueID))
	}
	if mode == "mentions-failure" {
		for _, event := range []string{"INSERT", "UPDATE OF is_mentioned"} {
			name := "fail_pull_finish_mentions_insert"
			if event != "INSERT" {
				name = "fail_pull_finish_mentions_update"
			}
			addTrigger(name, fmt.Sprintf("BEFORE %s ON issue_user WHEN NEW.issue_id=%d AND NEW.is_mentioned=1 BEGIN SELECT RAISE(ABORT, 'native mentions failure'); END", event, receipt.IssueID))
		}
	}
	t.Cleanup(func() {
		for _, name := range triggers {
			_, err := db.GetEngine(context.WithoutCancel(ctx)).Exec("DROP TRIGGER IF EXISTS " + name)
			require.NoError(t, err)
		}
	})
	gitBefore := refs()
	var finished extension.OperationRecord
	var finishErr error
	if mode == "concurrent" {
		start := make(chan struct{})
		results := make([]extension.OperationRecord, 4)
		failures := make([]error, len(results))
		var wg sync.WaitGroup
		for i := range results {
			wg.Go(func() {
				<-start
				results[i], failures[i] = svc.FinishHumanPullCreate(owned, humanMergeProcessInstallation, q)
			})
		}
		close(start)
		wg.Wait()
		winners := 0
		for i, e := range failures {
			if e == nil {
				winners++
				finished = results[i]
			}
		}
		require.Equal(t, 1, winners)
	} else {
		finished, finishErr = svc.FinishHumanPullCreate(owned, humanMergeProcessInstallation, q)
	}
	after := counts()
	require.Equal(t, gitBefore, refs(), "finishing rewrote a ref")
	current, err := nativeoperation_model.LookupOperation(ctx, humanMergeProcessInstallation, q.OperationID)
	require.NoError(t, err)
	require.Equal(t, string(primary.Receipt), current.Receipt)
	require.Equal(t, extension.EffectCommitted, current.EffectState)
	reservation, err := nativeoperation_model.ReadReservation(ctx)
	require.NoError(t, err)
	require.Equal(t, held.Owner, reservation.Owner)
	require.Equal(t, held.Generation, reservation.Generation)
	var scope nativeoperation_service.Scope
	require.NoError(t, json.Unmarshal([]byte(reservation.Scope), &scope))
	refused := mode == "missing-proof" || mode == "parent-tamper" || mode == "ref-tamper" || mode == "claim-rollback"
	partial := mode == "history-failure" || mode == "codeowners-failure" || mode == "mentions-failure"
	if refused || partial || mode == "record-rollback" {
		require.Error(t, finishErr)
		if refused {
			require.Equal(t, before, after)
			require.Equal(t, nativeoperation_service.HumanPullCreateRefDone, scope.CompletionPhase)
		} else {
			require.Equal(t, nativeoperation_service.HumanPullCreateFinishStarted, scope.CompletionPhase)
			if partial {
				require.Equal(t, extension.CompletionNeedsIntervention, current.Completion)
			}
		}
		_, err = svc.CompleteHumanPullCreate(owned, humanMergeProcessInstallation, q)
		require.Error(t, err)
		if !refused {
			_, err = svc.FinishHumanPullCreate(owned, humanMergeProcessInstallation, q)
			require.Error(t, err)
			require.Equal(t, after, counts(), "partial finishing replayed work")
		}
		if mode == "codeowners-failure" || mode == "mentions-failure" || mode == "record-rollback" {
			n, err := db.GetEngine(ctx).Where("issue_id=? AND type=?", receipt.IssueID, issues_model.CommentTypePullRequestPush).Count(new(issues_model.Comment))
			require.NoError(t, err)
			require.EqualValues(t, 1, n, "fixture did not reach work before its partial failure")
		}
		_, err = os.Stat(x.CapabilityPath)
		require.NoError(t, err)
		t.Logf("human PR finishing %s: exact committed primary retained; phase=%s completion=%s, no replay/release", mode, scope.CompletionPhase, current.Completion)
		return
	}
	require.NoError(t, finishErr)
	require.Equal(t, primary.Receipt, finished.Receipt)
	require.Equal(t, nativeoperation_service.HumanPullCreateFinishDone, scope.CompletionPhase)
	require.Equal(t, extension.CompletionPending, finished.CompletionState)
	for _, i := range []int{0, 1, 6} {
		require.Equal(t, before[i], after[i])
	}
	var pushComments []*issues_model.Comment
	require.NoError(t, db.GetEngine(ctx).Where("issue_id=? AND type=?", receipt.IssueID, issues_model.CommentTypePullRequestPush).Find(&pushComments))
	if mode == "equal-tips" {
		require.Empty(t, pushComments)
	} else {
		require.Len(t, pushComments, 1)
		var content issues_model.PushActionContent
		require.NoError(t, json.Unmarshal([]byte(pushComments[0].Content), &content))
		require.Contains(t, content.CommitIDs, q.Expected.HeadOID)
	}
	reviews, err := db.GetEngine(ctx).Where("issue_id=? AND reviewer_id=? AND type=?", receipt.IssueID, 4, issues_model.ReviewTypeRequest).Count(new(issues_model.Review))
	require.NoError(t, err)
	if mode == "draft" || mode == "equal-tips" {
		require.Zero(t, reviews)
	} else {
		require.EqualValues(t, 1, reviews)
	}
	mentions, err := issues_model.GetIssueMentionIDs(ctx, receipt.IssueID)
	require.NoError(t, err)
	require.Contains(t, mentions, int64(4))
	notifications, err := db.GetEngine(ctx).Where("issue_id=? AND user_id=?", receipt.IssueID, 4).Count(new(activities_model.Notification))
	require.NoError(t, err)
	require.EqualValues(t, 1, notifications)
	actions, err := db.GetEngine(ctx).Where("repo_id=? AND op_type=?", base.ID, activities_model.ActionCreatePullRequest).Count(new(activities_model.Action))
	require.NoError(t, err)
	require.Positive(t, actions)
	_, err = svc.FinishHumanPullCreate(owned, humanMergeProcessInstallation, q)
	require.ErrorIs(t, err, nativeoperation_service.ErrHumanPullCreateFinishClaimed)
	require.Equal(t, after, counts())
	if mode == "complete-evidence" {
		n, err := db.GetEngine(ctx).ID(receipt.IssueID).Cols("content").Update(&issues_model.Issue{Content: "different completion body"})
		require.NoError(t, err)
		require.EqualValues(t, 1, n)
		_, err = svc.CompleteHumanPullCreate(owned, humanMergeProcessInstallation, q)
		require.Error(t, err)
		_, err = db.GetEngine(ctx).ID(receipt.IssueID).Cols("content").Update(&issues_model.Issue{Content: q.Body})
		require.NoError(t, err)
	}
	if mode == "release-rollback" {
		addTrigger("fail_pull_finish_release", "BEFORE UPDATE OF owner ON reservation WHEN NEW.owner='' BEGIN SELECT RAISE(ABORT, 'native completion release rollback'); END")
		_, err = svc.CompleteHumanPullCreate(owned, humanMergeProcessInstallation, q)
		require.Error(t, err)
		lookup, err := svc.Get(ctx, humanMergeProcessInstallation, q.OperationID)
		require.NoError(t, err)
		require.Equal(t, extension.CompletionPending, lookup.Record.CompletionState)
		reservation, err := nativeoperation_model.ReadReservation(ctx)
		require.NoError(t, err)
		require.Equal(t, held.Owner, reservation.Owner)
		_, err = os.Stat(x.CapabilityPath)
		require.NoError(t, err)
		_, err = db.GetEngine(ctx).Exec("DROP TRIGGER fail_pull_finish_release")
		require.NoError(t, err)
	}
	completed, err := svc.CompleteHumanPullCreate(owned, humanMergeProcessInstallation, q)
	require.NoError(t, err)
	require.Equal(t, extension.CompletionComplete, completed.CompletionState)
	require.Equal(t, primary.Receipt, completed.Receipt)
	reservation, err = nativeoperation_model.ReadReservation(ctx)
	require.NoError(t, err)
	require.Empty(t, reservation.Owner)
	require.Empty(t, reservation.Verifier)
	_, err = os.Stat(x.CapabilityPath)
	require.True(t, os.IsNotExist(err))
	lookup, err := svc.Get(ctx, humanMergeProcessInstallation, q.OperationID)
	require.NoError(t, err)
	require.Equal(t, completed, *lookup.Record)
	replay, err := svc.SubmitHumanPullCreatePrimary(ctx, humanMergeProcessInstallation, q, func(context.Context) error { return nil })
	require.NoError(t, err)
	require.Equal(t, completed, replay)
	require.Equal(t, after, counts())
	require.Equal(t, gitBefore, refs())
	if mode == "ordinary" {
		// Qualify the ordinary caller of the extracted shared finishing helper.
		sourceTestGit(t, head.RepoPath(), nil, "update-ref", "refs/heads/ordinary", q.Expected.HeadOID)
		actor := unittest.AssertExistsAndLoadBean(t, &user_model.User{ID: 2})
		issue := &issues_model.Issue{RepoID: base.ID, Repo: base, PosterID: actor.ID, Poster: actor, IsPull: true, Title: "Ordinary native PR", Content: q.Body}
		ordinary := &issues_model.PullRequest{BaseRepoID: base.ID, HeadRepoID: head.ID, BaseRepo: base, HeadRepo: head, BaseBranch: q.Expected.BaseBranch, HeadBranch: "ordinary", Type: issues_model.PullRequestGitea, Flow: issues_model.PullRequestFlowGithub}
		require.NoError(t, pull_service.NewPullRequest(ctx, base, issue, nil, nil, ordinary, nil))
		_ = counts()
		require.Equal(t, q.Expected.HeadOID, sourceTestGit(t, base.RepoPath(), nil, "rev-parse", ordinary.GetGitRefName()))
		history, err := db.GetEngine(ctx).Where("issue_id=? AND type=?", issue.ID, issues_model.CommentTypePullRequestPush).Count(new(issues_model.Comment))
		require.NoError(t, err)
		require.EqualValues(t, 1, history)
		reviews, err := db.GetEngine(ctx).Where("issue_id=? AND type=?", issue.ID, issues_model.ReviewTypeRequest).Count(new(issues_model.Review))
		require.NoError(t, err)
		require.EqualValues(t, 1, reviews)
	}
	t.Logf("human PR finishing %s: native history/review/mentions/UI/feed dispatch once, exact completion/release and retained replay; no finishing ref writes", mode)
}

func checkHumanPullCreateRef(t *testing.T, fixture sourceTestFixture, base, head *repo_model.Repository, p extension.RepositoryPullCreateSnapshot, mode string) {
	t.Helper()
	finishMode := ""
	if strings.HasPrefix(mode, "finish:") {
		finishMode = strings.TrimPrefix(mode, "finish:")
		mode = "valid"
	}
	recoveryMode := ""
	if strings.HasPrefix(finishMode, "recovery:") {
		recoveryMode = strings.TrimPrefix(finishMode, "recovery:")
		if recoveryMode == "ref-before" {
			mode = "prepared-reply-loss"
		}
		if recoveryMode == "ref-after" {
			mode = "record-rollback"
		}
	}
	ctx := t.Context()
	oldData := setting.AppDataPath
	setting.AppDataPath = t.TempDir()
	t.Cleanup(func() { setting.AppDataPath = oldData })
	svc := nativeoperation_service.NewService()
	operation, err := extension.HumanPullCreateOperationID(p.ActorID, p.RepositoryID, "pull-ref-"+mode)
	require.NoError(t, err)
	q := extension.HumanPullCreateRequest{OperationID: operation, Expected: p, NotAfter: time.Now().Add(time.Minute).Unix(), Title: "Native ref 完整", Body: "Captured private-source PR.\n"}
	if finishMode != "" {
		reviewer := unittest.AssertExistsAndLoadBean(t, &user_model.User{ID: 4})
		q.Body += "Please review @" + reviewer.Name + ".\n"
		if finishMode == "draft" {
			q.Title = "WIP: " + q.Title
		}
		_, err := db.GetEngine(ctx).Insert(&access_model.Access{RepoID: base.ID, UserID: reviewer.ID, Mode: perm.AccessModeRead}, &repo_model.Collaboration{RepoID: base.ID, UserID: reviewer.ID, Mode: perm.AccessModeRead}, &repo_model.Watch{RepoID: base.ID, UserID: reviewer.ID, Mode: repo_model.WatchModeNormal})
		require.NoError(t, err)
		if !strings.HasPrefix(finishMode, "process:") {
			for _, notifier := range []notify_service.Notifier{uinotification.NewNotifier(), feed.NewNotifier()} {
				notify_service.RegisterNotifier(notifier)
				t.Cleanup(func() { notify_service.UnregisterNotifier(notifier) })
			}
		}
		t.Cleanup(func() { require.NoError(t, queue.GetManager().FlushAll(context.WithoutCancel(ctx), 5*time.Second)) })
	}
	if mode == "expiry-after" {
		q.NotAfter = time.Now().Add(2 * time.Second).Unix()
	}
	admit := func(c context.Context) error {
		_, status := resolveCurrentUser(c, nativeAdmissions.get(fixture.token))
		if status != http.StatusOK {
			return nativeoperation_service.ErrAuthorityLost
		}
		return nil
	}
	if strings.HasPrefix(finishMode, "submit:") {
		checkHumanPullCreateSubmit(t, fixture, base, head, q, strings.TrimPrefix(finishMode, "submit:"))
		return
	}
	if strings.HasPrefix(finishMode, "sdk:") {
		checkHumanPullCreateSDK(t, fixture, base, head, q, strings.TrimPrefix(finishMode, "sdk:"))
		return
	}
	if strings.HasPrefix(finishMode, "process:") {
		checkHumanPullCreateProcess(t, fixture, base, head, q, strings.TrimPrefix(finishMode, "process:"))
		return
	}
	var reopen func()
	if recoveryMode != "" {
		require.NoError(t, queue.GetManager().FlushAll(ctx, 5*time.Second))
		root := t.TempDir()
		_, err := db.GetEngine(ctx).Exec("VACUUM INTO ?", filepath.Join(root, "native.sqlite"))
		require.NoError(t, err)
		previous := db.DefaultContext.(db.Engined).Engine()
		engine := openHumanMergeProcessDatabase(t, root)
		t.Cleanup(func() { db.SetDefaultEngine(context.Background(), previous); require.NoError(t, engine.Close()) })
		reopen = func() {
			require.NoError(t, queue.GetManager().FlushAll(ctx, 5*time.Second))
			require.NoError(t, engine.Close())
			engine = openHumanMergeProcessDatabase(t, root)
		}
	}
	pendingRecovery := strings.HasPrefix(recoveryMode, "pending")
	if pendingRecovery {
		_, err := db.GetEngine(ctx).Exec(fmt.Sprintf("CREATE TRIGGER fail_stopped_pull_primary BEFORE INSERT ON pull_request WHEN NEW.base_repo_id=%d BEGIN SELECT RAISE(ABORT, 'stopped PR primary rollback'); END", base.ID))
		require.NoError(t, err)
	}
	primary, err := svc.SubmitHumanPullCreatePrimary(ctx, humanMergeProcessInstallation, q, admit)
	if pendingRecovery {
		require.Error(t, err)
		_, err := db.GetEngine(ctx).Exec("DROP TRIGGER fail_stopped_pull_primary")
		require.NoError(t, err)
		lookup, err := svc.Get(ctx, humanMergeProcessInstallation, q.OperationID)
		require.NoError(t, err)
		require.NotNil(t, lookup.Record)
		primary = *lookup.Record
		require.Equal(t, extension.EffectPending, primary.EffectState)
	} else {
		require.NoError(t, err)
		require.Equal(t, extension.EffectCommitted, primary.EffectState)
	}
	var receipt extension.HumanPullCreateReceipt
	var pr *issues_model.PullRequest
	if !pendingRecovery {
		require.NoError(t, json.Unmarshal(primary.Receipt, &receipt))
		pr, err = issues_model.GetPullRequestByID(ctx, receipt.PullID)
		require.NoError(t, err)
	}
	if base.ID != head.ID && finishMode != "equal-tips" && recoveryMode != "equal-tips" {
		_, _, err := git.NewCommand(ctx, "cat-file", "-e").AddDynamicArguments(p.HeadOID).RunStdString(&git.RunOpts{Dir: base.RepoPath()})
		require.Error(t, err, "private head must be absent from base before this ref consumer")
	}
	held, err := nativeoperation_model.ReadReservation(ctx)
	require.NoError(t, err)
	t.Cleanup(func() {
		current, err := nativeoperation_model.ReadReservation(context.WithoutCancel(ctx))
		require.NoError(t, err)
		if current.Owner == held.Owner {
			require.NoError(t, nativeoperation_model.ReleaseExactOwner(context.WithoutCancel(ctx), current.Owner, current.Generation))
		}
	}) // Owned synchronous fixture disposal, not product stopped-writer recovery.
	files, err := filepath.Glob(filepath.Join(setting.AppDataPath, "nativeop-exec", "*"))
	require.NoError(t, err)
	require.Len(t, files, 1)
	x := &execcontext.Execution{Owner: held.Owner, Generation: held.Generation, CapabilityPath: files[0]}
	owned := execcontext.NewContext(ctx, x)
	if recoveryMode != "" {
		needsRef := recoveryMode == "ref-before" || recoveryMode == "ref-after" || recoveryMode == "ref-done" || recoveryMode == "finished" || recoveryMode == "equal-tips" || recoveryMode == "partial" || recoveryMode == "uncertain-dispatch" || recoveryMode == "history-missing" || recoveryMode == "history-tamper" || recoveryMode == "derived-moved"
		if !needsRef {
			checkHumanPullCreateRecovery(t, fixture, base, head, q, held, x, reopen, recoveryMode)
			return
		}
	}
	if mode == "missing-proof" {
		owned = ctx
	}
	if mode == "wrong-proof" {
		proofFile := filepath.Join(t.TempDir(), "wrong-proof")
		require.NoError(t, os.WriteFile(proofFile, []byte("wrong proof"), 0o600))
		copy := *x
		copy.CapabilityPath = proofFile
		owned = execcontext.NewContext(ctx, &copy)
	}
	if mode == "wrong-generation" {
		copy := *x
		copy.Generation++
		owned = execcontext.NewContext(ctx, &copy)
	}
	if mode == "stale-head" {
		sourceTestGit(t, head.RepoPath(), nil, "update-ref", "refs/heads/"+p.HeadBranch, fixture.base)
	}
	if mode == "stale-base" {
		sourceTestGit(t, base.RepoPath(), nil, "update-ref", "refs/heads/"+p.BaseBranch, fixture.tip)
	}
	if mode == "existing-ref" {
		sourceTestGit(t, base.RepoPath(), nil, "update-ref", pr.GetGitRefName(), fixture.base)
	}
	op, err := nativeoperation_model.LookupOperation(ctx, humanMergeProcessInstallation, operation)
	require.NoError(t, err)
	switch mode {
	case "intent-tamper":
		_, err = db.GetEngine(ctx).ID(op.ID).Cols("intent_digest").Update(&nativeoperation_model.Operation{IntentDigest: "changed"})
	case "receipt-tamper":
		changed := receipt
		changed.HeadOID = fixture.tip
		raw, encodeErr := json.Marshal(changed)
		require.NoError(t, encodeErr)
		_, err = db.GetEngine(ctx).ID(op.ID).Cols("receipt").Update(&nativeoperation_model.Operation{Receipt: string(raw)})
	case "parent-tamper":
		var changed int64
		changed, err = db.GetEngine(ctx).ID(receipt.IssueID).Cols("name").Update(&issues_model.Issue{Title: "changed after primary"})
		require.NoError(t, err)
		require.EqualValues(t, 1, changed)
		issue, readErr := issues_model.GetIssueByID(ctx, receipt.IssueID)
		require.NoError(t, readErr)
		require.Equal(t, "changed after primary", issue.Title)
	case "scope-tamper":
		var scope nativeoperation_service.Scope
		require.NoError(t, json.Unmarshal([]byte(held.Scope), &scope))
		scope.HeadRepositoryID++
		raw, encodeErr := json.Marshal(scope)
		require.NoError(t, encodeErr)
		require.NoError(t, nativeoperation_model.UpdateScopeWhere(ctx, held.Owner, string(raw)))
	case "late-cancel":
		cancelled, cancelErr := svc.Cancel(ctx, humanMergeProcessInstallation, operation)
		require.NoError(t, cancelErr)
		require.Equal(t, extension.CancellationTooLate, cancelled.CancellationStatus)
	case "session-after":
		fixture.session.uid = 1
	case "expiry-after":
		time.Sleep(time.Until(time.Unix(q.NotAfter, 0)))
	}
	require.NoError(t, err)
	oldApp, oldConf, oldToken := setting.AppPath, setting.CustomConf, setting.InternalToken
	t.Cleanup(func() { setting.AppPath, setting.CustomConf, setting.InternalToken = oldApp, oldConf, oldToken })
	setting.AppPath = os.Getenv("SODA_FOUNTAIN_PULL_CREATE_REF_HOOK_EXECUTABLE")
	require.True(t, filepath.IsAbs(setting.AppPath))
	setting.CustomConf = filepath.Join(t.TempDir(), "app.ini")
	secret := make([]byte, 32)
	_, err = rand.Read(secret)
	require.NoError(t, err)
	setting.InternalToken = fmt.Sprintf("%x", secret)
	var preparedCalls, committedCalls atomic.Int64
	paused, resume := make(chan struct{}), make(chan struct{})
	privateHandler := http.StripPrefix("/api/internal", private_router.Routes())
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		r = r.WithContext(web_middleware.WithContextData(r.Context()))
		if strings.Contains(r.URL.Path, "/reference-transaction/") {
			raw, err := io.ReadAll(io.LimitReader(r.Body, 1<<20))
			require.NoError(t, err)
			r.Body = io.NopCloser(bytes.NewReader(raw))
			var options private_api.TransactionOptions
			require.NoError(t, json.Unmarshal(raw, &options))
			if options.Phase == nativeoperation_service.PhasePrepared && len(options.RefFullNames) > 0 {
				n := preparedCalls.Add(1)
				if n == 1 && (mode == "concurrent" || mode == "hook-denials") {
					close(paused)
					select {
					case <-resume:
					case <-time.After(10 * time.Second):
						http.Error(w, "fixture pause expired", 500)
						return
					}
				}
				if mode == "source-at-hook" {
					// Force one unparticipating source mutation to exercise the
					// native hook's final tip check, then restore the delegate.
					require.NoError(t, os.Remove(filepath.Join(head.RepoPath(), "hooks", "reference-transaction")))
					sourceTestGit(t, head.RepoPath(), nil, "update-ref", "refs/heads/"+p.HeadBranch, fixture.base)
					require.NoError(t, repo_module.CreateDelegateHooks(head.RepoPath()))
				}
				if mode == "scope-at-hook" {
					current, err := nativeoperation_model.ReadReservation(ctx)
					require.NoError(t, err)
					var scope nativeoperation_service.Scope
					require.NoError(t, json.Unmarshal([]byte(current.Scope), &scope))
					scope.CompletionNewOID = fixture.tip
					raw, err := json.Marshal(scope)
					require.NoError(t, err)
					require.NoError(t, nativeoperation_model.UpdateScopeWhere(ctx, held.Owner, string(raw)))
				}
			}
			if options.Phase == nativeoperation_service.PhaseCommitted && len(options.RefFullNames) > 0 {
				committedCalls.Add(1)
			}
			if len(options.RefFullNames) > 0 && (options.Phase == nativeoperation_service.PhasePrepared && mode == "prepared-reply-loss" || options.Phase == nativeoperation_service.PhaseCommitted && mode == "committed-reply-loss") {
				response := httptest.NewRecorder()
				privateHandler.ServeHTTP(response, r)
				http.Error(w, "native hook reply withheld", 503)
				return
			}
		}
		privateHandler.ServeHTTP(w, r)
	}))
	t.Cleanup(server.Close)
	currentUser, err := osuser.Current()
	require.NoError(t, err)
	config := fmt.Sprintf("RUN_USER = %s\nRUN_MODE = prod\n[server]\nPROTOCOL = http\nLOCAL_ROOT_URL = %s/\nAPP_DATA_PATH = %s\n[repository]\nROOT = %s\n[security]\nINSTALL_LOCK = true\nINTERNAL_TOKEN = %s\n[log]\nMODE = console\nLEVEL = fatal\n", currentUser.Username, server.URL, setting.AppDataPath, setting.RepoRootPath, setting.InternalToken)
	require.NoError(t, os.WriteFile(setting.CustomConf, []byte(config), 0o600))
	require.NoError(t, repo_module.CreateDelegateHooks(base.RepoPath()))
	if head.ID != base.ID {
		require.NoError(t, repo_module.CreateDelegateHooks(head.RepoPath()))
	}
	if mode == "record-rollback" || mode == "phase-rollback" {
		phase := nativeoperation_service.HumanPullCreateRefDone
		if mode == "phase-rollback" {
			phase = nativeoperation_service.HumanPullCreateRefPrepared
		}
		_, err := db.GetEngine(ctx).Exec(fmt.Sprintf("CREATE TRIGGER fail_human_pull_ref BEFORE UPDATE OF scope ON reservation WHEN instr(NEW.scope, '%s')>0 BEGIN SELECT RAISE(ABORT, 'PR ref phase rollback'); END", phase))
		require.NoError(t, err)
		t.Cleanup(func() {
			_, err := db.GetEngine(context.WithoutCancel(ctx)).Exec("DROP TRIGGER fail_human_pull_ref")
			require.NoError(t, err)
		})
	}
	counts := func() [7]int64 {
		var result [7]int64
		for i, row := range []any{new(issues_model.Issue), new(issues_model.PullRequest), new(issues_model.Comment), new(activities_model.Action), new(activities_model.Notification), new(issues_model.IssueIndex), new(issues_model.IssueUser)} {
			result[i], err = db.GetEngine(ctx).Count(row)
			require.NoError(t, err)
		}
		return result
	}
	refs := func(repo *repo_model.Repository) string {
		return sourceTestGit(t, repo.RepoPath(), nil, "for-each-ref", "--format=%(refname) %(objectname)")
	}
	beforeCounts, baseRefs, headRefs := counts(), refs(base), refs(head)
	baseConfig, err := os.ReadFile(filepath.Join(base.RepoPath(), "config"))
	require.NoError(t, err)
	headConfig, err := os.ReadFile(filepath.Join(head.RepoPath(), "config"))
	require.NoError(t, err)
	var result extension.OperationRecord
	var completeErr error
	if mode == "outer-transaction" {
		require.NoError(t, db.WithTx(owned, func(tx context.Context) error {
			_, err := svc.CompleteHumanPullCreateRef(tx, humanMergeProcessInstallation, q)
			require.ErrorIs(t, err, nativeoperation_service.ErrInvalidIntent)
			return nil
		}))
		completeErr = nativeoperation_service.ErrInvalidIntent
	} else if mode == "concurrent" || mode == "hook-denials" {
		type outcome struct {
			record extension.OperationRecord
			err    error
		}
		finished := make(chan outcome, 1)
		go func() {
			r, e := svc.CompleteHumanPullCreateRef(owned, humanMergeProcessInstallation, q)
			finished <- outcome{r, e}
		}()
		select {
		case <-paused:
		case <-time.After(10 * time.Second):
			t.Fatal("native prepared hook did not pause")
		}
		_, err := nativeoperation_service.NewService().CompleteHumanPullCreateRef(owned, humanMergeProcessInstallation, q)
		require.ErrorIs(t, err, nativeoperation_service.ErrHumanPullCreateRefClaimed)
		if mode == "hook-denials" {
			env := execcontext.AppendExecEnv(repo_module.RefWriteEnvironment(base), x)
			for _, ref := range []string{"refs/heads/escape", "refs/tags/escape", "refs/pull/99999/head", "refs/pull/1/merge"} {
				_, _, err := git.NewCommand(owned, "update-ref").AddDynamicArguments(ref, fixture.tip, strings.Repeat("0", len(p.HeadOID))).RunStdString(&git.RunOpts{Dir: base.RepoPath(), Env: env})
				require.Error(t, err, "generated hook allowed unrelated ref %s", ref)
			}
			if head.ID != base.ID {
				env = execcontext.AppendExecEnv(repo_module.RefWriteEnvironment(head), x)
				_, _, err := git.NewCommand(owned, "update-ref").AddDynamicArguments("refs/heads/escape", fixture.tip).RunStdString(&git.RunOpts{Dir: head.RepoPath(), Env: env})
				require.Error(t, err, "base proof allowed a source repository write")
			}
		}
		close(resume)
		out := <-finished
		result, completeErr = out.record, out.err
	} else {
		result, completeErr = svc.CompleteHumanPullCreateRef(owned, humanMergeProcessInstallation, q)
	}
	current, err := nativeoperation_model.LookupOperation(ctx, humanMergeProcessInstallation, operation)
	require.NoError(t, err)
	afterHeld, err := nativeoperation_model.ReadReservation(ctx)
	require.NoError(t, err)
	require.Equal(t, held.Owner, afterHeld.Owner)
	require.Equal(t, held.Generation, afterHeld.Generation)
	require.Equal(t, held.Revision, afterHeld.Revision)
	require.Equal(t, beforeCounts, counts(), "derived ref dispatched collaboration effects")
	require.Equal(t, extension.EffectCommitted, current.EffectState)
	require.Equal(t, extension.CompletionPending, current.Completion)
	if mode != "receipt-tamper" {
		require.Equal(t, string(primary.Receipt), current.Receipt)
	}
	var scope nativeoperation_service.Scope
	require.NoError(t, json.Unmarshal([]byte(afterHeld.Scope), &scope))
	success := mode == "valid" || mode == "same-repository" || mode == "late-cancel" || mode == "session-after" || mode == "expiry-after" || mode == "concurrent" || mode == "hook-denials" || mode == "committed-reply-loss"
	wrote := success || mode == "record-rollback"
	if success {
		require.NoError(t, completeErr)
		require.Equal(t, extension.EffectCommitted, result.EffectState)
		require.Equal(t, nativeoperation_service.HumanPullCreateRefDone, scope.CompletionPhase)
		require.Equal(t, p.HeadOID, sourceTestGit(t, base.RepoPath(), nil, "rev-parse", pr.GetGitRefName()))
		prepared, committed := preparedCalls.Load(), committedCalls.Load()
		replay, err := nativeoperation_service.NewService().CompleteHumanPullCreateRef(owned, humanMergeProcessInstallation, q)
		require.NoError(t, err)
		require.Equal(t, result, replay)
		require.Equal(t, prepared, preparedCalls.Load())
		require.Equal(t, committed, committedCalls.Load())
		require.EqualValues(t, 1, committed)
		require.GreaterOrEqual(t, prepared, int64(1))
		_, _, err = git.NewCommand(ctx, "cat-file", "-e").AddDynamicArguments(p.HeadOID).RunStdString(&git.RunOpts{Dir: base.RepoPath()})
		require.NoError(t, err, "private head object was not transferred")
	} else {
		require.Error(t, completeErr)
		if mode == "record-rollback" || mode == "prepared-reply-loss" {
			require.Equal(t, nativeoperation_service.HumanPullCreateRefPrepared, scope.CompletionPhase)
			_, err := svc.CompleteHumanPullCreateRef(owned, humanMergeProcessInstallation, q)
			require.ErrorIs(t, err, nativeoperation_service.ErrHumanPullCreateRefClaimed)
		}
	}
	if wrote {
		require.Equal(t, p.HeadOID, sourceTestGit(t, base.RepoPath(), nil, "rev-parse", pr.GetGitRefName()))
		withoutRef := strings.TrimSpace(strings.ReplaceAll(refs(base), pr.GetGitRefName()+" "+p.HeadOID, ""))
		require.Equal(t, baseRefs, withoutRef)
	} else {
		require.Equal(t, baseRefs, refs(base))
	}
	if head.ID != base.ID && mode != "source-at-hook" {
		require.Equal(t, headRefs, refs(head))
	}
	if mode == "source-at-hook" {
		require.Equal(t, strings.ReplaceAll(headRefs, "refs/heads/"+p.HeadBranch+" "+p.HeadOID, "refs/heads/"+p.HeadBranch+" "+fixture.base), refs(head))
	}
	for i, repo := range []*repo_model.Repository{base, head} {
		raw, err := os.ReadFile(filepath.Join(repo.RepoPath(), "config"))
		require.NoError(t, err)
		want := baseConfig
		if i == 1 {
			want = headConfig
		}
		require.Equal(t, want, raw, "object transfer configured a remote")
		_, err = os.Stat(filepath.Join(repo.RepoPath(), "FETCH_HEAD"))
		require.True(t, os.IsNotExist(err), "object transfer wrote FETCH_HEAD")
	}
	_, err = os.Stat(x.CapabilityPath)
	require.NoError(t, err, "ref consumer retired the pending completion proof")
	if recoveryMode != "" {
		checkHumanPullCreateRecovery(t, fixture, base, head, q, held, x, reopen, recoveryMode)
		return
	}
	if finishMode != "" {
		checkHumanPullCreateCompletion(t, fixture, base, head, q, primary, held, x, finishMode)
		return
	}
	t.Logf("human PR derived ref %s: actual generated hooks prepared=%d committed=%d, phase=%s; exact primary retained, no notifications or owner release", mode, preparedCalls.Load(), committedCalls.Load(), scope.CompletionPhase)
}

// Real native SDK/Unix/SQL/Git preparation; no response or repository is mocked.
func checkHumanPullCreatePrimary(t *testing.T, fixture sourceTestFixture, base, head *repo_model.Repository, p extension.RepositoryPullCreateSnapshot, mode string) {
	t.Helper()
	if strings.HasPrefix(mode, "ref:") {
		checkHumanPullCreateRef(t, fixture, base, head, p, strings.TrimPrefix(mode, "ref:"))
		return
	}
	ctx, cancel := context.WithCancel(t.Context())
	defer cancel()
	svc := nativeoperation_service.NewService()
	operation, err := extension.HumanPullCreateOperationID(p.ActorID, p.RepositoryID, "pull-primary-"+mode)
	require.NoError(t, err)
	q := extension.HumanPullCreateRequest{OperationID: operation, Expected: p, NotAfter: time.Now().Add(time.Minute).Unix(), Title: "WIP: Native PR 完整", Body: "## Human native PR\r\n\nExact Markdown 🌋.\n"}
	if mode == "empty-body" {
		q.Body = ""
	}
	if mode == "max-body" {
		q.Body = strings.Repeat("<", extension.MaxHumanPullCreateBodyBytes)
		q.Title = strings.Repeat("t", extension.MaxHumanPullCreateTitleBytes)
	}
	if mode == "allow-maintainer" || mode == "allow-maintainer-reader" {
		q.AllowMaintainerEdit = true
	}
	if mode == "allow-maintainer" {
		for _, row := range []any{&access_model.Access{Mode: perm.AccessModeWrite}, &repo_model.Collaboration{Mode: perm.AccessModeWrite}} {
			_, err := db.GetEngine(ctx).Where("repo_id=? AND user_id=?", head.ID, 2).Cols("mode").Update(row)
			require.NoError(t, err)
		}
	}
	if mode == "expiry" {
		q.NotAfter = time.Now().Add(2 * time.Second).Unix()
	}
	canonical, digest, err := extension.CanonicalHumanPullCreateIntent(q)
	require.NoError(t, err)
	installation := humanMergeProcessInstallation
	t.Cleanup(func() {
		held, err := nativeoperation_model.ReadReservation(context.WithoutCancel(ctx))
		require.NoError(t, err)
		if held.Owner == "cond:"+installation+"/"+operation {
			require.NoError(t, nativeoperation_model.ReleaseExactOwner(context.WithoutCancel(ctx), held.Owner, held.Generation))
		}
	}) // Owned synchronous fixture disposal, not production recovery.
	if mode == "duplicate" {
		issue := &issues_model.Issue{RepoID: base.ID, Index: 99, PosterID: 1, IsPull: true, Title: "other native PR"}
		_, err := db.GetEngine(ctx).Insert(issue)
		require.NoError(t, err)
		_, err = db.GetEngine(ctx).Insert(&issues_model.PullRequest{IssueID: issue.ID, Index: 99, BaseRepoID: base.ID, HeadRepoID: head.ID, BaseBranch: p.BaseBranch, HeadBranch: p.HeadBranch, Flow: issues_model.PullRequestFlowGithub})
		require.NoError(t, err)
	}
	if mode == "archived" {
		_, err := db.GetEngine(ctx).ID(base.ID).Cols("is_archived").Update(&repo_model.Repository{IsArchived: true})
		require.NoError(t, err)
	}
	if mode == "blocked" {
		_, err := db.GetEngine(ctx).Insert(&user_model.BlockedUser{UserID: base.OwnerID, BlockID: 2})
		require.NoError(t, err)
	}
	if mode == "base-permission" || mode == "source-permission" {
		id := base.ID
		if mode == "source-permission" {
			id = head.ID
		}
		for _, row := range []any{new(access_model.Access), new(repo_model.Collaboration)} {
			_, err := db.GetEngine(ctx).Where("repo_id=? AND user_id=?", id, 2).Cols("mode").Update(row)
			require.NoError(t, err)
		}
	}
	if mode == "base-unit" || mode == "source-unit" {
		id, kind := base.ID, unit.TypePullRequests
		if mode == "source-unit" {
			id, kind = head.ID, unit.TypeCode
		}
		_, err := db.GetEngine(ctx).Where("repo_id=? AND type=?", id, kind).Delete(new(repo_model.RepoUnit))
		require.NoError(t, err)
	}
	if mode == "stale-base" {
		sourceTestGit(t, base.RepoPath(), nil, "update-ref", "refs/heads/"+p.BaseBranch, fixture.tip)
	}
	if mode == "stale-head" {
		sourceTestGit(t, head.RepoPath(), nil, "update-ref", "refs/heads/"+p.HeadBranch, fixture.base)
	}
	if mode == "cancel-before-submit" {
		_, err := svc.Cancel(ctx, installation, operation)
		require.NoError(t, err)
	}
	if strings.HasPrefix(mode, "sql-") {
		table, when := "issue", fmt.Sprintf("NEW.repo_id=%d", base.ID)
		event := "INSERT"
		if mode == "sql-pr-rollback" {
			table = "pull_request"
			when = fmt.Sprintf("NEW.base_repo_id=%d", base.ID)
		}
		if mode == "sql-receipt-rollback" {
			table = "operation"
			event = "UPDATE OF effect_state"
			when = "NEW.effect_state='committed'"
		}
		_, err := db.GetEngine(ctx).Exec(fmt.Sprintf("CREATE TRIGGER fail_human_pull_primary BEFORE %s ON %s WHEN %s BEGIN SELECT RAISE(ABORT, 'human pull primary rollback'); END", event, table, when))
		require.NoError(t, err)
		t.Cleanup(func() {
			_, err := db.GetEngine(context.WithoutCancel(ctx)).Exec("DROP TRIGGER fail_human_pull_primary")
			require.NoError(t, err)
		})
	}
	counts := func() [7]int64 {
		var n [7]int64
		for i, row := range []any{new(issues_model.Issue), new(issues_model.PullRequest), new(issues_model.Comment), new(activities_model.Action), new(activities_model.Notification), new(issues_model.IssueIndex), new(issues_model.IssueUser)} {
			n[i], err = db.GetEngine(context.WithoutCancel(ctx)).Count(row)
			require.NoError(t, err)
		}
		return n
	}
	gitState := func() []string {
		var s []string
		seen := map[int64]bool{}
		for _, r := range []*repo_model.Repository{base, head} {
			if seen[r.ID] {
				continue
			}
			seen[r.ID] = true
			s = append(s, sourceTestGit(t, r.RepoPath(), nil, "for-each-ref", "--format=%(refname) %(objectname)"))
			raw, err := os.ReadFile(filepath.Join(r.RepoPath(), "config"))
			require.NoError(t, err)
			s = append(s, string(raw))
		}
		return s
	}
	stats := func() [2]int64 {
		r, err := repo_model.GetRepositoryByID(context.WithoutCancel(ctx), base.ID)
		require.NoError(t, err)
		return [2]int64{int64(r.NumIssues(context.WithoutCancel(ctx))), int64(r.NumPulls(context.WithoutCancel(ctx)))}
	}
	before, gitBefore, statsBefore := counts(), gitState(), stats()
	var intervened bool
	admit := func(c context.Context) error {
		op, err := nativeoperation_model.LookupOperation(c, installation, operation)
		if err != nil {
			return err
		}
		if op != nil && op.Submitted && !intervened {
			switch {
			case !db.InTransaction(c) && mode == "cancel-after-claim":
				intervened = true
				_, err = svc.Cancel(c, installation, operation)
			case !db.InTransaction(c) && mode == "expiry":
				intervened = true
				time.Sleep(time.Until(time.Unix(q.NotAfter, 0)))
			case !db.InTransaction(c) && mode == "context":
				intervened = true
				cancel()
			case !db.InTransaction(c) && mode == "tampered-intent":
				intervened = true
				_, err = db.GetEngine(c).ID(op.ID).Cols("intent_digest").Update(&nativeoperation_model.Operation{IntentDigest: "tampered"})
			case !db.InTransaction(c) && mode == "wrong-generation":
				intervened = true
				held, e := nativeoperation_model.ReadReservation(c)
				if e != nil {
					return e
				}
				_, err = db.GetEngine(c).ID(1).Cols("generation").Update(&nativeoperation_model.Reservation{Generation: held.Generation + 1})
			case !db.InTransaction(c) && mode == "scope-tamper":
				intervened = true
				_, err = db.GetEngine(c).ID(1).Cols("scope").Update(&nativeoperation_model.Reservation{Scope: "{}"})
			case db.InTransaction(c) && mode == "session-in-primary":
				n, e := db.GetEngine(c).Where("base_repo_id=? AND head_repo_id=?", base.ID, head.ID).Count(new(issues_model.PullRequest))
				if e != nil {
					return e
				}
				if n > 0 {
					intervened = true
					fixture.session.uid = 1
				}
			}
			if err != nil {
				return err
			}
		}
		if c.Err() != nil {
			return nativeoperation_service.ErrAuthorityLost
		}
		_, status := resolveCurrentUser(c, nativeAdmissions.get(fixture.token))
		if status != http.StatusOK {
			return nativeoperation_service.ErrAuthorityLost
		}
		return nil
	}
	if mode == "invalid" {
		for _, mutate := range []func(*extension.HumanPullCreateRequest){
			func(q *extension.HumanPullCreateRequest) { q.Title = " " }, func(q *extension.HumanPullCreateRequest) { q.Title = strings.Repeat("t", 256) }, func(q *extension.HumanPullCreateRequest) { q.Title = string([]byte{0xff}) }, func(q *extension.HumanPullCreateRequest) {
				q.Body = strings.Repeat("b", extension.MaxHumanPullCreateBodyBytes+1)
			}, func(q *extension.HumanPullCreateRequest) { q.Body = "bad\x00body" }, func(q *extension.HumanPullCreateRequest) { q.OperationID = "unscoped-operation" }, func(q *extension.HumanPullCreateRequest) { q.Expected.NativeRevision = 0 }, func(q *extension.HumanPullCreateRequest) { q.Expected.Action.State = "denied" }, func(q *extension.HumanPullCreateRequest) { q.Expected.HeadOID = "HEAD" }, func(q *extension.HumanPullCreateRequest) { q.Expected.HeadRepositoryID = "01" },
		} {
			v := q
			mutate(&v)
			_, err := svc.SubmitHumanPullCreatePrimary(ctx, installation, v, admit)
			require.ErrorIs(t, err, nativeoperation_service.ErrInvalidIntent)
		}
		require.Equal(t, before, counts())
		require.Equal(t, gitBefore, gitState())
		op, err := nativeoperation_model.LookupOperation(ctx, installation, operation)
		require.NoError(t, err)
		require.Nil(t, op)
		return
	}
	if mode == "session-before" {
		fixture.session.uid = 1
	}
	var record extension.OperationRecord
	var submitErr error
	if mode == "outer-transaction" {
		require.NoError(t, db.WithTx(ctx, func(tx context.Context) error {
			_, err := svc.SubmitHumanPullCreatePrimary(tx, installation, q, admit)
			require.ErrorIs(t, err, nativeoperation_service.ErrInvalidIntent)
			return nil
		}))
	} else if mode == "busy" {
		require.NoError(t, nativeoperation_service.WithAuthorityOwnership(ctx, "user/2", base.ID, func(context.Context) error {
			_, err := svc.SubmitHumanPullCreatePrimary(ctx, installation, q, admit)
			require.ErrorIs(t, err, nativeoperation_service.ErrBusy)
			return nil
		}))
	} else {
		record, submitErr = svc.SubmitHumanPullCreatePrimary(ctx, installation, q, admit)
	}
	fixture.session.uid = 2
	op, err := nativeoperation_model.LookupOperation(context.WithoutCancel(ctx), installation, operation)
	require.NoError(t, err)
	if mode == "session-before" || mode == "outer-transaction" || mode == "busy" {
		if mode == "session-before" {
			require.ErrorIs(t, submitErr, nativeoperation_service.ErrAuthorityLost)
		}
		require.Nil(t, op)
		require.Equal(t, before, counts())
		require.Equal(t, gitBefore, gitState())
		return
	}
	require.NotNil(t, op)
	if mode == "cancel-before-submit" {
		require.ErrorIs(t, submitErr, nativeoperation_service.ErrCancelledBeforeSubmit)
		require.False(t, op.Submitted)
		require.Equal(t, nativeoperation_model.CancellationCancelled, op.Cancellation)
		require.Equal(t, before, counts())
		return
	}
	fenced := strings.HasPrefix(mode, "sql-") || mode == "tampered-intent" || mode == "wrong-generation" || mode == "scope-tamper"
	committed := mode == "valid" || mode == "same-repository" || mode == "allow-maintainer" || mode == "empty-body" || mode == "max-body"
	if committed {
		require.NoError(t, submitErr)
		require.Equal(t, extension.EffectCommitted, record.EffectState)
		require.Equal(t, extension.CompletionPending, record.CompletionState)
		require.Equal(t, nativeoperation_model.KindHumanPullCreate, op.Kind)
		require.NotEqual(t, nativeoperation_model.KindPRCreate, op.Kind)
		require.Zero(t, op.TokenID)
		require.Empty(t, op.CredentialFingerprint)
		require.Equal(t, canonical, op.Intent)
		require.Equal(t, digest, op.IntentDigest)
		var receipt extension.HumanPullCreateReceipt
		require.NoError(t, json.Unmarshal(record.Receipt, &receipt))
		require.True(t, extension.ValidHumanPullCreateReceipt(receipt, q))
		issue, err := issues_model.GetIssueByID(ctx, receipt.IssueID)
		require.NoError(t, err)
		pr, err := issues_model.GetPullRequestByID(ctx, receipt.PullID)
		require.NoError(t, err)
		require.True(t, issue.IsPull)
		require.Equal(t, q.Title, issue.Title)
		require.Equal(t, q.Body, issue.Content)
		require.EqualValues(t, 2, issue.PosterID)
		require.Equal(t, pr.IssueID, issue.ID)
		require.Equal(t, receipt.Index, issue.Index)
		require.Equal(t, head.ID, pr.HeadRepoID)
		require.Empty(t, pr.HeadCommitID) // Native computed field is not a SQL column.
		require.Equal(t, p.HeadOID, receipt.HeadOID)
		require.Equal(t, p.HeadOID, sourceTestGit(t, head.RepoPath(), nil, "rev-parse", "refs/heads/"+p.HeadBranch))
		require.Equal(t, receipt.MergeBaseOID, pr.MergeBase)
		require.Equal(t, q.AllowMaintainerEdit, pr.AllowMaintainerEdit)
		after := counts()
		require.Equal(t, before[0]+1, after[0])
		require.Equal(t, before[1]+1, after[1])
		require.Equal(t, before[5]+1, after[5])
		for _, i := range []int{2, 3, 4} {
			require.Equal(t, before[i], after[i])
		}
		require.Equal(t, [2]int64{statsBefore[0], statsBefore[1] + 1}, stats())
		held, err := nativeoperation_model.ReadReservation(ctx)
		require.NoError(t, err)
		require.Equal(t, "cond:"+installation+"/"+operation, held.Owner)
		var scope nativeoperation_service.Scope
		require.NoError(t, json.Unmarshal([]byte(held.Scope), &scope))
		require.Equal(t, head.ID, scope.HeadRepositoryID)
		require.Empty(t, scope.CompletionRef)
		require.Empty(t, scope.NewOID)
		replay, err := nativeoperation_service.NewService().SubmitHumanPullCreatePrimary(ctx, installation, q, admit)
		require.NoError(t, err)
		require.Equal(t, record, replay)
		require.Equal(t, after, counts())
		changed := q
		changed.Body += "changed"
		_, err = svc.SubmitHumanPullCreatePrimary(ctx, installation, changed, admit)
		require.Error(t, err)
		require.Equal(t, after, counts())
		fixture.session.uid = 1
		_, err = svc.SubmitHumanPullCreatePrimary(ctx, installation, q, admit)
		require.ErrorIs(t, err, nativeoperation_service.ErrAuthorityLost)
		fixture.session.uid = 2
		cancelled, err := svc.Cancel(ctx, installation, operation)
		require.NoError(t, err)
		require.Equal(t, extension.CancellationTooLate, cancelled.CancellationStatus)
		require.Equal(t, record.Receipt, cancelled.Receipt)
		require.Equal(t, after, counts())
	} else {
		require.Equal(t, before, counts())
		require.Equal(t, statsBefore, stats())
		require.Empty(t, op.Receipt)
		held, err := nativeoperation_model.ReadReservation(context.WithoutCancel(ctx))
		require.NoError(t, err)
		if fenced {
			require.Error(t, submitErr)
			require.Equal(t, nativeoperation_model.EffectPending, op.EffectState)
			require.NotEmpty(t, held.Owner)
		} else {
			if mode == "context" || mode == "session-in-primary" {
				require.ErrorIs(t, submitErr, nativeoperation_service.ErrAuthorityLost)
			} else {
				require.NoError(t, submitErr)
			}
			require.Equal(t, nativeoperation_model.EffectNotCommitted, op.EffectState)
			require.Empty(t, held.Owner)
			if mode == "cancel-after-claim" {
				require.Equal(t, nativeoperation_model.CancellationCancelled, op.Cancellation)
			}
		}
	}
	require.Equal(t, gitBefore, gitState(), "primary changed native refs or remotes before completion")
	t.Logf("human PR primary %s: effect=%s completion=%s; exact atomic issue/index/PR/receipt, replay and no finishing/ref effects", mode, op.EffectState, op.Completion)
}

func runHumanPullCreateSnapshot(t *testing.T) {
	t.Helper()
	fixture := newSourceTestFixture(t)
	ctx := t.Context()
	owner := unittest.AssertExistsAndLoadBean(t, &user_model.User{ID: 1})
	base := &repo_model.Repository{OwnerID: owner.ID, OwnerName: owner.Name, Name: "pull-create-base", LowerName: "pull-create-base", DefaultBranch: "main", IsPrivate: true, ObjectFormatName: "sha1"}
	_, err := db.GetEngine(ctx).Insert(base)
	require.NoError(t, err)
	head := &repo_model.Repository{OwnerID: owner.ID, OwnerName: owner.Name, Name: "pull-create-head", LowerName: "pull-create-head", DefaultBranch: "work", IsPrivate: true, IsFork: true, ForkID: base.ID, ObjectFormatName: "sha1"}
	_, err = db.GetEngine(ctx).Insert(head)
	require.NoError(t, err)
	for _, repo := range []*repo_model.Repository{base, head} {
		require.NoError(t, os.MkdirAll(filepath.Dir(repo.RepoPath()), 0o700))
		sourceTestGit(t, fixture.work, nil, "clone", "--bare", fixture.work, repo.RepoPath())
		_, err = db.GetEngine(ctx).Insert(&access_model.Access{RepoID: repo.ID, UserID: 2, Mode: perm.AccessModeRead}, &repo_model.Collaboration{RepoID: repo.ID, UserID: 2, Mode: perm.AccessModeRead})
		require.NoError(t, err)
	}
	baseCode := &repo_model.RepoUnit{RepoID: base.ID, Type: unit.TypeCode}
	pulls := &repo_model.RepoUnit{RepoID: base.ID, Type: unit.TypePullRequests}
	headCode := &repo_model.RepoUnit{RepoID: head.ID, Type: unit.TypeCode}
	_, err = db.GetEngine(ctx).Insert(baseCode, pulls, headCode)
	require.NoError(t, err)
	sourceTestGit(t, base.RepoPath(), nil, "update-ref", "refs/heads/main", fixture.base)
	sourceTestGit(t, base.RepoPath(), nil, "update-ref", "refs/heads/work", fixture.tip)
	sourceTestGit(t, base.RepoPath(), nil, "update-ref", "refs/heads/same-tip", fixture.base)
	sourceTestGit(t, head.RepoPath(), nil, "update-ref", "refs/heads/work", fixture.tip)
	sourceTestGit(t, head.RepoPath(), nil, "update-ref", "refs/heads/feature/完整", fixture.tip)
	sourceTestGit(t, head.RepoPath(), nil, "tag", "v1", fixture.tip)
	root := shortWitnessRoot(t)
	socket := filepath.Join(root, "c")
	var change atomic.Value
	change.Store("")
	var callbacks atomic.Int64
	native := CallbackHandlerForInstance("source-test")
	server := &http.Server{Handler: http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		callbacks.Add(1)
		if change.Load().(string) == "" {
			native.ServeHTTP(w, r)
			return
		}
		response := httptest.NewRecorder()
		native.ServeHTTP(response, r)
		raw := response.Body.Bytes()
		if response.Code == http.StatusOK {
			var result extension.CallbackResponse
			require.NoError(t, json.Unmarshal(raw, &result))
			p := result.PullCreateSnapshot
			switch change.Load().(string) {
			case "actor":
				p.ActorID = "1"
			case "repository":
				p.RepositoryID = "1"
			case "head-repository":
				p.HeadRepositoryID = "1"
			case "base-branch":
				p.BaseBranch = "different"
			case "head-branch":
				p.HeadBranch = "different"
			case "base-oid":
				p.BaseOID = "HEAD"
			case "head-oid":
				p.HeadOID = "HEAD"
			case "revision":
				p.NativeRevision = -1
			case "action":
				p.Action.State = "ready"
			case "extra":
				result.Actor = &extension.Actor{ID: "2"}
			}
			var err error
			raw, err = json.Marshal(result)
			require.NoError(t, err)
		}
		for k, vs := range response.Header() {
			for _, v := range vs {
				w.Header().Add(k, v)
			}
		}
		w.WriteHeader(response.Code)
		_, _ = w.Write(raw)
	})}
	listener, err := net.Listen("unix", socket)
	require.NoError(t, err)
	go func() { _ = server.Serve(listener) }()
	t.Cleanup(func() { _ = server.Close() })
	t.Setenv(extension.CallbackEnv, socket)
	t.Setenv(extension.ServiceCallbackEnv, "")
	raw, err := json.Marshal(fixture.authority)
	require.NoError(t, err)
	request := httptest.NewRequest("GET", "/pull-create-preparation", nil)
	request.Header.Set(extension.ContextHeader, string(raw))
	request.Header.Set(extension.AdmissionHeader, fixture.token)
	authority, err := extension.RequestContext(request)
	require.NoError(t, err)
	repository := strconv.FormatInt(base.ID, 10)
	q := extension.RepositoryPullCreateSnapshotRequest{HeadRepositoryID: strconv.FormatInt(head.ID, 10), BaseBranch: "main", HeadBranch: "work"}
	_, err = nativeoperation_service.Default().ReadNativeRevision(ctx)
	require.NoError(t, err)
	if mode := os.Getenv("SODA_FOUNTAIN_PULL_CREATE_PRIMARY_CASE"); mode != "" {
		if mode == "same-repository" || mode == "ref:same-repository" || mode == "ref:finish:same-repository" || mode == "ref:finish:submit:same-repository" || mode == "ref:finish:sdk:same-repository" {
			head = base
			q.HeadRepositoryID = repository
		}
		if strings.HasPrefix(mode, "ref:") {
			if strings.HasPrefix(mode, "ref:finish:") {
				reviewer := unittest.AssertExistsAndLoadBean(t, &user_model.User{ID: 4})
				require.NoError(t, os.WriteFile(filepath.Join(fixture.work, "CODEOWNERS"), []byte(".* @"+reviewer.Name+"\n"), 0o600))
				sourceTestGit(t, fixture.work, nil, "add", "CODEOWNERS")
				sourceTestGit(t, fixture.work, nil, "commit", "-m", "native code owners")
				codeTip := sourceTestGit(t, fixture.work, nil, "rev-parse", "HEAD")
				sourceTestGit(t, base.RepoPath(), nil, "fetch", "--no-tags", "--no-write-fetch-head", fixture.work, codeTip)
				sourceTestGit(t, base.RepoPath(), nil, "update-ref", "refs/heads/main", codeTip)
			}
			// A real private-source object that the base clone never had.
			require.NoError(t, os.WriteFile(filepath.Join(fixture.work, "private-change"), []byte("fork-only head\n"), 0o600))
			sourceTestGit(t, fixture.work, nil, "add", "private-change")
			sourceTestGit(t, fixture.work, nil, "commit", "-m", "private fork-only object")
			forkTip := sourceTestGit(t, fixture.work, nil, "rev-parse", "HEAD")
			if mode == "ref:finish:equal-tips" || mode == "ref:finish:recovery:equal-tips" || mode == "ref:finish:submit:equal-tips" {
				forkTip = sourceTestGit(t, fixture.work, nil, "rev-parse", "HEAD^")
			}
			sourceTestGit(t, head.RepoPath(), nil, "fetch", "--no-tags", "--no-write-fetch-head", fixture.work, forkTip)
			sourceTestGit(t, head.RepoPath(), nil, "update-ref", "refs/heads/work", forkTip)
		}
		p, err := authority.RepositoryPullCreateSnapshot(ctx, repository, q)
		require.NoError(t, err)
		require.Equal(t, "allowed", p.Action.State)
		checkHumanPullCreatePrimary(t, fixture, base, head, p, mode)
		return
	}
	counts := func() [7]int64 {
		var n [7]int64
		for i, model := range []any{new(issues_model.Issue), new(issues_model.PullRequest), new(issues_model.Comment), new(activities_model.Action), new(activities_model.Notification), new(nativeoperation_model.Operation), new(issues_model.IssueIndex)} {
			n[i], err = db.GetEngine(ctx).Count(model)
			require.NoError(t, err)
		}
		return n
	}
	gitState := func() []string {
		var state []string
		for _, repo := range []*repo_model.Repository{base, head} {
			refs := sourceTestGit(t, repo.RepoPath(), nil, "for-each-ref", "--format=%(refname) %(objectname)")
			config, err := os.ReadFile(filepath.Join(repo.RepoPath(), "config"))
			require.NoError(t, err)
			state = append(state, refs, string(config))
		}
		return state
	}
	take := func(selector extension.RepositoryPullCreateSnapshotRequest, want string) extension.RepositoryPullCreateSnapshot {
		t.Helper()
		before, gitBefore := counts(), gitState()
		revision, err := nativeoperation_service.Default().ReadNativeRevision(ctx)
		require.NoError(t, err)
		p, err := authority.RepositoryPullCreateSnapshot(ctx, repository, selector)
		require.NoError(t, err)
		require.True(t, extension.ValidRepositoryPullCreateSnapshot(&p, repository, "2", selector))
		require.Equal(t, want, p.Action.State)
		require.Equal(t, revision.Revision, p.NativeRevision)
		require.Equal(t, fixture.base, p.BaseOID)
		raw, err := json.Marshal(p)
		require.NoError(t, err)
		require.NotContains(t, string(raw), fixture.token)
		require.NotContains(t, string(raw), "session_generation")
		require.NotContains(t, string(raw), "credential")
		require.Equal(t, before, counts())
		require.Equal(t, gitBefore, gitState())
		after, err := nativeoperation_service.Default().ReadNativeRevision(ctx)
		require.NoError(t, err)
		require.Equal(t, revision, after)
		return p
	}
	expect := func(selector extension.RepositoryPullCreateSnapshotRequest, want error) {
		t.Helper()
		before := counts()
		_, err := authority.RepositoryPullCreateSnapshot(ctx, repository, selector)
		require.ErrorIs(t, err, want)
		require.Equal(t, before, counts())
	}
	t.Run("explicit-private-fork-reader", func(t *testing.T) { p := take(q, "allowed"); require.Equal(t, fixture.tip, p.HeadOID) })
	t.Run("same-repository", func(t *testing.T) {
		v := q
		v.HeadRepositoryID = repository
		take(v, "allowed")
		v.HeadBranch = "main"
		take(v, "denied")
		v.HeadBranch = "same-tip"
		p := take(v, "allowed")
		require.Equal(t, p.BaseOID, p.HeadOID)
	})
	t.Run("unicode-branch", func(t *testing.T) { v := q; v.HeadBranch = "feature/完整"; take(v, "allowed") })
	t.Run("explicit-readable-nonfork", func(t *testing.T) {
		_, err := db.GetEngine(ctx).ID(head.ID).Cols("is_fork", "fork_id").Update(&repo_model.Repository{})
		require.NoError(t, err)
		take(q, "allowed")
	})
	t.Run("source-archive-is-readable", func(t *testing.T) {
		_, err := db.GetEngine(ctx).ID(head.ID).Cols("is_archived").Update(&repo_model.Repository{IsArchived: true})
		require.NoError(t, err)
		take(q, "allowed")
		_, err = db.GetEngine(ctx).ID(head.ID).Cols("is_archived").Update(&repo_model.Repository{})
		require.NoError(t, err)
	})
	t.Run("target-archive", func(t *testing.T) {
		_, err := db.GetEngine(ctx).ID(base.ID).Cols("is_archived").Update(&repo_model.Repository{IsArchived: true})
		require.NoError(t, err)
		take(q, "denied")
		_, err = db.GetEngine(ctx).ID(base.ID).Cols("is_archived").Update(&repo_model.Repository{})
		require.NoError(t, err)
	})
	t.Run("owner-block", func(t *testing.T) {
		blocked := &user_model.BlockedUser{UserID: 1, BlockID: 2}
		_, err := db.GetEngine(ctx).Insert(blocked)
		require.NoError(t, err)
		take(q, "denied")
		_, err = db.GetEngine(ctx).ID(blocked.ID).Delete(new(user_model.BlockedUser))
		require.NoError(t, err)
	})
	t.Run("duplicate-open-and-closed", func(t *testing.T) {
		issue := &issues_model.Issue{RepoID: base.ID, Index: 1, PosterID: 1, IsPull: true, Title: "existing native pull"}
		_, err := db.GetEngine(ctx).Insert(issue)
		require.NoError(t, err)
		pr := &issues_model.PullRequest{IssueID: issue.ID, Index: 1, BaseRepoID: base.ID, HeadRepoID: head.ID, BaseBranch: "main", HeadBranch: "work", Flow: issues_model.PullRequestFlowGithub}
		_, err = db.GetEngine(ctx).Insert(pr)
		require.NoError(t, err)
		take(q, "denied")
		_, err = db.GetEngine(ctx).ID(issue.ID).Cols("is_closed").Update(&issues_model.Issue{IsClosed: true})
		require.NoError(t, err)
		take(q, "allowed")
	})
	t.Run("hidden-units", func(t *testing.T) {
		for _, u := range []*repo_model.RepoUnit{baseCode, pulls, headCode} {
			_, err := db.GetEngine(ctx).ID(u.ID).Delete(new(repo_model.RepoUnit))
			require.NoError(t, err)
			expect(q, extension.ErrRepositoryNotVisible)
			_, err = db.GetEngine(ctx).Insert(u)
			require.NoError(t, err)
		}
	})
	t.Run("source-permission", func(t *testing.T) {
		for _, model := range []any{new(access_model.Access), new(repo_model.Collaboration)} {
			_, err := db.GetEngine(ctx).Where("repo_id=? AND user_id=?", head.ID, 2).Cols("mode").Update(model)
			require.NoError(t, err)
		}
		expect(q, extension.ErrRepositoryNotVisible)
		for _, model := range []any{&access_model.Access{Mode: perm.AccessModeRead}, &repo_model.Collaboration{Mode: perm.AccessModeRead}} {
			_, err := db.GetEngine(ctx).Where("repo_id=? AND user_id=?", head.ID, 2).Cols("mode").Update(model)
			require.NoError(t, err)
		}
		take(q, "allowed")
	})
	t.Run("missing-branches-and-tag", func(t *testing.T) {
		for _, name := range []string{"missing", "v1"} {
			v := q
			v.HeadBranch = name
			expect(v, extension.ErrRepositoryNotVisible)
		}
		v := q
		v.BaseBranch = "missing"
		expect(v, extension.ErrRepositoryNotVisible)
	})
	t.Run("invalid-queries", func(t *testing.T) {
		for _, mutate := range []func(*extension.RepositoryPullCreateSnapshotRequest){func(q *extension.RepositoryPullCreateSnapshotRequest) { q.HeadRepositoryID = "01" }, func(q *extension.RepositoryPullCreateSnapshotRequest) { q.HeadRepositoryID = "opaque" }, func(q *extension.RepositoryPullCreateSnapshotRequest) { q.BaseBranch = "" }, func(q *extension.RepositoryPullCreateSnapshotRequest) { q.BaseBranch = "main~1" }, func(q *extension.RepositoryPullCreateSnapshotRequest) { q.HeadBranch = "work\x00" }, func(q *extension.RepositoryPullCreateSnapshotRequest) { q.HeadBranch = "work\n" }, func(q *extension.RepositoryPullCreateSnapshotRequest) { q.HeadBranch = "work@{0}" }, func(q *extension.RepositoryPullCreateSnapshotRequest) { q.HeadBranch = "work[0]" }, func(q *extension.RepositoryPullCreateSnapshotRequest) { q.HeadBranch = "work/.hidden" }, func(q *extension.RepositoryPullCreateSnapshotRequest) { q.HeadBranch = "work.lock" }, func(q *extension.RepositoryPullCreateSnapshotRequest) { q.HeadBranch = "work/" }, func(q *extension.RepositoryPullCreateSnapshotRequest) { q.HeadBranch = "work//topic" }} {
			v := q
			mutate(&v)
			before := callbacks.Load()
			expect(v, extension.ErrPullCreateSnapshotQuery)
			require.Equal(t, before, callbacks.Load())
		}
	})
	t.Run("object-format", func(t *testing.T) {
		_, err := db.GetEngine(ctx).ID(head.ID).Cols("object_format_name").Update(&repo_model.Repository{ObjectFormatName: "sha256"})
		require.NoError(t, err)
		expect(q, extension.ErrPullCreateSnapshotQuery)
		_, err = db.GetEngine(ctx).ID(head.ID).Cols("object_format_name").Update(&repo_model.Repository{ObjectFormatName: "sha1"})
		require.NoError(t, err)
	})
	t.Run("strict-callback-shape", func(t *testing.T) {
		transport := &http.Transport{DialContext: func(ctx context.Context, _, _ string) (net.Conn, error) {
			return (&net.Dialer{}).DialContext(ctx, "unix", socket)
		}}
		defer transport.CloseIdleConnections()
		for _, mutate := range []func(*extension.CallbackRequest){func(r *extension.CallbackRequest) { r.PullCreateSnapshot = nil }, func(r *extension.CallbackRequest) { r.Operation = extension.OperationCurrentActor }, func(r *extension.CallbackRequest) { r.Query = "extra" }, func(r *extension.CallbackRequest) { r.Limit = 1 }, func(r *extension.CallbackRequest) { r.RepositoryID = "0" }, func(r *extension.CallbackRequest) {
			r.MergeSnapshot = &extension.RepositoryMergeSnapshotRequest{Index: "1", Method: "merge"}
		}} {
			r := extension.CallbackRequest{Operation: extension.OperationRepositoryPullCreateSnapshot, RepositoryID: repository, Authority: fixture.authority, PullCreateSnapshot: &q}
			mutate(&r)
			body, err := json.Marshal(r)
			require.NoError(t, err)
			request, err := http.NewRequestWithContext(ctx, http.MethodPost, "http://native"+extension.NativeCallbackPath, bytes.NewReader(body))
			require.NoError(t, err)
			request.Header.Set("Content-Type", "application/json")
			request.Header.Set(extension.AdmissionHeader, fixture.token)
			response, err := (&http.Client{Transport: transport}).Do(request)
			require.NoError(t, err)
			_, _ = io.Copy(io.Discard, response.Body)
			require.NoError(t, response.Body.Close())
			require.Equal(t, http.StatusBadRequest, response.StatusCode)
		}
	})
	t.Run("result-binding", func(t *testing.T) {
		for _, field := range []string{"actor", "repository", "head-repository", "base-branch", "head-branch", "base-oid", "head-oid", "revision", "action", "extra"} {
			change.Store(field)
			_, err := authority.RepositoryPullCreateSnapshot(ctx, repository, q)
			require.Error(t, err, field)
		}
		change.Store("")
	})
	t.Run("busy", func(t *testing.T) {
		require.NoError(t, nativeoperation_service.WithAuthorityOwnership(ctx, "user/2", base.ID, func(context.Context) error { expect(q, extension.ErrPullCreateSnapshotUnavailable); return nil }))
	})
	t.Run("native-revision-race", func(t *testing.T) {
		at := fixture.session.reads + 2
		fixture.session.onRead = func(n int) {
			if n == at {
				require.NoError(t, nativeoperation_service.WithAuthorityOwnership(ctx, "user/2", base.ID, func(context.Context) error { return nil }))
			}
		}
		expect(q, extension.ErrPullCreateSnapshotChanged)
		fixture.session.onRead = nil
	})
	t.Run("target-ref-race", func(t *testing.T) {
		at := fixture.session.reads + 2
		fixture.session.onRead = func(n int) {
			if n == at {
				sourceTestGit(t, base.RepoPath(), nil, "update-ref", "refs/heads/main", fixture.tip)
			}
		}
		expect(q, extension.ErrPullCreateSnapshotChanged)
		fixture.session.onRead = nil
		sourceTestGit(t, base.RepoPath(), nil, "update-ref", "refs/heads/main", fixture.base)
	})
	t.Run("source-ref-race", func(t *testing.T) {
		at := fixture.session.reads + 2
		fixture.session.onRead = func(n int) {
			if n == at {
				sourceTestGit(t, head.RepoPath(), nil, "update-ref", "refs/heads/work", fixture.base)
			}
		}
		expect(q, extension.ErrPullCreateSnapshotChanged)
		fixture.session.onRead = nil
		sourceTestGit(t, head.RepoPath(), nil, "update-ref", "refs/heads/work", fixture.tip)
	})
	t.Run("archive-race", func(t *testing.T) {
		at := fixture.session.reads + 2
		fixture.session.onRead = func(n int) {
			if n == at {
				_, err := db.GetEngine(ctx).ID(base.ID).Cols("is_archived").Update(&repo_model.Repository{IsArchived: true})
				require.NoError(t, err)
			}
		}
		expect(q, extension.ErrPullCreateSnapshotChanged)
		fixture.session.onRead = nil
		_, err := db.GetEngine(ctx).ID(base.ID).Cols("is_archived").Update(&repo_model.Repository{})
		require.NoError(t, err)
	})
	t.Run("session-race", func(t *testing.T) {
		at := fixture.session.reads + 2
		fixture.session.onRead = func(n int) {
			if n == at {
				fixture.session.uid = 4
			}
		}
		expect(q, extension.ErrPullCreateSnapshotAdmission)
		fixture.session.onRead = nil
		fixture.session.uid = 2
	})
	t.Run("capability-and-retirement", func(t *testing.T) {
		entry := nativeAdmissions.get(fixture.token)
		delete(entry.capabilities, extension.CapabilityRepositoryRead)
		expect(q, extension.ErrPullCreateSnapshotAdmission)
		entry.capabilities[extension.CapabilityRepositoryRead] = struct{}{}
		take(q, "allowed")
		nativeAdmissions.revoke(fixture.token)
		expect(q, extension.ErrPullCreateSnapshotAdmission)
	})
	t.Log("PASS: native human PR creation preparation over real SDK/private Unix/SQL/Git; exact explicit repositories/branches/tips and native revision, reader/fork/duplicate/archive/block/access facts, strict request/result binding and live races; no issue/index/operation/ref/remote or notification effects")
}

