													require.Equal(t, nativeoperation_model.CompletionComplete, completed.CompletionState)
													require.Equal(t, pushed.Receipt, completed.Receipt)
													require.Equal(t, pushed.EffectState, completed.EffectState)
													_, err = os.Stat(capability)
													require.True(t, os.IsNotExist(err), "released execution capability file remains")
													require.NoError(t, queue.GetManager().FlushAll(t.Context(), 5*time.Second))
													idle, err := nativeoperation_model.ReadReservation(t.Context())
													require.NoError(t, err)
													require.Empty(t, idle.Owner)
													require.Empty(t, idle.OwnerKind)
													require.Empty(t, idle.Verifier)
													require.Empty(t, idle.Scope)
													require.GreaterOrEqual(t, idle.Revision, held.Revision)
													lookup, err := fresh.Get(t.Context(), installation, operation)
													require.NoError(t, err)
													require.Equal(t, completed, *lookup.Record, "lost completion return changed retained truth")
													_, err = svc.CompleteHumanMerge(owned, installation, q, stage)
													require.ErrorIs(t, err, nativeoperation_model.ErrWrongOwner)
													replayed = nil
													require.NoError(t, db.GetEngine(t.Context()).Where("repo_id=? AND op_type=?", repo.ID, activities_model.ActionCommitRepo).OrderBy("id").Find(&replayed))
													require.Equal(t, acts, replayed)
