				fork := &repo_model.Repository{OwnerID: owner.ID, OwnerName: owner.Name, Name: "human-merge-push-fork", LowerName: "human-merge-push-fork", IsPrivate: true, DefaultBranch: "private-work", ObjectFormatName: repo.ObjectFormatName}
